  ["24:4633"] = "¡Habla con esa\\\npersona!",
  ["40:4615"] = "¡Bienvenido a\\\nnuestro CENTRO\\11POKéMON!",
  ["40:4640"] = "¡Hola! ¡Bienvenido\\\na nuestro CENTRO\\11POKéMON!",
  ["40:4664"] = "¡Buenas noches!\\\nBienvenido a\\12nuestro CENTRO\\\nPOKéMON.",
  ["40:469f"] = "Nosotros curamos\\\na tus POKéMON.\\12¿Quieres curar a\\\ntus POKéMON?",
  ["40:46e2"] = "Muy bien, déjame\\\ntus POKéMON.",
  ["40:46fc"] = "¡Gracias por\\\nesperar!\\12Tus POKéMON están\\\nen plena forma.",
  ["40:4730"] = "¡Vuelve siempre\\\nque quieras!",
  ["40:4766"] = "Tus POKéMON\\\ntienen minúsculas\\12formas de vida\\\nunidas a ellos.\\12Tus POKéMON están\\\nsanos y parecen\\11contentos.\\12Pero no podemos\\\ndarte más\\12información en un\\\nCENTRO POKéMON.",
  ["40:4801"] = "Está llena de\\\nlibros complejos.",
  ["40:481f"] = "¡Una colección de\\\nlibros ilustrados\\11de POKéMON!",
  ["40:484a"] = "Revistas POKéMON…\\\nTELEVISOR POKéMON,\\12MANUAL POKéMON,\\\nGRÁFICA POKéMON…",
  ["40:4880"] = "VOTOS TEAM ROCKET\\12Robar POKéMON para\\\nenriquecernos.\\12Explotarlos para\\\nenriquecernos.\\12¡Todo POKéMON\\\nexiste para gloria\\11del TEAM ROCKET!",
  ["40:48ef"] = "¿Qué es esto?\\12¡Oh! ¡Es un\\\npebetero!",
  ["40:4919"] = "¡Cantidad de\\\nartículos POKéMON!",
  ["40:4934"] = "MAPA del PUEBLO.",
  ["40:4947"] = "¡Mi reflejo!\\\n¡Qué guapo!",
  ["40:4965"] = "Es una TV.",
  ["40:4970"] = "PÁGINA DE INICIO\\\nREVISTA POKéMON.\\12No ha sido\\\nactualizada…",
  ["40:49cd"] = "Aquí dentro no\\\nhay nada…",
  ["40:4a26"] = "Cura a tus POKéMON\\\nCENTRO POKéMON",
  ["40:4a43"] = "Todo lo necesario\\\npara tus POKéMON\\12TIENDA POKéMON",
  ["40:4a66"] = "Vamos a evaluar\\\na tus POKéMON.\\12……\\\n……\\12¡Hemos elegido a\\\nlos ganadores!\\12¿Estás preparado?",
  ["40:4ac8"] = "¡Uauu! ¡Eres\\\nbastante fuerte!\\12¿Me das tu número\\\nde teléfono?\\12Te llamaré para\\\nvolver a pelear.",
  ["40:4b1d"] = "¿Grabar el número\\\nde teléfono?",
  ["40:4b39"] = "{PLAYER} grabó el\\\nNº de {STRBUF}.",
  ["40:4b56"] = "Te llamaré si\\\nsurge algo.",
  ["40:4b7a"] = "¡Ah! ¡Vale…!\\\nPues habla conmigo\\12cuando quieras\\\nmi número.",
  ["40:4bb7"] = "En tu teléfono\\\nno tienes espacio\\11para más números.",
  ["40:4bef"] = "Te esperaba.\\\n¡Luchemos!",
  ["40:4c14"] = "¡Uauu! Peleas\\\nmuy bien.\\12¿Me das tu número\\\nde teléfono?\\12Te llamaré para\\\nvolver a pelear.",
  ["40:4c77"] = "¿Grabar el número\\\nde teléfono?",
  ["40:4c93"] = "{PLAYER} grabó el\\\nNº de {STRBUF}.",
  ["40:4cb0"] = "Te llamaré si\\\nsurge algo.",
  ["40:4cd0"] = "De acuerdo.\\\nCuando quieras\\12mi número de\\\nteléfono, dímelo.",
  ["40:4d12"] = "En tu teléfono\\\nno tienes espacio\\11para más números.",
  ["40:4d4a"] = "Te esperaba.\\\n¡Luchemos!",
  ["40:4d6a"] = "{PLAYER} gana el\\\npremio Nº{STRBUF}:\\11¡una {STRBUF}!",
  ["40:4d90"] = "{PLAYER} recibió\\\n{STRBUF}.",
  ["40:4da3"] = "¡Participa en el\\\npróximo concurso!",
  ["40:4dc9"] = "¡Todos los demás\\\nreciben una BAYA\\11como consolación!",
  ["40:4dff"] = "A ver si mejoras\\\nla próxima vez.",
  ["40:4e21"] = "Aquí tienes los\\\nPOKéMON que\\12te estábamos\\\ncuidando.",
  ["40:4e55"] = "¡Equipo completo!\\\nEl POKéMON fue\\12enviado a tu CAJA\\\nen el PC de BILL.",
  ["40:4e96"] = "GIMNASIO POKéMON\\\nDE {STRBUF}",
  ["40:4ea4"] = "LÍDER: {STRBUF}\\12GANADORES:\\\n{PLAYER}",
  ["40:4ec7"] = "Bienvenido al\\\nCASINO.",
  ["40:4ee4"] = "¿Necesitas fichas\\\nde juego?\\12¡Oh! No tienes\\\nun MONEDERO\\11para tus fichas.",
  ["40:4f2b"] = "¿Necesitas fichas\\\nde juego?\n50 fichas por\\\n1000¥. ¿Quieres\\11comprar?",
  ["40:4f78"] = "¡Gracias! Aquí\\\ntienes 50 fichas.",
  ["40:4f97"] = "¡Gracias! Aquí\\\ntienes 500 fichas.",
  ["40:4fb7"] = "No tienes\\\nbastante dinero.",
  ["40:4fd4"] = "¡Uups! Tu MONEDERO\\\nestá lleno.",
  ["40:4ff5"] = "¿No quieres\\\nfichas?\\12Vuelve cuando\\\nquieras.",
  ["40:5014"] = "¡Oh! Tu MOCHILA\\\nestá llena.\\12Te guardaremos\\\nesto. Vuelve\\12cuando tengas\\\nsitio.",
  ["40:5072"] = "¡Uauu! ¡Tú y tus\\\nPOKéMON estáis\\11muy unidos!",
  ["40:509c"] = "Cuanto más tiempo\\\npases con los\\12POKéMON, más\\\nte querrán.",
  ["40:50d1"] = "No has domesticado\\\na tu POKéMON.\\12Si no eres amable,\\\néste se enfadará.",
  ["41:4a8a"] = "Buenos días.",
  ["41:4a99"] = "¿Dígame?\\12¡Hola, {PLAYER}!\\\n¿Trabajando duro?",
  ["41:4aba"] = "Así que estás en\\\n{STRBUF}.\\12¿No está ahí\\\n{STRBUF}?\\12¿Has ido a echar\\\nun vistazo?",
  ["41:4b04"] = "¿Sí? ¿Estás en\\\n{STRBUF}?\\12Nunca he estado\\\nallí. ¡Genial,\\11{PLAYER}!",
  ["41:4b4a"] = "¿Qué? ¿Estás en\\\n{STRBUF}?\\12¡Ven a verme\\\ncuando quieras!",
  ["41:4b7d"] = "¿Estás visitando a\\\n{STRBUF}?\\12¿Por qué no vienes\\\nun rato a casa?",
  ["41:4bb5"] = "¡Uau! ¿Estás en\\\n{STRBUF}?\\12¡Suerte en tu\\\naventura POKéMON!",
  ["41:4be9"] = "Eso parece\\\nbastante duro.\\12Pero, {PLAYER}, sé\\\nque estás decidido\\12y que te irá bien,\\\n¿de acuerdo?",
  ["41:4c40"] = "Por cierto, has\\\nahorrado {STRBUF}¥.\\12¿Quieres seguir\\\nahorrando dinero?",
  ["41:4c83"] = "Es importante que\\\nahorres dinero.",
  ["41:4ca6"] = "¡Oh, {PLAYER}!\\\nNo estás ahorrando\\12dinero. ¿Quieres\\\nahorrar?",
  ["41:4ce2"] = "Por cierto, has\\\nahorrado {STRBUF}¥.\\12¿Quieres seguir\\\nahorrando?",
  ["41:4d22"] = "Vale. Te guardaré\\\nel dinero.",
  ["41:4d3c"] = "Vale. Dejaré de\\\nguardarte dinero.",
  ["41:4d5d"] = "¡Sigue así,\\\n{PLAYER}!\\11¡Estoy contigo!",
  ["41:4d87"] = "¿Dígame?\\12¡Hola, {PLAYER}!\\\n¿No te esperaba\\11el PROF. ELM?",
  ["41:4dba"] = "¿Dígame?\\12¡Hola, {PLAYER}!\\\n¿Tienes una misión\\12importante del\\\nPROF. ELM? ¡Bien!",
  ["41:4dfc"] = "¿Dígame?\\12¡Hola, {PLAYER}!\\\nCuando termines\\12tu misión, vuelve\\\na casa.",
  ["41:4e3e"] = "¿Dígame?\\12¿{PLAYER}…?\\\nMe dijo el PROF.\\12ELM que saliste\\\nde viaje.\\12Ojalá me lo\\\nhubieras dicho…\\12¿Y el dinero? ¿Te\\\nlo guardo?",
  ["41:4ec4"] = "¡Buenos días!\\12SERVICIO de\\\nADMÓN. del SISTEMA\\12de ALMACENAMIENTO\\\nde los POKéMON.",
  ["41:4f0d"] = "¡Buenos días!\\12SERVICIO de\\\nADMÓN. del SISTEMA\\12de ALMACENAMIENTO\\\nde los POKéMON.",
  ["41:4f52"] = "¡Buenas noches!\\12SERVICIO de\\\nADMÓN. del SISTEMA\\12de ALMACENAMIENTO\\\nde los POKéMON.",
  ["41:4f9b"] = "¿Quién llama?\\12{PLAYER}, ¿eres tú?\\\nEspera un segundo.\\12……\\\n……",
  ["41:4fc7"] = "¡Gracias por\\\nesperar!\\12{PLAYER}, en tu\\\nCAJA cabe/n {STRBUF}\\11POKéMON más.\\12¡Adelante!\\\n¡Llénala!",
  ["41:5024"] = "¡Gracias por\\\nesperar!\\12{PLAYER}, en tu\\\nCAJA sólo cabe/n\\11{STRBUF} POKéMON más.\\12Quizá deberías\\\ncambiar de CAJA.",
  ["41:508a"] = "¡Gracias por\\\nesperar!\\12¡{PLAYER}, tu\\\nCAJA está llena!\\12Si quieres atrapar\\\nmás POKéMON,\\12tendrás que\\\ncambiar de CAJA.",
  ["41:50ef"] = "Hola, ¿{PLAYER}?\\\n¡Soy yo, BILL!\\12Gracias por usar\\\nmi SISTEMA de\\11ALMACENAMIENTO.\\12Tu CAJA se llenó\\\ncon el último\\12POKéMON que\\\nenviaste.\\12Si quieres atrapar\\\nmás POKéMON,\\12tendrás que\\\ncambiar de CAJA.\\12¡Hasta luego!",
  ["41:5199"] = "Hola, ¿{PLAYER}?\\12No te\\\nexcedas.\\12No olvides curar\\\na tus POKéMON\\11si están heridos.\\\n",
  ["41:51e6"] = "Hola, ¿{PLAYER}?\\12¿Viste al SR.\\\nPOKéMON? ¡Genial!\\11¡Vuelve ileso!",
  ["41:5221"] = "¿{PLAYER}? Ahora\\\nestoy muy triste.\\12Nos han robado un\\\nPOKéMON. ¿Cómo\\12han podido\\\nhacerlo?",
  ["41:5272"] = "Hola, ¿{PLAYER}?\\12Estamos analizando\\\nel HUEVO. Parece\\12ser un HUEVO de\\\nPOKéMON.",
  ["41:52b9"] = "Hola, ¿{PLAYER}?\\12¿Has visto a mi\\\nayudante? Está en\\12el CENTRO POKéMON\\\nde CIUDAD MALVA.",
  ["41:5305"] = "Hola, ¿{PLAYER}?\\12¿Qué tal el HUEVO?\\\n¿Ha cambiado algo?\\12Si pasa algo, por\\\nfavor llámame.",
  ["41:5358"] = "Hola, ¿{PLAYER}?\\\n¿Qué tal el HUEVO?\\12¿Qué? ¿Se ha\\\nabierto? ¡Uau!\\11¿Qué POKéMON es?\\12¡Por favor, ven\\\na enseñármelo!",
  ["41:53bc"] = "Hola, ¿{PLAYER}?\\12Acabo de hacer un\\\ndescubrimiento.\\12El tiempo que\\\ntarda un HUEVO en\\12abrirse depende\\\ndel POKéMON.",
  ["41:541f"] = "Hola, ¿{PLAYER}?\\12Los movimientos de\\\nun POKéMON recién\\12nacido son\\\nun misterio.\\12Ahora estamos\\\ninvestigando eso.",
  ["41:5484"] = "Hola, ¿{PLAYER}?\\12He descubierto\\\nalgo extraño.\\12Parece haber algo\\\nllamado POKéRUS\\12que infecta\\\na los POKéMON.\\12¡Sí! Es como un\\\nvirus, por eso se\\11llama POKéRUS.\\12Se multiplica\\\nrápido e infecta\\12a otros POKéMON.\\\nPero eso es todo.\\12Parece que no\\\nhace nada y que\\12desaparece con\\\nel tiempo.\\12Creo que no hay\\\nde qué preocuparse\\11¡Adiós!",
  ["41:55b4"] = "¿Hola? ¿{PLAYER}?\\\n¡Qué desastre!\\12¡Ee…, ee…, es\\\nterrible!\\12¿Qué hacer?\\\n¡Oh, no…!\\12¡Vuelve aquí\\\nahora mismo!",
  ["41:5624"] = "Hola, ¿{PLAYER}?\\\n¡Hemos descubierto\\12algo sobre el\\\nHUEVO!\\12Mi ayudante está\\\nen el CENTRO\\12POKéMON de CIUDAD\\\nMALVA. ¿Podrías\\11hablar con él?",
  ["41:56a3"] = "{PLAYER}, ¿qué tal\\\nvan las cosas?\\12Te llamo porque\\\npasó algo raro\\12con las emisiones\\\nde radio.\\12Hablaban del\\\nTEAM ROCKET.\\12{PLAYER}, ¿sabes\\\nalgo sobre\\11esto?\\12Quizá ha vuelto\\\nel TEAM ROCKET.\\12No, no puede\\\nser cierto.\\12Siento molestarte.\\\n¡Cuídate!",
  ["41:57a6"] = "Hola, ¿{PLAYER}?\\12Tengo algo para\\\nti aquí.\\12¿Puedes venir\\\nal LABORATORIO?\\12¡Hasta luego!",
  ["41:5862"] = "Hola. Soy\\\n{STRBUF}…\\12¡Buenos días,\\\n{PLAYER}!",
  ["41:588a"] = "Hola. Soy\\\n{STRBUF}…\\12¿Qué tal,\\\n{PLAYER}?",
  ["41:58b3"] = "Hola. Soy\\\n{STRBUF}…\\12¡Buenas noches,\\\n{PLAYER}!",
  ["41:58db"] = "Hola. Soy\\\n{STRBUF}.\\12¡Hola, {PLAYER}!\\\nBuenos días.",
  ["41:5904"] = "Hola. Soy\\\n{STRBUF}.\\12¡Hola, {PLAYER}!\\\n¿Cómo estás?",
  ["41:592c"] = "Hola. Soy\\\n{STRBUF}.\\12¡Hola, {PLAYER}!\\\nBuenas noches.",
  ["41:5955"] = "¡Buenos días,\\\n{PLAYER}!\\12Soy yo, {STRBUF}.\\\n¿Qué tal estás?",
  ["41:5989"] = "Hola, {PLAYER}.\\12Soy yo, {STRBUF}.\\\n¿Qué tal va todo?",
  ["41:59b5"] = "¡Buenas noches,\\\n{PLAYER}!\\12Soy yo, {STRBUF}.\\\n¿Tienes un minuto?",
  ["41:59e4"] = "Buenos días,\\\n{PLAYER}.\\12Soy {STRBUF}.\\\n¿Te he despertado?",
  ["41:5a15"] = "Hola, {PLAYER}.\\12Soy {STRBUF}.\\\n¿Qué tal todo?",
  ["41:5a3f"] = "Buenas noches,\\\n{PLAYER}.\\12Soy {STRBUF}.\\\n¿Estabas dormido?",
  ["41:5a70"] = "¿Qué tal están\\\ntus POKéMON?\\12Mi {STRBUF}\\\ntiene mucha\\11energía. ¡Genial!",
  ["41:5ab5"] = "¿Qué tal están\\\ntus POKéMON?\\12Mi {STRBUF}\\\nestá en forma\\12porque lo llevo al\\\nCENTRO POKéMON.",
  ["41:5b0d"] = "Mi {STRBUF}\\\ntiene un aspecto\\12increíble. Ojalá\\\npudieras verlo.",
  ["41:5b42"] = "He vestido a mi\\\n{STRBUF}.\\12Tiene mucho mejor\\\naspecto que antes.",
  ["41:5b7b"] = "¡Sí! He ganado\\\na un fuerte\\11{STRBUF}.\\12Debo fortalecer\\\na mi equipo.",
  ["41:5bcb"] = "¡Tienes que oír\\\nesto! El otro día\\12derroté a\\\n{STRBUF}.\\12¡Fue sencillo!\\\nTuve ventaja.",
  ["41:5c27"] = "¡Eh, escucha!\\\nCasi atrapo a\\12{STRBUF} el\\\notro día.\\12¡Oh, estuve\\\nmuy cerca!",
  ["41:5c76"] = "¿Sabes lo que me\\\npasó el otro día?\\12Se me volvió\\\na escapar\\12{STRBUF}.\\\nQuizá no sea tan\\11guay en esto…",
  ["41:5cdb"] = "¿Quieres luchar?\\\nNo volverá a\\12ocurrir lo de la\\\núltima vez.\\12Estaré por\\\n{STRBUF}.",
  ["41:5d37"] = "¿Quieres luchar?\\\n¡Esta vez ganaré!\\12Te estaré\\\nesperando por\\12{STRBUF}.\\\nBúscame, ¿vale?",
  ["41:5da0"] = "¿Hola? Soy\\\n{STRBUF}…\\12¡Oh, oh…! ¡Tú no\\\neres MATEO! ¡Vaya,\\11me he equivocado!",
  ["41:5de2"] = "Hola, soy\\\n{STRBUF}. ¿Cómo\\11estás, ARIADNA?\\12¿Eh? ¿{PLAYER}?\\\n¡Me he equivocado!",
  ["41:5e2e"] = "¡Hasta luego!",
  ["41:5e3e"] = "¡Adiós!",
  ["41:5e48"] = "¡Tienes que ver\\\nesto! ¡Es salvaje!\\12¡Ha aparecido\\\nun grupo de\\12{STRBUF}\\\nalrededor de\\11{STRBUF}!",
  ["41:5e9c"] = "¡Es increíble!\\12En {STRBUF},\\\nestán picando\\12{STRBUF} como si\\\nno hubiera mañana.\\12¡{PLAYER}, trae\\\ntu CAÑA, tío!",
  ["41:5efa"] = "Un amigo me lo\\\nacaba de decir.\\12Ha visto muchos\\\n{STRBUF} en\\11{STRBUF}.\\12{PLAYER}, deberías\\\nir a verlo.",
  ["41:5f50"] = "Hoy se celebra el\\\nConcurso de\\12Captura de Bichos\\\nen el PARQUE.\\12¿Vas a ir,\\\n{PLAYER}?",
  ["41:5fa4"] = "¿Sabes qué,\\\n{PLAYER}?\\12Dicen que el TEAM\\\nROCKET ha asaltado\\12la TORRE de RADIO\\\nde CIUDAD TRIGAL.\\12¿Pero qué es el\\\nTEAM ROCKET?",
  ["41:6014"] = "¿{PLAYER}, has\\\noído las noticias?\\12El TEAM ROCKET ha\\\nasaltado la TORRE\\12de RADIO de\\\nCIUDAD TRIGAL.\\12¿Estarán bien\\\nlos trabajadores?",
  ["41:608d"] = "¡Hola, {PLAYER}!\\\n¡Las ventas de\\12BICIS han subido\\\nespectacularmente!\\12Y todo gracias a\\\nla publicidad\\12que has hecho\\\ncon nuestra BICI.\\12Quédate con esa\\\nBICI como\\12agradecimiento.\\\n¡Gracias de nuevo!",
  ["42:4027"] = "Montamos guardia\\\nen esta torre.\\12Así expresamos\\\nnuestra gratitud a\\11todos los POKéMON.",
  ["42:4078"] = "¡Gra-Gracias!",
  ["42:4087"] = "Todos los seres\\\nvivos coexisten\\11en cooperación.\\12Deberíamos\\\nestar agradecidos.",
  ["42:40dc"] = "Sólo obtendrás\\\nuna MO si llegas\\11arriba.",
  ["42:410e"] = "La TORRE\\\nBELLSPROUT fue\\12construida para\\\nentrenar POKéMON.",
  ["42:414d"] = "Un BELLSPROUT de\\\n30 m de altura.\\12Dice la gente que\\\nse convirtió en la\\11columna central.",
  ["42:41a1"] = "¿Ves cómo se\\\nmueve la columna?\\12Arriba hay gente\\\nentrenando.",
  ["42:41da"] = "Estatua POKéMON…\\12Parece muy\\\nilustre.",
  ["42:42ad"] = "Por mucho que\\\nluchemos, la TORRE\\11seguirá en pie.",
  ["42:42e3"] = "Luché con fuerza\\\npero estoy débil.",
  ["42:4303"] = "La columna\\\nflexible protege\\12la TORRE hasta\\\nde los terremotos.",
  ["42:4345"] = "Se mueve como las\\\nhojas al viento…",
  ["42:4365"] = "¡Oh, estoy débil!",
  ["42:4373"] = "Quería imitar los\\\nsuaves movimientos\\12de BELLSPROUT\\\npara pelear…\\12Pero no me\\\nentrené bastante.",
  ["42:43cc"] = "Estatua POKéMON…\\12Parece muy\\\nilustre.",
  ["42:452b"] = "ANCIANO: Eres\\\nun entrenador\\11muy hábil.\\12Como te prometí,\\\naquí tienes tu MO.\\12Pero déjame que te\\\ndiga que deberías\\12tratar mejor a\\\ntus POKéMON.\\12Luchas de forma\\\nmuy violenta.\\12Los POKéMON no son\\\narmas de guerra.",
  ["42:45f0"] = "…\\\n¡Bah!\\12Afirma ser el\\\nANCIANO, pero\\11es muy débil.\\12Es evidente.\\12Jamás perdería\\\nante quienes dicen\\12que hay que ser\\\nbuenos con\\11los POKéMON.\\12Sólo me interesan\\\nlos POKéMON\\11ganadores.\\12Paso de los\\\nPOKéMON\\11débiles.",
  ["42:46cc"] = "¡{RIVAL}\\\nusó\\11CUERDA HUIDA!",
  ["42:46e4"] = "¡Encantado de\\\nverte por aquí!\\12TORRE BELLSPROUT\\\nes un lugar de\\11entrenamiento.\\12La gente y los\\\nPOKéMON evalúan\\12sus vínculos para\\\nconstruir juntos\\11un futuro mejor.\\12Yo soy la prueba\\\nfinal.\\12¡Déjame evaluar\\\ntus vínculos con\\11los POKéMON!",
  ["42:47b6"] = "¡Ah, excelente!",
  ["42:47c6"] = "Tú y tus POKéMON\\\nno deberíais tener\\12problemas con\\\neste movimiento.\\12Toma esta MO.\\\nEs DESTELLO.",
  ["42:4817"] = "DESTELLO ilumina\\\nhasta el lugar\\11más oscuro.\\12Y con la MEDALLA\\\nde CIUDAD MALVA,\\12podrás usarlo\\\nfuera del combate.",
  ["42:488c"] = "¡Ojalá aprendas y\\\nmadures con\\11tu viaje!",
  ["42:48ba"] = "¡Entreno para\\\nsaberlo todo\\11sobre los POKéMON!",
  ["42:48e2"] = "¡Derrotado por\\\nun mocoso!",
  ["42:48fb"] = "Cuanto más fuerte\\\nsea el POKéMON,\\12más fuerte será\\\nsu entrenador.\\12No, espera. Cuanto\\\nmás fuerte sea el\\12entrenador, más\\\nfuerte el POKéMON.",
  ["42:4961"] = "A ver cuánto\\\nconfías en tus\\11POKéMON.",
  ["42:498b"] = "¡Sí, tu confianza\\\nes auténtica!",
  ["42:49a5"] = "No estás lejos\\\ndel ANCIANO.",
  ["42:49c2"] = "La MO del ANCIANO\\\nalumbra hasta\\11lo más oscuro.",
  ["42:49f4"] = "¡Mi cerebro sí\\\nque es brillante!",
  ["42:4a13"] = "¡Que haya luz\\\nen tus viajes!",
  ["42:4a38"] = "Es un bonito\\\ncuadro de un\\11BELLSPROUT.",
  ["42:4a62"] = "Estatua POKéMON…\\12Parece muy\\\nilustre.",
  ["42:4b20"] = "Intento desvelar\\\nel secreto del\\12POKéMON legendario\\\nque, en teoría,\\11descansa aquí.\\12Dicen que este\\\nPOKéMON no ha\\12dejado de volar\\\ndesde que se quemó\\11la TORRE Oeste.\\12Por eso pensé que\\\nsi tuviera algo\\12de ese POKéMON,\\\néste se sentiría\\11atraído por mí.\\12Creo que ese\\\nobjeto es…\\12¡Un ALA ARCOIRIS!\\12Pero, ¿dónde\\\nencontrar una?",
  ["42:4f24"] = "…… …… ……\\12¡Ah, eres tú!\\12Querías ser más\\\nfuerte y por eso\\12has venido a por\\\nel POKéMON\\12legendario que\\\nvive aquí. Ésa es\\11tu historia, ¿no?\\12Pues ya te puedes\\\nir olvidando.\\12¡Porque ese\\\nPOKéMON será mío!\\12Quiero ser el\\\nmejor entrenador\\12del mundo y ese\\\nPOKéMON legendario\\12sería perfecto\\\npara mí.\\12De todos modos,\\\nya estoy harto de\\12ver a un mocoso\\\ncomo tú siempre\\11por aquí.",
  ["42:5093"] = "¡Bah!\\12¡Por eso no me\\\ngusta luchar\\12contra memos!\\\n¡Son tan malos!",
  ["42:50da"] = "¡Que más da!\\12Jamás podrías\\\natrapar un\\12POKéMON\\\nlegendario.",
  ["42:5124"] = "¡Bah!\\12¡Por eso no me\\\ngusta luchar\\12contra memos! ¡Qué\\\npérdida de tiempo!",
  ["42:516d"] = "Estoy entrenándome\\\nen secreto.\\12¡Me da vergüenza\\\nque mires!",
  ["42:51ac"] = "¡Terminé\\\nhecho cenizas…!",
  ["42:51cb"] = "Estaba tan ocupado\\\nentrenándome que\\12caí por este\\\nagujero.",
  ["42:5202"] = "¡Mi alma está\\\nardiendo! ¡Déjame\\12que te enseñe\\\ncómo quema!",
  ["42:5236"] = "Aún no hace\\\nbastante calor…",
  ["42:524d"] = "En el pasado\\\nexistían POKéMON\\12que corrían\\\npor la hierba a\\11gran velocidad.\\12Dicen que corren\\\ncomo el viento.\\12Si te encuentras\\\ncon uno de ellos,\\11puede que escape.",
  ["42:552a"] = "Del suelo salieron\\\nun montón de\\12DIGLETT.\\\n¡Qué susto!",
  ["42:562d"] = "…… …… ……\\12¡Cuánto tiempo,\\\n{PLAYER}!\\12Tras haber sido\\\nderrotado por\\12ti, estuve\\\npensando en mis\\11POKéMON…\\12Y llegué a una\\\nconclusión.\\12¡Ahora verás,\\\n{PLAYER}!",
  ["42:56c5"] = "…… …… ……\\12Creía haber\\\nentrenado muy\\12bien a mis\\\nPOKéMON…\\12Pero estaba\\\nequivocado…",
  ["42:5722"] = "…… …… ……\\12Has ganado\\\njustamente.\\12Lo admito. Pero\\\nesto no termina\\11aquí.\\12Voy a ser el mejor\\\nentrenador POKéMON\\11del mundo.\\12Ya que estos\\\nchicos me apoyan.\\12Mira, {PLAYER}.\\12Uno de estos días\\\nte demostraré lo\\12bueno que soy,\\\nderrotándote.",
  ["42:5808"] = "…… …… ……\\12Ya te he pagado\\\nmi deuda.\\12Con mis POKéMON\\\nganaré al CAMPEÓN\\12y seré el mejor\\\nentrenador\\11del mundo.",
  ["42:5a87"] = "Espera.\\12¿Vas a\\\nparticipar en la\\11LIGA POKéMON?\\12No me hagas reír.\\\nEres mucho más\\12débil que yo,\\\nporque ya no\\12soy el mismo\\\nde antes.\\12¡Ahora tengo los\\\nPOKéMON mejores\\12y más fuertes!\\\n¡Soy invencible!\\12¡{PLAYER}!\\\n¡Yo te desafío!",
  ["42:5b65"] = "He perdido…\\12Hice todo lo\\\nque pude…\\12Lo que tú tienes\\\ny yo no tengo…\\12Empiezo a entender\\\nlo que me dijo\\12aquel maestro\\\nde dragones…",
  ["42:5bf6"] = "Sigo queriendo\\\nser el mejor\\11entrenador…\\12Descubriré por qué\\\nno puedo ganar\\12y ser más\\\nfuerte…\\12Te desafiaré en\\\ncuanto lo sepa.\\12Y te aplastaré\\\ncon todo\\11mi poder.\\12Hasta entonces,\\\n¡sigue entrenando!",
  ["42:5cd2"] = "¡Bah!\\12Después de todo,\\\nnada mejor que\\11el poder.\\12No necesito\\\nnada más.",
  ["43:4196"] = "¡Eh! ¡Mira mi\\\nmochila!\\12Imprimí de la\\\nPOKéDEX mis\\12POKéMON favoritos\\\ny los pegué\\11en ella.",
  ["43:41f1"] = "Es una CARTA\\\nde mi hija.\\11¡Me da ánimos!",
  ["43:4228"] = "¡Presta atención,\\\npor favor!\\12¡Ups! A ver si\\\ndejo de hablar\\12como si fuera\\\nuna maestra.\\12Eres un entrenador\\\nPOKéMON.\\12Como estás\\\ntrabajando tan\\12duro, te voy\\\na dar esto.",
  ["43:42d0"] = "Dale a un POKéMON\\\nesa GARRA RÁPIDA.\\12Y a veces atacará\\\nel primero\\11en combate.",
  ["43:4320"] = "Estoy jugando con\\\nlas pegatinas de\\11mi POKéDEX.",
  ["43:4352"] = "La pegatina de la\\\nPOKéDEX del otro\\12chico será mía,\\\nsi gano.",
  ["43:437f"] = "Doy paseos por\\\nel PARQUE, pero\\12nunca entro en\\\nla hierba.\\12Los entrenadores\\\nsiempre luchan…",
  ["43:43d9"] = "PERSIAN: ¡Persiia!",
  ["43:43ed"] = "Estoy imprimiendo\\\nmi POKéDEX.\\12También puedes\\\nimprimir las\\12CARTAS y\\\nCAJAS de tu PC.",
  ["43:4441"] = "El mundo POKéMON\\\nes muy amplio.\\12Y sigue habiendo\\\nmuchas cosas que\\11ignoramos.\\12¡Pero yo sé\\\nmás que tú!",
  ["43:44a7"] = "¿Qué, qué, qué?",
  ["43:44b6"] = "Hay muchas cosas\\\nque aprender.\\12Por ejemplo…\\12Hay 50 tipos de\\\nMT.\\12Los POKéMON\\\nintercambiados\\12suben antes\\\nde nivel.",
  ["43:4514"] = "Mis POKéMON son\\\nmuy monos. Te los\\11voy a enseñar.",
  ["43:4547"] = "Quizá no pueda\\\nvencerte…\\12Pero los míos son\\\nmucho más bonitos.",
  ["43:4584"] = "Un amigo mío tiene\\\nun MARILL. ¡Es\\12precioso! ¡Ojalá\\\ntuviera un MARILL!",
  ["43:45c1"] = "Queremos a\\\nnuestros POKéMON,\\12aunque ellos\\\nno nos quieran.\\12Eso significa ser\\\nun FAN POKéMON.",
  ["43:4611"] = "¡M-mi POKéMON!",
  ["43:461d"] = "Perdí el combate,\\\npero mis POKéMON\\12son más adorables\\\nque los tuyos.",
  ["43:4662"] = "¿Hola?\\\n¿Y tú que miras?\\12¿Quieres luchar?",
  ["43:4693"] = "¡Mmmm…!",
  ["43:469b"] = "Por como me\\\nmirabas, pensé\\11que te gustaba.\\12Al fin y al cabo,\\\nsoy tan guapa…",
  ["43:46e4"] = "PLAZA DEL DESCANSO\\\nPARQUE NACIONAL",
  ["43:4705"] = "¿Qué dice\\\neste cartel?\\12Por favor, lucha\\\nsólo en la hierba.\\12PUESTO DEL GUARDA\\\nPARQUE NACIONAL",
  ["43:475a"] = "PISTAS ENTRENADOR\\12Imprime una CARTA\\\nabriéndola y\\11pulsando START.",
  ["43:48e0"] = "RAFA: ¡Voy a\\\nganar! No me\\11molestes.",
  ["43:4907"] = "SAM: Mi PARASECT\\\nduerme a los\\12POKéMON con\\\nESPORA.",
  ["43:4937"] = "NANO: Entreno a\\\nPOKéMON rápidos\\11para luchar.",
  ["43:4960"] = "GUILLE: No me\\\nimporta ganar.\\12Sólo busco\\\nPOKéMON raros.",
  ["43:49a9"] = "TINO: ¡Ssh! Vas a\\\nasustar a SCYTHER.\\12Hablaré contigo\\\ndespués.",
  ["43:49e6"] = "BENITO: Debilita a\\\nlos POKéMON\\12bicho y lánzales\\\nuna PARQUE BALL.",
  ["43:4a25"] = "CINDY: ¿Qué pasa?\\12¿Te parece\\\ngracioso que\\12una chica atrape\\\nPOKéMON bicho?",
  ["43:4a70"] = "KAI: Colecciono\\\nPOKéMON bicho\\12desde que era\\\nsólo un niño.\\12¡Es imposible\\\nque pueda perder!",
  ["43:4acd"] = "SAMUEL: Si tienes\\\ntiempo para\\12conversar, busca\\\nPOKéMON bicho.",
  ["43:4b0c"] = "KOLDO: Soy un gran\\\nestudioso de los\\11POKéMON bicho.\\12Seguro que\\\ngano.",
  ["43:4b4f"] = "PLAZA DEL DESCANSO\\\nPARQUE NACIONAL",
  ["43:4b70"] = "¿Qué dice\\\neste cartel?\\12Por favor, lucha\\\nsólo en la hierba.\\12PUESTO DEL GUARDA\\\nPARQUE NACIONAL",
  ["43:4bc5"] = "PISTAS ENTRENADOR\\12Imprime una CARTA\\\nabriéndola y\\11pulsando START.",
  ["43:4e1f"] = "¡Bienvenido!",
  ["43:4e29"] = "Hola. Lo siento\\\npero hoy no\\12se admiten\\\nvisitas.",
  ["43:4e62"] = "¿Quieres probar\\\nen el NÚMERO DE\\11LA SUERTE?\\12¿Compruebo los\\\nnúmeros ID de\\11tus POKéMON?\\12Si tienes suerte,\\\nganarás un premio.",
  ["43:4ee2"] = "El número de esta\\\nsemana es {STRBUF}.",
  ["43:4f02"] = "A ver si coincide\\\ncon tu número.",
  ["43:4f21"] = "……\\\n……",
  ["43:4f26"] = "Vuelve la próxima\\\nsemana y participa\\12otra vez en el\\\nNº DE LA SUERTE.",
  ["43:4f5d"] = "¡Uauu! ¡Tus cinco\\\nnúmeros coinciden!\\12¡Ya tenemos un\\\nganador!\\12¡Has ganado una\\\nMASTER BALL!",
  ["43:4fcb"] = "¡Oye! ¡Tus tres\\\núltimos números\\11coinciden!\\12¡Ganaste el\\\nsegundo premio:\\11REPARTIR EXP!",
  ["43:501e"] = "¡Ooh! ¡Tus dos\\\núltimos números\\11coinciden!\\12Ganaste el tercer\\\npremio: MÁS PP.",
  ["43:5068"] = "¡No! Tus números\\\nID no coinciden.",
  ["43:508e"] = "No tienes sitio\\\npara tu premio.\\12Hazle sitio y\\\nvuelve enseguida.",
  ["43:50d5"] = "Ahora tenemos\\\nuna promoción\\11especial.\\12Acierta estas 5\\\npreguntas y gana\\11una TARJETA RADIO.\\12Introdúcela en tu\\\nPOKéGEAR para oír\\12la radio siempre\\\nque quieras.\\12¿Quieres\\\nparticipar?",
  ["43:519a"] = "Pregunta 1:\\12¿Se puede ver el\\\nMAPA del PUEBLO\\11en el POKéGEAR?",
  ["43:51d1"] = "¡Correcto!\\\nPregunta 2:\\12¿NIDORINA es\\\nsiempre hembra?",
  ["43:5204"] = "¡Perfecto!\\\nPregunta 3:\\12¿Utiliza BONTURI\\\nCÉSAR, el artesano\\11de las POKé BALL?",
  ["43:524d"] = "¡Por ahora bien!\\\nPregunta 4:\\12¿Es cierto que\\\nMAGIKARP no puede\\12aprender ningún\\\nmovimiento de MT?",
  ["43:528b"] = "¡Otro acierto!\\\nY ahora la última\\11pregunta:\\12La HORA POKéMON\\\ndel PROF. OAK es\\11muy popular.\\12¿Es ROSI la\\\nco-presentadora?",
  ["43:530b"] = "¡Bingo!\\\n¡Enhorabuena!\\12Éste es tu premio:\\\n¡la TARJETA RADIO!",
  ["43:5350"] = "¡El POKéGEAR de\\\n{PLAYER} se puede\\11usar como radio!",
  ["43:5375"] = "Sintoniza nuestros\\\nprogramas.",
  ["43:5399"] = "Lo siento mucho,\\\npero te has\\12equivocado.\\\n¡Vuelve a probar!",
  ["43:53d3"] = "¡Ah! Entiendo.\\\nVuelve a probar si\\11cambias de idea.",
  ["43:5403"] = "NARDO es un DJ\\\nfabuloso.\\12¡Su dulce voz\\\nme derrite!",
  ["43:5439"] = "Me gusta ROSA, de\\\nla HORA POKéMON.\\12Aunque sólo\\\nconozca su voz.",
  ["43:5481"] = "¡Por fin nos hemos\\\napoderado de la\\11TORRE de RADIO!\\12¡Ahora todos\\\nexperimentarán el\\12verdadero terror\\\ndel TEAM ROCKET!\\12¡Ya veréis qué\\\nhorribles somos!",
  ["43:550f"] = "¡Demasiado fuerte!\\\nTe vigilaremos…",
  ["43:552f"] = "Eres muy fuerte.\\12Arruinarías\\\nnuestros planes.\\12Mejor alertar a\\\nlos otros…",
  ["43:5574"] = "PB RECEPCIÓN\\\nP1 VENTAS\\12P2 PERSONAL\\\nP3 PRODUCCIÓN\\12P4 OFICINA DEL\\\n   DIRECTOR",
  ["43:55be"] = "¡CANAL SUERTE!\\12¡Gana con los ID\\\nde los POKéMON!\\12¡Cambia POKéMON\\\ny reúne diferentes\\11números ID!",
  ["43:570e"] = "Puedes escuchar la\\\nradio en cualquier\\11lugar. ¡Sintoniza!",
  ["43:5740"] = "Las nanas de la\\\nradio duermen\\11a los POKéMON.",
  ["43:576d"] = "¿Por qué querrían\\\napoderarse de la\\11TORRE de RADIO?",
  ["43:57a0"] = "JIGGLYPUFF:\\\nJiggly…",
  ["43:57b5"] = "¡Aviso!\\\nProhibido entrar\\11sin autorización.\\12Antes no\\\nera así.\\12Debe de haber\\\nalgún problema con\\11el DIRECTOR…",
  ["43:582e"] = "Puedes mirar por\\\ntodas partes.\\12El DIRECTOR ya\\\nno está enfadado.",
  ["43:5885"] = "Hace tres años, el\\\nTEAM ROCKET tuvo\\11que separarse.\\12¡Pero nos estamos\\\nvolviendo a\\11reunir aquí!",
  ["43:58db"] = "¡Bah! ¡No te\\\nhagas el chulo!",
  ["43:58f1"] = "¡No permitiremos\\\nque arruines\\11nuestros planes!",
  ["43:5923"] = "¡Somos el\\\nTEAM ROCKET,\\12explotadores de\\\nlos POKéMON!\\12¡Nos gusta ser\\\nmalos! ¿Asustado?",
  ["43:596a"] = "¿Te crees\\\nun héroe?",
  ["43:5983"] = "No siempre somos\\\nmalos. Hacemos\\11lo que queremos.",
  ["43:59b7"] = "¡Oye! ¡Fuera de\\\nnuestro camino!",
  ["43:59d7"] = "¡Argg! Me rindo.",
  ["43:59ea"] = "Nuestros\\\nEJECUTIVOS\\12quieren hacerse\\\ncon este lugar.\\12Tienen grandes\\\nplanes. ¿Cuáles\\11serán?",
  ["43:5a4e"] = "¡Jajaja!\\12¡Qué aburrimiento!\\\n¡Fue tan sencillo\\12apoderarse de\\\neste lugar!\\12¡Venga,\\\nentretenme!",
  ["43:5aa9"] = "¿Quién eres tú?",
  ["43:5aba"] = "¡Me venciste y no\\\npienso olvidarlo!",
  ["43:5ade"] = "P1 VENTAS",
  ["43:5ae8"] = "La HORA POKéMON\\\ndel PROF. OAK.\\12¡El mejor programa\\\nde la radio!",
  ["43:5b1b"] = "Radio POKéMON.\\\nA cualquier hora\\11y en todas partes.",
  ["43:5cbf"] = "Hemos grabado los\\\ngritos de todos\\12los POKéMON\\\ndescubiertos.\\12Debemos de tener\\\nunos 200 tipos.",
  ["43:5d20"] = "Los POKéMON son\\\nmuy queridos por\\11sus entrenadores.\\12Es horrible ver\\\ncómo trata el\\12TEAM ROCKET\\\na los POKéMON.",
  ["43:5d89"] = "Emitimos programas\\\nde entretenimiento\\12las 24 horas\\\ndel día.\\12¡Intentaremos\\\nhacerlo lo mejor\\11posible!",
  ["43:5df2"] = "El jefe del TEAM\\\nROCKET se ha\\11encerrado.\\12Pero el DIRECTOR\\\npuede abrirle.\\12Está en el\\\ncuarto piso.\\12¡Sálvale!",
  ["43:5e69"] = "¿Está a salvo\\\nel DIRECTOR?",
  ["43:5e80"] = "¡Gracias!\\\n¡Eres mi héroe!\\12Toma esto como\\\nagradecimiento.",
  ["43:5ebf"] = "¡Es DÍA SOLEADO!\\\nMejora movimientos\\12del tipo fuego\\\ndurante un tiempo.",
  ["43:5efa"] = "¡Estuviste\\\ngenial!",
  ["43:5f16"] = "He recibido\\\nórdenes.\\12¡Aplastaré a todo\\\naquél que desafíe\\11al TEAM ROCKET!",
  ["43:5f66"] = "¿¡Qué!?",
  ["43:5f6e"] = "No he cumplido\\\ncon mi deber…\\12Y me van a\\\nbajar el sueldo…",
  ["43:5fa2"] = "Me encanta ordenar\\\na los POKéMON que\\11cometan delitos.",
  ["43:5fd2"] = "¿Bromeas?",
  ["43:5fe2"] = "¡No me gusta\\\nperder!\\12¡Odio a los\\\nPOKéMON inútiles!",
  ["43:601b"] = "¿Por qué se\\\nabrió la puerta?\\12¿Acaso eres tú\\\nel responsable?",
  ["43:6060"] = "¡Es mi fin!",
  ["43:606e"] = "¿Qué? ¿Esquivaste\\\na nuestros hombres\\11del SUBTERRÁNEO?\\12¿Cómo lo hiciste?",
  ["43:60b2"] = "¿Un niño que\\\nmerodea por aquí?\\12¿Quién eres?",
  ["43:60e1"] = "¡Vaya! ¡No te tomé\\\nmuy en serio!",
  ["43:60ff"] = "¡Jajajajaja…!\\12Desde aquí puedo\\\ntransmitir todo\\11tipo de señales.",
  ["43:6142"] = "Es la ranura de la\\\nLLAVE MAGNÉTICA.",
  ["43:615a"] = "{PLAYER}\\\nusó la\\11LLAVE MAGNÉTICA.",
  ["43:6174"] = "P2 PERSONAL",
  ["43:6182"] = "MÚSICA POKéMON\\\ncon el DJ NARDO",
  ["43:62b0"] = "Mientras estaba\\\nen las RUINAS\\11oía la radio.\\12Y escuché una\\\nextraña emisión.",
  ["43:6306"] = "ROSA: ¿Por qué?\\\n¿Por qué debo\\11sufrir?\\12¡MEOWTH, ayúdame!",
  ["43:6349"] = "ROSA: ¡Oh! ¡Eres\\\nmi salvador!\\12¿Aceptas esto como\\\nagradecimiento?",
  ["43:638d"] = "ROSA: Es para los\\\nPOKéMON que\\12saben movimientos\\\nnormales.",
  ["43:63ca"] = "ROSA: Sintoniza\\\nconmigo en la\\12HORA POKéMON\\\ndel PROF. OAK.",
  ["43:6404"] = "MEOWTH: Meowth…",
  ["43:6415"] = "¿Quieres rescatar\\\nal DIRECTOR?\\12¡Pues ya te puedes\\\nir olvidando de\\12eso, porque te\\\nvoy a ganar!",
  ["43:646d"] = "¡No! ¡Increíble!",
  ["43:6480"] = "¡Increíble!\\\n¡He perdido!",
  ["43:64a2"] = "¡Alto ahí!\\\n¡Me llaman la\\12fortaleza del\\\nTEAM ROCKET!\\12¡No des un\\\npaso más!",
  ["43:64ee"] = "¡La fortaleza\\\nse derrumbó!",
  ["43:6507"] = "Te has ganado mi\\\nrespeto. ¡Te daré\\11un consejo!\\12Aún estás a\\\ntiempo de darte\\11la vuelta.",
  ["43:6562"] = "¿Son buenos mis\\\nPOKéMON?\\12¡Creeré que mis\\\nPOKéMON son buenos\\12cuando derroten\\\na los tuyos!",
  ["43:65b3"] = "¡Oh, no! ¡Son\\\ntan inútiles!",
  ["43:65cf"] = "¡Me gusta mi\\\npersonalidad!\\12¿Qué importan\\\nlos POKéMON?",
  ["43:6600"] = "¡Extraordinario!\\12Esta TORRE de\\\nRADIO completará\\11nuestro gran plan.",
  ["43:6641"] = "¡Mmmm…!\\12Todo gran plan\\\ntiene sus pegas.",
  ["43:6669"] = "¿De verdad crees\\\nque puedes detener\\11al TEAM ROCKET?",
  ["43:669c"] = "P3 PRODUCCIÓN",
  ["43:66ab"] = "P3 ESTUDIO 2",
  ["43:686a"] = "¡Tú! ¿Has venido\\\na rescatarme?",
  ["43:6889"] = "¿Es eso lo que\\\nestabas esperando?\\12¡Pues no!\\\n¡Soy un impostor!\\12Me hice pasar por\\\nel director para\\12preparar nuestra\\\ninvasión.\\12¿Quieres saber\\\ndónde escondimos\\11al DIRECTOR?\\12Te lo diré,\\\n¡pero sólo si eres\\11capaz de vencerme!",
  ["43:6965"] = "Muy bien. Te diré\\\ndónde está.",
  ["43:6988"] = "Escondimos al\\\nauténtico DIRECTOR\\12en el ALMACÉN\\\nSUBTERRÁNEO.\\12Está al otro\\\nextremo del\\11SUBTERRÁNEO.\\12Pero dudo que\\\nllegues tan lejos.",
  ["43:6a0d"] = "Hola, jovencito.\\\n¿Me recuerdas de\\12la GUARIDA de\\\nPUEBLO CAOBA?\\12Entonces perdí,\\\npero ahora no.",
  ["43:6a70"] = "¡Esto no me puede\\\nestar pasando!\\12He luchado y\\\nhe perdido…",
  ["43:6aaa"] = "{PLAYER}, ¿verdad?\\12Un mocoso como tú\\\nno puede apreciar\\12la grandeza del\\\nTEAM ROCKET.\\12¡Qué lástima!\\\nTendrías futuro\\11con nosotros.",
  ["43:6b23"] = "¿Cómo has logrado\\\nllegar tan lejos?\\12Debes de ser un\\\nbuen entrenador.\\12Queremos hacernos\\\ncon esta EMISORA\\12de RADIO para\\\nanunciar nuestra\\11vuelta.\\12Eso debería\\\nhacer regresar a\\12GIOVANNI de su\\\nentrenamiento.\\12Vamos a recuperar\\\nla gloria\\11perdida.\\12Y no voy a\\\npermitir que\\12interfieras en\\\nnuestros planes.",
  ["43:6c45"] = "¡No! ¡Perdóname,\\\nGIOVANNI!",
  ["43:6c60"] = "¿Qué ha pasado?\\12Nuestros sueños\\\nhechos añicos.\\12No estaba listo\\\npara la tarea.\\12Como ya hiciera\\\nGIOVANNI, hoy\\12abandonaré yo el\\\nTEAM ROCKET.\\12¡Adiós!",
  ["43:6d04"] = "DIRECTOR: Gracias,\\\n{PLAYER}.\\12Tu valiente\\\nacción ha salvado\\12a los POKéMON\\\nde todo el país.\\12Sé que no es\\\nmucho, pero\\11acepta esto.",
  ["43:6d7e"] = "En CIUDAD TRIGAL\\\nhabía una\\11torre.\\12Pero era vieja\\\ne inestable.\\12Y la sustituimos\\\npor nuestra\\11TORRE de RADIO.\\12Al demolerla,\\\nencontramos eso en\\11la parte superior.\\12Dicen que antes\\\nvolaban enormes\\12POKéMON sobre\\\nCIUDAD TRIGAL.\\12Podría ser de\\\nun POKéMON.\\12Como el que\\\naparece en la\\12TORRE HOJALATA\\\nde CIUDAD IRIS.\\12Mejor que vuelva\\\na mi OFICINA.",
  ["43:6ee3"] = "En CIUDAD TRIGAL\\\nhabía una\\11torre.\\12Pero era vieja\\\ne inestable.\\12Y la sustituimos\\\npor nuestra\\11TORRE de RADIO.\\12Al demolerla,\\\nencontramos eso en\\11la parte superior.\\12Dicen que antes\\\nvolaban enormes\\12POKéMON sobre\\\nCIUDAD TRIGAL.\\12Podría ser de\\\nun POKéMON.\\12Como el que\\\naparece en ISLAS\\12REMOLINO, cerca de\\\nCIUDAD ORQUÍDEA.\\12Mejor que vuelva\\\na mi OFICINA.",
  ["43:7049"] = "DIRECTOR: ¡Hola,\\\n{PLAYER}!\\12Ya sabes que amo\\\na los POKéMON.\\12Construí la TORRE\\\nde RADIO para\\12expresar mi amor\\\npor los POKéMON.\\12¡Ojalá difrute la\\\ngente con nuestros\\11programas!",
  ["43:70e3"] = "NARDO: ¿Escuchas\\\nnuestra música?",
  ["43:7105"] = "P4 OFICINA\\\n   DEL DIRECTOR",
  ["43:711e"] = "P4 ESTUDIO 1",
  ["44:409f"] = "¿Eh? Es una\\\nPOKéDEX, ¿verdad?\\11¿Puedo verla?\\12Hay muchos tipos\\\nde POKéMON.\\12¿Y esto qué es?\\12¿Cuál es este\\\nPOKéMON?\\12Se parece a las\\\nraras escrituras\\12de las paredes\\\nde las RUINAS.\\12Si esos dibujos\\\nson POKéMON,\\12debería haber\\\nmuchos más.\\12¡Ya sé! Voy a\\\nactualizar tu\\11POKéDEX. Sígueme.",
  ["44:42c3"] = "¡Mmm…! ¡Qué\\\nlugar tan extraño!",
  ["44:42e3"] = "…",
  ["44:42e6"] = "Me gusta pensar\\\naquí.",
  ["44:42fd"] = "SALA DEL PANEL DE\\\nPIEDRA MISTERIOSO",
  ["44:431a"] = "RUINAS ALFA\\\n¡Bienvenidos!",
  ["44:433a"] = "C. INVESTIGACIÓN\\\nDE LAS RUINAS ALFA\\12La Autoridad en\\\nlas RUINAS ALFA",
  ["44:443c"] = "Es una réplica\\\nde un antiguo\\11POKéMON.",
  ["44:4461"] = "Un POKéMON que\\\nvuela elegante,\\12con alas de color\\\narcoiris.",
  ["44:4516"] = "¡Bienvenido a\\\nesta cámara!\\12Hay unos paneles\\\ncon el dibujo de\\12un POKéMON, hecho\\\npor los antiguos.\\12Mueve los paneles\\\ny completa el\\11dibujo.\\12A la derecha verás\\\nuna descripción\\11del POKéMON.",
  ["44:45cb"] = "Es una réplica\\\nde un antiguo\\11POKéMON.",
  ["44:45f0"] = "Un POKéMON que se\\\noculta en el mar.\\12Con sus ojos\\\nexplora la zona.",
  ["44:46bb"] = "Es una réplica\\\nde un antiguo\\11POKéMON.",
  ["44:46e0"] = "Este POKéMON\\\nflota a la deriva\\12moviendo sus\\\ndiez tentáculos.",
  ["44:4795"] = "Es una réplica\\\nde un antiguo\\11POKéMON.",
  ["44:47ba"] = "Este POKéMON\\\nvolador ataca a\\12su presa con sus\\\nfuertes colmillos.",
  ["44:484a"] = "Siento una\\\nrara presencia…",
  ["44:486d"] = "Esta habitación es\\\nmuy grande, pero\\11aquí no hay nada.",
  ["44:489b"] = "Este lugar está\\\nimpregnado de\\11misticismo.\\12Parece hasta\\\netéreo.",
  ["44:48e5"] = "Los edificios\\\nantiguos suelen\\12ser tumbas\\\nde reyes.\\12Como por ejemplo,\\\nlas pirámides.",
  ["44:4933"] = "Es una réplica\\\nde un antiguo\\11POKéMON.",
  ["44:4b1e"] = "¡Ya está!\\12He modificado\\\ntu POKéDEX.\\12Añadí una\\\nPOKéDEX opcional\\12para guardar los\\\ndatos de UNOWN.\\12Los registra en\\\nel orden en que\\11son atrapados.",
  ["44:4ba0"] = "Mejorada POKéDEX\\\nde {PLAYER}.",
  ["44:4bb7"] = "Todos los UNOWN\\\nque atrapes serán\\11registrados aquí.\\12A ver cuántos\\\ntipos existen.",
  ["44:4c05"] = "¿Atrapaste a todos\\\nlos UNOWN?\\12¡Es un gran\\\nlogro!\\12He ajustado la\\\nimpresora para\\11UNOWN.\\12Puedes usarla\\\ncuando quieras.",
  ["44:4c93"] = "Las RUINAS datan\\\nde hace unos\t1.500 años.\\12Pero ignoramos\\\npor qué o por\\12quién fueron\\\nconstruidas.",
  ["44:4ceb"] = "¿Cuántos tipos de\\\nPOKéMON habrá\\11en las RUINAS?",
  ["44:4d1e"] = "¿Hay POKéMON\\\nen las RUINAS?\\12¡Qué noticia\\\ntan increíble!\\12Tendremos que\\\ninvestigarlo.",
  ["44:4d71"] = "En las paredes de\\\nlas RUINAS hay\\12unos dibujos\\\nmuy raros.\\12Son la clave\\\npara resolver\\12el misterio\\\nde las RUINAS.",
  ["44:4ded"] = "¿Los POKéMON\\\nraros que viste\\11en las RUINAS?\\12Son muy parecidos\\\na los dibujos de\\12esas paredes\\\nde ahí.\\12¡Mmm…!\\12Debe de significar\\\nque hay muchos\\11tipos diferentes…",
  ["44:4e8b"] = "RUINAS ALFA\n10 Años\\\nde Exploración",
  ["44:4eae"] = "Nombre de POKéMON\\\nmisterioso: UNOWN\\12Encontrados un\\\ntotal de 26 tipos.",
  ["44:4ee3"] = "Parece que esto\\\naún no funciona.",
  ["44:4f02"] = "Se puede imprimir\\\nUNOWN.",
  ["44:4f5b"] = "Hay muchos libros\\\nacadémicos.\\12Ruinas Antiguas…\\\nLos Misterios de\\11los Antiguos…",
  ["44:505c"] = "¿Te diriges a\\\nPUEBLO AZALEA?\\12Demuestra a\\\nmis POKéMON que\\11vales para luchar.",
  ["44:50b0"] = "¡Oh, oh, oh!",
  ["44:50bd"] = "¡Muy bien!\\\nYa lo he decidido.\\12¡No me iré hasta\\\nque mis POKéMON\\11se fortalezcan!",
  ["44:5106"] = "Merodeo por todas\\\npartes en busca\\11de POKéMON.\\12¿También tú vas en\\\nbusca de POKéMON?\\12¡Pues entonces\\\neres mi rival\\11coleccionista!",
  ["44:516c"] = "¡Ugh! Mis pobres\\\nPOKéMON…",
  ["44:5182"] = "Todos los viernes\\\nse escucha a un\\12POKéMON que ruge\\\nen la cueva.",
  ["44:51c4"] = "¡Uauu!\\\n¡Qué sorpresa!\\12¡No esperaba\\\nver a nadie!",
  ["44:51ff"] = "¡Uauu! ¡Me\\\nhan machacado!",
  ["44:521a"] = "Me obligaron a\\\ncomprar una COLA\\11de SLOWPOKE.\\12Lo siento por\\\nel pobre POKéMON.",
  ["44:5266"] = "El SUPERSÓNICO de\\\nZUBAT confunde a\\11mis POKéMON.\\12¡Y eso me\\\npreocupa!",
  ["44:52b1"] = "¡Me inflamé!",
  ["44:52c0"] = "Los fines de\\\nsemana se oyen\\12extraños rugidos\\\nen la cueva.",
  ["44:5300"] = "Si hay luz, no me\\\nasusta la cueva.\\12Si eres fuerte,\\\nlos POKéMON no\\11se asustarán.",
  ["44:5345"] = "¡DESTELLO!",
  ["44:534d"] = "El fuego de mi\\\nPOKéMON\\11ilumina la cueva.",
  ["44:546e"] = "Hace mucho\\\ntiempo que no\\11veo a nadie.\\12No seas tímido.\\\n¡Luchemos!",
  ["44:54bb"] = "¡Uurggh…!",
  ["44:54c4"] = "Llevo perdido\\\nmucho tiempo…\\12No es que me\\\nimporte, ¡pero\\11estoy hambriento!",
  ["44:5510"] = "¡Qué sabes tú!\\\n¡Un visitante!",
  ["44:552e"] = "¡Jajaja! ¡Eres\\\nmuy susceptible!",
  ["44:554c"] = "Vivo aquí abajo.\\12Y tú también\\\npodrías si\\11quisieras.\\12Como ves, hay\\\nmucho sitio.",
  ["44:559b"] = "¿Quién anda ahí?\\12¡Déjame en paz,\\\na mí y a mis\\11POKéMON!",
  ["44:55c4"] = "¡Fuera…!\\\n¡Lárgate!",
  ["44:55d2"] = "Sólo yo y mis\\\nPOKéMON. ¡Me\\11muero de alegría!",
  ["44:5601"] = "He venido hasta\\\naquí para estudiar\\11a los POKéMON.\\12¡Te demostraré\\\nmis hallazgos en\\11un combate real!",
  ["44:5668"] = "¡Lo has demostrado\\\nconmigo!",
  ["44:5681"] = "Debería reunir\\\ny publicar mis\\11hallazgos.\\12Podría hacerme\\\ntan famoso como\\11el PROF. ELM.",
  ["44:57bf"] = "Hay dos tipos\\\nde personas.\\12Los que tienen\\\nestilo y los que\\11no lo tienen.\\12¿A qué tipo\\\nperteneces tú?",
  ["44:5826"] = "¡Tu estilo es\\\ndeslumbrante!",
  ["44:5841"] = "El estilo de tus\\\nPOKéMON es\\11sorprendente.\\12¡Seguirás\\\nmejorando!",
  ["44:5895"] = "Estoy entrenando.\\\n¿Quieres luchar?",
  ["44:58b8"] = "No, eres demasiado\\\nbueno para mí.",
  ["44:58d9"] = "Seguiré\\\nentrenándome\\11hasta que mejore.",
  ["44:5907"] = "Si los POKéMON\\\nque me gustan\\12estuvieran ahí,\\\niría sin pensarlo.\\12Eso haría un\\\nbuen entrenador.",
  ["44:5958"] = "¡Preferiría cuidar\\\nde mis niños!",
  ["44:597c"] = "Cada semana viene\\\nun POKéMON hasta\\11la orilla.\\12Quería ver a ese\\\nPOKéMON…",
  ["44:5b06"] = "CÉSAR: ¡Hola,\\\n{PLAYER}!\\12Los guardias de\\\narriba huyeron en\\11cuanto les grité.\\12Pero entonces\\\nme caí por el\\11POZO.\\12Me golpeé en la\\\nespalda y ahora\\11no puedo moverme.\\12Si estuviera bien,\\\nmis POKéMON\\12los habrían\\\nmachacado…\\12¡Bah! Pero no\\\npuedo hacer nada.\\12¡{PLAYER},\\\ndemuéstrales lo\\11que vales!",
  ["44:5c1d"] = "CÉSAR: ¡Muy bien,\\\n{PLAYER}!\\12El TEAM ROCKET\\\nha huido.\\12Y yo estoy mejor\\\nde mi espalda.\\11¡Salgamos de aquí!",
  ["44:5c78"] = "¡Maldición! Estaba\\\nde guardia arriba\\12cuando un viejo\\\nmemo me gritó.\\12Me asusté tanto\\\nque me he caído\\11aquí abajo.\\12¡Creo que voy\\\na desahogar mi\\12ira luchando\\\ncontra ti!",
  ["44:5d1f"] = "¡Arrg! ¡Hoy NO\\\nes mi día!",
  ["44:5d3b"] = "Sí, hemos estado\\\ncortando las colas\\12de los SLOWPOKE\\\ny vendiéndolas.\\12Lo hacemos sólo\\\npor dinero.\\12¡Así es! Somos\\\nel TEAM ROCKET,\\12¡y haríamos lo que\\\nfuera por dinero!",
  ["44:5dde"] = "¿Qué quieres?\\12¡Si nos molestas,\\\nno esperes\\11misericordia!",
  ["44:5e23"] = "Lo hiciste bien,\\\nmocoso, pero ya\\11verás la próxima.",
  ["44:5e54"] = "Sí, el TEAM ROCKET\\\nse separó hace\\11tres años.\\12Pero seguimos\\\nclandestinamente\\12con nuestras\\\nactividades.\\12¡Diviértete ahora\\\ncon nuestras\\11fechorías!",
  ["44:5ee5"] = "¿Dejar de cortar\\\nlas COLAS de\\11los SLOWPOKE?\\12¡Obedecerte\\\narruinaría la\\12reputación del\\\nTEAM ROCKET!",
  ["44:5f37"] = "Simplemente…\\\nMuy fuerte…",
  ["44:5f4a"] = "Necesitamos pasta,\\\n¿pero vendiendo\\11COLAS de SLOWPOKE?\\12¡Es muy duro ser\\\nun SOLDADO ROCKET!",
  ["44:5f9b"] = "¿No más COLAS?\\12¡Claro! ¡Intenta\\\nvencernos a todos!",
  ["44:5fd3"] = "¡Maldito lambrijo!",
  ["44:5fe5"] = "¡Las COLAS de los\\\nSLOWPOKE se\\11regeneran rápido!\\12¿Qué hay de malo\\\nen venderlas?",
  ["44:6023"] = "Un SLOWPOKE\\\nsin COLA…\\12¿Qué? Tiene una\\\nCARTA. ¿Leerla?",
  ["44:6061"] = "{PLAYER} lee\\\nla CARTA.\\12Sé bueno y cuida\\\nla casa donde\\12está el abuelo y\\\nSLOWPOKE.\\12Te quiere, papá.",
  ["44:60b9"] = "Un SLOWPOKE\\\nsin COLA…",
  ["44:6182"] = "Me gustaría ver\\\ncómo evoluciona\\11SLOWPOKE.\\12Observándolos\\\nhe hecho un nuevo\\11descubrimiento.\\12Un SLOWPOKE con\\\nuna ROCA DEL REY\\12suele ser mordido\\\npor un SHELLDER.\\12Toma, compartiré\\\nuna ROCA DEL REY\\11contigo.",
  ["44:624a"] = "Voy a ser como\\\nSLOWPOKE.\\12Tendré paciencia\\\ny a ver si\\11evoluciona alguno.",
  ["44:62c5"] = "En este FARO se\\\nentrena la gente.\\12No es fácil subir\\\nporque hay muchos\\11entrenadores.",
  ["44:631a"] = "Antes había unos\\\nPOKéMON que\\12iluminaban el mar\\\nque rodea OLIVO.\\12El FARO se\\\nconstruyó en honor\\11a esos POKéMON.",
  ["44:646b"] = "¡Los hombres de\\\nmar siempre\\11quieren luchar!",
  ["44:64a1"] = "¡Urf!\\\n¡He perdido!",
  ["44:64af"] = "¡Qué poder!\\\n¿Te gustaría\\12navegar conmigo\\\npor estos mares?",
  ["44:64e9"] = "¿Qué? Aquí\\\nno se juega.",
  ["44:650c"] = "¡Ah! Ya veo que\\\nvas en serio.",
  ["44:652f"] = "Arriba hay un\\\nPOKéMON que\\11ilumina el FARO.\\12Pero dicen que\\\nestá enfermo y que\\12la medicina normal\\\nno puede curarle.",
  ["44:6625"] = "¿Qué haces aquí?\\\n¿Sólo mirando?\\12¡Pues mejor\\\nque te vayas!",
  ["44:666e"] = "Estás realmente\\\npreocupado…",
  ["44:6689"] = "¿Cómo diablos\\\nse sube?\\12Quiero visitar\\\nal POKéMON\\12enfermo, pero no\\\npuedo subir…",
  ["44:66dd"] = "Los marineros\\\nsomos fuertes y\\11simpáticos. ¿Y tú?",
  ["44:670f"] = "Eres fuerte y\\\nsimpático…",
  ["44:672e"] = "Siempre que vuelvo\\\na CIUDAD OLIVO\\11voy al GIMNASIO.\\12El tipo de POKéMON\\\nde su LÍDER ha\\12cambiado sin\\\ndarme cuenta.",
  ["44:679e"] = "Viajo por el mundo\\\npara entrenar a\\12mis POKéMON.\\\n¿Quieres luchar?",
  ["44:67e1"] = "(Suspiro…)\\\nDebo entrenar más.",
  ["44:6801"] = "YASMINA solía\\\nutilizar POKéMON\\11roca como ONIX.",
  ["44:68bc"] = "YASMINA debe de\\\nestar preocupada\\11por este POKéMON.\\12Ni siquiera\\\nsonríe.",
  ["44:690f"] = "Yo tampoco puedo\\\nsonreír…",
  ["44:692e"] = "Hablando de\\\nenfermedades, hay\\12una FARMACIA en\\\nCIUDAD ORQUÍDEA.",
  ["44:696f"] = "YASMINA es LÍDER\\\nde este GIMNASIO.\\12Quería que viniera\\\nconmigo.\\12¡No he encontrado\\\na nadie mejor!",
  ["44:69d5"] = "¡Ay! ¡Mi POKéMON!",
  ["44:69e6"] = "Cualquiera estaría\\\npreocupado si sus\\12POKéMON estuvieran\\\nenfermos.\\12Rezaré por este\\\nPOKéMON, para que\\12YASMINA regrese\\\nal GIMNASIO.",
  ["44:6aef"] = "Quería luchar con\\\nYASMINA, pero no\\12está disponible.\\\n¿Y tú, qué…?",
  ["44:6b3a"] = "¡Uauu! ¡Eres\\\nincreíble!",
  ["44:6b5b"] = "Ser LÍDER de un\\\nGIMNASIO no es\\12sólo una cuestión\\\nde fuerza. Todo\\12LÍDER también debe\\\nser compasivo.",
  ["44:6bb0"] = "Estamos bastante\\\naltos aquí. Mis\\12POKéMON pájaro\\\nestán en forma.",
  ["44:6beb"] = "¡Uups…!\\\n¡Se estrellaron!",
  ["44:6bff"] = "Mi POKéMON\\\naprendió VUELO en\\11CIUDAD ORQUÍDEA.\\12Y como soy un\\\nperdedor, cruzaré\\11el mar VOLANDO…",
  ["44:6dbd"] = "YASMINA: Este\\\nPOKéMON siempre\\12iluminaba el mar\\\npor la noche.\\12Pero de pronto\\\nenfermó… Le\\11cuesta respirar…\\12Dicen que hay\\\nuna FARMACIA\\12estupenda en\\\nCIUDAD ORQUÍDEA…\\12Pero está al otro\\\nlado del mar…\\12Y no puedo dejar\\\nsolo a AMPHY…",
  ["44:6ea0"] = "¿Podrías traerme\\\nsu medicina?\\11¿Por favor?",
  ["44:6ed5"] = "YASMINA: ¡Ah…!\\\n¿Le das a AMPHY\\11esa medicina?",
  ["44:6eff"] = "{PLAYER} entregó\\\nla POCIÓN SECRETA\\11a YASMINA.",
  ["44:6f26"] = "YASMINA: ¡Mmm!\\\nPor favor, no te\\11ofendas…\\12AMPHY no aceptaría\\\nnada de nadie,\\11sólo confía en mí.",
  ["44:6f80"] = "YASMINA: …\\12AMPHY, ¿cómo te\\\nsientes?",
  ["44:6fa8"] = "YASMINA: ¡Oh…!\\\n¡Qué alivio…!\\12Es tan\\\nestupendo…\\12Muchísimas\\\ngracias.\\12Regresaré\\\nal GIMNASIO…",
  ["44:701b"] = "YASMINA: Ya veo.",
  ["44:702d"] = "¡AMPHY, aguanta!",
  ["44:703f"] = "AMPHY: ¡Am…\\\nAm… phyphy…!",
  ["44:7055"] = "Apenas puede\\\nrespirar…",
  ["44:7079"] = "AMPHY: ¡Amphy!\\\n¡Amphy!",
  ["45:4126"] = "¡Arrg…!\\\nHas encontrado la\\11escalera secreta.",
  ["45:414f"] = "El experimento\\\nfuncionó a las mil\\11maravillas.\\12Los MAGIKARP no\\\nvalen nada, pero\\12los GYARADOS son\\\nmuy productivos.",
  ["45:41bc"] = "¡Urrg…!\\12Los POKéMON dragón\\\nde ese chico\\11son muy fuertes…",
  ["45:41e5"] = "LANCE: DRAGONITE,\\\nHÍPER RAYO.",
  ["45:4204"] = "¿Por qué tardaste\\\ntanto, {PLAYER}?\\12Como pensaba,\\\nesa extraña señal\\12de radio viene\\\nde aquí.",
  ["45:4259"] = "Las escaleras\\\nestán justo aquí.",
  ["45:4275"] = "LANCE: {PLAYER},\\\nseparémonos para\\12registrarlo todo.\\\nYo iré primero.",
  ["45:47cd"] = "¡Cuidado!\\\n¡Un intruso!",
  ["45:47e3"] = "¡Vaya…! Fallé…",
  ["45:47f4"] = "¡Me toca a mí!\\\n¡No puedes huir!",
  ["45:4814"] = "En las estatuas de\\\nlos POKéMON hay\\12cámaras de\\\nvigilancia.\\12Seguiremos\\\napareciendo hasta\\12que pulses un\\\nbotón secreto.",
  ["45:4876"] = "Esto era una\\\nguarida ninja.\\12Hay trampas para\\\nconfundir a los\\11intrusos como tú.",
  ["45:48c6"] = "Lo tengo…",
  ["45:48d1"] = "Bien. Te contaré\\\nun secreto sobre\\11nuestra guarida.\\12Eso que hay en\\\nel suelo es un\\11panel deslizante.\\12Si te colocas\\\nencima, te\\12llevará de vuelta\\\na la entrada.",
  ["45:4972"] = "¡Je, je! ¿Te crees\\\nafortunado?\\12Adelante, da\\\notro paso.\\12¡El suelo está\\\nlleno de trampas!",
  ["45:49cd"] = "¡Kabum!",
  ["45:49d6"] = "Yo ni siquiera sé\\\ndónde están las\\11trampas.\\12Tendrás que\\\nser valiente\\11y caminar.",
  ["45:4a37"] = "Es una estatua de\\\nPERSIAN…\\12Sus ojos tienen un\\\nbrillo extraño.",
  ["45:4a68"] = "¡Un botón secreto!\\\nMejor pulsarlo.",
  ["45:4a8b"] = "El interruptor\\\nestá apagado.",
  ["45:4f65"] = "¡Alto ahí!",
  ["45:4f7b"] = "No podemos dejar\\\nque un mocoso como\\11tú nos toree.\\12Es malo para el\\\norgullo del TEAM\\11ROCKET.\\12Por muy fuerte que\\\nseas, no podrás\\12derrotarnos al\\\nmismo tiempo.\\12Lo siento, chico.\\\n¡Prepárate para\\11ser aniquilado!",
  ["45:5044"] = "¡Oye! No seas tan\\\negoísta. Comparte\\11la diversión.",
  ["45:5075"] = "¿Qué? ¿Tenías un\\\ncómplice? ¿Dónde\\12está tu sentido\\\ndel honor?\\12Como sustituto\\\nprovisional\\12de GIOVANNI, ¡ya\\\nte enseñaré yo a\\12no meterte con\\\nel TEAM ROCKET!",
  ["45:5114"] = "¡Uau! Eres muy\\\nfuerte.\\12¡Qué lástima!\\12Si te unieras al\\\nTEAM ROCKET,\\12podrías llegar a\\\nser un EJECUTIVO.",
  ["45:517e"] = "Esta guarida\\\nse acabó…\\12Pero no importa.\\\nEl experimento de\\12emisión fue\\\ntodo un éxito.\\12Qué más da lo que\\\npase ahora con\\11esta guarida.\\12Tenemos planes más\\\nimportantes.\\12Muy pronto\\\nconocerás el\\12verdadero poder\\\ndel TEAM ROCKET.\\12Disfruta mientras\\\npuedas…\\12¡Fufufufu…!",
  ["45:5290"] = "LANCE: Funcionó.\\\nHemos derrotado\\12a todos estos\\\nROCKETS.\\12Pero me preocupa\\\nese joven contra\\11el que luché…",
  ["45:5306"] = "Perdona, {PLAYER}.\\\nComo lo estabas\\12haciendo tan bien,\\\nme retiré.\\12Lo único que hay\\\nque hacer ahora es\\12apagar esa extraña\\\nseñal radiofónica.",
  ["45:5387"] = "Esta máquina está\\\ncausando todos\\11los problemas.\\12Pero no veo ningún\\\ninterruptor…\\12No tenemos\\\nelección. Hay que\\12debilitar a todos\\\nlos ELECTRODE.\\12Eso impedirá que\\\nesta máquina siga\\12transmitiendo esa\\\nextraña señal.\\12Los POKéMON no\\\ntienen la culpa\\12y por eso yo me\\\nsiento culpable.\\12{PLAYER}, mejor\\\nque nos dividamos\\11la tarea.",
  ["45:54a2"] = "LANCE: Déjame\\\neste lado.",
  ["45:54c1"] = "LANCE: Por fin\\\nha parado esa\\11extraña señal.\\12El LAGO vuelve a\\\nla normalidad.\\12¡Eres un héroe!\\\nMuchas gracias\\12en nombre de\\\ntodos los POKéMON.\\12¡Ah, sí! Toma\\\nesto.\\12Lo encontré aquí,\\\npero yo no lo\\11necesito.",
  ["45:55b0"] = "Es TORBELLINO.\\\nEnséñasela a\\12un POKéMON y\\\npodrá cruzar\\11torbellinos.\\12Pero recuerda\\\nque…\\12Sólo podrás usarla\\\nfuera de los\\12combates con la\\\nMEDALLA del\\11GIMNASIO CAOBA.",
  ["45:564c"] = "{PLAYER}…\\12El viaje para ser\\\nun MAESTRO\\12POKéMON es largo\\\ny difícil.\\12Y ya que lo sabes,\\\n¿quieres seguir?\\12…\\12Entiendo. No,\\\ntienes razón.\\12Si te rindieras\\\ntan fácilmente,\\12jamás habrías\\\nperseguido este\\12maravilloso\\\nsueño.\\12¡Espero volver\\\na verte!",
  ["45:574f"] = "LANCE: ¿Estás\\\nbien?\\12Tus POKéMON están\\\nheridos, cansados.\\12Toma, dales un\\\npoco de mi\\11medicina.",
  ["45:57af"] = "LANCE: {PLAYER},\\\ntenemos que hacer\\12todo lo posible\\\npor los POKéMON.",
  ["45:57da"] = "¿No se abre\\\nla puerta?\\12Bueno, necesitas\\\nuna contraseña que\\12sólo conoce el\\\nTEAM ROCKET.",
  ["45:5831"] = "¿Qué? ¿He perdido?",
  ["45:5840"] = "¿Qué? Soy sólo\\\nun SOLDADO.\\12Y no conozco la\\\ncontraseña. Lo\\11siento por ti.",
  ["45:5882"] = "¡Oh! ¿Un niño?\\\nNo me gusta,\\12pero debo\\\neliminarte.",
  ["45:58c1"] = "Sabía que\\\nperdería…",
  ["45:58d2"] = "En mi última\\\nmisión también fui\\12derrotado por\\\nun niño.\\12Cuando estábamos\\\nsecuestrando unos\\12POKéMON, un\\\nchico pelirrojo y\\12de extraña mirada\\\nme machacó…",
  ["45:5968"] = "¡Tú! ¡Pequeño\\\nparásito podrido!",
  ["45:5981"] = "¡Grrrr…!",
  ["45:5989"] = "¡Oye! Sólo el jefe\\\nconoce la clave\\11de esa puerta.\\12¿Dónde está el\\\njefe? ¡Quién sabe!\\11Encuéntralo tú.",
  ["45:59f1"] = "La puerta está\\\ncerrada…\\12Requiere una\\\ncontraseña.",
  ["45:5a23"] = "La puerta está\\\ncerrada…\\12{PLAYER} introdujo\\\nla contraseña.\\12¡Puerta abierta!",
  ["45:5a5f"] = "La emisora de\\\nradio está\\12emitiendo una\\\nsiniestra señal.\\12Está funcionando a\\\nmáxima capacidad.",
  ["45:5abb"] = "Por fin la emisora\\\nde radio ha dejado\\12de transmitir esa\\\nmaldita señal.",
  ["45:5e2f"] = "LANCE: Necesitas\\\ndos contraseñas\\12para entrar en el\\\ncuarto del jefe.\\12Y sólo conocen\\\nesas contraseñas\\11algunos ROCKETS.\\12Me lo ha contado\\\nese ROCKET que\\11está ahí.\\12{PLAYER}, busquemos\\\nesas contraseñas.",
  ["45:5eeb"] = "¡Urrgg…! El\\\nchico de la capa\\11es muy fuerte…",
  ["45:5f1d"] = "…\\12¿No te había\\\ndicho que iba a\\12destruir al TEAM\\\nROCKET?\\12Dime, ¿quién\\\nera el chico de la\\12capa que usaba los\\\nPOKéMON dragón?\\12Mis POKéMON no\\\npudieron con él.\\12No me importa\\\nperder. Podría\\12ganarle con otros\\\nPOKéMON.\\12Lo que me molestó\\\nes lo que dijo…\\12Me dijo que no\\\namo ni confío\\12bastante en mis\\\nPOKéMON.\\12Me enfurece haber\\\nperdido contra un\\11memo como él.\\12¡Humph! ¡No tengo\\\ntiempo para\\11gente como tú!",
  ["45:60b6"] = "¿Qué? ¿Quién eres?\\\nÉsta es la oficina\\12de nuestro líder,\\\nGIOVANNI.\\12Lleva entrenándose\\\ndesde que el TEAM\\12ROCKET se separó\\\nhace tres años.\\12Pero seguro que\\\nvolverá algún día\\12para retomar el\\\nmando.\\12Por eso estamos\\\naquí de guardia.\\12¡No permitiré que\\\nnadie perturbe\\11este lugar!",
  ["45:61c7"] = "Yo…, no pude\\\nevitarlo…\\12GIOVANNI,\\\nperdóname…",
  ["45:61fe"] = "No puedo dejar\\\nque me afecte.\\12Tengo que informar\\\na los otros…",
  ["45:623b"] = "MURKROW: La\\\ncontraseña es…\\12VIVA GIOVANNI.",
  ["45:6265"] = "¿Conozco yo la\\\ncontraseña?\\12A lo mejor.\\12¡Pero no será de\\\nningún debilucho!",
  ["45:62a7"] = "Muy bien. Espera.\\\nTe la diré.",
  ["45:62c7"] = "La contraseña de\\\nla oficina del\\11jefe es…\\12COLASLOWPOKE.\\12Pero no te servirá\\\nde nada si no\\11tienes las dos.",
  ["45:6327"] = "¡Je, je, je!\\12¿Me desafías a\\\nun combate? ¡Bah!\\12¡Estás loco, pero\\\ntienes agallas!\\12¡Eso me gusta!\\12¡Si me vences, te\\\ndiré la contraseña\\12de la oficina\\\ndel jefe!",
  ["45:63cd"] = "¡Ji, Ji, Ji!\\\n¡Eres bueno!",
  ["45:63ed"] = "¡Ji, Ji, Ji!\\12La contraseña\\\nde la oficina del\\11jefe es…\\12¡Eh…! Creo que\\\nes COLARATICATE.",
  ["45:6443"] = "Trabajaba para\\\nSILPH, pero ahora\\12investigo para el\\\nTEAM ROCKET.\\12Un entrometido\\\ncomo tú debería\\11ser castigado.",
  ["45:64b8"] = "Un error táctico\\\nacabó conmigo…",
  ["45:64d8"] = "Una señal de radio\\\nque vuelve locos a\\11los POKéMON…\\12Mi experimento es\\\ntodo un éxito.\\12Mi ascenso está\\\nasegurado. Esta\\12derrota no\\\nsignifica nada.",
  ["45:6562"] = "Me da igual que\\\nlos POKéMON sufran\\12debido a nuestros\\\nexperimentos.",
  ["45:6595"] = "Mi fuerte es\\\npensar, no pelear.",
  ["45:65c0"] = "Si enviáramos\\\nnuestra señal de\\12radio por todo\\\nel país…\\12¡Me emociono\\\nsólo de pensarlo!",
  ["45:6626"] = "La puerta está\\\ncerrada…\\12Necesitas dos\\\ncontraseñas.",
  ["45:6659"] = "La puerta está\\\ncerrada…\\12{PLAYER} introdujo\\\ndos contraseñas.\\12¡Puerta abierta!",
  ["45:6a44"] = "¡Vaya…! Mi jefe\\\nse va a poner\\11furioso…\\12Se me escapó el\\\nFARFETCH'D que\\12CORTA árboles para\\\nconseguir carbón.\\12No puedo ir a\\\nbuscarlo al\\11ENCINAR.\\12Demasiado grande y\\\noscuro para mí…",
  ["45:6b01"] = "¡Uauu! ¡Muchísimas\\\ngracias!\\12El POKéMON de\\\nmi jefe no me\\12obedecía porque\\\nno tengo MEDALLAS.",
  ["45:6b57"] = "¡Es el POKéMON\\\nperdido!",
  ["45:6b6e"] = "FARFETCH'D: ¡Farf!",
  ["45:6b81"] = "¡Mi FARFETCH'D!\\12¡Genial! ¡Lo has\\\nencontrado!\\12Sin él no podíamos\\\nCORTAR árboles\\12para conseguir\\\ncarbón.\\12¡Gracias, chico!\\12¿Cómo podría\\\nagradecértelo…?\\12¡Ya sé! Toma\\\nesto.",
  ["45:6c29"] = "Es la MO CORTE.\\\n¡Enséñasela a un\\12POKéMON para\\\ncortar arbustos!\\12Pero necesitarás\\\nla MEDALLA del\\12GIMNASIO AZALEA\\\npara usarla.",
  ["45:6ca8"] = "¿Quieres que te\\\nenseñe a trabajar\\11con el carbón?\\12¡En diez años\\\nserás el mejor!",
  ["45:6d03"] = "¿Que qué hago?\\12Agitar los árboles\\\ncon GOLPE CABEZA.\\12Es muy divertido.\\\n¡Toma, pruébalo!",
  ["45:6d55"] = "Agita los árboles\\\ncon GOLPE CABEZA.\\12A veces caen\\\nPOKéMON dormidos.",
  ["45:6d97"] = "Hay tantos árboles\\\nen el ENCINAR que\\12no se ve ni\\\nel cielo.\\12Por favor, busca\\\nobjetos que puedan\\11haber caído.",
  ["45:6e11"] = "SANTUARIO del\\\nENCINAR…\\12Construido en\\\nhonor del guardián\\11del encinar…",
  ["46:42dc"] = "Me echaron\\\ndel CASINO.\\12Intentaba hacer\\\ntrampas usando\\11mis POKéMON…",
  ["46:4329"] = "¡Caray…!",
  ["46:4334"] = "Supongo que\\\ndebería actuar\\11honradamente…",
  ["46:4362"] = "¿Tienes en cuenta\\\nlos tipos durante\\11el combate?\\12Si conoces bien\\\nlos distintos\\12tipos, rendirás\\\nmás en combate.",
  ["46:43cb"] = "¡Oo, oo, oo!",
  ["46:43d8"] = "Conozco mis tipos\\\nde POKéMON.\\12Pero sólo uso un\\\ntipo de POKéMON.",
  ["46:441a"] = "¡Les corté el pelo\\\na mis POKéMON!\\12¡Ahora verás lo\\\nfuertes que son!",
  ["46:4458"] = "¡Ayyyy!",
  ["46:4462"] = "Los POKéMON serán\\\nmás amigos tuyos\\12si los llevas a\\\ncortar el pelo.",
  ["46:449b"] = "Creo que tienes\\\nalgunos POKéMON\\11muy raros.\\12¡Déjame verlos!",
  ["46:44d7"] = "¡Bah! ¡He perdido!\\\n¡Qué rabia me da!",
  ["46:44f9"] = "¿Tienes una\\\nPOKéDEX? Pues te\\11daré una pista.\\12El MONTAÑERO de\\\nla RUTA 33, LUIS,\\11es un buen chico.\\12Te telefoneará\\\nsi ve algún\\11POKéMON raro.",
  ["46:457a"] = "Puerta cerrada…",
  ["46:458d"] = "Puerta abierta.",
  ["46:45a0"] = "Puerta abierta con\\\nLLAVE del SÓTANO.",
  ["46:45c3"] = "¡Hola! ¡Yo dirijo\\12la PELUQUERÍA\\\nPOKéMON!\\12Soy el mayor y\\\nel mejor de los\\12dos HERMANOS\\\nPELUQUEROS.\\12Puedo poner guapos\\\na tus POKéMON por\\11sólo 500¥.\\12¿Quieres que les\\\ncorte el pelo?",
  ["46:4664"] = "¿A qué POKéMON\\\nle corto el pelo?",
  ["46:4682"] = "¡Vale! ¡Verás lo\\\nbien que queda!",
  ["46:46a2"] = "¡Bien! ¡Ya está!",
  ["46:46b4"] = "¿De verdad?\\\n¡Qué vergüenza!",
  ["46:46d3"] = "Necesitarás más\\\ndinero.",
  ["46:46f5"] = "Sólo corto el pelo\\\nuna vez al día.\\11Ya vale por hoy.",
  ["46:4726"] = "¡Bienvenido a la\\\nPELUQUERÍA!\\12Soy el más joven y\\\nel más novato de\\12los dos HERMANOS\\\nPELUQUEROS.\\12Pondré guapos a\\\ntus POKéMON por\\11sólo 300¥.\\12¿Qué dices?",
  ["46:47bb"] = "¿A qué POKéMON\\\nle corto el pelo?",
  ["46:47d8"] = "¡Vale! Ya verás lo\\\nbien que queda.",
  ["46:47f4"] = "¡Muy bien!\\\n¡Ya está!",
  ["46:480c"] = "¿No?\\\n¡Qué lástima!",
  ["46:4825"] = "No te queda\\\nmucho dinero.",
  ["46:4845"] = "Sólo corto el pelo\\\nuna vez al día.\\12Perdona, pero hoy\\\nno trabajo más.",
  ["46:4889"] = "{STRBUF}\\\nparece un poco\\11más feliz.",
  ["46:48a6"] = "{STRBUF}\\\nparece feliz.",
  ["46:48b8"] = "¡{STRBUF}\\\nestá encantado!",
  ["46:48ce"] = "Lo siento,\\\nhemos cerrado.",
  ["46:48e4"] = "PROHIBIDO PASAR\\\nDE ESTE PUNTO",
  ["46:4e67"] = "¡Alto ahí!\\12Te he visto y te\\\nhe seguido.\\12No quiero verte\\\ncerca mientras\\12me ocupo del TEAM\\\nROCKET.\\12Espera un segundo.\\\nMe venciste antes,\\11¿verdad?\\12¡Tuviste mucha\\\nsuerte!\\12¡Pero yo pago\\\nmis deudas!",
  ["46:4f27"] = "¿Por qué? ¿Cómo\\\nhe podido perder?\\12He usado a mis\\\nmejores POKéMON.\\12No he bajado la\\\nguardia.\\12¿Cómo he perdido?",
  ["46:4f8c"] = "No lo\\\nentiendo…\\12¿Es verdad lo que\\\ndijo ese LANCE?\\12¿Qué no cuido bien\\\na mis POKéMON?\\12Amor…\\12Confianza…\\12¿Es eso lo que\\\nme falta?\\12¿Es eso lo que me\\\nimpide ganar?\\12Yo… No lo\\\nentiendo.\\12Pero esto no\\\nacaba aquí.\\12Ahora no. No por\\\nesta razón.\\12¡No renunciaré a\\\nmi sueño de ser el\\12mejor entrenador\\\nPOKéMON del mundo!",
  ["46:50cc"] = "¡Bah! ¡Mira\\\nqué fuerte soy!\\12Destruiré al\\\nTEAM ROCKET.\\12Y machacaré a\\\nese tal LANCE.",
  ["46:5140"] = "Me desafiaron a\\\nun combate en el\\11piso de abajo.\\12Ahí abajo son muy\\\nduros. Mejor que\\11tengas cuidado.",
  ["46:519a"] = "Abajo hay algunas\\\ntiendas…\\12Pero también hay\\\nentrenadores.\\12Me da miedo\\\nbajar ahí.",
  ["46:51f5"] = "Una puerta se abre\\\ny otra se cierra.\\12¡Seguro que no\\\nconsigues llegar!",
  ["46:5239"] = "¡Caramba! ¡Perdí\\\npor mi indecisión!",
  ["46:525a"] = "Tampoco lo sé…\\\nPrimero hay que\\12pulsar el último\\\nbotón, pero…",
  ["46:52a2"] = "¡Ajajaja!\\12¿Confundido con\\\ntanta llave?\\12¡Te contaré un\\\nsecreto si logras\\11vencerme!",
  ["46:52ff"] = "¡Ohhh…!\\\nFallé.",
  ["46:5311"] = "Bien. ¡Una pista!\\12Cambia el orden al\\\npulsar botones.\\12Y cambiará la\\\nforma en que se\\12abren y se cierran\\\nlas puertas.",
  ["46:5378"] = "¡Paga tus\\\ndeudas!",
  ["46:5391"] = "¡Misericordia!",
  ["46:5399"] = "¡Robar y vender!\\\n¡La base de todo\\11acto criminal!",
  ["46:53c5"] = "Abandonaron este\\\nproyecto antes\\11de terminarlo.\\12Estoy buscando\\\nrestos.",
  ["46:5416"] = "¡Por encima!",
  ["46:5425"] = "¿Al ALMACÉN\\\nSUBTERRÁNEO?\\12¿Para qué quieres\\\nir ahí?\\12Ahí abajo no\\\nhay nada.",
  ["46:547c"] = "¡Qué me importa si\\\nte has perdido!\\12Apareciste aquí,\\\n¡eres sólo una\\11víctima!",
  ["46:54c6"] = "¡Seguro! Te crees\\\ngenial, ¿verdad?",
  ["46:54e9"] = "Debes de tener\\\nhielo en las venas\\12para enfrentarte\\\nal TEAM ROCKET.",
  ["46:551e"] = "Viene marcado\\\ncomo BOTÓN 1.",
  ["46:5535"] = "¿Estás perdido?\\\nNo, es imposible.\\12No pareces\\\nasustado.\\12¡Te daré algo\\\nque te\\11asustará!",
  ["46:55a0"] = "¿Cómo ha sido?",
  ["46:55b0"] = "¡Ve a donde\\\nquieras! ¡Lárgate!\\11¡No me importa!",
  ["46:55e1"] = "Está APAGADO.\\\n¿ENCENDERLO?",
  ["46:55f7"] = "Está ENCENDIDO.\\\n¿APAGARLO?",
  ["46:560d"] = "Viene marcado\\\ncomo BOTÓN 2.",
  ["46:5624"] = "Viene marcado\\\ncomo BOTÓN 3.",
  ["46:563b"] = "Viene marcado\\\ncomo EMERGENCIA.",
  ["46:5795"] = "¡Eh, chico! ¡Estás\\\ninterrumpiéndonos!\\12¡Tenemos por\\\ncostumbre trabajar\\12sin que nadie\\\nnos vea!",
  ["46:57f7"] = "Pierdo las ganas\\\nde trabajar si hay\\11alguien mirando.\\12¡Venga, chaval,\\\nfuera de aquí!",
  ["46:5840"] = "¡Oohah! ¡Oohah!\\12Hay cosas tiradas\\\npor el suelo.\\12¡Recógelas si\\\nquieres!",
  ["46:5886"] = "MACHOKE: ¡Machok!",
  ["46:59b3"] = "¿Cómo has llegado\\\nhasta aquí?\\12Supongo que no\\\npudieron evitarlo.\\11¡Acabaré contigo!",
  ["46:59fd"] = "Acabó conmigo…",
  ["46:5a11"] = "El TEAM ROCKET\\\nseguirá esperando\\12el regreso de\\\nGIOVANNI.\\12Haremos lo que\\\nsea necesario.",
  ["46:5a70"] = "¡No vas a ir\\\nmás lejos!\\12¡Soy implacable\\\ncon mis enemigos\\12y con cualquier\\\nmocoso!",
  ["46:5abf"] = "¡Maldición!",
  ["46:5aca"] = "He perdido…\\12¡Perdóname,\\\nGIOVANNI!",
  ["46:5af0"] = "¡Ji, ji, ji!\\\n¡Te recuerdo!\\12¡Me diste bien\\\nen la guarida!",
  ["46:5b34"] = "¡Ji, ji, ji!\\\n¿Así funcionas?",
  ["46:5b57"] = "¡Ji, ji, ji!\\\n¡Vaya combate!\\11¡No te olvidaré!",
  ["46:5b8f"] = "DIRECTOR: ¿Quién?\\\n¿Qué? ¿Has venido\\11a rescatarme?\\12¡Gracias!\\12La TORRE de RADIO.\\12¿Qué está pasando\\\nahí dentro?\\12¿Invadida por el\\\nTEAM ROCKET?\\12Mira. Toma esta\\\nLLAVE MAGNÉTICA.",
  ["46:5c24"] = "DIRECTOR: Úsala\\\npara abrir las\\11puertas de la P2.",
  ["46:5c56"] = "Te ruego que\\\nme ayudes.\\12¡Quién sabe lo\\\nque harían si se\\12apoderaran de la\\\nemisora!\\12¡Podrían hasta\\\ncontrolar a los\\12POKéMON usando una\\\nseñal especial!\\12Sólo tú puedes\\\nayudarme.\\12Salva la TORRE\\\nde RADIO…\\12¡Y a todos los\\\nPOKéMON del mundo!",
  ["46:5f3d"] = "¡Hola!\\12¡Soy el REY\\\ndel KARATE!\\12¡Me entreno solo\\\nen la oscuridad!\\12¡Tú!\\\n¡Lucha conmigo!\\12¡Uaaarggh!",
  ["46:5f99"] = "¡Aaaargg!\\\n¡He perdido!",
  ["46:5fb0"] = "He… perdido…\\12Tendré que seguir\\\nentrenándome…\\12Pero una derrota\\\nes una derrota.\\12Como prueba de tu\\\nvictoria, te voy\\12a dar un raro\\\nPOKéMON de lucha.",
  ["46:6045"] = "{PLAYER} recibió\\\na TYROGUE.",
  ["46:605a"] = "TYROGUE es del\\\ntipo lucha.\\12Evoluciona en\\\nun POKéMON\\11más fuerte.\\12Sigue así.\\\nYo también seguiré\\11entrenándome.\\12¡Adiós!",
  ["46:60cf"] = "¡No tienes sitio\\\nen tu equipo!",
  ["46:61cc"] = "La piedra cayó\\\npor el agujero.",
  ["46:6267"] = "Está empotrado\\\nen el hielo.",
  ["47:41c8"] = "¡Gyaaas!",
  ["47:4292"] = "…\\\n…",
  ["47:4297"] = "…",
  ["47:429a"] = "…\\\n…",
  ["47:438b"] = "¡Uauu! ¡Me has\\\nasustado!\\12Tenía puestas las\\\nGAFAS DE SOL y\\12no me di cuenta\\\nde tu presencia.\\12¿Que qué estoy\\\nhaciendo aquí?\\12No te preocupes\\\npor eso.\\12Te daré unas GAFAS\\\nDE SOL si olvidas\\12que me has\\\nvisto, ¿vale?",
  ["47:4458"] = "Las GAFAS DE SOL\\\naumentan el poder\\12de los movimientos\\\nde tipo siniestro.",
  ["47:459c"] = "DÉBORA: Muy bien.\\\nReconozco tu\\12verdadero poder.\\\nToma esta MEDALLA.",
  ["47:45e1"] = "{PLAYER} recibió\\\nla MEDALLA DRAGÓN.",
  ["47:45fa"] = "La MEDALLA DRAGÓN\\\npermitirá que tus\\12POKéMON usen el\\\nmovimiento para\\11subir cascadas.\\12Y los POKéMON\\\nte reconocerán\\12como entrenador y\\\nobedecerán todas\\12tus órdenes sin\\\nrechistar.\\12Además, te voy\\\na dar esta MT.",
  ["47:46d6"] = "Esta MT contiene\\\nDRAGOALIENTO.\\12No, no tiene\\\nnada que ver\\11con mi aliento.\\12Si no la quieres,\\\nno es necesario\\11que la aceptes.",
  ["47:4754"] = "Así que has\\\nconseguido todas\\11las MEDALLAS.\\12Ahora debes\\\ndirigirte a la\\12LIGA POKéMON\\\nde MESETA AÑIL.\\12¿Sabes cómo llegar\\\nhasta allí?\\12Desde aquí, ve a\\\nPUEBLO PRIMAVERA.\\12Luego haz SURF\\\nhacia el Este.\\11No será fácil.\\12¡Ni se te ocurra\\\nperder en la LIGA\\11POKéMON!\\12Si pierdes, ¡me\\\nsentiré aún peor\\12por haber perdido\\\ncontra ti!",
  ["47:4881"] = "SANTUARIO DRAGÓN\\12Erigido en honor\\\nde los POKéMON\\12dragón de la\\\nGUARIDA DRAGÓN",
  ["47:48d6"] = "…\\\n¿Qué? ¿{PLAYER}?\\12No, no lucharé\\\ncontra ti…\\12Mis POKéMON no\\\npueden ganarte.\\12Y ahora no puedo\\\npresionarles.\\12La disciplina es\\\nclave para ser el\\12mejor entrenador\\\nPOKéMON.",
  ["47:4980"] = "…\\12¡Vaya…!\\12Aprende a no\\\ncruzarte en\\11mi camino.",
  ["47:49a6"] = "¡{PLAYER} encontró\\\n{STRBUF}!",
  ["47:49b8"] = "Pero {PLAYER} no\\\npuede llevar\\11más cosas.",
  ["48:4101"] = "¡Uau! ¡Tu POKéGEAR\\\nes impresionante!\\12¿Te la ha dado\\\ntu madre?",
  ["48:413e"] = "¡Espera, {PLAYER}!",
  ["48:4148"] = "¿Qué crees que\\\nestás haciendo?",
  ["48:4168"] = "¡Es peligroso\\\nsalir sin\\11un POKéMON!\\12De camino hacia la\\\nsiguiente ciudad\\12te encontrarás\\\nPOKéMON salvajes.",
  ["48:41ce"] = "¡Oh, tu POKéMON es\\\nadorable! ¡Ojalá\\11tuviera yo uno!",
  ["48:41fc"] = "¡Hola, {PLAYER}!\\\n¿Te vas otra vez?\\12Deberías decirle\\\na tu madre que\\11te vas.",
  ["48:4240"] = "Llama a tu madre\\\ncon la POKéGEAR\\12y cuéntale cómo\\\nte va.",
  ["48:427e"] = "¡Hola, {PLAYER}!\\12Dicen que el PROF.\\\nELM ha descubierto\\11nuevos POKéMON.",
  ["48:42b0"] = "……\\12Así que éste es el\\\nfamoso LABORATORIO\\11POKéMON de ELM…",
  ["48:42d7"] = "¿Qué estás\\\nmirando?",
  ["48:42f2"] = "PUEBLO PRIMAVERA\\12El pueblo donde\\\nsoplan vientos de\\11un nuevo amanecer",
  ["48:4332"] = "CASA DE {PLAYER}",
  ["48:433c"] = "LABORATORIO DE ELM",
  ["48:434a"] = "CASA DE ELM",
  ["48:45ae"] = "Eres un entrenador\\\nnovato, ¿verdad?\\11¡Estoy seguro!\\12¡Está bien! ¡Todo\\\nel mundo es novato\\11alguna vez!\\12Si quieres, te\\\npuedo enseñar\\11algunas cosas.",
  ["48:463a"] = "¡De acuerdo!\\\n¡Sígueme!",
  ["48:4650"] = "Esto es un\\\nCENTRO POKéMON.\\12Aquí curan a\\\ntus POKéMON.\\12Vas a necesitar\\\nmucho de ellos,\\12así que mejor\\\nconocerlos.",
  ["48:46cf"] = "Esto es una TIENDA\\\nPOKéMON.\\12Hay POKé BALL para\\\ncapturar POKéMON\\12salvajes y otras\\\nmuchas cosas.",
  ["48:4724"] = "La RUTA 30 está\\\npor aquí.\\12En ella luchan\\\nlos entrenadores\\12con sus queridos\\\nPOKéMON.",
  ["48:4772"] = "Como puedes ver,\\\nesto es el mar.\\12Algunos POKéMON\\\nsólo viven en\\11el agua.",
  ["48:47b7"] = "Y…\\12¡Ésta es mi casa!\\\nGracias por\\11acompañarme.\\12Déjame darte\\\nun regalito.",
  ["48:4803"] = "¡Ahora el POKéGEAR\\\nde {PLAYER}\\11tiene un MAPA!",
  ["48:481c"] = "El POKéGEAR será\\\nmás útil cuando\\11añadas TARJETAS.\\12¡Mucha suerte\\\nen tu aventura!",
  ["48:486a"] = "¡Oh…! Me\\\ngusta hacerlo…\\12Vale. Ven a verme\\\ncuando quieras.",
  ["48:48ad"] = "¿Qué…?\\12¿Te han dado\\\nun POKéMON\\11en el LABORATORIO?\\12¡Qué desperdicio!\\\n¡Eres tan inútil!\\12…\\12¿No entiendes\\\nlo que digo?\\12Pues yo también\\\ntengo un buen\\12POKéMON. ¡Te\\\nlo demostraré!",
  ["48:4942"] = "¿Estás contento\\\nde haber ganado?",
  ["48:4961"] = "…\\12¿Mi nombre?\\12Voy a ser el\\\nmejor entrenador\\12POKéMON del\\\nmundo.",
  ["48:49a5"] = "¡Vaya pérdida\\\nde tiempo!",
  ["48:49c7"] = "…\\12¿Mi nombre?\\12Voy a ser el\\\nmejor entrenador\\12POKéMON del\\\nmundo.",
  ["48:4a0b"] = "¿Has hablado con\\\nel anciano que\\12está cerca del\\\nCENTRO POKéMON?\\12Te dará un MAPA\\\nde JOHTO para tu\\11POKéGEAR.",
  ["48:4a63"] = "Cuando vas con los\\\nPOKéMON, cualquier\\11sitio está bien.",
  ["48:4a91"] = "La casa del SR.\\\nPOKéMON está\\11más adelante.",
  ["48:4abc"] = "He luchado contra\\\nlos entrenadores\\11del camino.\\12Mis POKéMON han\\\nperdido. ¡Están\\12fatal! Los llevaré\\\nal CENTRO POKéMON.",
  ["48:4b21"] = "Atrapé un POKéMON\\\ncon un objeto.\\12Creo que es\\\nAGUA MÍSTICA.\\12No lo necesito,\\\n¿lo quieres?",
  ["48:4b7c"] = "Pues yo me\\\nvoy a pescar.",
  ["48:4b9b"] = "CIUDAD CEREZO\\12La ciudad de las\\\nflores bonitas y\\11fragantes",
  ["48:4bd0"] = "CASA DEL GUÍA",
  ["48:4d29"] = "¡Hola! ¿Eres un\\\nentrenador? ¿Has\\12ganado al LÍDER\\\ndel GIMNASIO?",
  ["48:4d62"] = "¡Oh la la!\\\n¡Muy bien!",
  ["48:4d81"] = "¿Es verdad? ¡Pues\\\ntú estudiarás!\\11¡Sígueme!",
  ["48:4daf"] = "El profesor soy\\\nyo. ¡Bien está\\11que aquí estudies!",
  ["48:4ddf"] = "Dicen que en la\\\nTORRE BELLSPROUT\\11hay fantasmas.\\12Y dicen que los\\\nPOKéMON normales\\12no afectan\\\na los fantasmas.",
  ["48:4e49"] = "¿Eres entrenador\\\nPOKéMON?\\12¡Si ganas a este\\\nLÍDER de GIMNASIO,\\12estarás en el\\\ncamino del éxito!",
  ["48:4ea5"] = "¡PEGASO, del\\\nGIMNASIO POKéMON\\12de CIUDAD MALVA,\\\nes magnífico!\\12Heredó el\\\ngimnasio de su\\12padre y ha hecho\\\nun gran trabajo.",
  ["48:4f1b"] = "¡He visto un árbol\\\nque se mueve!\\12¡Si lo tocas,\\\nse retuerce y\\11baila! ¡Es genial!",
  ["48:4f68"] = "CIUDAD MALVA\\12La ciudad de los\\\naromas nostálgicos",
  ["48:4f92"] = "LÍDER DEL GIMNASIO\\\nPOKéMON DE CIUDAD\\11MALVA: PEGASO\\12El elegante\\\nmaestro de los\\11POKéMON voladores",
  ["48:4fda"] = "TORRE BELLSPROUT\\12Vive la vida\\\nPOKéMON",
  ["48:5003"] = "ACADEMIA POKéMON\\\nDE PRIMO",
  ["48:51e7"] = "Dime una\\\ncosa…\\12¿Es cierto que\\\nel TEAM ROCKET\\11ha vuelto?\\12¿Qué? ¿Los has\\\nderrotado? ¡Anda!\\11¡No me mientas!\\12¿Bromeas?\\\nPues a ver lo\\11bueno que eres.",
  ["48:5280"] = "¡Vaya!\\\n¡Inútiles POKéMON!\\12¡Escúchame! ¡Has\\\nganado porque\\12mis POKéMON\\\neran débiles!",
  ["48:52cd"] = "Odio a los\\\ndébiles.\\12Ya sean POKéMON\\\no entrenadores. Da\\11igual quién o qué.\\12Seré fuerte\\\ny acabaré con los\\11enclenques.\\12Eso también va por\\\nel TEAM ROCKET.\\12Son fuertes cuando\\\nestán en grupo,\\12pero si están\\\nsolos, son unos\\11cobardes.\\12¡Cuánto les odio!\\12¡Fuera de mi\\\nvista! ¡Eres tan\\12insignificante\\\ncomo el resto!",
  ["48:53f5"] = "¡Ja! Sabía\\\nque mentías.",
  ["48:5415"] = "Entrar ahí es muy\\\npeligroso, por eso\\11estoy de guardia.\\12¿A que soy un\\\nbuen samaritano?",
  ["48:5461"] = "¿Sabes algo sobre\\\nlas COLASLOWPOKE?\\12¡Dicen que son\\\nmuy sabrosas!\\12¿Contento de que\\\nte lo haya dicho?",
  ["48:54b5"] = "Los SLOWPOKE han\\\ndesaparecido del\\11pueblo…\\12Dicen que venden\\\nsus COLAS en algún\\11lugar.",
  ["48:550d"] = "Los SLOWPOKE\\\nhan vuelto.\\12Conociéndolos,\\\nquizá han estado\\12remoloneando en\\\nalgún lugar.",
  ["48:5568"] = "¿Viste a CÉSAR\\\npara que te diera\\11algunas BALL?\\12Muchas personas\\\nlo hacen.",
  ["48:55b4"] = "Ataja por PUEBLO\\\nAZALEA y llegarás\\11al ENCINAR.\\12Pero estos\\\narbolitos te\\11impiden pasar.\\12Los POKéMON del\\\nCARBONERO pueden\\11CORTAR árboles.",
  ["48:564a"] = "SLOWPOKE: …\\12…… …… ……",
  ["48:565d"] = "(bostezo)……",
  ["48:5679"] = "PUEBLO AZALEA\\\nDonde la gente y\\12los POKéMON viven\\\nen feliz armonía",
  ["48:56b2"] = "CASA DE CÉSAR",
  ["48:56c0"] = "LÍDER DEL GIMNASIO\\\nPOKéMON DE PUEBLO\\11AZALEA: ANTÓN\\12La enciclopedia\\\nandante de los\\11POKéMON bicho",
  ["48:5706"] = "POZO SLOWPOKE\\12Conocido también\\\ncomo POZO LLUVIA.\\12Los nativos creen\\\nque el bostezo de\\12SLOWPOKE invoca\\\nla lluvia.\\12Hace 400 años\\\nun bostezo de\\12SLOWPOKE acabó\\\ncon una sequía.",
  ["48:57ac"] = "CASA DEL CARBONERO",
  ["48:57bb"] = "EL ENCINAR\\12Entra por la\\\npuerta",
  ["48:5936"] = "¿Has cruzado el\\\nmar para llegar\\12hasta aquí? ¡Habrá\\\nsido duro!\\12Todo sería mucho\\\nmás fácil si tus\\12POKéMON supieran\\\nVUELO…",
  ["48:59a8"] = "Pero no puedes\\\nusar VUELO sin la\\12MEDALLA de esta\\\nciudad.\\12Si vences al LÍDER\\\nde este GIMNASIO,\\11ven a verme.\\12Te daré un\\\nbonito regalo.",
  ["48:5a28"] = "¡Es la MEDALLA de\\\nCIUDAD ORQUÍDEA!\\12¡Toma esta\\\nMO!",
  ["48:5a62"] = "Enseña VUELO a\\\ntus POKéMON.\\12En un instante\\\npodrás VOLAR a\\12cualquier lugar al\\\nque ya hayas ido.",
  ["48:5abc"] = "Mi marido perdió\\\ncontra ti. Debería\\11entrenarse más.\\12Menos mal, porque\\\nya estaba\\11engordando.",
  ["48:5b24"] = "Si usas VUELO,\\\npodrás volver a\\12CIUDAD OLIVO\\\nenseguida.",
  ["48:5b5e"] = "Las piedras del\\\nnorte del pueblo\\11se pueden romper.\\12Quizá escondan\\\nalgo.\\12Tus POKéMON pueden\\\nusar el GOLPE ROCA\\11para romperlas.",
  ["48:5bd9"] = "ANÍBAL, el LÍDER\\\ndel GIMNASIO,\\12pelea con sus\\\nPOKéMON de lucha.",
  ["48:5c78"] = "CIUDAD ORQUÍDEA\\12Un puerto rodeado\\\nde agitadas aguas",
  ["48:5ca7"] = "LÍDER DEL GIMNASIO\\\nPOKéMON DE CIUDAD\\12ORQUÍDEA: ANÍBAL\\12Sus puños\\\nhablan por él",
  ["48:5cee"] = "500 años de\\\ntradición\\12FARMACIA DE\\\nCIUDAD ORQUÍDEA\\12Aceptamos\\\npedidos",
  ["48:5d3d"] = "ESTUD. FOTOGRÁFICO\\\nDE CIUDAD ORQUÍDEA\\12¡Hazte una foto\\\nde recuerdo!",
  ["48:5ec6"] = "Han construido una\\\nTORRE RADIO nueva\\12que sustituye a\\\nla antigua.",
  ["48:5f06"] = "Sé que hay una\\\nnueva TIENDA de\\12BICIS, pero no\\\nla encuentro.",
  ["48:5f43"] = "¿Ese hombre de\\\nnegro se ha\\12vestido como uno\\\ndel TEAM ROCKET?\\11¡Qué tonto!",
  ["48:5f8a"] = "¿Pertenecía ese\\\nhombre de negro\\12al TEAM ROCKET?\\\n¡Es increíble!",
  ["48:5fd0"] = "La TORRE de RADIO\\\nde CIUDAD TRIGAL\\11es muy importante.\\12Ahora están en\\\nuna campaña\\11promocional.\\12Modificarán tu\\\nPOKéGEAR para\\12que te sirva\\\ntambién de radio.",
  ["48:6071"] = "¡Oh, tu POKéGEAR\\\nsirve de radio!",
  ["48:6093"] = "¡Eh, eh, eh…!\\12Me he metido en\\\nlíos por jugar en\\12el sótano del\\\nCENTRO COMERCIAL.",
  ["48:60e0"] = "El hombre de esa\\\ncasa evalúa los\\12nombres de\\\ntus POKéMON.\\12Y puede renombrar\\\na tus POKéMON.",
  ["48:612c"] = "¡Uau! Esta ciudad\\\nes muy grande.\\12No sé dónde\\\nestá nada.",
  ["48:616a"] = "Así que ésta es la\\\nTORRE de RADIO…",
  ["48:6187"] = "¿Qué quieres,\\\npesado? ¡Fuera!",
  ["48:61ab"] = "¡Fuera de mi\\\ncamino! ¡Pesado!",
  ["48:61ca"] = "Asaltemos la\\\nTORRE de RADIO…\\12¿Qué? ¡Y a ti\\\nqué te importa!",
  ["48:6207"] = "¿Los POKéMON?\\\n¡Sólo son\\12herramientas para\\\nganar dinero!",
  ["48:623f"] = "Nuestro sueño se\\\ncumplirá pronto…\\12Ha sido una lucha\\\ntan larga…",
  ["48:627c"] = "¡Eh, mocoso! ¡Tú\\\nno eres de aquí!\\11¡Lárgate!",
  ["48:62a8"] = "¡Prueba el\\\nverdadero terror\\11del TEAM ROCKET!",
  ["48:62d4"] = "ESTACIÓN DE\\\nCIUDAD TRIGAL",
  ["48:62ec"] = "TORRE DE RADIO\\\nDE CIUDAD TRIGAL",
  ["48:6308"] = "¡Una gran gama de\\\nartículos POKéMON!\\12CENTRO COMERCIAL\\\nDE CIUDAD TRIGAL",
  ["48:6341"] = "LÍDER DEL GIMNASIO\\\nPOKéMON DE CIUDAD\\11TRIGAL: BLANCA\\12¡La increíble y\\\nbella señorita!",
  ["48:6386"] = "CIUDAD TRIGAL\\12La alegre ciudad\\\nde rico encanto",
  ["48:63b8"] = "¡El mundo es un\\\ncamino de bicis!\\11TIENDA DE BICIS",
  ["48:63de"] = "¡Tu zona de juego!\\12CASINO DE\\\nCIUDAD TRIGAL",
  ["48:640b"] = "INSPECTOR DE MOTES\\12Evalúa los motes\\\nde tus POKéMON",
  ["48:6435"] = "ENTRADA\\\nSUBTERRÁNEA",
  ["48:644b"] = "ENTRADA\\\nSUBTERRÁNEA",
  ["49:40d7"] = "…\\12¿Tú otra vez?\\12¿Y a mí qué me\\\nimporta? No me\\12asustan los\\\ncanijos como tú.\\12Y hablando de\\\ndebiluchos, la\\12LÍDER del GIMNASIO\\\nno está aquí.\\12Se supone que está\\\ncuidando a un\\12POKéMON enfermo\\\nen el FARO.\\12¡Buuuu! ¡Fuera\\\nlos POKéMON\\11enfermos!\\12¡Los POKéMON que\\\nno pueden luchar\\11son unos inútiles!\\12¿Por qué no vas\\\na entrenar al\\11FARO?\\12¿Quién sabe?\\\n¡A lo mejor\\11te refuerza!",
  ["49:4235"] = "Las calles oscuras\\\nson muy peligrosas\\11por la noche.\\12Pero si es noche\\\ncerrada, ¡el mar\\12es aún más\\\ntraicionero!\\12Si no les guiara\\\nla luz del FARO,\\12los barcos no\\\npodrían navegar.",
  ["49:42e1"] = "Eso que tienes\\\nes un POKéGEAR,\\12¿verdad? ¡Uauu!\\\n¡Es genial!",
  ["49:431e"] = "¡Uauu, tienes una\\\nPOKéDEX! Es\\12realmente\\\nincreíble.",
  ["49:434e"] = "¡Hola, chaval!\\\n¡Me gusta el mar!\\12¡Canta conmigo!\\\n¡Yo jo!\\11¡Yo jo…!",
  ["49:439a"] = "CIUDAD OLIVO\\12El puerto a\\\ntierras lejanas",
  ["49:43ca"] = "PUERTO OLIVO\\\nMUELLE DEL FERRY",
  ["49:43e7"] = "LÍDER DEL GIMNASIO\\\nPOKéMON DE CIUDAD\\11OLIVO: YASMINA\\12La chica\\\nde acero",
  ["49:442a"] = "FARO DE OLIVO\\\nTambién conocido\\12como el FARO\\\nBRILLANTE.",
  ["49:4604"] = "En CIUDAD IRIS\\\nhabía dos torres:\\12una en el Este y\\\notra en el Oeste.",
  ["49:4646"] = "¡Ah, chaval!\\\n¿Has aprendido a\\12bailar como las\\\nCHICAS KIMONO?\\12Si vas a su\\\nTEATRO de DANZA,\\12un anciano raro te\\\ndará algo bonito.\\11Eso me han dicho.",
  ["49:46de"] = "Voy a practicar en\\\nel TEATRO de\\12DANZA. ¿Vienes\\\nconmigo?",
  ["49:471d"] = "Esa torre era\\\nmucho más alta,\\12pero se quemó\\\nen un incendio.",
  ["49:4761"] = "Tres POKéMON\\\nhuyeron en tres\\12direcciones.\\\n¿Qué eran?",
  ["49:47a4"] = "He oído un rumor\\\nsobre el FARO\\11OLIVO.\\12El POKéMON que\\\nusan como luz\\12ha caído enfermo.\\\nParece que tienen\\11problemas.",
  ["49:481d"] = "El POKéMON de\\\nFARO OLIVO se\\11ha curado.\\12Los barcos pueden\\\nvolver a navegar\\11seguros de noche.",
  ["49:487e"] = "Los POKéMON están\\\ncausando estragos\\12en el LAGO DE\\\nLA FURIA. Me\\11encantaría verlo.",
  ["49:48c3"] = "CIUDAD IRIS\\\nUna ciudad donde\\12conviven el pasado\\\ny el presente",
  ["49:4905"] = "TORRE HOJALATA\\12Aquí duerme un\\\nPOKéMON\\11legendario.",
  ["49:493a"] = "LÍDER DEL GIMNASIO\\\nPOKéMON DE CIUDAD\\11IRIS: MORTI\\12El místico adivino\\\ndel futuro",
  ["49:497e"] = "TEATRO DE DANZA\\\nDE CIUDAD IRIS",
  ["49:4996"] = "TORRE QUEMADA\\12Destruida por\\\nun misterioso\\11incendio.\\12¡Atención!\\\n¡Peligro!",
  ["49:4b65"] = "¡Hola, hijito! Ya\\\nveo que eres nuevo\\11en PUEBLO CAOBA.\\12¡Ya que eres nuevo\\\ndeberías probar\\12el delicioso\\\nCARAMELO FURIA!\\12¡Puede ser tuyo\\\npor sólo 300¥!\\11¿Quieres uno?",
  ["49:4c03"] = "¡Bien! ¡Saboréalo!",
  ["49:4c14"] = "No tienes\\\nbastante dinero.",
  ["49:4c31"] = "¡Oh, de acuerdo…!",
  ["49:4c41"] = "No tienes\\\nespacio para esto.",
  ["49:4c5f"] = "CARAMELOS FURIA\\\nagotados.\\12Estoy haciendo las\\\nmaletas. No me\\11molestes, hijito.",
  ["49:4ca2"] = "¿Vas al LAGO a ver\\\na los violentos\\11GYARADOS?",
  ["49:4cda"] = "MAGIKARP ha\\\nvuelto al LAGO\\11DE LA FURIA.\\12Son buenas\\\nnoticias para\\11los pescadores.",
  ["49:4d33"] = "Has venido de muy\\\nlejos. Tómate\\12tiempo para ver\\\nel paisaje.\\12Deberías ir hacia\\\nel Norte y ver lo\\12que pasa en el\\\nLAGO DE LA FURIA.",
  ["49:4daf"] = "Visita la tienda\\\nde la Abuela. Hay\\12cosas que sólo\\\nella tiene.",
  ["49:4deb"] = "PUEBLO CAOBA\\12Bienvenido al\\\nhogar de los Ninja",
  ["49:4e1b"] = "¡Si visitas PUEBLO\\\nCAOBA, prueba\\11un CARAMELO FURIA!",
  ["49:4e4e"] = "LÍDER DEL GIMNASIO\\\nPOKéMON DE PUEBLO\\11CAOBA: FREDO\\12El maestro del\\\ncrudo invierno",
  ["49:5063"] = "Este LAGO\\\nestá lleno de\\11GYARADOS…\\12Así que los\\\nMAGIKARP\\12deben haber\\\nevolucionado.",
  ["49:50c0"] = "¿Has venido hasta\\\naquí por los\\11rumores?\\12¿Eres {PLAYER}?\\\nYo soy LANCE, un\\11entrenador más.\\12He oído rumores\\\ny he venido a\\11investigar…\\12Te he visto\\\nluchar, {PLAYER}.\\12Creo que como\\\nentrenador eres\\11muy bueno.\\12Si no te importa,\\\n¿quieres ayudarme\\11a investigar?",
  ["49:51d2"] = "LANCE: ¡Excelente!\\12Parece que los\\\nMAGIKARP del LAGO\\12se ven obligados a\\\nevolucionar.\\12La razón es una\\\nmisteriosa emisión\\12de radio desde\\\nPUEBLO CAOBA.\\12Te esperaré\\\nallí, {PLAYER}.",
  ["49:527d"] = "¡Oh…! Si\\\ncambias de opinión\\12agradecería tu\\\nayuda.",
  ["49:52b1"] = "LANCE: ¿Qué?\\\n¿Me vas a ayudar?",
  ["49:52d7"] = "GYARADOS: ¡Gyaraa!",
  ["49:52eb"] = "{PLAYER} obtuvo\\\nuna ESCAMA ROJA.",
  ["49:5304"] = "¡Los GYARADOS\\\nestán enfadados!\\12¡Mal presagio!",
  ["49:532d"] = "¡Ajaa! ¡Los\\\nMAGIKARP pican!",
  ["49:5350"] = "Dicen que este\\\nlago fue obra\\12de violentos\\\nGYARADOS.\\12Me pregunto si eso\\\nestará relacionado\\12con su actual\\\nrebelión.",
  ["49:53c7"] = "¿Me han engañado\\\nmis ojos? He visto\\12un GYARADOS rojo\\\nen el LAGO…\\12Yo pensaba que\\\nlos GYARADOS eran\\11siempre azules.",
  ["49:542e"] = "¡Déjame luchar con\\\nel POKéMON que\\11acabo de atrapar!",
  ["49:545a"] = "Puede que sea un\\\npescador experto,\\12pero soy un mal\\\nentrenador…",
  ["49:549b"] = "¡No perderé como\\\npescador! Me paso\\12el día capturando\\\nPOKéMON.",
  ["49:54cc"] = "Haga lo que haga,\\\nsiempre capturo\\12los mismos\\\nPOKéMON…",
  ["49:5503"] = "Mi caña se ha\\\nenredado…",
  ["49:551d"] = "¿Por qué no atrapo\\\nbuenos POKéMON?",
  ["49:553e"] = "Si un entrenador\\\nse encuentra con\\12otro entrenador,\\\ndebe desafiarle.\\12Ése es nuestro\\\ndestino.",
  ["49:5594"] = "¡Uauu…!\\\nBuen combate.",
  ["49:55a8"] = "Los POKéMON y su\\\nentrenador se\\12hacen más fuertes\\\ncuanto más luchan.",
  ["49:55eb"] = "¿Qué ocurrió con\\\nel GYARADOS rojo?\\12¿Se ha ido?\\12¡Maldición! ¿He\\\nvenido para nada?\\12Ya sé.\\\n¡Luchemos!",
  ["49:5651"] = "¡Muy bien!",
  ["49:565e"] = "Pensándolo bien,\\\ncreo que vi un\\11BUTTERFREE rosa.",
  ["49:5690"] = "MIGUEL: Hola,\\\n¿qué tal estás?\\12Hoy es miércoles\\\ny yo soy MIGUEL,\\12por lo de\\\nmiércoles.",
  ["49:56e9"] = "Encantado de\\\nconocerte. Toma\\11un recuerdo.",
  ["49:5717"] = "MIGUEL: CINTURÓN\\\nNEGRO potencia los\\11ataques de lucha.",
  ["49:5750"] = "MIGUEL: Como me\\\nhas encontrado,\\12habrás visto a\\\nmis hermanos.\\12¿O es que has\\\ntenido suerte?",
  ["49:57b5"] = "MIGUEL: Hoy no\\\nes miércoles.\\11¡Qué pena!",
  ["49:57e3"] = "LAGO DE LA FURIA,\\\nconocido como\\11LAGO DE GYARADOS.",
  ["49:580f"] = "CASA DEL GURÚ\\\nPESCADOR",
  ["49:5994"] = "Lo siento.\\12Nuestro LÍDER de\\\nGIMNASIO está\\12entrenando en una\\\ncueva aquí detrás.\\12No tengo ni idea\\\nde cuándo volverá.",
  ["49:5a01"] = "Te espera el LÍDER\\\ndel GIMNASIO.\\12Pero es imposible\\\nque le gane un\\12entrenador del\\\nmontón.",
  ["49:5a6b"] = "¿Venciste al LÍDER\\\ndel GIMNASIO? ¡Es\\11increíble!\\12Con tu poder,\\\nseguro que\\12triunfas en la\\\nLIGA POKéMON.",
  ["49:5ad0"] = "Aquí sólo pueden\\\nentrenar los que\\12usan dragones.\\\nVete, por favor.",
  ["49:5b0e"] = "DÉBORA, la maestra\\\nde los dragones,\\12da su permiso, así\\\nque puedes entrar.",
  ["49:5b4e"] = "¿Mi radio está\\\nrota? Sólo recibo\\11esta rara señal.",
  ["49:5b87"] = "¡Auu! ¡Voces en\\\nmi cabeza! ¿Cómo?\\12¡Estoy escuchando\\\nla radio!",
  ["49:5bc1"] = "¿Quieres que\\\ntus POKéMON\\12olviden algún\\\nmovimiento?",
  ["49:5bf5"] = "Voy a usar\\\ndragones como\\11hace DÉBORA.",
  ["49:5c1f"] = "SABINO: …\\12Es sábado…\\12Soy SABINO, por\\\nsábado…",
  ["49:5c4f"] = "Toma esto…",
  ["49:5c63"] = "SABINO: …\\12HECHIZO…\\12Mejora los\\\nmovimientos de\\11tipo fantasma.\\12Te voy a\\\nasustar…",
  ["49:5cae"] = "SABINO: …\\12Nos vemos otro\\\nsábado…\\12Pero ya no tendré\\\nmás regalos…",
  ["49:5cf8"] = "SABINO: Hoy no\\\nes sábado…",
  ["49:5d16"] = "¡Uau! ¿Has venido\\\npor la RUTA\\11HELADA?\\12¡Debes de ser un\\\nentrenador genial!",
  ["49:5d5f"] = "CIUDAD ENDRINO\\12Un tranquilo\\\nrefugio de montaña",
  ["49:5d89"] = "LÍDER DEL GIMNASIO\\\nPOKéMON DE CIUDAD\\11ENDRINO: DÉBORA\\12La gran experta en\\\nPOKéMON dragón",
  ["49:5dd1"] = "CASA DEL\\\nQUITA-MOVIMIENTOS",
  ["49:5de7"] = "HACIA LA GUARIDA\\\nDEL DRAGÓN",
  ["49:5dfb"] = "PISTAS ENTRENADOR\\12Todo POKéMON que\\\nvaya equipado con\\12una BAYA MILAGRO\\\nse curará a sí\\11mismo en combate.",
  ["49:5f27"] = "MT. PLATEADO",
  ["4a:4175"] = "Estoy haciendo\\\nlos últimos\\12preparativos para\\\nla LIGA POKéMON.",
  ["4a:41ab"] = "¡Caramba!",
  ["4a:41b7"] = "Va a ser difícil\\\nganar en la\\11LIGA.\\12Tengo que\\\nentrenar más.\\12Dicen que el ALTO\\\nMANDO es más duro\\12que los LÍDERES\\\nde GIMNASIO.",
  ["4a:4246"] = "Es en estos duros\\\ncombates donde\\11ganas más poder.",
  ["4a:4276"] = "¡La vida es\\\naún más dura!",
  ["4a:4293"] = "Para llegar a la\\\nLIGA POKéMON,\\12hay que pasar por\\\nla CALLE VICTORIA.\\12Pero la CALLE\\\nVICTORIA es dura.\\12¡No va allí\\\ncasi nadie!",
  ["4a:430b"] = "Si has llegado tan\\\nlejos, debes de\\11ser muy bueno.\\12¡Voy a dar todo\\\nlo que tengo en\\11este combate!",
  ["4a:436c"] = "¡No! ¡No puedo\\\ncreerlo!",
  ["4a:4386"] = "Como había vencido\\\na ocho LÍDERES\\12de GIMNASIO, me\\\nconfié demasiado.\\12Tendré que\\\nesforzarme más.",
  ["4a:43e5"] = "He perdido contra\\\n{RIVAL}.\\12Era realmente\\\nfuerte, pero…\\12Parecía como si\\\ntuviera que ganar\\11a toda costa.\\12Me dieron pena\\\nsus POKéMON.",
  ["4a:446e"] = "Los POKéMON no son\\\narmas de guerra.",
  ["4a:4488"] = "Los POKéMON son\\\nvaliosos amigos\\11para toda la vida.",
  ["4a:44b3"] = "¡Uau! ¡Cuántas\\\nMEDALLAS! Estoy\\11impresionado.\\12Pero no te basta\\\nsólo con\\12coleccionarlas,\\\n¿verdad?",
  ["4a:4519"] = "¡Buena batalla!",
  ["4a:4527"] = "Las personas y los\\\nPOKéMON se\\12enriquecen con la\\\nexperiencia.\\12No seas vago\\\ny conformista.",
  ["4a:4573"] = "¡Hoy me siento\\\nmuy bien!\\12¡Siento que podría\\\nvencer hasta al\\11CAMPEÓN de LIGA!",
  ["4a:45bc"] = "¡No! ¡En esta\\\nbatalla, no!",
  ["4a:45d5"] = "Como en la pesca,\\\ncon los POKéMON\\12todo está perdido\\\nsi te rindes.",
  ["4a:4613"] = "RUTA 26\\12RECEPCIÓN DE LA\\\nLIGA POKéMON",
  ["4a:486a"] = "¡Eh!",
  ["4a:4870"] = "¿Sabes lo que\\\nacabas de hacer?\\12Acabas de\\\nentrar en\\11KANTO.\\12Consulta el MAPA\\\ndel POKéGEAR.",
  ["4a:48d8"] = "Pareces muy\\\nfuerte. ¡Déjame\\11luchar contigo!",
  ["4a:4904"] = "¡Yau!",
  ["4a:490a"] = "Si continúas por\\\neste duro camino,\\12¡conocerás la\\\nverdad!\\12Lo siento, pero me\\\napetecía decir\\11algo chulo.",
  ["4a:497b"] = "¿Mmm? Eres bueno,\\\n¿verdad?",
  ["4a:4997"] = "¡Tal como pensaba!",
  ["4a:49ab"] = "Un buen entrenador\\\nsabe reconocer a\\12otros buenos\\\nentrenadores.",
  ["4a:49de"] = "No deberías\\\nsubestimar a los\\12POKéMON salvajes\\\nde esta zona.",
  ["4a:4a18"] = "¡Oh! ¡Qué\\\nfuerte eres!",
  ["4a:4a34"] = "Eres sólo un niño,\\\npero tampoco\\12se te puede\\\nsubestimar.",
  ["4a:4a72"] = "Es raro que venga\\\nalguien por aquí.\\12¿Te estás\\\nentrenando solo?",
  ["4a:4ab3"] = "¡Oh! ¡Eres\\\nmuy fuerte!",
  ["4a:4acd"] = "Estoy investigando\\\nlos POKéMON antes\\12y después de que\\\nevolucionen.\\12Los POKéMON se\\\nhacen más fuertes\\11al evolucionar.\\12Pero aprenderán\\\nnuevos movimientos\\12mucho más despacio\\\nque antes.",
  ["4a:4b54"] = "¡No digas nada!\\12Déjame adivinar lo\\\nque piensas.\\12¡Mmmmmmm…!\\12¡Listo! ¡Estás\\\nen la LIGA\\11POKéMON!",
  ["4a:4bc0"] = "¡Eres demasiado!",
  ["4a:4bd1"] = "Con tus\\\nhabilidades,\\12te irá bien\\\nen la LIGA.\\12Eso es lo que\\\npresiento.",
  ["4a:4c21"] = "¡Pío! ¡Pío!\\\n¡Píooo!",
  ["4a:4c39"] = "¡Pío!",
  ["4a:4c41"] = "Los ORNITÓLOGOS\\\nimitan el canto de\\12los pájaros para\\\ncontrolar POKéMON.",
  ["4a:4c7e"] = "CATARATAS TOHJO\\12La conexión entre\\\nKANTO y JOHTO.",
  ["4a:4d53"] = "RUTA 28",
  ["4a:4ed2"] = "Los POKéMON se\\\nesconden en la\\12hierba. Nadie sabe\\\ncuando salen…",
  ["4a:4f0a"] = "Te he visto un par\\\nde veces. ¿Cuántos\\12POKéMON has\\\natrapado?\\12¿Quieres que te\\\nenseñe a atrapar\\11POKéMON?",
  ["4a:4f78"] = "Así es como\\\nse hace.\\12Si los debilitas,\\\nlos POKéMON\\12son más fáciles\\\nde atrapar.",
  ["4a:4fc2"] = "¡Ah! ¡Muy bien!\\12Pero si quieres\\\natrapar POKéMON,\\12tendrás que\\\ncaminar mucho.",
  ["4a:500e"] = "¿Qué? ¿Quieres que\\\nte enseñe a\\11atrapar POKéMON?",
  ["4a:503f"] = "¿Cómo están tus\\\nPOKéMON?\\12Si están débiles y\\\nno pueden luchar,\\12no entres en\\\nla hierba.",
  ["4a:5097"] = "¿Ves esos setos?\\\nDa miedo\\11saltarlos.\\12Pero puedes ir a\\\nPUEBLO PRIMAVERA\\12sin pasar por\\\nla hierba.",
  ["4a:5104"] = "Quería descansar\\\nun poco, así que\\12guardé la\\\npartida.",
  ["4a:5177"] = "Estoy esperando a\\\nlos POKéMON\\12que aparecen sólo\\\npor la noche.",
  ["4a:51a7"] = "Estoy esperando a\\\nlos POKéMON\\12que aparecen sólo\\\npor la mañana.",
  ["4a:51dd"] = "MARTA: Creo que\\\nes la primera\\12vez que nos\\\nvemos.\\12Déjame que me\\\npresente. Soy\\12MARTA, por\\\nmartes.",
  ["4a:525a"] = "Como presentación,\\\npor favor, toma\\12este regalo:\\\nun LAZO ROSA.",
  ["4a:529a"] = "MARTA: ¿No\\\ncrees que es\\11adorable?\\12Fortalece los\\\nataques normales.\\12Seguro que te\\\nserá muy útil.",
  ["4a:5312"] = "MARTA: ¿Has visto\\\na LUNA, mi hermana\\11mayor?\\12¿O a mi hermano\\\npequeño, MIGUEL?\\12Soy la segunda de\\\nsiete hermanos.",
  ["4a:5384"] = "MARTA: Hoy no es\\\nmartes. ¡Qué\\11pena…!",
  ["4a:53b9"] = "RUTA 29\\12CIUDAD CEREZO -\\\nPUEBLO PRIMAVERA",
  ["4a:53e4"] = "RUTA 29\\12CIUDAD CEREZO -\\\nPUEBLO PRIMAVERA",
  ["4a:55ad"] = "¡Ve, RATTATA!\\12¡PLACAJE!",
  ["4a:55c3"] = "¿Qué? ¡Es un\\\ngran combate!\\11¡Déjame en paz!",
  ["4a:55f0"] = "Acabo de perder\\\ny estoy buscando\\11más POKéMON.\\12¡Espera! ¡Pareces\\\ndébil! ¡Venga,\\11luchemos!",
  ["4a:5649"] = "¡Vaya! No tengo\\\nmás POKéMON.",
  ["4a:566a"] = "Necesito tener\\\nmás POKéMON\\11para luchar.\\12¡Voy a atrapar\\\nunos cuantos más!",
  ["4a:56ae"] = "Eres un entrenador\\\nPOKéMON, ¿verdad?\\12¡Pues entonces\\\nluchemos!",
  ["4a:56e5"] = "¡Qué extraño!\\\n¡Creí que ganaría!",
  ["4a:5703"] = "Es muy duro llegar\\\na ser un buen\\11entrenador.\\12Tengo que luchar\\\ncontra más gente\\11para mejorar.",
  ["4a:575e"] = "¡En lugar de un\\\nPOKéMON bicho,\\12he encontrado\\\nun entrenador!",
  ["4a:5789"] = "¡Arg! ¡Eres\\\nmuy fuerte!",
  ["4a:57a2"] = "Me quedé sin\\\nPOKé BALL mientras\\11atrapaba POKéMON.\\12Debería haber\\\ncomprado más…",
  ["4a:57f0"] = "¿La casa del SR.\\\nPOKéMON? Está un\\11poco más adelante.",
  ["4a:581a"] = "¡Todo el mundo se\\\ndivierte luchando!\\12¡Tú también\\\ndeberías hacerlo!",
  ["4a:584a"] = "No soy una\\\nentrenadora.\\12Pero si miras a\\\nuno a los ojos,\\12prepárate\\\na luchar.",
  ["4a:5891"] = "RUTA 30\\12CIUDAD MALVA -\\\nCIUDAD CEREZO",
  ["4a:58ba"] = "CASA SR. POKéMON\\\n¡Todo recto!",
  ["4a:58db"] = "CASA SR. POKéMON",
  ["4a:58ec"] = "PISTAS ENTRENADOR\\12¡No robes los\\\nPOKéMON de otros!\\12¡Las POKé BALL\\\nsólo se lanzan a\\11POKéMON salvajes!",
  ["4a:5b1e"] = "CUEVA OSCURA…\\12Si los POKéMON\\\npudieran\\12iluminarla,\\\nla exploraría.",
  ["4a:5b54"] = "He atrapado un\\\nmontón de POKéMON.\\11¡Luchemos!",
  ["4a:5b87"] = "¡Auuuu…!",
  ["4a:5b90"] = "Puedes atrapar\\\nPOKéMON aunque\\12ya lleves seis\\\ncontigo.\\12Si atrapas alguno\\\nmás, será enviado\\11a la CAJA.",
  ["4a:5bf8"] = "¡Arg…! ¿Eh?\\12Hoy he caminado\\\nmucho buscando\\11POKéMON.\\12Me duelen los pies\\\ny tengo sueño…\\12Si fuera un\\\nPOKéMON salvaje,\\12sería fácil\\\natraparme…\\12¡Zzzz…!",
  ["4a:5c80"] = "Zzzz… ¿Eh?\\12¿Qué es eso? ¿Una\\\nCARTA para mí?",
  ["4a:5caf"] = "{PLAYER} entregó\\\nel POKéMON que\\11lleva la CARTA.",
  ["4a:5cd9"] = "Veamos…\\12La C. OSCURA lleva\\\na otro camino.\\12Es bueno\\\nsaberlo.\\12Gracias por\\\ntraerme esto.\\12Mi amigo es un\\\nbuen chico. ¡Tú\\12también eres\\\nincreíble!\\12¡Me gustaría\\\ndevolverte el\\11favor!\\12¡Ya sé!\\\n¡Toma esto!",
  ["4a:5dbb"] = "MT50 es PESADILLA.\\12Es un movimiento\\\nterrible que\\12reduce los PS de\\\nun rival dormido.\\12¡Ooooh…!\\\n¡Qué miedo…!\\12No me gustan las\\\npesadillas.",
  ["4a:5e46"] = "Esta CARTA no\\\nes para mí.",
  ["4a:5e5e"] = "¿Por qué es espe-\\\ncial este POKéMON?\\12No tiene ninguna\\\nCARTA.",
  ["4a:5e97"] = "¿Qué? ¿No\\\nquieres nada?",
  ["4a:5eb6"] = "Si te quito ese\\\nPOKéMON, ¿qué\\12vas a usar en los\\\ncombates?",
  ["4a:5efa"] = "He encontrado un\\\nbuen POKéMON en\\11la CUEVA OSCURA.\\12Voy a criarlo\\\npara enfrentarme\\11a PEGASO.\\12Es el líder del\\\nGIM. de C. MALVA.",
  ["4a:5f6a"] = "RUTA 31\\12CIUDAD MALVA -\\\nCIUDAD CEREZO",
  ["4a:5f93"] = "CUEVA OSCURA",
  ["4b:42a5"] = "¡Espera!\\\n¿Por qué corres?",
  ["4b:42c0"] = "{PLAYER}, ¿verdad?\\\nUn tipo con\\12gafas te estaba\\\nbuscando.\\12Compruébalo tú\\\nmismo. Te está\\12esperando en el\\\nCENTRO POKéMON.",
  ["4b:43c5"] = "¿Has ido al\\\nGIMNASIO POKéMON?\\12Allí puedes probar\\\na tus POKéMON\\11y a ti mismo.\\12¡Es un rito para\\\ntodos los\\11entrenadores!",
  ["4b:443a"] = "Tienes POKéMON\\\nmuy buenos.\\12Seguro que es por\\\nhaberlos entrenado\\12en los alrededores\\\nde CIUDAD MALVA.\\12El entrenamiento\\\nen el GIMNASIO ha\\12debido de ser de\\\ngran ayuda.\\12Toma esto como\\\nrecuerdo de\\11CIUDAD MALVA.\\12Aumenta el poder\\\nde los movimientos\\11de tipo planta.",
  ["4b:452a"] = "Tu experiencia en\\\nCIUDAD MALVA\\12debería ayudarte\\\nen tu viaje.",
  ["4b:456e"] = "¿Te gustaría tener\\\nesta sabrosa y\\12nutritiva\\\nCOLASLOWPOKE?\\12¡Sólo te costará\\\n1.000.000¥!\\12¡Te gustará!",
  ["4b:45e4"] = "¡Vaya! Pensaba que\\\nlos niños de hoy\\12en día estaban\\\nforrados…",
  ["4b:4611"] = "¿No la quieres?\\\nPues lárgate.",
  ["4b:4636"] = "¡Vaya!\\12¡Se me escapó ese\\\npez por tu culpa!",
  ["4b:4659"] = "¡Splash!",
  ["4b:4663"] = "Paciencia… La\\\nbase de la pesca\\12y de los POKéMON\\\nes la misma.",
  ["4b:46a4"] = "Soy un buen\\\npescador, pero\\12como entrenador\\\nsoy aún mejor.",
  ["4b:46d3"] = "Intenté acelerar\\\nlas cosas…",
  ["4b:46f1"] = "¡Pescar es una\\\npasión eterna y\\12los POKéMON son\\\namigos eternos!",
  ["4b:4863"] = "¿Mi POKéMON?\\\n¡Recién pescado!",
  ["4b:487d"] = "¡Splash!",
  ["4b:4886"] = "Los POKéMON\\\nrecién atrapados\\12no son comparables\\\ncon los criados.",
  ["4b:48c2"] = "No te había\\\nvisto antes.\\12¿Te crees\\\nmuy duro?",
  ["4b:4907"] = "¡Eres fuerte!",
  ["4b:4916"] = "Intentaré ser el\\\nmejor con mis\\11favoritos.\\12No uso los mismos\\\nPOKéMON que\\11todo el mundo.",
  ["4b:497c"] = "¡He encontrado\\\nPOKéMON muy buenos\\11en la hierba!\\12¡Creo que me\\\nservirán!",
  ["4b:49bf"] = "¡Maldición! Creía\\\nque podía ganar.",
  ["4b:49dd"] = "En la hierba hay\\\ncosas pegajosas.",
  ["4b:4a02"] = "Esa mirada…\\\nMe intriga.",
  ["4b:4a20"] = "¡Mmmm! ¡Qué\\\ndecepción!",
  ["4b:4a3e"] = "Si no quieres\\\nluchar, evita el\\11contacto visual.",
  ["4b:4a73"] = "Sí. Y sabes\\\nque…\\12¿Luchar? ¡Estoy\\\nal teléfono!\\12Vale. Pero que\\\nsea rápido.",
  ["4b:4ad2"] = "¡Tranquilízate!\\\n¡Eso no está bien!",
  ["4b:4aed"] = "Yo también estaba\\\ncharlando.",
  ["4b:4b0c"] = "¡Esa MEDALLA! ¡Es\\\nde CIUDAD MALVA!\\12¿Ganaste a PEGASO?",
  ["4b:4b41"] = "Conozco mis\\\ndebilidades.",
  ["4b:4b61"] = "Debería volver a\\\nentrenarme en el\\12GIMNASIO de\\\nCIUDAD MALVA.",
  ["4b:4bc0"] = "¡GRRR!\\\n¡TODOS HUYEN\\12CUANDO RUJO! ¡PERO\\\nTÚ HAS VENIDO!\\12¡ESO ME GUSTA!\\\n¡TOMA ESTO!",
  ["4b:4c19"] = "¡GRRR!\\\n¡ES RUGIDO! HASTA\\12LOS POKéMON HUYEN\\\nCON UN RUGIDO.",
  ["4b:4c4e"] = "VICKI: ¡Yuju!\\\n¡Es viernes!\\12Soy VICKI, por\\\nviernes.\\12¡Mucho gusto!",
  ["4b:4c91"] = "¡Toma una FLECHA\\\nVENENOSA!",
  ["4b:4caf"] = "VICKI: Dásela a un\\\nPOKéMON de tipo\\11veneno.\\12¡Oh!\\12¡Es terrible!\\12¡Te sorprenderá\\\nver cómo mejora\\12los movimientos\\\nde tipo veneno!",
  ["4b:4d27"] = "VICKI: ¡Hola! ¿Qué\\\ndía prefieres?\\12A mí me gusta el\\\nviernes. Sin duda.\\12¿No crees que\\\nes genial?",
  ["4b:4d8c"] = "VICKI: ¿Hoy no\\\nes viernes?\\12¡Me aburro cuando\\\nno lo es!",
  ["4b:4dc7"] = "RUTA 32\\12CIUDAD MALVA -\\\nPUEBLO AZALEA",
  ["4b:4deb"] = "RUINAS ALFA\\\nENTRADA ESTE",
  ["4b:4e08"] = "Hacia la\\\nCUEVA UNIÓN",
  ["4b:4fad"] = "Crucé el túnel\\\ny todavía me\\12queda mucha\\\nenergía.",
  ["4b:4ff1"] = "¡Uauu, chico! ¡Qué\\\nmarcha tienes!",
  ["4b:5011"] = "Los MONTAÑEROS\\\nsomos felices en\\11las montañas.",
  ["4b:503e"] = "RUTA 33",
  ["4b:52ee"] = "¡Aquí es donde\\\nentreno!",
  ["4b:530f"] = "¿Qué ha pasado?",
  ["4b:531f"] = "Voy a entrenar\\\nmás aún.\\12Estoy intentado\\\nconvertirme en un\\11LÍDER de GIMNASIO.",
  ["4b:536c"] = "Soy el mejor de mi\\\nclase en POKéMON.",
  ["4b:538e"] = "¡No! Hay mejores\\\nentrenadores…",
  ["4b:53b0"] = "Estoy esforzándome\\\npara ser el mejor\\11de mi clase.",
  ["4b:53e2"] = "Confío en mi\\\ncapacidad para\\11criar POKéMON.\\12¿Quieres verlo?",
  ["4b:541a"] = "¿No lo hice lo\\\nbastante bien?",
  ["4b:5439"] = "Quizá debería\\\ndejar uno en la\\12GUARDERÍA.\\\n¿Qué debo hacer?",
  ["4b:5473"] = "¿Eres entrenador?\\12Libremos un\\\ncombate de prueba.",
  ["4b:54a4"] = "¡Oh, no! No\\\npuedo ganar…",
  ["4b:54be"] = "Eres demasiado\\\nfuerte para\\11practicar conmigo.",
  ["4b:54ea"] = "¿Quién anda ahí?\\\n¿Qué es lo que\\11quieres?",
  ["4b:550f"] = "Eres un chaval\\\nmuy fuerte.",
  ["4b:552a"] = "Hoy no veo\\\nnada malo. Sé\\12bueno y no te\\\nmetas en líos.",
  ["4b:5570"] = "Estoy buscando\\\nindividuos\\11sospechosos.",
  ["4b:559c"] = "Acabo de recoger\\\nmi POKéMON de la\\11GUARDERÍA.\\12¡Veamos lo fuerte\\\nque es ahora!",
  ["4b:55e7"] = "¿Por qué acaba\\\nasí?",
  ["4b:5602"] = "Mi POKéMON sabía\\\nmovimientos que yo\\11desconocía.\\12¡Eso me confundió\\\nmuchísimo!",
  ["4b:5649"] = "MAR: ¡Vaya, nos\\\nha visto un chico!",
  ["4b:5669"] = "MAR: ¡Ohhhh!\\\n¡Es muy fuerte!",
  ["4b:5688"] = "MAR: ¡Mi hermana\\\nLISA te lo hará\\11pagar!",
  ["4b:56b6"] = "MAR: ¿No te parece\\\nuna playa genial?\\12¡Es nuestro\\\npequeño refugio!",
  ["4b:56f4"] = "ILDA: ¡No puedes\\\nvencer a MAR e\\11irte sin más!",
  ["4b:5722"] = "ILDA: ¡Lo siento\\\nmucho, MAR!",
  ["4b:573f"] = "ILDA: ¡No seas\\\nchulo! ¡Mi hermana\\11LISA es fuerte!",
  ["4b:576f"] = "ILDA: El sol\\\nfortalece tu\\11cuerpo.",
  ["4b:5799"] = "LISA: ¡Seguro que\\\nhas sido malo con\\11mis hermanitas!",
  ["4b:57c9"] = "LISA: ¡He perdido!\\\n¡Increíble!",
  ["4b:57eb"] = "LISA: Eres muy\\\nfuerte. No pude\\11hacer nada.\\12Toma. Te lo\\\nmereces.",
  ["4b:5834"] = "LISA: Sentimos\\\nhaberte atacado.\\12Pensábamos que\\\naquí nadie nos\\12encontraría. ¡Nos\\\nhas sorprendido!",
  ["4b:58b1"] = "RUTA 34\\12CIUDAD TRIGAL -\\\nPUEBLO AZALEA\\12EL ENCINAR\\\nEntre medias",
  ["4b:58f6"] = "PISTAS ENTRENADOR\\12Todos los días\\\ncrecen BAYAS\\11en los árboles.\\12Toma nota de los\\\ntipos de BAYAS que\\11tiene cada árbol.",
  ["4b:595a"] = "GUARDERÍA\\12¡Déjanos criar a\\\ntu POKéMON por ti!",
  ["4b:5c09"] = "He estado cogiendo\\\ndatos de POKéMON\\12de mi radio. Creo\\\nque soy bueno.",
  ["4b:5c44"] = "¡Me rindo!",
  ["4b:5c4d"] = "La música de la\\\nradio cambia el\\12ánimo de los\\\nPOKéMON salvajes.",
  ["4b:5c81"] = "Le voy a demostrar\\\na mi novia lo\\11bueno que soy.",
  ["4b:5cac"] = "Ojalá hubieras\\\nperdido por mí…",
  ["4b:5cd0"] = "Me humillaste\\\ndelante de mi\\11novia…",
  ["4b:5cfd"] = "Mi novio es débil.\\\nAsí que no puedo\\11confiar en él.",
  ["4b:5d29"] = "¡Cielos! ¡Eres tan\\\nfuerte!",
  ["4b:5d43"] = "Confío más en\\\nmis POKéMON\\11que en mi novio.",
  ["4b:5d73"] = "¿Vas al GIMNASIO?\\\n¡Yo también!",
  ["4b:5d96"] = "¡Vaya! No pude\\\nganar…",
  ["4b:5daa"] = "Me gustan las\\\nMEDALLAS de\\12los GIMNASIOS.\\\nLas colecciono.",
  ["4b:5dd6"] = "¿Qué tipo de\\\nPOKé BALL usas?",
  ["4b:5df8"] = "¡Vaya! ¡No lo\\\nbastante rápido!",
  ["4b:5e11"] = "Algunos POKéMON\\\nhuyen enseguida.\\12Intenta atraparlos\\\ncon la RAPID BALL\\11de CÉSAR.\\12Cuando encuentro\\\nun BONGURI BLA, se\\11lo llevo a CÉSAR.\\12Él lo convierte en\\\nuna POKé BALL.",
  ["4b:5eaa"] = "¡Observa cómo uso\\\nlas POKé BALL!",
  ["4b:5ece"] = "¡Uauuu! ¡Vaya\\\nsacudida!",
  ["4b:5ee6"] = "Quería\\\nimpresionarte con\\11mi premio POKéMON.\\12¡Pero tu habilidad\\\nme ha electrizado!",
  ["4b:5f36"] = "Iré a cualquier\\\nlugar donde haya\\11POKéMON bicho.",
  ["4b:5f61"] = "Ya veo. Ésta es tu\\\nforma de luchar.",
  ["4b:5f81"] = "Mi VENONAT ganó\\\nel Concurso de\\12Captura de Bichos\\\ndel PARQUE\\11NACIONAL.",
  ["4b:5fc3"] = "Practico mi\\\naliento de fuego.",
  ["4b:5fe5"] = "¡Me he quemado la\\\npunta de la nariz!",
  ["4b:6009"] = "La Marcha POKéMON\\\nde la radio atrae\\11POKéMON salvajes.",
  ["4b:6037"] = "¡El peligro acecha\\\npor la noche!",
  ["4b:6053"] = "¡Uy!",
  ["4b:605c"] = "Ya sabes, la noche\\\nes divertida a su\\11manera.\\12Pero no te pases,\\\n¿vale?",
  ["4b:60a3"] = "Tus POKéMON son\\\nbastante fuertes.\\12Estarás seguro en\\\ncualquier parte.",
  ["4b:60e1"] = "RUTA 35",
  ["4b:6321"] = "Un árbol extraño.\\\n¿Usar REGADERA?",
  ["4b:6346"] = "{PLAYER} usó\\\nla REGADERA.",
  ["4b:6360"] = "¡Al árbol extraño\\\nno le gusta la\\11REGADERA!\\12¡El árbol extraño\\\natacó!",
  ["4b:63a7"] = "¡Cielos!\\12Iba a quitar\\\nese árbol con\\12un gran\\\nderechazo.\\12Pero no pude.\\\n¡Soy un fracaso!",
  ["4b:6408"] = "¿Quitaste ese\\\npobre árbol?\\12¡Estoy\\\nimpresionado! Toma\\11esto.",
  ["4b:6464"] = "Se trata del\\\nGOLPE ROCA.\\12Puedes destrozar\\\nrocas con un\\12simple golpe bien\\\ndirigido.\\12Si encuentras una\\\nroca en tu camino,\\11¡destrózala!",
  ["4b:64f0"] = "Un árbol extraño\\\nbloquea el camino\\11a CIUDAD TRIGAL.\\12No me permite\\\nir de compras.\\12Habría que hacer\\\nalgo.",
  ["4b:6568"] = "Ese árbol extraño\\\ndesapareció sin\\11dejar rastro.\\12¡Oh! ¿Ese árbol\\\nera un POKéMON?",
  ["4b:65b7"] = "¡Te voy a leer\\\nel pensamiento!",
  ["4b:65d8"] = "¡Te malinterpreté!",
  ["4b:65e8"] = "Sería fuerte si\\\npudiera saber lo\\12que está pensando\\\nmi rival.",
  ["4b:662a"] = "¡Gracias a mis\\\nestudios, estoy\\12preparado para\\\ncualquier POKéMON!",
  ["4b:665a"] = "¡Uups! ¿Error de\\\ncálculo?",
  ["4b:6674"] = "Yo también estudio\\\n5 horas al día.\\12Leyendo libros\\\npuedes aprender\\11muchas cosas.",
  ["4b:66cc"] = "JOSUÉ: ¿Quién\\\neres tú?\\12Soy JOSUÉ, por\\\njueves.",
  ["4b:66f9"] = "Toma. Coge\\\nesto.",
  ["4b:6713"] = "JOSUÉ: Debería\\\nusarlo un POKéMON\\12con habilidades\\\nde tipo roca.\\12Mejora los ataques\\\nde tipo roca.",
  ["4b:6776"] = "JOSUÉ: Soy JOSUÉ,\\\npor jueves. Soy\\12el segundo de\\\nsiete hermanos.",
  ["4b:67bf"] = "JOSUÉ: Hoy no\\\nes jueves. ¡Qué\\11desilusión!",
  ["4b:67f0"] = "RUTA 36",
  ["4b:67fa"] = "RUINAS ALFA\\\nENTRADA NORTE",
  ["4b:6818"] = "PISTAS ENTRENADOR\\12Las habilidades de\\\nlos POKéMON varían\\12incluso dentro de\\\nuna misma especie.\\12Al principio, sus\\\nhabilidades pueden\\11parecerse.\\12Sin embargo, las\\\ndiferencias surgen\\12a medida que el\\\nPOKéMON crece.",
  ["4b:68ba"] = "PISTAS ENTRENADOR\\12Usa EXCAVAR para\\\nvolver a la\\11entrada.\\12Es útil para\\\nexplorar cuevas\\12y otros\\\nlugares.",
  ["4c:4093"] = "ANA: ¡ANY y yo\\\nestamos en esto\\11juntas!",
  ["4c:40bc"] = "ANA-ANY: ¡Eres\\\nmuy malo!",
  ["4c:40d5"] = "ANA: Sé lo que\\\nestán pensando\\12mi hermana y mis\\\nPOKéMON.",
  ["4c:410f"] = "ANY: ¡ANA y yo\\\nestamos en esto\\11juntas!",
  ["4c:4138"] = "ANA-ANY: ¡Eres\\\nmuy malo!",
  ["4c:4151"] = "ANY: Sentimos\\\nlo mismo que\\11nuestros POKéMON.",
  ["4c:4180"] = "Los POKéMON no\\\npueden hacer nada\\11dormidos.\\12¡Yo te enseñaré el\\\nmiedo que da eso!",
  ["4c:41ca"] = "He perdido. ¡Qué\\\npena…!",
  ["4c:41e5"] = "Dormir o paralizar\\\na los POKéMON\\12son buenas\\\ntécnicas de lucha.",
  ["4c:422d"] = "DOMINGO: ¡Hola!\\12Soy DOMINGO, por\\\nel día. Es decir,\\11¡hoy es domingo!",
  ["4c:4269"] = "¡Me dijeron que\\\nte diera esto si\\11te veía!",
  ["4c:4294"] = "DOMINGO: Eso…\\12¡Um…!\\12¿Qué era…?\\12…\\12¡Ah! ¡Ahora lo\\\nrecuerdo!\\12Debería llevarlo\\\nun POKéMON\\12con habilidades\\\neléctricas.\\12¡Mi hermana LUNA\\\ndice que mejora\\12las habilidades\\\neléctricas!",
  ["4c:4336"] = "DOMINGO: Mis\\\nhermanos son\\11LUNA, MARTA,\\11MIGUEL, JOSUÉ,\\11VICKY y SABINO.\\12¡Son todos\\\nmayores que yo!",
  ["4c:43a8"] = "DOMINGO: ¿Hoy no\\\nes domingo?\\11¡Um…! ¡Lo olvidé!",
  ["4c:43d1"] = "RUTA 37",
  ["4c:45a8"] = "¡Vuela alto hacia\\\nel cielo, querido\\11pájaro POKéMON!",
  ["4c:45d6"] = "¡Me apetece salir\\\nvolando ahora!",
  ["4c:45f9"] = "Pienso entrenar en\\\nCIUDAD ORQUÍDEA\\12y enseñar a volar\\\na mis POKéMON.",
  ["4c:4638"] = "Déjame probar\\\nalgo que he\\11aprendido hoy.",
  ["4c:4661"] = "Creo que no\\\nestudié bastante.",
  ["4c:4681"] = "Tengo que hacer\\\nmuchos exámenes y\\12no tengo tiempo\\\npara los POKéMON.\\12Así que, cuando\\\npuedo jugar, me\\11concentro mucho.",
  ["4c:46f0"] = "¿Estás\\\nentrenándote?\\12Si es así, ¿puedes\\\nenseñarme cómo?",
  ["4c:472e"] = "Ya veo. De modo\\\nque luchas así.",
  ["4c:4752"] = "¡Tengo una buena\\\nnoticia!\\12La leche de la\\\nGRANJA MUU-MUU\\12es famosa por\\\nsu sabor.",
  ["4c:4796"] = "¡Hola! ¡Eres\\\nmuy guapo!\\12¿Me dejas ver a\\\ntus POKéMON?",
  ["4c:47ca"] = "Encantada de\\\nhaber visto\\11a tus POKéMON.",
  ["4c:47eb"] = "Cuando veo\\\nPOKéMON me\\11tranquilizo.",
  ["4c:481d"] = "He estado en el\\\nextranjero. ¡Así\\12que conozco todo\\\ntipo de POKéMON!",
  ["4c:4856"] = "¡Tu destreza es de\\\ncategoría mundial!",
  ["4c:4872"] = "Gentes de todo el\\\nmundo viven\\12felices con\\\nlos POKéMON.",
  ["4c:48b2"] = "RUTA 38\\12CIUDAD OLIVO -\\\nCIUDAD IRIS",
  ["4c:48d9"] = "PISTAS ENTRENADOR\\12Si un POKéMON\\\nva a evolucionar,\\11puedes pararlo.\\12Pulsa el Botón B\\\nmientras intenta\\11evolucionar.\\12Esto asusta al\\\nPOKéMON y detiene\\11su evolución.",
  ["4c:4abc"] = "MUU-MUU: ¡Muu!",
  ["4c:4acc"] = "Acabo de volver\\\nde CIUDAD OLIVO.\\12¿Te apetece luchar\\\ncon los POKéMON?",
  ["4c:4b05"] = "¡Awaaargh!",
  ["4c:4b10"] = "Mis POKéMON han\\\nsido atrapados y\\12entrenados en el\\\nextranjero.\\12Son mis compañeros\\\nde esos largos\\11viajes.",
  ["4c:4b68"] = "¿Te importa si\\\npresumo de mis\\11POKéMON?",
  ["4c:4b94"] = "No puedo\\\npresumir…",
  ["4c:4bae"] = "¡No te estoy\\\nescuchando!\\12¡Los POKéFANS\\\ntenemos la norma\\12de no escuchar a\\\nlos presumidos!",
  ["4c:4c11"] = "¡Qué POKéMON\\\nmás encantadores!\\12Enseñemos nuestros\\\nPOKéMON al\\11mismo tiempo.",
  ["4c:4c53"] = "No me importa\\\nperder.",
  ["4c:4c68"] = "¿Sabes algo sobre\\\nlos POKéMON bebés?\\12¡Seguro que\\\nson adorables!",
  ["4c:4ca2"] = "Déjame ver de qué\\\nson capaces tus\\11POKéMON.",
  ["4c:4ccd"] = "¡Ooh! Tus POKéMON\\\ntienen potencial.",
  ["4c:4ced"] = "¿Sabes que\\\nlos POKéMON\\12tienen distintas\\\nhabilidades?\\12Son como las\\\npersonas. Cada\\12uno tiene su\\\npropio potencial.",
  ["4c:4d5a"] = "RUTA 39\\12CIUDAD OLIVO -\\\nCIUDAD IRIS",
  ["4c:4d81"] = "GRANJA MUU-MUU\\12Prueba nuestra\\\nrica leche fresca",
  ["4c:4dad"] = "PISTAS ENTRENADOR\\12Usa GOLPE CABEZA\\\nen los árboles\\12para que salgan\\\nPOKéMON.\\12De los árboles\\\npueden caer varios\\11tipos de POKéMON.",
  ["4c:4f84"] = "Debes calentar\\\nantes de entrar\\11en el agua.\\12Es imprescindible.",
  ["4c:4fc3"] = "¡Vale! ¡Me rindo!",
  ["4c:4fd7"] = "CIUDAD ORQUÍDEA\\\nestá bastante\\11lejos de aquí.",
  ["4c:5009"] = "Un joven como tú\\\ndebería nadar.\\12No hagas SURF\\\nsobre tus POKéMON.",
  ["4c:5044"] = "¡Oh, he perdido…!",
  ["4c:5054"] = "La natación\\\nfortalece tu\\11cuerpo. Es sana.",
  ["4c:5087"] = "¿Vas a CIUDAD\\\nORQUÍDEA?\\12¿Te apetece luchar\\\nantes?",
  ["4c:50c3"] = "¡He perdido!",
  ["4c:50d5"] = "Creo que nado\\\nmejor que tú.\\11¡Sin duda!",
  ["4c:5103"] = "Yo no necesito\\\nflotador.\\12¡Voy agarrada a\\\nun POKéMON de mar!",
  ["4c:5137"] = "¡Ooh, estoy\\\nmareada!",
  ["4c:514f"] = "Mientras flote\\\nasí, las olas\\11me llevarán.",
  ["4c:5183"] = "Aunque no se ve\\\ndesde aquí, CIUDAD\\12ORQUÍDEA está al\\\notro lado del mar.",
  ["4c:51c4"] = "LUNA: Encantada de\\\nconocerte. Soy\\12LUNA, por lunes.",
  ["4c:51f4"] = "¡Como prueba de\\\nnuestra amistad,\\12tengo un regalo\\\npara ti!",
  ["4c:522a"] = "LUNA: Es un objeto\\\nque aumenta el\\12poder de los\\\nataques de vuelo.\\12Deberías dar este\\\nobjeto a un\\11POKéMON pájaro.",
  ["4c:529a"] = "LUNA: Mis hermanos\\\ny hermanas están\\12por todas\\\npartes.\\12¡A ver si los\\\nencuentras!",
  ["4c:52f5"] = "LUNA: No creo\\\nque hoy sea\\11lunes. ¡Qué pena…!",
  ["4c:5325"] = "RUTA 40\\12CIUDAD ORQUÍDEA -\\\nCIUDAD OLIVO",
  ["4c:54a1"] = "Aquí el agua está\\\ntemplada. Estoy\\11muy a gusto.\\12Por supuesto,\\\n¡lucharé contigo!",
  ["4c:54e4"] = "¡Vaya! ¡Estoy\\\ncomo una pasa!",
  ["4c:5500"] = "¡Qué relajante\\\nes flotar\\11así!",
  ["4c:552b"] = "Estoy cansado. Si\\\ngano, ¿me prestas\\11tus POKéMON?",
  ["4c:5559"] = "(jadeo…)",
  ["4c:5566"] = "CIUDAD ORQUÍDEA\\\nestá muy lejos.\\12Pero tampoco es\\\nfácil volver a\\11CIUDAD OLIVO.\\12¿Qué hacer?",
  ["4c:55c0"] = "¿Ves esas islas\\\naisladas por\\11torbellinos?\\12¡Tiene que haber\\\nun secreto!",
  ["4c:5612"] = "¿Cuál es tu\\\nsecreto?",
  ["4c:5636"] = "Era de noche\\\ny llovía…\\12Vi un POKéMON\\\ngigante volando\\11desde las islas.\\12Dejaba caer las\\\nplumas de sus\\11alas plateadas.",
  ["4c:56b8"] = "Aquí hay mucho\\\noleaje.\\12Cuesta mucho\\\nnadar.",
  ["4c:56f4"] = "¡Me has vencido!",
  ["4c:56fe"] = "La corriente me\\\nimpide llegar\\11a las islas.",
  ["4c:572f"] = "¿Estás buscando\\\nel secreto de las\\11ISLAS REMOLINO?",
  ["4c:575e"] = "¡Ooh, tienes una\\\ngran resistencia!",
  ["4c:577f"] = "Un secreto sobre\\\nISLAS REMOLINO…\\12¡Dentro está muy\\\noscuro!",
  ["4c:57b6"] = "Voy hacia las\\\nISLAS REMOLINO.\\12Voy a explorarlas\\\ncon unos amigos.",
  ["4c:57f9"] = "¿Así es como\\\nlo haces?",
  ["4c:5811"] = "Dicen que hay un\\\ngran POKéMON\\12bajo las\\\nISLAS REMOLINO.\\12Me pregunto\\\ncómo será…",
  ["4c:586c"] = "Estás tan elegante\\\nmontado en tu\\11POKéMON.",
  ["4c:5896"] = "He perdido.",
  ["4c:58a3"] = "¿No había una\\\ncanción famosa\\12sobre un niño que\\\nmontaba un LAPRAS?",
  ["4c:58d8"] = "¡Hace muy buen\\\ndía! ¡Estoy\\11aturdida!",
  ["4c:5904"] = "¡Ohhh!",
  ["4c:590b"] = "El sol es muy malo\\\npara la piel.\\12Pero yo no uso\\\nprotección solar.\\12No quiero\\\nensuciar el agua.",
  ["4c:5962"] = "Si necesitas\\\ndescansar, ve por\\11el agua.\\12El viento te\\\nempujará y podrás\\12seguir siendo\\\nfuerte.",
  ["4c:59c5"] = "¡Oh! Tienes más\\\nenergía que yo.",
  ["4c:59ea"] = "He oído rugidos\\\nprocedentes de\\11las ISLAS.",
  ["4c:5a17"] = "Por la noche,\\\nlos STARYU se\\12reúnen cerca de la\\\nsuperficie.",
  ["4c:5a49"] = "¡Oh, querido…!",
  ["4c:5a54"] = "Los grupos de\\\nSTARYU se iluminan\\11al mismo tiempo.\\12Es muy bonito,\\\npero da miedo.",
  ["4c:5c16"] = "¡Déjame que te\\\nenseñe el poder de\\11mis POKéMON!",
  ["4c:5c4a"] = "¿Qué? Eso no está\\\nbien.",
  ["4c:5c62"] = "Quiero convertirme\\\nen un CAMPEÓN\\12con los POKéMON\\\nque he atrapado.\\12¡Eso es lo mejor\\\nde la pesca!",
  ["4c:5cbf"] = "¡Ah! ¡Qué bien\\\nestar fuera! ¡Me\\11siento tan libre!",
  ["4c:5cec"] = "¡Gahahah!",
  ["4c:5cf6"] = "¡Perder no tiene\\\nimportancia si lo\\12comparas con el\\\ninmenso cielo!",
  ["4c:5d33"] = "¡OYE!\\12¡Éste es mi lugar\\\nsecreto! ¡Fuera de\\11aquí, intruso!",
  ["4c:5d6a"] = "Debí haber usado\\\nmi PIEDRA LUNAR…",
  ["4c:5d8d"] = "¿Tienes una\\\nPOKéDEX?\\12¡Uau, habrás visto\\\nPOKéMON muy\\11raros!\\12¿Puedo verla,\\\npor favor?",
  ["4c:5dee"] = "RUTA 42\\12CIUDAD IRIS -\\\nPUEBLO CAOBA",
  ["4c:5e16"] = "MONTE MORTERO\\12CUEVA CASCADA\\\nInterior",
  ["4c:5e3a"] = "MONTE MORTERO\\12CUEVA CASCADA\\\nInterior",
  ["4c:5e5e"] = "RUTA 42\\12CIUDAD IRIS -\\\nPUEBLO CAOBA",
  ["4d:418e"] = "¡Me encantan\\\nlos POKéMON!\\12¡Ésa es la razón\\\npor la que empecé\\12a coleccionar\\\nPOKéMON!",
  ["4d:41d8"] = "¿Cómo me has\\\npodido hacer esto?",
  ["4d:41f6"] = "¿Que qué me gusta\\\nademás de los\\11POKéMON?\\12Oír a ROSA en la\\\nradio. ¡Seguro que\\11es muy guapa!",
  ["4d:423d"] = "¡Eh! ¿Tienes algún\\\nPOKéMON raro?",
  ["4d:425e"] = "¡Oh, mis pobres\\\nPOKéMON!",
  ["4d:427d"] = "Sería feliz con\\\nsólo tener un\\11POKéMON raro.",
  ["4d:42aa"] = "¿Te lo puedes\\\ncreer?\\12¡{RIVAL} se ha\\\nburlado de mi\\11POKéMON!\\12¡Maldición! ¡Mi\\\nPOKéMON es genial!",
  ["4d:42fa"] = "¡Mi NIDOKING lo\\\nha hecho muy bien!",
  ["4d:431c"] = "Es bueno que a la\\\ngente le gusten\\12distintos tipos de\\\nPOKéMON.\\12No sólo se trata\\\nde tener el\\11más fuerte.",
  ["4d:4385"] = "No estoy de racha.\\12Quizá sea por el\\\nequipo que uso.\\12Luchemos. A ver si\\\ncambia mi suerte.",
  ["4d:43d4"] = "He perdido, pero\\\nme siento mejor.",
  ["4d:43f7"] = "Las CEBO BALL de\\\nCÉSAR son las\\12mejores para\\\npescar POKéMON.\\12Son mucho más\\\nefectivas que las\\11ULTRA BALL.",
  ["4d:4459"] = "Puedo hacer muchas\\\ncosas con mis\\12POKéMON.\\\n¡Es muy divertido!",
  ["4d:4489"] = "Perder no es nada\\\ndivertido…",
  ["4d:44a2"] = "¿Qué ocurre en el\\\nLAGO DE LA FURIA?\\12Teníamos pensado\\\nacampar aquí.",
  ["4d:44e5"] = "¿Tú también vas al\\\nLAGO DE LA FURIA?\\12¡Juguemos un\\\nratito!",
  ["4d:4528"] = "¡He jugado mucho!",
  ["4d:453c"] = "Voy a ir de picnic\\\ncon mis POKéMON.\\12¿No te vienes?",
  ["4d:456f"] = "RUTA 43\\12LAGO DE LA FURIA -\\\nPUEBLO CAOBA",
  ["4d:4596"] = "RUTA 43\\12LAGO DE LA FURIA -\\\nPUEBLO CAOBA",
  ["4d:45bd"] = "PISTAS ENTRENADOR\\12Todos los POKéMON\\\ntienen ventajas y\\12desventajas según\\\nel tipo.\\12Entre dos POKéMON\\\nde distinto tipo,\\12puede perder el\\\nde nivel superior.\\12Aprende qué tipos\\\nson fuertes o\\12débiles contra tu\\\ntipo de POKéMON.",
  ["4d:488b"] = "¡Me has hecho\\\nperder a POLIWAG!\\12¿Qué vas a hacer\\\npara remediarlo?",
  ["4d:48d1"] = "¡Simplemente,\\\nolvídalo!",
  ["4d:48e8"] = "Ese POLIWAG que\\\nescapó…\\11Era enorme.\\12¡Juraría que medía\\\nunos 5 metros!",
  ["4d:4937"] = "Pesco hasta que\\\nno puedo más.\\12Y lucho hasta\\\ndesfallecer.\\12Ésta es la\\\nrelación que tengo\\11con mis POKéMON.",
  ["4d:4995"] = "¡Mmmmm…!\\\nEso no está bien.",
  ["4d:49af"] = "Son 100 victorias\\\ny 101 derrotas.\\12No lucharé\\\nen un rato.",
  ["4d:49ef"] = "¿Sabes algo sobre\\\nel POKéMON\\11pájaro legendario?",
  ["4d:4a1b"] = "¡Uauu! Eres un\\\nhacha.",
  ["4d:4a33"] = "ARTICUNO, ZAPDOS y\\\nMOLTRES son los\\12pájaros POKéMON\\\nlegendarios.\\12Aunque dicen que\\\nhay otros pájaros\\11legendarios.",
  ["4d:4aa7"] = "¡Voy a ganar!\\\n¡Seguro!",
  ["4d:4ac0"] = "¡Arrgh…! No\\\nesperaba perder.",
  ["4d:4adf"] = "Es importante\\\ntener confianza\\11en uno mismo.",
  ["4d:4b0f"] = "¡Haré lo que sea\\\npara conseguir\\11POKéMON raros!",
  ["4d:4b3e"] = "Oooh, tus POKéMON\\\nson muy bonitos.",
  ["4d:4b61"] = "Los POKéMON\\\nde colores\\12poco habituales\\\ntienen más valor.\\12¿Qué? ¿Insinúas\\\nque no es cierto?",
  ["4d:4bbf"] = "Con sólo mirarte\\\nsé si eres un\\11buen entrenador.\\12Yo soy bueno con\\\nlos POKéMON y veo\\11que tú también.",
  ["4d:4c26"] = "¡Vaya! Ha sido una\\\nauténtica derrota.",
  ["4d:4c49"] = "¡Uauu! Tienes\\\nmuchas MEDALLAS.\\12No me extraña que\\\nseas tan fuerte.\\12Me pregunto si\\\nMORTI, de GIMNASIO\\12IRIS, estará\\\naún entrenándose.\\12Él sí que me\\\ndio una paliza.",
  ["4d:4cd0"] = "Pareces fuerte.\\12Los buenos\\\nentrenadores\\12siempre buscan\\\nbuenos rivales.",
  ["4d:4d14"] = "¡No! Esto no\\\nservirá para nada.",
  ["4d:4d30"] = "Todos mejoramos\\\nluchando\\11muchas veces.\\12He luchado mucho\\\npara llegar a ser\\12lo que soy hoy:\\\nuna campeona.",
  ["4d:4d96"] = "RUTA 44\\\nHACIA RUTA HELADA",
  ["4d:4daf"] = "RUTA 44\\12PUEBLO CAOBA -\\\nCIUDAD ENDRINO",
  ["4d:4feb"] = "¡Prepárate para\\\ncualquier cosa!\\12¡Déjame ver si\\\nhas entrenado bien\\11a tus POKéMON!",
  ["4d:5039"] = "¡Oh, he perdido!",
  ["4d:504b"] = "Volveré a la RUTA\\\nHELADA de CIUDAD\\12ENDRINO y seguiré\\\nentrenándome.",
  ["4d:5087"] = "¡Eres valiente!\\\nPero…\\12¿Sabes qué?\\\nPara valiente,\\11¡yo!",
  ["4d:50dc"] = "¡A mis POKéMON les\\\nfaltaron agallas!",
  ["4d:50fb"] = "¡Cómo me gusta\\\nMÁS PS! ¡Mmmm!\\12¡Me bebo la de mis\\\nPOKéMON!\\12No puedo evitarlo.",
  ["4d:5147"] = "¡Mis POKéMON son\\\nmuy poderosos!",
  ["4d:5162"] = "¡Buaaaaa! ¡Soy un\\\nperdedor!",
  ["4d:517e"] = "No se me da muy\\\nbien pensar.\\12¡Así que utilizo\\\nsólo la fuerza!",
  ["4d:51c4"] = "¿Que por qué\\\nescalo montañas?\\12Porque están\\\nahí.\\12¿Que por qué\\\nentreno POKéMON?\\12¡Porque están\\\nahí!",
  ["4d:5220"] = "Las derrotas…\\\n¡También están!",
  ["4d:523b"] = "Lo mejor que me ha\\\npasado nunca fue\\12descubrir a los\\\nPOKéMON.",
  ["4d:5276"] = "Estaba entrenando\\\naquí solo.\\12¡Observa el fruto\\\nde mi trabajo!",
  ["4d:52b1"] = "¡Waaaargh!",
  ["4d:52bc"] = "Debo tomar\\\nmedidas extremas.\\12Debo ir a los\\\nmontes y entrenar\\11allí, en soledad.",
  ["4d:530e"] = "¿Qué piensas sobre\\\nla educación\\11de los POKéMON?",
  ["4d:5339"] = "Te has ganado\\\nmi respeto.",
  ["4d:5350"] = "Veo que estás\\\neducando a tus\\12POKéMON\\\ncon cariño.\\12El vínculo que\\\nos une os salvará\\12en las situaciones\\\ndifíciles.",
  ["4d:53b2"] = "¿Cuál es tu\\\nestrategia?\\12Es de tontos usar\\\nataques fuertes\\12de forma\\\nindiscriminada.",
  ["4d:5405"] = "Vale. He perdido.",
  ["4d:5414"] = "No soy partidaria\\\nde los ataques\\11demasiado fuertes.\\12Quiero ganar, pero\\\nno quiero herir\\11a los POKéMON.",
  ["4d:5490"] = "RUTA 45\\\nCAMINO MONTAÑA",
  ["4d:561f"] = "De acuerdo. ¡Te\\\nenseñaré el poder\\12de los POKéMON\\\nde montaña!",
  ["4d:5652"] = "¡Me has demostrado\\\ntu poder!",
  ["4d:5674"] = "Se acabó. Pero no\\\nme importa. \\12Los MONTAÑEROS\\\nsomos así.",
  ["4d:56a5"] = "¡Yo también\\\nentreno POKéMON!\\12¿Quieres luchar\\\ncontra mí?",
  ["4d:56d6"] = "¿Qué…?",
  ["4d:56dd"] = "Hice lo que pude\\\npero no sirvió.\\12No hay excusa que\\\nvalga. He perdido.",
  ["4d:571b"] = "¡Yo también\\\nentreno POKéMON!\\12¡Luchemos!",
  ["4d:573b"] = "¡Oh, maldición!",
  ["4d:5749"] = "He estado en\\\nmuchos GIMNASIOS,\\12pero mi favorito\\\nes el de TRIGAL.\\12¡Está lleno de\\\npreciosas flores!",
  ["4d:57aa"] = "RUTA 46\\\nCAMINO MONTAÑA",
  ["4d:588a"] = "¿Has ido al GIM.\\\nde C. PLATEADA?\\12El LÍDER utiliza\\\nPOKéMON roca.",
  ["4d:58c8"] = "Por la noche,\\\nCLEFAIRY sale a\\11jugar al MT. MOON.\\12Pero no todas\\\nlas noches.",
  ["4d:590e"] = "¡Vaya! ¿Vienes\\\nde JOHTO?\\12Me trae muchos\\\nrecuerdos. Cuando\\12era joven, fui a\\\nJOHTO a entrenar.\\12Te pareces\\\nmucho a mí\\12cuando yo\\\ntenía tu edad.\\12Me gustaría darte\\\neste objeto que\\11encontré en JOHTO.",
  ["4d:59f2"] = "Visitar nuevos\\\nsitios y conocer\\11gente nueva…\\12Eso es lo\\\nbueno de viajar.",
  ["4d:5a47"] = "CIUDAD PLATEADA\\\nLa ciudad de\\11piedra grisácea",
  ["4d:5a66"] = "LÍDER POKéMON\\\nDEL GIMNASIO DE\\11C. PLATEADA: BROCK\\12El Entrenador\\\nPOKéMON más\\12fuerte que\\\nuna roca.",
  ["4d:5aa6"] = "Aquí hay una\\\nnota…\\12MUSEO DE LA\\\nCIENCIA DE CIUDAD\\12PLATEADA: Cerrado\\\npor obras…",
  ["4d:5af1"] = "Aquí hay una\\\nnota…\\12¡TIENDA DE REGALOS\\\nMT. MOON abierta!",
  ["4d:5b24"] = "¡Bienvenido a\\\nCIUDAD PLATEADA!",
  ["4d:5c1a"] = "Mis POKéMON bicho\\\nson muy fuertes.\\12¡Prepárate para\\\nperder!",
  ["4d:5c43"] = "Me vencieron…",
  ["4d:5c53"] = "Voy a buscar\\\nPOKéMON bichos\\11más fuertes.",
  ["4d:5c7c"] = "Si caminas por la\\\nhierba alta con\\12pantalones cortos,\\\n¿no te arañas?",
  ["4d:5cc2"] = "¡Au, au, au!",
  ["4d:5cd5"] = "Seguro que te\\\npican si te\\11bañas.",
  ["4d:5d00"] = "¿Por qué a las\\\nchicas no les\\12gustan los\\\nPOKéMON bicho?",
  ["4d:5d1f"] = "¡Muy mal!",
  ["4d:5d29"] = "Los POKéMON bicho\\\nparecen muñecos\\12de goma cuando les\\\naprietas la tripa.\\12¡Me encanta\\\ntocarlos!",
  ["4d:5d80"] = "RUTA 2\\12CIUDAD VERDE -\\\nCIUDAD PLATEADA",
  ["4d:5da5"] = "CUEVA DIGLETT",
  ["4e:4062"] = "¡Hola, chico! ¡Me\\\nacabo de tomar un\\12café doble y estoy\\\ncomo una moto!\\12¡Tengo que hablar\\\ncon alguien, así\\11que te toca a ti!\\12Puede que ahora no\\\nlo parezca, pero\\12yo era un experto\\\natrapando POKéMON.\\12¿Me crees?",
  ["4e:412c"] = "Muy bien. Sí, yo\\\nera algo fuera de\\12lo normal. ¡Déjame\\\ncontártelo!",
  ["4e:4174"] = "¿Qué? ¡Pequeño\\\nbribón!\\12Si fuera un poco\\\nmás joven, te\\12enseñaría un par\\\nde cosas. ¡Vaya!",
  ["4e:41ce"] = "Este GIMNASIO no\\\nha tenido LÍDER\\11hasta hace poco.\\12Un joven de\\\nPUEBLO PALETA se\\12convirtió en LÍDER\\\npero viaja mucho.",
  ["4e:423b"] = "¿Vas a enfrentarte\\\nal LÍDER?\\12¡Buena suerte! ¡La\\\nvas a necesitar!",
  ["4e:4281"] = "¡Qué sueño!\\12Me habré quedado\\\ndormido al sol.\\12He soñado que\\\nun DROWZEE se\\12comía mi sueño.\\\nEs raro, ¿verdad?\\12¿Eh?\\\n¿Qué es esto?\\12¿De dónde ha\\\nsalido esta MT?\\12¡Esto es muy\\\nmisterioso! Aquí\\11tienes esta MT.",
  ["4e:4343"] = "MT42 contiene\\\nCOME SUEÑOS…\\12¡Zzzzz…!",
  ["4e:4367"] = "Dicen que en el\\\nsuelo del BOSQUE\\12VERDE hay muchos\\\nobjetos.",
  ["4e:43ac"] = "CIUDAD VERDE\\12El Paraíso\\\nEternamente Verde",
  ["4e:43d8"] = "LÍDER DEL GIMNASIO\\\nPOKéMON DE\\11CIUDAD VERDE:…\\12El resto del texto\\\nes ilegible…",
  ["4e:441d"] = "Bienvenido a\\\nCIUDAD VERDE,\\12la entrada a\\\nla MESETA AÑIL",
  ["4e:4456"] = "CASA DE ENTRENADOR\\12Club de Mejores\\\nEntrenadores",
  ["4e:44fc"] = "LIGA POKéMON\\12ENTRADA A\\\nCALLE VICTORIA",
  ["4e:455e"] = "Luchar es lo\\\nprimero que hacen\\12los entrenadores\\\nsi se encuentran.",
  ["4e:4592"] = "Tengo el récord de\\\ncombates perdidos.",
  ["4e:45b2"] = "Es obvio que los\\\nentrenadores\\12luchemos cuando\\\nnos encontremos.",
  ["4e:45f0"] = "¡Estás ahí!\\\n¿Quieres luchar?",
  ["4e:460c"] = "He perdido…",
  ["4e:461b"] = "Eres fuerte.\\12Seguro que te has\\\nentrenado mucho.",
  ["4e:4650"] = "RUTA 1\\12PUEBLO PALETA -\\\nCIUDAD VERDE",
  ["4e:46c2"] = "Yo también entreno\\\nPOKéMON. Son\\12mis guardaespaldas\\\npersonales.",
  ["4e:46fb"] = "¡La tecnología es\\\nincreíble!\\12Ahora puedes\\\ncambiar POKéMON\\12con el pasado,\\\ncomo un e-mail.",
  ["4e:4746"] = "PUEBLO PALETA\\12Un tranquilo lugar\\\nde paz y pureza",
  ["4e:4778"] = "CASA DE ROJO",
  ["4e:4785"] = "LABORATORIO DE\\\nINVESTIGACIÓN\\11POKéMON DE OAK",
  ["4e:479c"] = "CASA DE AZUL",
  ["4e:482b"] = "Tierra a la vista.\\\n¡Sigamos adelante!",
  ["4e:4847"] = "¡Glup…!",
  ["4e:484e"] = "Ese chico tan\\\narrogante estaba\\12en el volcán de\\\nISLA CANELA.",
  ["4e:487b"] = "¡Hola!\\12Me iba a poner\\\nun poco de\\11protección solar.",
  ["4e:48ab"] = "No quiero\\\nquemarme…",
  ["4e:48c6"] = "Debería tener\\\ncuidado con las\\12manchas causadas\\\npor el sol.",
  ["4e:48fc"] = "Estoy aburrido de\\\npescar. ¡Luchemos!",
  ["4e:4921"] = "Un fracaso…",
  ["4e:4931"] = "Seguiré\\\npescando…",
  ["4e:49a7"] = "¿Quién eres tú?\\12Es evidente\\\nque eres un\\11entrenador…\\12Me llamo AZUL.\\12Y una vez fui el\\\nCAMPEÓN, pero sólo\\12durante poco\\\ntiempo…\\12El entrometido de\\\nROJO me ganó…\\12¡Pero qué más da!\\\n¿Y tú qué quieres?\\12¿Has venido a\\\ndesafiarme?\\12Lo siento, pero\\\nno, ahora no\\12tengo ganas\\\nde luchar.\\12Echa un vistazo a\\\ntu alrededor…\\12Un volcán entra\\\nen erupción y una\\12ciudad entera\\\ndesaparece.\\12En POKéMON se\\\npuede ganar y\\12perder, pero si\\\nse tuercen las\\12cosas, se puede\\\nperder enseguida.\\12…\\12Así son las\\\ncosas…\\12Sin embargo, sigo\\\nsiendo entrenador.\\12Y encontrarme con\\\nun rival fuerte me\\11anima a luchar.\\12Si quieres luchar\\\ncontra mí, ven\\12al GIMNASIO de\\\nla CIUDAD VERDE.\\12Y aceptaré\\\ntu desafío…",
  ["4e:4c48"] = "Aquí hay una\\\nnota…\\12El GIMNASIO DE\\\nISLA CANELA se ha\\12trasladado a ISLAS\\\nESPUMA.\\12BLAINE",
  ["4e:4c97"] = "ISLA CANELA\\12La abrasadora isla\\\ndel ardiente deseo",
  ["4e:4d3d"] = "Me siento más\\\nligera en el agua.",
  ["4e:4d5f"] = "¡Oh, no!",
  ["4e:4d68"] = "La natación\\\nfortalece todo el\\12cuerpo. ¡Es muy\\\nbuena!",
  ["4e:4da5"] = "¡Vaya colección\\\nde MEDALLAS\\12de GIMNASIO!\\\n¡Luchemos!",
  ["4e:4de5"] = "¡No!",
  ["4e:4dea"] = "SURF ya no es el\\\núnico movimiento\\12que se utiliza\\\nen el agua.",
  ["4e:4e20"] = "Supongo que es\\\nimposible ir\\12nadando hasta\\\nJOHTO.",
  ["4e:4e58"] = "¡Aiyaa!",
  ["4e:4e60"] = "Además de nadar\\\nen el mar, puedo\\12nadar en estanques\\\ny ríos.",
  ["4e:4e97"] = "¿Qué pone en\\\neste letrero?\\12LÍDER del GIMNASIO\\\nde ISLA CANELA:\\11BLAINE",
  ["4e:4fa6"] = "¿Has nadado alguna\\\nvez en el mar por\\11la noche?",
  ["4e:4fd8"] = "¡Glup…!",
  ["4e:4fdf"] = "De noche, el mar\\\nestá oscuro. Da la\\12impresión de que\\\nte va a tragar.",
  ["4e:5025"] = "(Resoplido)…\\\nUn… poco más…\\12y… llegaré…\\\na CIUDAD FUCSIA…",
  ["4e:5058"] = "¡Me ahogo!",
  ["4e:5066"] = "Le… pedí a mi\\\nnovia que nadara\\11a CIUDAD FUCSIA…",
  ["4e:509a"] = "¡No me gustan los\\\ncanijos!",
  ["4e:50b9"] = "Podría ganarte\\\nnadando…",
  ["4e:50d8"] = "No hay que nadar\\\nmucho desde CIUDAD\\12FUCSIA a las ISLAS\\\nESPUMA…\\12¡Mi novio es un\\\ngrandullón!\\12¡Qué canijo!",
  ["4e:5144"] = "Soy malísimo\\\nnadando.\\12Sólo estoy\\\nchapoteando por\\12estas aguas poco\\\nprofundas.",
  ["4e:5191"] = "Creía que podía\\\nganar.",
  ["4e:51a9"] = "Puede que no nade\\\nmuy bien, pero me\\11encanta el mar.",
  ["4e:51da"] = "Lo siento. La\\\ncarretera está\\11cortada por obras.\\12Si quieres llegar\\\na ISLA CANELA, ve\\12por el Sur, desde\\\nPUEBLO PALETA.",
  ["4e:524f"] = "Estoy sudando.\\\n¡Voy a bañarme!",
  ["4e:5270"] = "A saber cuánto se\\\ntardaría en mover\\11esta roca…",
  ["4e:52a8"] = "Las obras de la\\\ncarretera ya han\\11terminado.\\12Ya puedo volver a\\\npescar.",
  ["4e:52e7"] = "RUTA 19\\12CIUDAD FUCSIA -\\\nISLAS ESPUMA",
  ["4e:5310"] = "Por favor, ten\\\ncuidado si vas\\12nadando hasta las\\\nISLAS ESPUMA\\12POLICÍA C. FUCSIA",
  ["4e:53eb"] = "Un miembro del\\\nALTO MANDO era el\\12LÍDER del GIMNASIO\\\nde CIUDAD FUCSIA.",
  ["4e:5429"] = "La hija de KOGA le\\\nha sucedido como\\12LÍDER del GIMNASIO\\\ncuando él se unió\\11al ALTO MANDO.",
  ["4e:5479"] = "La ZONA SAFARI\\\nestá cerrada. Da\\12pena, ya que es\\\nla mayor atracción\\11de CIUDAD FUCSIA.",
  ["4e:54c8"] = "CIUDAD FUCSIA\\12¡Mirad la CIUDAD\\\nFUCSIA! ¡La pasión\\11rosa!",
  ["4e:54f0"] = "LÍDER DEL GIMNASIO\\\nPOKéMON DE CIUDAD\\11FUCSIA: SACHIKO\\12La venenosa\\\nmaestra ninja.",
  ["4e:5531"] = "Aquí hay una\\\nnota…\\12El PUESTO GUARDA\\\nDE LA ZONA SAFARI\\12está cerrado hasta\\\nnuevo aviso.",
  ["4e:557b"] = "CASA DEL GUARDA\\\nDE LA ZONA SAFARI",
  ["4e:5596"] = "El GUARDA está\\\nde viaje. Ésa es\\12la razón por la\\\nque la ZONA SAFARI\\11está cerrada.",
  ["4e:55dd"] = "No ensuciar.\\12Por favor, no\\\ntirar basura.",
  ["4e:56d3"] = "Si estás buscando\\\nPOKéMON, mira\\12en las zonas de\\\nhierba alta.",
  ["4e:5713"] = "¡Ayyyy!",
  ["4e:571c"] = "Siendo tan fuerte,\\\ndebe de ser muy\\11divertido luchar.",
  ["4e:574e"] = "El CAMINO BICIS es\\\nun atajo a CIUDAD\\11AZULONA.",
  ["4e:577c"] = "¡Uau…!",
  ["4e:5784"] = "Si no tienes una\\\nBICI, no podrás\\12usar el atajo.",
  ["4e:57c8"] = "RUTA 18\\12CIUDAD AZULONA -\\\nCIUDAD FUCSIA",
  ["4e:587f"] = "¡Eh, tú! Eres de\\\nJOHTO, ¿verdad?",
  ["4e:58a1"] = "¡Venga, golpea!",
  ["4e:58b2"] = "¡No seas chulo,\\\npunki de JOHTO!",
  ["4e:58d3"] = "¡Uau! ¡Qué BICI\\\nmás guay!",
  ["4e:58ef"] = "Pero tú no\\\npareces guay…",
  ["4e:590d"] = "Soy guay, pero\\\nestoy débil. Por\\11eso no lo parezco.\\12Debería entrenar\\\nmucho más…",
  ["4e:5957"] = "¡Eh! ¿Un combate\\\nrapidito?",
  ["4e:597a"] = "¡Vaya! ¡Qué\\\nvitalidad!",
  ["4e:599c"] = "Montar sin manos\\\nen el CAMINO BICIS\\11es muy guay.",
  ["4e:59d3"] = "¡Somos estrellas\\\nde la carretera!",
  ["4e:59f1"] = "¡Arrrg! ¡Chocar y\\\narder!",
  ["4e:5a0a"] = "¡Conducir de forma\\\nimprudente causa\\12accidentes! ¡Ten\\\ncuidado!",
  ["4e:5aa6"] = "CAMINO BICIS\\12¡Cuesta abajo\\\npor la costa!",
  ["4e:5b3a"] = "Este POLIWRATH es\\\nmi compañero.\\12Me pregunto si\\\nalgún día\\12evolucionará en\\\nuna rana POKéMON.",
  ["4e:5b88"] = "POLIWRATH: ¡Polii!",
  ["4e:5b9b"] = "Volví a perder en\\\nlas tragaperras.\\12Las chicas también\\\njugamos a las\\12tragaperras.\\\nPrueba tú también.",
  ["4e:5c00"] = "Últimamente han\\\naparecido GRIMER.\\12¿Ves esa charca\\\nque hay delante de\\12la casa? Ahí\\\nviven GRIMER.\\12¿De dónde han\\\nvenido? Es un\\11grave problema…",
  ["4e:5c99"] = "¡Bravo! ¡Este\\\nGIMNASIO es\\12genial! ¡Es sólo\\\npara chicas!",
  ["4e:5cd2"] = "¿Te cuento\\\nun secreto?\\12La MANSIÓN AZULONA\\\ntiene una puerta\\11trasera secreta.",
  ["4e:5d12"] = "Hay un concurso\\\nde tragones\\11en el restaurante.\\12Sólo verlo hace\\\nque me sienta\\11lleno…",
  ["4e:5d7a"] = "El C. COMERCIAL\\\nde CIUDAD AZULONA\\12dispone de los\\\nmejores artículos.\\12Si no encuentras\\\nalgo aquí, no lo\\12encontrarás en\\\nningún otro sitio.\\12¡Vaya…! Parezco\\\nuna vendedora.",
  ["4e:5e18"] = "Me he mareado de\\\nir mirando al\\12suelo mientras\\\ncaminaba.",
  ["4e:5e52"] = "CIUDAD AZULONA\\12La ciudad de los\\\nsueños de arcoiris",
  ["4e:5e7b"] = "LÍDER DEL GIMNASIO\\\nPOKéMON DE\\12CIUDAD AZULONA:\\\nERIKA\\12La princesa amante\\\nde la naturaleza",
  ["4e:5ebb"] = "¡Encuentra lo que\\\nnecesitas en el\\12CENTRO COMERCIAL\\\nDE CIUDAD AZULONA!",
  ["4e:5ee6"] = "MANSIÓN AZULONA",
  ["4e:5ef7"] = "CASINO DE CIUDAD\\\nAZULONA: Zona de\\11juego para todos",
  ["4e:5f2a"] = "PISTAS ENTRENADOR\\12PROTEC. ESP\\\nprotege a los\\12POKéMON de\\\nataques ESPECIALES\\11como fuego y agua.\\12¡Consigue los\\\nobjetos en el\\12CENTRO COMERCIAL\\\nde CIUDAD AZULONA!",
  ["4e:6081"] = "¿Y este cartel?\\12Algunos\\\nentrenadores han\\12estado luchando en\\\nVÍA SUBTERRÁNEA.\\12Tras numerosas\\\nquejas de los\\12vecinos, la VÍA\\\nSUBTERRÁNEA ha\\12sido cerrada\\\nindefinidamente.\\12POLICÍA C. AZULONA",
  ["4e:614f"] = "Está cerrada…",
  ["4f:407f"] = "¿Has olvidado\\\nalgo?",
  ["4f:409d"] = "¡Kiaaa!",
  ["4f:40a6"] = "Antes de ser\\\nmaestra, solía\\12olvidarme de\\\nmuchas cosas.",
  ["4f:40e4"] = "Creo que si hace\\\nsol, los niños\\12deberían estar\\\njugando en el\\12patio en lugar\\\nde estar en clase.",
  ["4f:414c"] = "No quería\\\nperder…",
  ["4f:4163"] = "Es importante\\\nestudiar, pero\\12hacer deporte\\\ntambién.",
  ["4f:419c"] = "Espera. Tengo que\\\nllamar a mamá.",
  ["4f:41be"] = "¡Lo siento, mamá!\\\n¡Me han vencido!",
  ["4f:41d9"] = "Mi madre se\\\npreocupa mucho por\\12mí, tengo que\\\nllamarla siempre.",
  ["4f:421d"] = "Luchemos.\\\n¡No perderé!",
  ["4f:4238"] = "¡Me olvidé de\\\nhacer los deberes!",
  ["4f:4255"] = "¡Sayonara! Lo he\\\naprendido en la\\11clase de japonés.",
  ["4f:428a"] = "Vamos a la TORRE\\\nRADIO de LAVANDA\\12para realizar unos\\\nestudios sociales.",
  ["4f:42cc"] = "¡Eres demasiado\\\nduro!",
  ["4f:42e3"] = "Estoy cansado de\\\ncaminar. Necesito\\11un descanso.",
  ["4f:4313"] = "¡Mi asignatura\\\nfavorita es la\\11gimnasia!",
  ["4f:432e"] = "¡Oh, no! ¿Cómo he\\\npodido perder?",
  ["4f:4349"] = "¡Si los POKéMON\\\nfueran una\\12asignatura, yo\\\nsería el mejor!",
  ["4f:437c"] = "RUTA 15\\12CIUDAD FUCSIA -\\\nPUEBLO LAVANDA",
  ["4f:4458"] = "Que sepas que\\\nme costó mucho\\12atrapar a mis\\\nqueridos POKéMON.",
  ["4f:4495"] = "¡Auuuu!",
  ["4f:449e"] = "SQUIRTLE, CHARMAN-\\\nDER y BULBASAUR.\\12Creo que es una\\\nbuena combinación.",
  ["4f:44e8"] = "Mi sueño es volar\\\ncon mi querido\\11POKéMON pájaro.",
  ["4f:4517"] = "Puedo soñar, pero\\\nnunca podré volar.",
  ["4f:453a"] = "¿Tienes POKéMON\\\nque conozcan la\\12MO VUELO? ¿Sí?\\\n¡Qué envidia!",
  ["4f:457a"] = "¿Has luchado\\\ncon todos los\\12entrenadores\\\nde GIMNASIO?",
  ["4f:45a0"] = "¡Oh! ¡Demasiado\\\nfuerte para mí!",
  ["4f:45bd"] = "Las MEDALLAS de\\\nKANTO te ayudarán\\12en los combates\\\ncon el CABLE LINK.",
  ["4f:46a7"] = "¡Arrodíllate ante\\\nmi regio POKéMON!",
  ["4f:46c7"] = "¿Qué? ¡Te burlas\\\nde la realeza!",
  ["4f:46e8"] = "¿Acaso no quiere\\\nser rey todo\\11el mundo?",
  ["4f:4714"] = "¡Jijiji! ¿Quieres\\\nluchar contra mi\\11grupo de PIKACHU?",
  ["4f:4747"] = "¡PI, PIKACHU!",
  ["4f:4754"] = "Parece que tienes\\\nmuchos POKéMON,\\12pero PIKACHU es\\\nel mejor.",
  ["4f:4796"] = "La agilidad es\\\nla clave de los\\11POKéMON pájaro.",
  ["4f:47c2"] = "Me venciste con\\\ntu velocidad…",
  ["4f:47e0"] = "Tus POKéMON\\\nestán muy bien\\11entrenados.",
  ["4f:4809"] = "Mira mis\\\nPOKéMON. Fíjate\\12en su color y\\\nen su plumaje.",
  ["4f:484e"] = "¡Vaya! ¡No soy lo\\\nbastante bueno!",
  ["4f:4867"] = "Los POKéMON son\\\nfelices si los\\11pones guapos.",
  ["4f:488b"] = "Debería ir al\\\nTÚNEL ROCA para\\11conseguir un ONIX.",
  ["4f:48be"] = "He perdido…",
  ["4f:48c7"] = "Parece que las\\\nformas geológicas\\11no cambian.\\12Pero sí que\\\ncambian, aunque\\11poco a poco.",
  ["4f:4921"] = "PISTAS ENTRENADOR\\12¡Mira! Allí, a\\\nla izquierda\\11del poste.",
  ["4f:4960"] = "RUTA 13 HACIA EL\\12NORTE AL PUENTE\\\nSILENCIO",
  ["4f:4982"] = "HACIA EL NORTE\\\nAL PUEBLO LAVANDA\\12HACIA EL OESTE\\\nA CIUDAD FUCSIA",
  ["4f:4a69"] = "La paciencia es la\\\nclave para pescar\\11y criar POKéMON.",
  ["4f:4a9a"] = "¡Guaaa!",
  ["4f:4aa3"] = "No tengo paciencia\\\npara la pesca…",
  ["4f:4ac2"] = "Me gusta pescar\\\nmientras escucho\\12canciones por\\\nla radio.",
  ["4f:4b0b"] = "¡Mi estúpida radio\\\nme ha distraído!",
  ["4f:4b2b"] = "¿Conoces las\\\nemisoras de\\12radio de KANTO?\\\nTenemos muchas.",
  ["4f:4b74"] = "¿Qué es lo más\\\nimportante en\\11nuestras vidas?",
  ["4f:4ba5"] = "¡La respuesta\\\nvendrá luego!",
  ["4f:4bc4"] = "Creo que la\\\nelectricidad es lo\\12más importante en\\\nnuestras vidas.\\12Si no lo fuera, no\\\nse habría montado\\12tanto follón\\\ncuando se estropeó\\12la CENTRAL\\\nde ENERGÍA.",
  ["4f:4c6b"] = "¿Te acuerdas?",
  ["4f:4c7d"] = "Te acuerdas, ¿no?",
  ["4f:4c8f"] = "El tirón de la\\\nCAÑA cuando ha\\12picado un\\\nPOKéMON…\\12Ésa es la mejor\\\nsensación para un\\11pescador como yo.",
  ["4f:4cf7"] = "RUTA 12\\12PUEBLO LAVANDA\\\nHACIA EL NORTE",
  ["4f:4d18"] = "COTO DE PESCA",
  ["4f:4de8"] = "No se puede hacer\\\ntrampa en POKéMON.\\12¡Que quede bien\\\nclaro!",
  ["4f:4e25"] = "¿Qué? ¿Cómo ha\\\npodido ocurrir?",
  ["4f:4e40"] = "He luchado con\\\nhonor.\\12No me\\\navergüenzo.",
  ["4f:4e81"] = "Cuando llevo\\\npantalones cortos\\12por la hierba, me\\\npican las piernas.",
  ["4f:4ebf"] = "¡Ayyyy!\\\n¡Me han pisado!",
  ["4f:4ed8"] = "Voy a capturar\\\nmás POKéMON en\\11la hierba.",
  ["4f:4f03"] = "…",
  ["4f:4f06"] = "…",
  ["4f:4f09"] = "…\\12Perdí cuando tenía\\\nlos ojos cerrados.",
  ["4f:4f2f"] = "Ya veo…\\12Todo lo que hay\\\nque ver de ti…",
  ["4f:4f5b"] = "No me imaginaba\\\ntu poder…",
  ["4f:4f7a"] = "Fuerza de\\\nconvicción…\\12Eres fuerte porque\\\nconfías en tus\\11POKéMON.",
  ["4f:4fc6"] = "RUTA 11",
  ["4f:5048"] = "Menudo\\\nedificio, ¿eh?\\12Es la TORRE de\\\nRADIO de KANTO.",
  ["4f:5080"] = "KANTO tiene muchos\\\nprogramas buenos.",
  ["4f:50a2"] = "Viene gente de\\\ntodas partes a\\12rendir homenaje\\\na las almas de\\12los POKéMON\\\nque han partido.",
  ["4f:50f2"] = "Para despertar a\\\nlos POKéMON,\\12sintoniza FLAUTA\\\nPOKéMON.\\12¡Todo entrenador\\\ndebería saberlo!",
  ["4f:513d"] = "PUEBLO LAVANDA\\12El noble pueblo\\\npúrpura",
  ["4f:5162"] = "EMISORA DE\\\nKANTO\\12¡Tus programas\\\nfavoritos a\\11cualquier hora!",
  ["4f:51a7"] = "CASA POKéMON\\\nDE VOLUNTARIOS DE\\11PUEBLO LAVANDA",
  ["4f:51c6"] = "CEMENTERIO\\12Que las almas de\\\nlos POKéMON\\11descansen en paz",
  ["4f:5308"] = "CIUDAD CARMÍN\\\nes el puerto\\12más importante\\\nde KANTO.\\12En él atracan\\\nlujosos\\12transatlánticos\\\nde todo el mundo.",
  ["4f:5362"] = "Mi POKéMON está\\\npreparando el\\12terreno donde\\\nedificar.\\12Pero no tengo\\\ndinero para el\\11proyecto…",
  ["4f:53bd"] = "MACHOP: ¡Machop\\\nmachop!",
  ["4f:53d5"] = "Un MACHOP gruñe\\\nmientras pisotea\\11el suelo.",
  ["4f:540d"] = "En KANTO hay ocho\\\nGIMNASIOS.\\12Ese gran edificio\\\nes el GIMNASIO\\12POKéMON de CIUDAD\\\nCARMÍN.",
  ["4f:5457"] = "SNORLAX duerme\\\nplácidamente…",
  ["4f:5477"] = "El POKéGEAR está\\\ncerca del\\11SNORLAX dormido.\\12…\\12¡SNORLAX se\\\ndespertó!",
  ["4f:54bb"] = "Los entrenadores\\\nexpertos se reúnen\\11en KANTO.\\12Los LÍDERES de\\\nGIMNASIO son\\11muy fuertes.\\12No serán fáciles\\\nde vencer.",
  ["4f:551e"] = "¿Has conseguido ya\\\nalguna MEDALLA de\\11GIMNASIO de KANTO?\\12¿A que los\\\nentrenadores\\12de KANTO son\\\nmuy fuertes?",
  ["4f:557b"] = "Supongo que pronto\\\nhabrás conseguido\\12todas las MEDALLAS\\\nde KANTO.\\12Cuando tengas\\\nlas ocho MEDALLAS,\\11dímelo.",
  ["4f:55e6"] = "¡Enhorabuena!\\12Tienes todas las\\\nMEDALLAS de KANTO.\\12Te recompensaré\\\npor tu esfuerzo.",
  ["4f:563d"] = "Llevar distintos\\\ntipos de POKéMON\\12te debería ayudar\\\nen el combate.\\12Seguro que las\\\nMEDALLAS de KANTO\\11te ayudarán.",
  ["4f:56ac"] = "CIUDAD CARMÍN\\12El puerto de los\\\nocasos exquisitos",
  ["4f:56da"] = "LÍDER DEL GIMNASIO\\\nPOKéMON DE LA\\12CIUDAD CARMÍN:\\\nLT. SURGE\\12El Rayo\\\nAmericano",
  ["4f:571b"] = "CLUB DE FANS\\\nDE POKéMON\\11¡Bienvenidos!",
  ["4f:5741"] = "CUEVA DIGLETT",
  ["4f:5751"] = "ENTRADA AL PUERTO\\\nCARMÍN",
  ["4f:5820"] = "La carretera está\\\ncortada hasta que\\12arreglen la\\\nCENTRAL ENERGÍA.",
  ["4f:5864"] = "VÍA SUBTERRÁNEA\\12CIUDAD CELESTE -\\\nCIUDAD CARMÍN",
  ["4f:5923"] = "Aquí vive una niña\\\nque es experta en\\12imitar a la\\\ngente.\\12Imita incluso a\\\nla gente con\\12la que habla,\\\ny te confunde.",
  ["4f:59a3"] = "La COPIONA parecía\\\nmuy triste.\\12Había perdido\\\nsu POKé MUÑECO\\11CLEFAIRY favorito.",
  ["4f:59f6"] = "¿Eres de\\\nJOHTO?\\12Si funcionara el\\\nMAGNETOTRÉN, no\\12tardarías nada en\\\nvolver a casa.",
  ["4f:5a44"] = "¿Eres de\\\nJOHTO?\\12Con el MAGNETOTRÉN\\\nenseguida estarás\\11en casa.",
  ["4f:5a94"] = "Iba al GIMNASIO\\\na luchar contra\\11entrenadores…\\12Y acabé en el\\\nviejo GIMNASIO\\12que hay\\\nal lado.\\12¡Chico, qué\\\nvergüenza pasé!",
  ["4f:5b24"] = "Es SILPH S.A.,\\\nfamosa por sus\\11artículos POKéMON.\\12En el pasado, el\\\nTEAM ROCKET quiso\\12hacerse con esta\\\ncompañía por esa\\11misma razón.",
  ["4f:5b92"] = "¡Ñam… ñam…!\\12Dicen que en la\\\nCENTRAL de ENERGÍA\\12tienen muchos\\\nproblemas.\\12¡Ñam… ñam…!",
  ["4f:5be1"] = "¡Ñam… ñam…!\\12Dicen que hay\\\nproblemas en la\\11CENTRAL ENERGÍA.\\12¡Ñam… ñam…!\\\n¡Estoy lleno!",
  ["4f:5c3b"] = "Entrar por primera\\\nvez en un callejón\\12me pone un\\\npoco nervioso.",
  ["4f:5c7b"] = "En CIUDAD VERDE\\\nhay un lugar\\12llamado la CASA\\\ndel ENTRENADOR,\\12donde se reúne\\\ngente de todas\\11partes.",
  ["4f:5cdb"] = "Nuestra ciudad\\\nsalió en un\\11programa de radio.\\12Está bien oír\\\nalabanzas sobre tu\\12ciudad, pero\\\ntambién da un poco\\11de vergüenza.",
  ["4f:5d4d"] = "CIUDAD AZAFRÁN\\12La brillante y\\\ndorada tierra del\\11comercio",
  ["4f:5d7c"] = "LÍDER DEL GIMNASIO\\\nPOKéMON DE CIUDAD\\11AZAFRÁN: SABRINA\\12Maestra de los\\\nPOKéMON psíquicos",
  ["4f:5dbf"] = "¡Bienvenidos!\\\nDOJO-KARATE",
  ["4f:5de0"] = "EDIFICIO-OFICINAS\\\nSILPH S.A.",
  ["4f:5dfb"] = "CASA DEL\\\nSR. PSÍQUICO",
  ["4f:5e0f"] = "ESTACIÓN DEL\\\nMAGNETOTRÉN DE\\11CIUDAD AZAFRÁN",
  ["4f:5f1e"] = "La carretera está\\\ncortada hasta que\\12arreglen la\\\nCENTRAL ENERGÍA.",
  ["4f:5f62"] = "VÍA SUBTERRÁNEA\\12CIUDAD CELESTE -\\\nCIUDAD CARMÍN",
  ["4f:5f93"] = "¿Qué es esto?\\12Casa en venta…\\\nNo vive nadie.",
  ["4f:60b0"] = "La CENTRAL de\\\nENERGÍA de KANTO\\12está al final de\\\nla RUTA 9. Hubo\\12una especie de\\\naccidente.",
  ["4f:610c"] = "¿Vas a atrapar\\\ntodos los tipos\\11de POKéMON?\\12Parece un gran\\\ndesafío, pero\\11será divertido.",
  ["4f:6170"] = "El CABO Norte es\\\nideal para llevar\\12a una chica.\\\n¡Les encanta!",
  ["4f:61b1"] = "SLOWBRO: ¿Slow?",
  ["4f:61c2"] = "¡Mi SLOWBRO y yo\\\nformamos un equipo\\11impresionante!",
  ["4f:61f1"] = "¡SLOWBRO, enséñame\\\ntu CONFUSIÓN!",
  ["4f:6213"] = "…",
  ["4f:6216"] = "Soy un gran\\\nseguidor de\\12la LÍDER MISTY\\\nde CIUDAD CELESTE.",
  ["4f:623d"] = "Vi a ese tipo\\\nsospechoso de\\12camino al CABO de\\\nCIUDAD CELESTE.",
  ["4f:6271"] = "Antes había una\\\ncueva aquí que\\12tenía POKéMON\\\nrealmente fuertes.",
  ["4f:62b6"] = "¡Caray!\\12Mi BUSCAOBJETOS\\\nresponde…",
  ["4f:62da"] = "CIUDAD CELESTE\\12Una misteriosa\\\naura azulada la\\11rodea",
  ["4f:630d"] = "LÍDER DEL GIMNASIO\\\nPOKéMON DE LA\\12CIUDAD CELESTE:\\\nMISTY\\12La Sirena\\\nDistorsionada",
  ["4f:6349"] = "Aquí hay una\\\nnota…\\12La TIENDA DE BICIS\\\nse ha trasladado a\\12CIUDAD TRIGAL, en\\\nJOHTO…",
  ["4f:6394"] = "Aquí hay una\\\nnota…\\12¡Acaba con los\\\nladrones y haz que\\12la ciudad sea más\\\ngrata y alegre!\\12POLICÍA C. CELESTE",
  ["4f:6403"] = "Hacia el\\\nCABO CELESTE",
  ["4f:6418"] = "Está cerrada…",
  ["50:4080"] = "He venido a\\\nexplorar el\\11TÚNEL ROCA.",
  ["50:40a0"] = "¡Uau! Peligro.",
  ["50:40b4"] = "Hirieron a mis\\\nPOKéMON antes\\12de entrar al\\\nTÚNEL ROCA.\\12Será mejor que los\\\nlleve ahora mismo\\12a un CENTRO\\\nPOKéMON.",
  ["50:411a"] = "¿Has ido alguna\\\nvez de picnic?\\12¡Es muy\\\ndivertido!",
  ["50:414f"] = "¡Ohhhh!",
  ["50:4157"] = "Hacemos dulces y\\\nlos repartimos\\12entre todos. ¡Son\\\ndeliciosos!",
  ["50:419d"] = "¡Eh, tú!\\\n¡No tires basura!",
  ["50:41b5"] = "Sólo estaba\\\ndiciendo que…",
  ["50:41d1"] = "Perdón. No estabas\\\ntirando basura. Me\\11he equivocado.",
  ["50:4202"] = "La gente no\\\ndebería dejar la\\11basura por ahí.",
  ["50:422c"] = "¡Ohh…! Perdí…",
  ["50:423a"] = "Es importante\\\nahorrar energía,\\12pues el entorno es\\\naún más vital.",
  ["50:4283"] = "Ella se desviará\\\npor MT. PLATEADO\\11cuando venga…\\12MT. PLATEADO está\\\nen JOHTO, ¿verdad?",
  ["50:42d2"] = "Estaba ocupado\\\ncantando…",
  ["50:42eb"] = "Los combates son\\\ncuestión de\\11concentración.",
  ["50:430d"] = "Te contaré un\\\nsecreto.\\12Pero primero,\\\n¡luchemos!",
  ["50:433b"] = "¡Caray!\\\nHe perdido…",
  ["50:4353"] = "La CENTRAL ENERGÍA\\\nestá al otro lado\\11de un riachuelo.",
  ["50:437d"] = "RUTA 9\\12CIUDAD CELESTE -\\\nTÚNEL ROCA",
  ["50:443b"] = "¡Eh, chico! ¡Un\\\nmiembro del TEAM\\11ROCKET ser yo!\\12Ser de otro país.\\\nEntrenador número\\11uno, ¡yo ése!\\12Pensar hice. Si\\\ncortar energía,\\12¡mucho pánico\\\naquí todos!\\12Misión secreta\\\nes, ¡no contar\\11a ti!\\12Pero, si ganar a\\\nmí, un hombre\\12soy y secreto mío\\\na ti contar.\\12¡Eh, chico!\\\n¡Lucha empezar!",
  ["50:4574"] = "¡Ayyyy! ¡No, no,\\\nno! ¡Creer no\\11puedo!\\12¡Fuerte mucho\\\neres! ¡Rival\\11para ti no soy!",
  ["50:45cd"] = "Vale. Secreto\\\ncontar a ti.\\12MAQUINARIA robar\\\nhice, en el GIM.\\12de CIUDAD\\\nCELESTE guardé.\\12En agua meter.\\\nEn el agua estar,\\12en el centro\\\ndel GIMNASIO.\\12¡Chico, olvidar\\\na mí, no!\\12TEAM ROCKET ganar\\\na ti seguro.\\12Amigos míos\\\nvenir de JOHTO.\\12Sí, venganza\\\nhabrá.",
  ["50:46f3"] = "…\\12¿Dices que TEAM\\\nROCKET adiós?\\12¿Roto? ¿Eso\\\ndices?\\12¡Oh, no! ¿Debo\\\nir por cuenta\\11mía ahora?",
  ["50:48e7"] = "MISTY: ¡Eh!\\\n¿Por qué\\12has venido a\\\nmolestarnos ahora?\\12¿Sabes cómo llaman\\\na la gente\\11como tú?\\12¡Pesados! Me has\\\noído bien, pesado.\\12…\\12¡Oh! Esas\\\nMEDALLAS… ¿Son\\12de los GIMNASIOS\\\nde JOHTO?\\12Si tienes ocho,\\\nserás muy bueno.\\12De acuerdo. Ven\\\nal GIMNASIO de\\11CIUDAD CELESTE.\\12Me enfrentaré a\\\nti encantada.\\12Soy MISTY, la\\\nLÍDER del GIMNASIO\\11de CIUDAD CELESTE.",
  ["50:4a2e"] = "¡Véncenos a los\\\nseis para ganar\\12un fantástico\\\npremio!\\12¿Lo conseguirás?",
  ["50:4a83"] = "¡Uau! Muy bien.",
  ["50:4a96"] = "Hice lo que pude.\\\nNo me arrepiento.",
  ["50:4ab9"] = "Ahora me toca a\\\nmí. ¡En guardia!",
  ["50:4ad6"] = "¿Cómo he\\\npodido perder?",
  ["50:4ae9"] = "Hice lo que pude.\\\nNo me arrepiento.",
  ["50:4b0c"] = "¡Soy el tercero!\\\nY no será fácil.",
  ["50:4b2a"] = "¡Au! ¡Se acabó!",
  ["50:4b3d"] = "Hice lo que pude.\\\nNo me arrepiento.",
  ["50:4b60"] = "¡Yo soy la cuarta!\\\n¿Cansado?",
  ["50:4b7a"] = "He perdido…",
  ["50:4b87"] = "Hice lo que pude.\\\nNo me arrepiento.",
  ["50:4baa"] = "Yo soy el quinto.\\\n¡Te machacaré!",
  ["50:4bc8"] = "¡Uau! Demasiado.",
  ["50:4bd9"] = "Hice lo que pude.\\\nNo me arrepiento.",
  ["50:4bfc"] = "Y por último yo,\\\npero te lo aviso,\\11¡soy la mejor!",
  ["50:4c2c"] = "¿Estás bromeando?",
  ["50:4c3c"] = "Hice lo que pude.\\\nNo me arrepiento.",
  ["50:4c5f"] = "¡Mufufufu…!\\12No tengo nada que\\\nver con los otros\\11seis entrenadores.\\12Pero he esperado a\\\nque estés cansado\\12de tanto pelear\\\npara vencerte.",
  ["50:4ce2"] = "¿No estás\\\ncansado?",
  ["50:4cfb"] = "Lo siento… No\\\nharé más trampas.",
  ["50:4d1c"] = "Tuviste que\\\nluchar una\\12vez más, pero\\\nganaste.\\12Como te prometí,\\\nel premio es tuyo.",
  ["50:4d7e"] = "Pero después de\\\nverte luchar, me\\12gustaría saber\\\ncómo me iría a mí.\\12Déjame luchar\\\ncontra ti.",
  ["50:4dde"] = "¡Nunca había visto\\\nnada igual!",
  ["50:4e01"] = "¡Ha sido\\\nfantástico!\\12Tus POKéMON y tú\\\nsois realmente\\11buenos.",
  ["50:4e48"] = "CASA DEL MAR\\\nCASA DE BILL",
  ["50:4f79"] = "¡Ah! Hace un\\\ntiempo estupendo.",
  ["50:4f9c"] = "Hace sol, pero\\\nestoy mojado…",
  ["50:4fb8"] = "Cuando llueve,\\\nes difícil\\11encenderlo…",
  ["50:4fe2"] = "¡Mmm…! No sé\\\nqué hacer…",
  ["50:5001"] = "Sabía que\\\nperdería…",
  ["50:5012"] = "Parecías fuerte.\\12Me daba miedo\\\ndesafiarte…",
  ["50:5043"] = "¡Puedo correr\\\ncomo el viento!",
  ["50:505d"] = "¡He perdido!",
  ["50:506a"] = "Siempre llevo\\\npantalones cortos.\\12Ésa es mi forma\\\nde vestir.",
  ["50:50a8"] = "¡Sube y echa\\\nun vistazo!",
  ["50:50c8"] = "¡Uau! ¡Eso quema!",
  ["50:50d9"] = "Soy el mejor\\\nCOMEFUEGOS de\\11KANTO.\\12Pero no el mejor\\\nentrenador…",
  ["50:5124"] = "PLAZA MT. MOON\\12Sube las\\\nescaleras",
  ["50:51d5"] = "Las noticias dicen\\\nque ha pasado algo\\11en la C. ENERGÍA.",
  ["50:520a"] = "¿Perdí? ¡Vaya\\\nnoticia!",
  ["50:5223"] = "Tengo que ir a la\\\nCENTRAL ENERGÍA.\\12¿Está cerca del\\\nTÚNEL ROCA?",
  ["50:525b"] = "Presiento que\\\npuedo ganar.\\12¡Veamos si\\\ntengo razón!",
  ["50:5293"] = "¡Uau! Eres\\\ndemasiado fuerte.",
  ["50:52ad"] = "Dicen que CLEFAIRY\\\naparece en el\\12MT. MOON.\\\n¿Pero dónde?",
  ["50:52eb"] = "¡Umm…!\\\nYo…",
  ["50:52f3"] = "…",
  ["50:52f6"] = "…Creo que seguiré\\\nentrenándome…",
  ["50:5311"] = "PLAZA MT. MOON\\12Sube las\\\nescaleras",
  ["50:53ef"] = "Somos el grupo de\\\nentrenadores de la\\12FEDERACIÓN POKéMON\\\nde KANTO.\\12¡Te vamos a\\\narrollar!",
  ["50:543f"] = "¡Lo…, lo siento!",
  ["50:5449"] = "¡Viva la\\\nFEDERACIÓN\\11POKéMON de KANTO!",
  ["50:5475"] = "Los polis han\\\ncerrado la VÍA\\12SUBTERRÁNEA. ¡Qué\\\nfastidio!",
  ["50:54b5"] = "¡Per…, perdóname!",
  ["50:54c4"] = "Destruido por\\\nun gamberro\\11de JOHTO…",
  ["50:54e8"] = "Somos la\\\nFEDERACIÓN\\12POKéMON de KANTO.\\\n¡Adelante, tío!",
  ["50:551b"] = "¡Vaya! ¡Perdona!",
  ["50:552a"] = "Intentaremos no\\\nmolestar a nadie\\11a partir de ahora.",
  ["50:5557"] = "¿Cómo funciona\\\nel MAGNETOTRÉN?",
  ["50:557a"] = "Quiero ver el\\\nMAGNETOTRÉN…",
  ["50:55a0"] = "¡El poder de los\\\nimanes es inmenso!",
  ["50:55c4"] = "Necesitamos\\\nelectricidad.\\12La CENTRAL ENERGÍA\\\nnos suministra la\\11electricidad.",
  ["50:5615"] = "¡No malgastes\\\nelectricidad!",
  ["50:562e"] = "La C. ENERGÍA, al\\\nnorte de LAVANDA,\\12suministra energía\\\nal MAGNETOTRÉN.",
  ["50:5675"] = "Está cerrada…",
  ["50:5682"] = "El cartel\\\nestá roto.\\12Es imposible\\\nleerlo…",
  ["50:571c"] = "CENTRAL DE\\\nENERGÍA DE KANTO",
  ["50:5776"] = "¡Ja, ja, ja!",
  ["50:5780"] = "¡Aaaaaaachís!",
  ["50:5790"] = "¡La alergia me\\\nhace estornudar!\\11¡AAACHÚS!",
  ["50:57bd"] = "Te gustan los\\\nPOKéMON, ¿verdad?\\12¡A mí también!",
  ["50:57df"] = "Tengo que decir\\\nque son mi ruina.",
  ["50:57fe"] = "Mira lo que\\\nhas hecho a\\11mis POKéMON.\\12No lo\\\nolvidaré…",
  ["50:5831"] = "RUTA 10\\12CIUDAD CELESTE -\\\nPUEBLO LAVANDA",
  ["50:588f"] = "MESETA AÑIL\\12¡El objetivo\\\nfinal de los\\11entrenadores!\\12El CG de la\\\nLIGA POKéMON",
  ["51:400e"] = "Los marineros son\\\nmuy generosos.\\12Uno enseñó FUERZA\\\na mi POKéMON y\\12ahora puede mover\\\ngrandes rocas.",
  ["51:4067"] = "Hay una persona en\\\nCIUDAD ORQUÍDEA,\\11cruzando el mar.\\12¡Dicen que\\\npresume de sus\\11raros POKéMON!",
  ["51:419a"] = "Gracias por\\\nayudarnos en el\\11FARO…\\12Pero esto es\\\ndistinto. Déjame\\11que me presente.\\12Soy YASMINA, una\\\nLÍDER de GIMNASIO.\\11Uso el tipo acero.\\12¿Sabes algo\\\ndel tipo acero?\\12Fue descubierto\\\nhace poco\\11tiempo.\\12¡Um…! ¡Veamos!",
  ["51:429c"] = "Eres mejor\\\nentrenador que yo,\\12tanto en habilidad\\\ncomo en simpatía.\\12De acuerdo con las\\\nnormas de la LIGA,\\12te concedo esta\\\nMEDALLA.",
  ["51:431b"] = "{PLAYER}\\\nrecibió la\\11MEDALLA MINERAL.",
  ["51:4335"] = "La MEDALLA MINERAL\\\naumenta la DEFENSA\\11de los POKéMON.\\12¡Eh…! Toma\\\nesto también…",
  ["51:4386"] = "Usa esta MT\\\npara enseñar\\11COLA FÉRREA.",
  ["51:43b2"] = "¡Eh…! No sé\\\ncómo decirlo, pero\\11buena suerte…",
  ["51:43e3"] = "YASMINA usa el\\\ntipo acero recién\\11descubierto.\\12No sé mucho\\\nsobre ese tipo.",
  ["51:4432"] = "Ha sido increíble.\\12¿El tipo acero,\\\neh?\\12¡Ha sido un gran\\\ncombate de un\\11tipo desconocido!",
  ["51:4489"] = "YASMINA, la LÍDER\\\ndel GIMNASIO, está\\11en el FARO.\\12Ha estado cuidando\\\na un POKéMON\\11enfermo.\\12Un buen entrenador\\\ndebe de ser\\11compasivo.",
  ["51:4583"] = "Cuando mis POKéMON\\\nenfermaron, el\\12FARMACÉUTICO de\\\nCIUDAD IRIS me\\11dio una medicina.",
  ["51:45d1"] = "RHYDON: ¡Rhydo!",
  ["51:4624"] = "De camino a CIUDAD\\\nORQUÍDEA, hay\\12cuatro islas\\\ndesiertas.\\12¡A los niños malos\\\nlos llevan a\\12las islas como\\\ncastigo!",
  ["51:4692"] = "Cuando me meto en\\\nlíos, papá siempre\\11se enfada.",
  ["51:472a"] = "¡CIUDAD OLIVO está\\\njunto al mar!\\12¡Y si está junto\\\nal mar, tiene que\\11haber peces!\\12Llevo 30 años\\\npescando aquí.\\12¿Quieres mirar\\\nal mar y\\11pescar?",
  ["51:47bc"] = "¡Ah, ja, ja!\\\n¡Ya tenemos un\\11nuevo pescador!",
  ["51:47e8"] = "No sólo hay peces\\\nen el mar. Puedes\\12encontrarlos allí\\\ndonde haya agua.",
  ["51:482d"] = "¿Quééé? ¿¡No te\\\ngusta pescar!?\\11¡Incomprensible!",
  ["51:4860"] = "¿Qué tal va todo?\\\n¿Pica el grande?",
  ["51:48bd"] = "¡Ajá! ¡Tus POKéMON\\\nparecen muy\\11débiles!\\12No son capaces\\\nde mover\\11rocas.\\12¡Toma! ¡Usa esto\\\ny enséñales\\11FUERZA!\\12Necesitas la\\\nMEDALLA TRIGAL\\12para usar FUERZA\\\nfuera del combate.",
  ["51:4980"] = "¡En el mar sólo\\\npuedes confiar\\11en ti mismo!\\12¡Y yo estoy en\\\nplena forma!",
  ["51:49e0"] = "¿Vas a cruzar el\\\nmar? Pues escucha:\\12hay torbellinos\\\nde camino hacia\\11CIUDAD ORQUÍDEA.\\12Para pasar los\\\ntorbellinos,\\12tienes que conocer\\\nun movimiento más.",
  ["51:4aaa"] = "¿Tus POKéMON saben\\\nun movimiento para\\12llevar personas\\\npor el agua?",
  ["51:4aec"] = "Mi BUTTERFREE ha\\\nestado con mi\\11novio.\\12Y me ha traído\\\nuna CARTA suya.\\12¿Quieres saber\\\nlo que dice?\\12Veamos… ¡No!\\\n¡Es un secreto!",
  ["51:4bb0"] = "¿De dónde has\\\ndicho que eras?\\12¿De PUEBLO\\\nPRIMAVERA?\\12El PROF. ELM vive\\\npor allí, ¿no?\\12Has recorrido un\\\nlargo camino.",
  ["51:4d04"] = "MUU-MUU está\\\nenferma…\\12Necesita muchas\\\nBAYAS.",
  ["51:4d30"] = "¡Estamos dando de\\\ncomer a MUU-MUU!",
  ["51:4d46"] = "MUU-MUU: ¡Muu…!",
  ["51:4d56"] = "Está débil…",
  ["51:4d68"] = "MILTANK: ¡MUU!",
  ["51:4d77"] = "¿Dar una BAYA a\\\nMUU-MUU?",
  ["51:4d91"] = "{PLAYER} dio una\\\nBAYA a MUU-MUU.",
  ["51:4dad"] = "¡MUU-MUU está un\\\npoco mejor!",
  ["51:4dd1"] = "¡MUU-MUU está\\\nmucho mejor!",
  ["51:4df0"] = "¡MUU-MUU se ha\\\nrecuperado!",
  ["51:4e11"] = "{PLAYER} no tiene\\\nBAYAS…",
  ["51:4e24"] = "{PLAYER} no le\\\nda una BAYA.\\12MUU-MUU parece\\\ntriste.",
  ["51:4f0d"] = "Mi MUU-MUU ya\\\nno me da\\11leche.\\12La leche de esta\\\nGRANJA es famosa.\\12Casi todos\\\nquieren probarla.\\12Supongo que si\\\nle doy muchas\\12BAYAS me dará\\\nmucha leche.",
  ["51:4fb7"] = "¿Te gusta mi\\\nLECHE MU-MU?\\12Es mi orgullo y\\\nmi alegría, hijo.\\12¡Dásela a los\\\nPOKéMON para\\11restaurar sus PS!\\12Tuya es por\\\nsólo 500¥.",
  ["51:5031"] = "¡Toma! ¡Bébetela\\\ny disfruta!",
  ["51:5050"] = "Lo siento, hijo.\\\n¡Si no hay dinero,\\11no hay trato!",
  ["51:506f"] = "Hijo, tu MOCHILA\\\nestá llena.",
  ["51:508e"] = "¿No la quieres?\\\nVuelve otro día.",
  ["51:50b3"] = "Mejor que me vaya\\\na ordeñar.",
  ["51:50cd"] = "Nuestra leche\\\nllega hasta KANTO.\\12Así que si nuestra\\\nMUU-MUU no nos da\\12leche, tendremos\\\nproblemas.",
  ["51:512d"] = "Has curado a\\\nnuestra MUU-MUU.\\12Ya vuelve a dar\\\nLECHE MU-MU.\\12Aquí tienes algo\\\nque te ayudará.",
  ["51:519e"] = "Esto es\\\nRONQUIDO.\\12Es un movimiento\\\nraro que sólo\\12funciona cuando el\\\nPOKéMON duerme.\\12Mejor que pienses\\\ncómo vas a\\11utilizarlo.",
  ["51:526c"] = "Dicen que ha\\\naparecido un\\12GYARADOS rojo\\\nen el LAGO.\\12¡Qué raro, porque\\\nen el lago no son\\12frecuentes ni los\\\nGYARADOS comunes!",
  ["51:52de"] = "¿Mi programa de\\\nradio favorito? La\\11MÚSICA POKéMON.",
  ["51:530d"] = "He estado oyendo\\\nrisas en la\\12radio… Es\\\nespeluznante.",
  ["51:545d"] = "Los POKéMON viven\\\ntodo tipo de\\11experiencias.\\12Yo también he\\\nvisto y sufrido\\11mucho en mi vida.\\12Soy más mayor, así\\\nque te enseñaré lo\\11que quiero decir.\\12He estado con los\\\nPOKéMON desde\\12antes de que tú\\\nnacieras.\\12Y no pierdo\\\nfácilmente.\\12¡Yo, FREDO, el\\\nentrenador del\\12invierno, te\\\nmostraré mi poder!",
  ["51:5583"] = "¡Ah! Me impresiona\\\ntu valor.\\12Con tu gran\\\nvoluntad, sé que\\12superarás todos\\\nlos obstáculos.\\12¡Te mereces\\\nesta MEDALLA!",
  ["51:560b"] = "{PLAYER}\\\nrecibió la\\11MEDALLA GLACIAR.",
  ["51:5625"] = "Esta MEDALLA sube\\\nlas habilidades\\12ESPECIALES de los\\\nPOKéMON.\\12Y tus POKéMON\\\nusarán TORBELLINO\\12para pasar los\\\ntorbellinos.\\12¡Además, te voy\\\na hacer un regalo!",
  ["51:56bf"] = "Esta MT contiene\\\nVIENTO HIELO.\\12Causa daño y baja\\\nla velocidad.\\12Demuestra la\\\ndureza del\\11invierno.",
  ["51:5729"] = "La primavera llega\\\ncuando se derrite\\12el hielo y la\\\nnieve.\\12Tú y tus POKéMON\\\npasaréis juntos\\11muchos años.\\12¡Pasadlo\\\nbien!",
  ["51:57b1"] = "¡Congelaré a tus\\\nPOKéMON! ¡No\\11podrás hacer nada!",
  ["51:57e0"] = "Maldición. No\\\npude hacer nada.",
  ["51:57fd"] = "Hay un movimiento\\\nque se puede usar\\12cuando el POKéMON\\\nestá congelado.",
  ["51:5835"] = "Este GIMNASIO\\\ntiene un suelo\\12resbaladizo. ¿A\\\nque es divertido?\\12¡Pero oye, aquí\\\nno estamos\\11jugando!",
  ["51:588d"] = "¿Ves lo serios\\\nque somos?",
  ["51:58ad"] = "Este GIMNASIO es\\\ngenial. ¡Me\\12encanta patinar\\\ncon mis POKéMON!",
  ["51:58df"] = "Conozco el secreto\\\nde FREDO.",
  ["51:58f6"] = "Te contaré el\\\nsecreto de FREDO.",
  ["51:5917"] = "El secreto del\\\npoder de FREDO…\\12Medita todos los\\\ndías bajo una\\12cascada para\\\nmejorar su cuerpo\\11y su mente.",
  ["51:597e"] = "Para vencer a\\\nFREDO, el LÍDER\\12del GIM., piensa\\\nantes de patinar.",
  ["51:59c4"] = "¡No perderé ante\\\nti esquiando!",
  ["51:59e6"] = "Si no patinas con\\\nprecisión, no\\12lograrás nada en\\\neste GIMNASIO.",
  ["51:5a27"] = "¡Mira qué bien\\\nesquío!",
  ["51:5a44"] = "¡No! ¡He perdido!",
  ["51:5a5f"] = "No debería haber\\\npresumido sobre mi\\11forma de esquiar.",
  ["51:5a8f"] = "FREDO es veterano.\\\nLleva entrenando\\12POKéMON desde\\\nhace 50 años.\\12Dicen que es bueno\\\ncongelando a sus\\12rivales con los\\\nataques de hielo.\\12¡Eso quiere decir\\\nque deberías\\12derretirle con tu\\\nardiente ambición!",
  ["51:5b45"] = "¡FREDO es bueno,\\\npero tú eres\\11aún mejor!\\12¡Ha sido un gran\\\ncombate que acortó\\12distancias entre\\\ngeneraciones!",
  ["51:5c32"] = "¿Qué pasa?\\\n¿Ha vuelto el\\11TEAM ROCKET?\\12He visto hombres\\\nde negro en el\\11LAGO DE LA FURIA.",
  ["51:5c83"] = "No permito que\\\nmis POKéMON\\12evolucionen\\\ndemasiado pronto.\\12Antes de dejarles\\\nevolucionar, les\\12enseño algunos\\\nmovimientos.",
  ["51:5ce8"] = "Al evolucionar,\\\nlos POKéMON se\\12fortalecen, pero\\\ntardan más en\\11aprender ataques.",
  ["51:5d88"] = "MONTE MORTERO es\\\ncomo un laberinto.\\12Ten cuidado. No\\\nte pierdas.",
  ["52:406c"] = "Sin la MEDALLA\\\ndel GIMNASIO de\\12CIUDAD IRIS, no se\\\nentra en la TORRE\\12HOJALATA. ¡Vaya,\\\ntendrás que irte!",
  ["52:40cc"] = "Sin la MEDALLA\\\nde CIUDAD IRIS,\\12no se entra en\\\nTORRE HOJALATA.\\12¡Ah!\\12¡La MEDALLA de\\\nla CIUDAD IRIS!\\11Puedes pasar.",
  ["52:413f"] = "La TORRE HOJALATA\\\nse construyó como\\12morada para los\\\nPOKéMON voladores.",
  ["52:417d"] = "¡La TORRE HOJALATA\\\nse ha movido! ¡Se\\12habrá posado un\\\nPOKéMON arriba!",
  ["52:41b9"] = "Dos torres…\\\nDos POKéMON…\\12Pero cuando una\\\nse quemó, los dos\\12POKéMON huyeron\\\ny nunca volvieron.",
  ["52:4304"] = "Hola, soy BILL.\\\n¿Quién eres tú?\\12¿Eh? {PLAYER}.\\\n¡Has llegado\\11justo a tiempo!",
  ["52:434e"] = "Ya he terminado de\\\najustar la CÁPSULA\\11del TIEMPO.\\12Sabes que puedes\\\ncambiar POKéMON,\\11¿verdad?\\12Mi CÁPSULA del\\\nTIEMPO sirve para\\12cambiar POKéMON\\\ncon el pasado.\\12Pero no podrás\\\nenviar nada que\\12no existiera en\\\nel pasado.\\12Si lo haces, el PC\\\ndel pasado podría\\11estropearse.\\12Así que debes\\\neliminar cualquier\\12cosa que no\\\nexistiera antes.\\12Esto es, no envíes\\\nnuevos movimientos\\12o nuevos POKéMON\\\na esta CÁPSULA.\\12No te preocupes.\\\nYa he acabado\\11de ajustarla.\\12Mañana funcionarán\\\ntodas las CÁPSULAS\\12del TIEMPO de los\\\nCENTROS POKéMON.\\12Debo volver pronto\\\na CIUDAD TRIGAL.\\11Mi familia espera.\\12¡Hasta luego!",
  ["52:4581"] = "Las CHICAS KIMONO\\\nson unas geniales\\12bailarinas, además\\\nde magníficas\\11con sus POKéMON.",
  ["52:45d6"] = "MORTI, el LÍDER\\\ndel GIMNASIO, es\\11muy bueno.\\12Y sus POKéMON\\\nson muy fuertes.",
  ["52:461c"] = "LAGO DE LA FURIA.\\12Un montón de\\\nGYARADOS…\\12¡Esto huele a\\\nconspiración!",
  ["52:46d3"] = "Sucedió cuando\\\nera joven.\\12El cielo se\\\noscureció de\\12repente. Un enorme\\\nPOKéMON estaba\\11tapando el sol.\\12Me pregunto qué\\\nsería ese POKéMON,\\12mezcla de pájaro\\\ny dragón.",
  ["52:4782"] = "¿Existe un POKéMON\\\ntan grande? Si\\12existe, debe de\\\nser muy fuerte.",
  ["52:48b8"] = "Tus POKéMON son\\\nencantadores.\\11¿Cómo luchan?",
  ["52:48e9"] = "¡Oh! ¡Eres muy\\\nfuerte!",
  ["52:4903"] = "Me ha gustado el\\\ncombate. Espero\\11volver a verte.",
  ["52:4938"] = "Yo siempre bailo\\\ncon mis POKéMON.\\12Y también los\\\nentreno, claro.",
  ["52:4974"] = "¡Estuve cerca!\\\nPor poco te venzo.",
  ["52:4995"] = "El ritmo es muy\\\nimportante para\\12la danza y para\\\nlos POKéMON.",
  ["52:49c9"] = "¿Te gusta\\\nmi pasador?\\12¡Ah! ¿Un combate\\\nPOKéMON?",
  ["52:49f6"] = "No me queda ningún\\\nPOKéMON…",
  ["52:4a12"] = "Cada mes pongo\\\nuna flor nueva\\11en mi pasador.",
  ["52:4a4a"] = "¡Oh! ¡Eres\\\ntan mono!\\11¿Quieres luchar?",
  ["52:4a7f"] = "Eres más fuerte de\\\nlo que pareces.",
  ["52:4a9e"] = "He entrenado mucho\\\ny creía que tenía\\12posibilidades,\\\npero no.",
  ["52:4ae6"] = "¿Te gusta como\\\nbailo? Y también\\12soy hábil con\\\nlos POKéMON.",
  ["52:4b14"] = "¡Oh! ¡Tú también\\\neres bueno!",
  ["52:4b32"] = "Sigo bailando\\\nporque hay gente\\12a la que le gusta\\\nlo que hago.\\12Mis POKéMON\\\nme animan.",
  ["52:4b94"] = "Las CHICAS KIMONO\\\nno sólo bailan.\\12También son\\\nextraordinarias\\11con los POKéMON.\\12Yo siempre las\\\ndesafío pero nunca\\12les he hecho\\\nni un rasguño…",
  ["52:4c1b"] = "¡Chico! Si vences\\\na todas las CHICAS\\12KIMONO, te daré\\\nun regalo.",
  ["52:4c5e"] = "Verte luchar ha\\\nsido como ver\\11una danza.\\12¡Ha sido un\\\nextraño combate!\\12Me gustaría darte\\\nesto. Adelante,\\11¡tuyo es!",
  ["52:4cdf"] = "Es SURF.\\12Un movimiento\\\nque permite nadar\\11a los POKéMON.",
  ["52:4d19"] = "Ojalá mis POKéMON\\\nfueran tan\\12elegantes como las\\\nCHICAS KIMONO…",
  ["52:4d4e"] = "RHYDON: ¡Rhydo,\\\nrhydo!",
  ["52:4d68"] = "Ese hombre siempre\\\nva con su RHYDON.\\12Dice que quiere un\\\nPOKéMON que baile\\11y haga SURF.\\12¿Intenta crear\\\nun POKéMON que\\12haga natación\\\nsincronizada?",
  ["52:4dee"] = "Las CHICAS KIMONO\\\nson tan guapas…\\12Pero tienen que\\\nentrenar mucho.\\12Y deben aprender\\\nlos distintos\\12bailes antes\\\nde actuar.\\12Pero si te gusta\\\nalgo, todo\\11es posible.",
  ["52:4ebd"] = "Es un elegante\\\npanel decorado\\11con flores.",
  ["52:4f8c"] = "Mi EEVEE\\\nevolucionó en\\11ESPEON.\\12Pero el EEVEE\\\nde mi amigo\\12evolucionó en\\\nUMBREON.\\12No sé por qué. Los\\\ndos educamos a\\12nuestros EEVEE de\\\nla misma forma…",
  ["52:5019"] = "Si usas REVIVIR,\\\nel POKéMON\\12debilitado se\\\nreanimará.",
  ["52:516b"] = "Me alegro de que\\\nhayas venido.\\12En CIUDAD IRIS,\\\nveneramos a los\\11POKéMON.\\12Dicen que a los\\\nentrenadores más\\12fuertes se les\\\naparecerán los\\12POKéMON\\\nlegendarios.\\12Yo lo creo y he\\\nentrenado aquí\\12en secreto toda\\\nmi vida.\\12Por eso, ahora\\\nveo lo que otros\\11no ven.\\12Un poco más…\\12Un poco más y\\\nen el futuro\\12encontraré a\\\nlos POKéMON\\11legendarios.\\12¡Y tú me vas a\\\nayudar a llegar\\11a ese nivel!",
  ["52:52f4"] = "Aún no soy lo\\\nbastante bueno…\\12De acuerdo. Esta\\\nMEDALLA es tuya.",
  ["52:532d"] = "{PLAYER}\\\nrecibió la\\11MEDALLA NIEBLA.",
  ["52:5343"] = "Con la MEDALLA\\\nNIEBLA, te\\12obedecerán todos\\\nlos POKéMON\\11hasta el nivel 50.\\12Y los POKéMON\\\nque sepan SURF\\12podrán usarlo en\\\ncualquier momento.\\12Quédate con\\\nesto también.",
  ["52:53d6"] = "Es BOLA SOMBRA.\\\nCausa daños y\\12puede reducir la\\\nDEFENSA ESPECIAL.\\12Úsala si te\\\ngusta.",
  ["52:542f"] = "Entiendo…\\12Tu viaje te\\\nha llevado a\\11tierras lejanas.\\12Y has presenciado\\\nmuchas más cosas\\11que yo.\\12¡Cómo te\\\nenvidio…!",
  ["52:54a7"] = "Pasé la primavera\\\ncon mis POKéMON.\\12Y el verano, otoño\\\ne invierno.\\12Luego volvió la\\\nprimavera. Hemos\\12vivido juntos\\\nmucho tiempo.",
  ["52:5527"] = "Viví victorias\\\ny derrotas.",
  ["52:554d"] = "¿De dónde vienen\\\nlos POKéMON?",
  ["52:5568"] = "¿Puedes causar\\\nalgún daño a\\11nuestros POKéMON?",
  ["52:5591"] = "¡Ah! ¡Bien hecho!",
  ["52:55a1"] = "Sólo usamos\\\nPOKéMON fantasma.\\12¡Los ataques\\\nnormales no les\\11hacen daño!",
  ["52:55e5"] = "¡Ganaré!",
  ["52:55f3"] = "¡He… he perdido!",
  ["52:5602"] = "¡Ganará el que\\\nmás lo desee!",
  ["52:5628"] = "¿Atónito por el\\\nsuelo invisible?\\12¡Si quieres una\\\npista, vénceme!",
  ["52:5669"] = "¿Có-Cómo?",
  ["52:5674"] = "Bien. Te contaré\\\nel secreto\\12del suelo\\\ninvisible.\\12¡La ruta está\\\nenfrente de ti!",
  ["52:56d2"] = "Estos entrenadores\\\ntienen motivos\\11secretos.\\12Si les ganas,\\\npodrían contarte\\12algunos secretos\\\nsobre CIUDAD IRIS.",
  ["52:573c"] = "¡Uauu, {PLAYER}!\\\n¡Genial!\\12¡Me escondí en\\\nel rincón\\11muerto de miedo!",
  ["52:58cc"] = "¡Ah! ¿Vas de\\\naventura con tus\\11POKéMON?\\12¿Y qué es una\\\naventura sin\\11un tesoro?\\12¿Tengo razón\\\no no?",
  ["52:5945"] = "¡Bien! Entiendes\\\nel verdadero\\12espíritu de\\\nla aventura.\\12¡Me gusta!\\\nToma esto.",
  ["52:599e"] = "Por aquí hay\\\nmuchos objetos\\12que no se ven\\\ntan fácilmente.\\12Utiliza el\\\nBUSCAOBJETOS para\\12saber si hay algún\\\nobjeto cerca.\\12Éste no indica el\\\nlugar exacto, así\\12que tú tendrás\\\nque encontrarlo.\\12¡Ah, sí! Dicen que\\\nhay muchos objetos\\12en TORRE QUEMADA\\\nde CIUDAD IRIS.",
  ["52:5a95"] = "¡Oh! A cada uno lo\\\nsuyo, supongo…",
  ["52:5ab6"] = "HISTORIA de\\\nCIUDAD IRIS\\12¿Quieres leerla?",
  ["52:5adc"] = "En CIUDAD IRIS\\\nhabía dos torres.\\12Cada una acogía a\\\nun fuerte POKéMON\\11volador.\\12Pero una de\\\nellas se quemó.\\12Y desde entonces\\\nno se ha visto a\\12ninguno de los\\\ndos POKéMON.\\12¿Seguir leyendo?",
  ["52:5b92"] = "En CIUDAD IRIS\\\ntambién vivían\\12tres POKéMON\\\nque corrían por\\11toda la ciudad.\\12Dicen que habían\\\nnacido del agua,\\12del fuego y del\\\nrayo.\\12Pero como no\\\npodían contener su\\11enorme fuerza…\\12Huyeron hacia\\\nlos pastos.",
  ["53:40f3"] = "Soy DÉBORA, la\\\nmejor maestra\\12de dragones\\\ndel mundo.\\12No pueden conmigo\\\nni los miembros\\12del ALTO MANDO de\\\nla LIGA POKéMON.\\12¿Todavía quieres\\\nluchar conmigo?\\12Está bien.\\\n¡Luchemos!\\12¡Como entrenadora,\\\nusaré todo mi\\12poder contra\\\ncualquier rival!",
  ["53:41cf"] = "¿He perdido?\\12No puedo creerlo.\\\nHa debido de haber\\11algún error…",
  ["53:4207"] = "No lo\\\nadmitiré.\\12Habré perdido,\\\npero aún no estás\\12preparado para la\\\nLIGA POKéMON.\\12Lo sé. Deberías\\\nenfrentarte al\\12desafío de los\\\nque usan dragones.\\12Detrás de este\\\nGIMNASIO está la\\11GUARIDA DRAGÓN.\\12Ve allí y tráeme\\\nel COLMILLO de\\12DRAGÓN que hay\\\nen la GUARIDA.\\12Ésa es la prueba\\\nque debes aceptar\\12si de verdad usas\\\ndragones.\\12Si lo logras,\\\nte aceptaré\\11como entrenador.\\12Hasta entonces, no\\\nte daré ninguna\\11MEDALLA.",
  ["53:4391"] = "DÉBORA: ¿Cuál es\\\nel problema?\\12Esta prueba no te\\\ncostará, salvo que\\12hayas ganado\\\nde chiripa.",
  ["53:43f0"] = "DÉBORA: No has\\\nconseguido eso en\\11la GUARIDA DRAGÓN.\\12Estás haciendo\\\ntrampas…\\12Me has\\\ndecepcionado.",
  ["53:4451"] = "DÉBORA: Me has\\\ndemostrado lo que\\11vales.\\12Esta MT es\\\npara ti.",
  ["53:44a7"] = "Esta MT contiene\\\nDRAGOALIENTO.\\12No, no tiene\\\nnada que ver\\11con mi aliento.\\12Si no la quieres,\\\nno es necesario\\11que la aceptes.",
  ["53:4525"] = "Así que has\\\nconseguido todas\\11las MEDALLAS.\\12Ahora debes\\\ndirigirte a la\\12LIGA POKéMON\\\nde MESETA AÑIL.\\12¿Sabes cómo llegar\\\nhasta allí?\\12Desde aquí, ve a\\\nPUEBLO PRIMAVERA.\\12Luego haz SURF\\\nhacia el Este. Es\\11una ruta difícil.\\12¡Ni se te ocurra\\\nperder en la\\11LIGA POKéMON!\\12¡Si pierdes, me\\\nsentiré aún peor\\12por haber perdido\\\nante ti!",
  ["53:4651"] = "¿Tu primer combate\\\ncontra dragones?\\12¡Te mostraré lo\\\nfuertes que son!",
  ["53:4696"] = "¡Qué decepción!",
  ["53:46a8"] = "¿Viste a LANCE, el\\\nmaestro de los\\12dragones? No puede\\\nser cierto.",
  ["53:46e5"] = "¿Mis posibilidades\\\nde perder? ¡Ni el\\11uno por ciento!",
  ["53:4711"] = "Es extraño.",
  ["53:471d"] = "Ahora sé cuál es\\\nmi punto débil.\\12¡Gracias por\\\nenseñármelo!",
  ["53:4753"] = "Los dragones son\\\nPOKéMON sagrados.\\12Están llenos de\\\nenergía vital.\\12Si no eres\\\nserio, no\\12podrás acabar\\\ncon ellos.",
  ["53:47c0"] = "¡Adelante!",
  ["53:47cc"] = "Los dragones son\\\ndébiles contra los\\12movimientos del\\\ntipo dragón.",
  ["53:47fa"] = "¡Hola, futuro\\\ncampeón!\\12¡Ha sido un largo\\\nviaje, pero casi\\12hemos acabado!\\\n¡Confía en mí!\\12DÉBORA usa los\\\nmíticos y sagrados\\12POKéMON de tipo\\\ndragón.\\12No son fáciles\\\nde dañar.\\12Pero se supone\\\nque son débiles\\12contra los ataques\\\ndel tipo hielo.",
  ["53:48e8"] = "¡Genial! ¡Has\\\nvencido a DÉBORA!\\12Sólo te queda el\\\ndesafío de la\\11LIGA POKéMON.\\12¡Vas a convertirte\\\nen el CAMPEÓN\\11POKéMON!",
  ["53:4a3f"] = "No es como si\\\ntodos usáramos\\11POKéMON dragón.\\12Mi política es\\\nusar POKéMON más\\12fuertes que los\\\nPOKéMON dragón.",
  ["53:4aa9"] = "Eres especial…",
  ["53:4abb"] = "¡Tú observa!\\\nMis POKéMON se\\12harán aún más\\\nfuertes.\\12Seremos un\\\nentrenador y un\\12equipo POKéMON\\\nmás fuertes.",
  ["53:4b20"] = "DÉBORA nos ha\\\nentrenado a\\12conciencia. No\\\npuedo perder.",
  ["53:4b69"] = "¡Arrrg!\\\n¡Qué disgusto!",
  ["53:4b83"] = "¡Uau…! ¡Tendré\\\nque replantearme\\11mi entrenamiento!",
  ["53:4bad"] = "¡La piedra cayó\\\npor el agujero!",
  ["53:4c64"] = "DÉBORA y LANCE\\\nentrenaron aquí\\12para perfeccionar\\\nsus técnicas.",
  ["53:4ca4"] = "DRATINI: ¡Draa!",
  ["53:4d20"] = "No puedes comprar\\\nMÁX. REVIVIR. Pero\\12éste reanima\\\na un POKéMON\\11debilitado.\\12Atención: No\\\nrestaura los PP o\\12PUNTOS de PODER de\\\nlos movimientos.",
  ["53:4d9f"] = "MÁX. REPEL evita\\\nque se acerquen\\11POKéMON débiles.\\12Es el repelente\\\nmás duradero\\11de todos.",
  ["53:4e3b"] = "En el corazón de\\\nla remota MESETA\\12AÑIL se celebra la\\\nLIGA POKéMON.\\12Dicen que allí se\\\nreúnen los mejores\\12entrenadores de\\\ntodo el país.",
  ["53:4eb3"] = "Tenía un\\\nmovimiento que\\12quería enseñar\\\na mi POKéMON.\\12Así que usé el\\\nQUITA-MOVIMIENTOS\\11y eliminé una MO.",
  ["53:4fa7"] = "Parece que BLAINE,\\\ndel GIMNASIO de\\12ISLA CANELA, vive\\\nsolo en la cueva\\11de ISLAS ESPUMA…",
  ["53:4ff1"] = "El volcán hizo\\\nerupción hace\\11un año.",
  ["53:507c"] = "El volcán de ISLA\\\nCANELA ha entrado\\11en erupción.\\12Y ha lanzado rocas\\\nque han cortado la\\12RUTA 19 hasta\\\nnuevo aviso.\\12Me pregunto si la\\\ngente de ISLA\\12CANELA estará\\\nbien…",
  ["53:50fc"] = "Nadie en ISLA\\\nCANELA resultó\\12herido por la\\\nerupción. ¡Bien!",
  ["53:51ba"] = "BLAINE: ¡Buaaa!\\12Mi GIMNASIO de\\\nISLA CANELA se ha\\11quemado.\\12El volcán nos ha\\\ndejado sin casa a\\12mis POKéMON\\\ncomefuego y a mí.\\12¡Buaaaa!\\12Pero sigo haciendo\\\nmi trabajo de\\12LÍDER de GIMNASIO\\\nen esta cueva.\\12Si me vences,\\\nte daré una\\11MEDALLA.\\12¡Ja! Espero que\\\ntengas ANTIQUEMAR.",
  ["53:52b8"] = "BLAINE: Increíble.\\\nMe consumí…\\12¡Has ganado la\\\nMEDALLA VOLCÁN!",
  ["53:52f5"] = "{PLAYER} recibió\\\nla MED. VOLCÁN.",
  ["53:530f"] = "BLAINE: Esta vez\\\nhe perdido, pero\\12la próxima te\\\nganaré.\\12Cuando reconstruya\\\nmi GIMNASIO de I.\\12CANELA, tendremos\\\nla revancha.",
  ["53:538e"] = "BLAINE: Mis\\\nPOKéMON de fuego\\12serán más fuertes.\\\n¡Ya lo verás!",
  ["53:53cb"] = "¡Vaya!\\12¿Eh…? ¿Ya\\\nha acabado?\\12¡Lo siento, tío!\\12El GIMNASIO de\\\nISLA CANELA ya no\\12existe y no sabía\\\ndónde encontrarte.\\12Pero eres fuerte\\\nhasta sin mis\\12consejos. ¡Sabía\\\nque ganarías!",
  ["53:5477"] = "Los GIMNASIOS\\\nPOKéMON están allí\\12donde se encuentre\\\nsu LÍDER.\\12No es necesario\\\nun edificio.",
  ["53:5521"] = "Te has\\\nperdido…\\12Aquí he meditado.\\\nUn nuevo poder se\\12ha despertado\\\ndentro de mí.\\12Déjame compartir\\\nmi poder con tus\\12POKéMON.\\\nToma esto, hijo.",
  ["53:55b4"] = "¿Lo ves? ¡Es PODER\\\nOCULTO!\\12Saca el poder de\\\nlos POKéMON para\\11atacar.\\12Recuerda: su tipo\\\ny poder dependen\\12del POKéMON\\\nque lo usa.",
  ["53:5649"] = "Estoy meditando…",
  ["53:5704"] = "El LAGO DE LA\\\nFURIA es un cráter\\12obra de violentos\\\nGYARADOS.\\12El cráter se llenó\\\nde agua de la\\12lluvia y se formó\\\nel LAGO.\\12Esta historia la\\\ncontó por primera\\12vez el tatarabuelo\\\nde mi abuelo.\\12Antes se podían\\\npescar MAGIKARP\\12en el lago,\\\npero…\\12No entiendo lo\\\nque ocurre ahora.",
  ["53:5823"] = "En el LAGO pasan\\\ncosas raras desde\\12que llegaron esos\\\nhombres de negro.",
  ["53:5866"] = "La normalidad ha\\\nvuelto al LAGO DE\\12LA FURIA. Vuelve a\\\nhaber MAGIKARP.\\12Quizá se cumpla\\\nmi sueño de ver\\12al MAGIKARP más\\\ngrande del mundo.\\12¿Tienes una CAÑA?\\\nSi tienes una,\\11ayúdame por favor.",
  ["53:5914"] = "¡Ah, tienes un\\\nMAGIKARP! A ver\\12lo grande que es\\\nese bebé.",
  ["53:594d"] = "¡Uau! ¡Éste es\\\nimpresionante!\\12¡Me quito el\\\nsombrero ante ti!\\12¡Toma esto como\\\nrecuerdo!",
  ["53:5999"] = "Lo importante es\\\nel récord. ¡Piensa\\12en él como una\\\nbonificación!",
  ["53:59d7"] = "¡Uau! ¡Éste es\\\nimpresionante!\\12Ojalá no tuviera\\\nque decirlo, pero\\12he visto uno más\\\ngrande antes.",
  ["53:5a32"] = "¿Qué? ¡Eso no es\\\nun MAGIKARP!",
  ["53:5a4f"] = "¿No tienes ninguno\\\nbueno para\\12enseñármelo? Quizá\\\nla próxima vez.",
  ["53:5af5"] = "Últimamente sólo\\\npasaron por aquí\\12los que iban al\\\nLAGO DE LA FURIA.",
  ["53:5b3b"] = "Ahora nadie\\\nva al LAGO\\11DE LA FURIA.",
  ["53:5ca8"] = "¡Alto ahí,\\\nseñor!\\12El precio por\\\npasar es 1000¥.",
  ["53:5ce1"] = "¡Gracias, señor!",
  ["53:5cf2"] = "Entonces paga\\\nlo que tengas.",
  ["53:5d13"] = "¡Je, je! Nos\\\nestamos forrando.\\12Todo el mundo\\\nquiere ver lo que\\12ocurre en el LAGO\\\nDE LA FURIA.",
  ["53:5d6d"] = "Esos gamberros de\\\nnegro me echaron\\11de mi puesto.\\12Se dejaron\\\nesto.\\12Me molesta.\\\n¿Podrías\\11llevártelo?",
  ["53:5dff"] = "Usa esta puerta\\\npara no andar\\11por la hierba.",
  ["54:4005"] = "¿Coleccionas las\\\nMEDALLAS DE KANTO?",
  ["54:405a"] = "Dicen que hay\\\nun tipo sospechoso\\11merodeando.\\12Si resulta ser\\\nel ladrón, le\\11detendré.",
  ["54:40c3"] = "Ya nos atracaron\\\nantes.",
  ["54:40e7"] = "DIGLETT: Dig, dig.",
  ["54:414d"] = "Mi marido vive\\\nfeliz con los\\12POKéMON que ha\\\nintercambiado.",
  ["54:418a"] = "Soy tan feliz…",
  ["54:419c"] = "KANGASKHAN: Kangas\\\nkangas.",
  ["54:41b5"] = "ZUBAT: Zuba zubaa.",
  ["54:4218"] = "La RUTA 9 va hacia\\\nel Este. La\\12CENTRAL de ENERGÍA\\\nestá al final.",
  ["54:4257"] = "El MAGNETOTRÉN\\\nviaja a unos\n550 Km/h. Puede\\\nllevarte de\\12KANTO a JOHTO en\\\npocos segundos.\\12Hace que sea muy\\\nfácil ir a JOHTO.",
  ["54:4453"] = "¡Uups! ¡Yo sentir!\\\nTú no hacer daño,\\11¿de acuerdo?\\12Yo muy ocupado.\\\nNo tener tiempo\\12para hablar\\\ncontigo. No poder\\11verme nadie.",
  ["54:44cc"] = "¡Oh, no! ¡Tú\\\nverme! ¡Yo cometer\\11gran error!",
  ["54:44fd"] = "¡Oye! Tú olvidar\\\nque me has visto,\\12¿vale? Tú ver, oír\\\ny saber nada, ¿de\\12acuerdo?\\\n¡Adiós, chico!\\12¡Hasta la vista!",
  ["54:4568"] = "Lo siento, estaré\\\nfuera un tiempo.\\12MISTY, LÍDER del\\\nGIMNASIO",
  ["54:459a"] = "Como MISTY ha\\\nsalido, nosotros\\12tampoco estaremos.\\\nLos ENTRENADORES",
  ["54:45cc"] = "MISTY: Te estaba\\\nesperando,\\11pesado.\\12Puede que tengas\\\nmuchas MEDALLAS de\\12JOHTO, pero será\\\nmejor que me tomes\\11en serio.\\12¡Mis POKéMON de\\\nagua son fuertes!",
  ["54:4664"] = "MISTY: Eres\\\nrealmente bueno…\\12Reconozco que eres\\\nun experto…\\12Aquí tienes la\\\nMEDALLA CASCADA.",
  ["54:46c0"] = "{PLAYER} recibió\\\nMEDALLA CASCADA.",
  ["54:46da"] = "MISTY: ¿Hay muchos\\\nentrenadores\\12fuertes en JOHTO?\\\nComo tú, digo.\\12Un día viajaré y\\\nlucharé contra\\12entrenadores\\\nexpertos.",
  ["54:4762"] = "Siento haber\\\nestado fuera.\\11¡A lo nuestro!",
  ["54:4790"] = "¡Me rindo! ¡Has\\\nganado!",
  ["54:47ae"] = "Estaré nadando\\\ntranquilamente.",
  ["54:47c8"] = "No te desanimes\\\npor mi elegante\\11forma de nadar.",
  ["54:47f7"] = "¡Ooh! Has acabado\\\nconmigo…",
  ["54:4818"] = "No fardes tanto de\\\nhaberme vencido.\\12MISTY acabará\\\ncontigo si te\\11confías demasiado.",
  ["54:486a"] = "¡Glup…!\\12¡Soy el primero!\\\n¡Ven a por mí!",
  ["54:488c"] = "No puede ser…",
  ["54:489b"] = "MISTY ha mejorado\\\nmucho en los\\11últimos años.\\12¡No bajes la\\\nguardia o acabarás\\11machacado!",
  ["54:48ff"] = "¡Hola, futuro\\\nCAMPEÓN!\\12Como MISTY no\\\nestaba, salí\\12a divertirme un\\\nrato. ¡Je, je, je!",
  ["54:4952"] = "¡Uauu! ¡Qué\\\nfuerte eres!\\12¡Como siempre, ha\\\nsido un combate\\11realmente bueno!",
  ["54:4a25"] = "Encontrarás muchos\\\nentrenadores de\\12camino hacia\\\nCABO CELESTE.\\12Quieren saber cómo\\\nson en comparación\\12con otros\\\nentrenadores.",
  ["54:4a9e"] = "MISTY es casi la\\\núnica persona de\\12la ciudad capaz de\\\nvencer a los\\12ENTRENADORES de\\\nCABO CELESTE.",
  ["54:4b49"] = "¿Un CENTRO POKéMON\\\njunto a una cueva?\\12¡Qué bien!\\\n",
  ["54:4b7e"] = "El DIRECTOR de la\\\nC. ENERGÍA busca\\12a un entrenador\\\nPOKéMON fuerte.\\12Necesita ayuda\\\npara recuperar\\12algo que le\\\nrobaron.",
  ["54:4bf6"] = "Dicen que el TEAM\\\nROCKET se reunió\\12en JOHTO, pero se\\\nvolvió a separar.\\12No tenía ni idea\\\nde eso.",
  ["54:4c64"] = "Cuando salgas,\\\nverás el tejado\\12de un edificio\\\nmuy grande.\\12Eso es la CENTRAL\\\nde ENERGÍA.",
  ["54:4e31"] = "Entró un ladrón en\\\nla C. ENERGÍA…\\12¿Adónde vamos a\\\nir a parar?",
  ["54:4e73"] = "Tengo noticias de\\\nCIUDAD CELESTE.\\12Parece que ha\\\nestado merodeando\\12por allí un hombre\\\nmuy sospechoso.",
  ["54:4ed0"] = "¿Puedo pedirte\\\nayuda?",
  ["54:4ef3"] = "Tendremos que\\\nreforzar nuestra\\11seguridad.",
  ["54:4f20"] = "Alguien ha robado\\\nuna pieza que\\12necesitamos para\\\nel generador.\\12¡Sin ella, el\\\nnuevo generador no\\11sirve para nada!",
  ["54:4f89"] = "El generador ya\\\nfunciona y está\\12generando mucha\\\nelectricidad.",
  ["54:4fca"] = "Esta CENTRAL de\\\nENERGÍA había\\12sido abandonada\\\nhace mucho tiempo.\\12Volvimos a ponerla\\\nen funcionamiento\\12para poder usar\\\nel MAGNETOTRÉN.",
  ["54:5040"] = "¡El generador\\\nya funciona!",
  ["54:505f"] = "El DIRECTOR de la\\\nCENTRAL ENERGÍA\\11está ahí delante.\\12Pero está triste y\\\nenfadado porque\\12alguien ha\\\nestropeado el\\11generador…",
  ["54:50d0"] = "El DIRECTOR está\\\ncontento porque\\12el generador ya\\\nestá arreglado.",
  ["54:5113"] = "El MAGNETOTRÉN\\\nconsume mucha\\11electricidad.\\12No se puede mover\\\nsi el nuevo\\12generador no\\\nfunciona.",
  ["54:5176"] = "¡Muy bien!\\\nEl MAGNETOTRÉN\\12puede volver a\\\nfuncionar.",
  ["54:51b5"] = "DIRECTOR: ¡Me voy\\\na enfadar con\\11alguien!\\12¿Quién ha roto mi\\\ngenerador?\\12¡Con el tiempo que\\\nle he dedicado!\\12¡Como lo atrape,\\\nva a saber lo\\12que es mi\\\nELECTROCAÑÓN!",
  ["54:5259"] = "DIRECTOR: ¡Nunca\\\nle perdonaré!\\12Aunque el culpable\\\nllore y suplique\\12perdón, ¡le\\\nmachacaré!\\12¡Ja, ja, ja!",
  ["54:52bf"] = "DIRECTOR: ¡Sí!\\12¡Ésa es la pieza\\\nque le faltaba a\\12mi generador! ¿La\\\nencontraste tú?",
  ["54:5315"] = "¡Yuju! ¡Gracias!\\12¡Toma esta MT\\\ncomo recompensa!",
  ["54:5345"] = "DIRECTOR: La MT07\\\nes mi ELECTRO-\\12CAÑÓN. ¡Es muy\\\npotente!\\12Aunque presenta\\\nel inconveniente\\12de no ser muy\\\nprecisa.",
  ["54:53c6"] = "DIRECTOR: ¡Mi\\\nquerido generador!\\12¡Sigue generando\\\nelectricidad!",
  ["54:5612"] = "¿Conoces a BILL?\\\nEs mi nieto.\\12Está en JOHTO\\\ntrabajando con\\12los PC. Yo le\\\ncuido la casa.",
  ["54:5676"] = "Si tienes ese\\\nPOKéMON, ¿me\\11dejas verlo?",
  ["54:56a4"] = "¿Me lo dejas ver?\\\n¡Qué amable eres!",
  ["54:56c8"] = "¿No lo tienes?\\\n¡Qué pena…!",
  ["54:56ea"] = "¡Ah! ¿es ése\\\n{STRBUF}?\\12¡Qué mono!\\\nEres muy\\11simpático.",
  ["54:5725"] = "¡Gracias!\\12Toma esto como\\\nagradecimiento.",
  ["54:5752"] = "Vuelve cuando\\\nquieras.",
  ["54:576e"] = "Gracias por\\\nmostrarme tantos\\12POKéMON\\\nbonitos.\\12Me he divertido\\\nmucho. Me alegro\\12de haber vivido\\\ntantos años.",
  ["54:57d5"] = "¿Mmm?\\12Ése no es el\\\nPOKéMON del\\11que me hablaron.",
  ["54:5804"] = "Mi nieto BILL me\\\ndijo que había un\\12POKéMON con una\\\nlengua muy larga.",
  ["54:5843"] = "Mi nieto mencionó\\\na un POKéMON verde\\12y redondo al que\\\nle crecen hojas en\\11la cabeza.",
  ["54:5897"] = "¿Conoces a un\\\nPOKéMON de mar que\\12tiene una esfera\\\nroja en el cuerpo?\\12Ya sabes, ése\\\nque tiene forma\\11de estrella.\\12Dicen que sale\\\npor la noche.\\12Me encantaría\\\nverlo.",
  ["54:5942"] = "BILL me habló de\\\nun POKéMON que\\12es muy fiel a su\\\nentrenador.\\12Se supone que\\\nRUGE bien.",
  ["54:599b"] = "He oído hablar de\\\nun POKéMON que\\11tiene seis colas.\\12Me gustaría\\\nabrazar a un\\11POKéMON así.",
  ["54:59f5"] = "¿Conoces a ese\\\nPOKéMON tan\\11popular?\\12El POKéMON de\\\ncuerpo amarillo\\11y mejillas rojas.\\12Me gustaría\\\nverlo antes\\12de que\\\nevolucione.",
  ["55:4013"] = "¿Tus POKéMON saben\\\nmovimientos MO?\\12Se pueden usar\\\nestos movimientos\\12aunque el POKéMON\\\nesté debilitado.",
  ["55:4067"] = "En el PC de BILL\\\nse almacenan 20\\11POKéMON por CAJA.",
  ["55:4092"] = "¿Sabes algo sobre\\\nlos BONGURI?\\12Abre uno, vacíalo\\\ny rellénalo con\\12un aparato\\\nespecial.\\12Así podrás atrapar\\\nPOKéMON.\\12Antes de que se\\\ninventaran las\\12POKé BALL, todos\\\nusaban BONGURI.",
  ["55:41ed"] = "Todos los SLOWPOKE\\\ndel pueblo\\11han desaparecido.\\12Quizá el guardián\\\ndel ENCINAR esté\\11enfadado…\\12Puede ser un mal\\\npresagio. Mejor\\11no salir.",
  ["55:4276"] = "Los SLOWPOKE han\\\nvuelto…\\12Pero mi APRENDIZ\\\nno ha vuelto del\\11ENCINAR.\\12¿Dónde demonios\\\nestá ese vago?",
  ["55:42ec"] = "¿Expulsaste al\\\nTEAM ROCKET y\\12fuiste solo al\\\nENCINAR?\\12¡Qué valiente! Me\\\ngustas. Entrena\\11con nosotros.",
  ["55:4359"] = "¿Adónde han ido\\\nlos SLOWPOKE?\\12¿Están jugando\\\nfuera?",
  ["55:439e"] = "Lo siento. Olvidé\\\ndarte las gracias.\\12Éste es el CARBÓN\\\nque he fabricado.\\12A los POKéMON de\\\nfuego les gustará\\11llevarlo.",
  ["55:440c"] = "Los SLOWPOKE han\\\nvuelto, hasta\\11FARFETCH'D.\\12¡Eres el mejor,\\\ntío!",
  ["55:445e"] = "FARFETCH'D: ¡Farf!",
  ["55:44c6"] = "Aquí no hay SÚPER\\\nBALL. Tendrás que\\12conformarte con\\\nlas POKé BALL.\\12¡Ojalá me pudiera\\\nfabricar CÉSAR\\11alguna BALL!",
  ["55:452f"] = "Mejor una SÚPER\\\nBALL para capturar\\12POKéMON que una\\\nPOKé BALL.\\12Pero a veces,\\\nlas de CÉSAR\\11son mejores.",
  ["55:47ee"] = "¿Quién eres?\\12{PLAYER},\\\n¿quieres que haga\\11alguna BALL?\\12Lo siento, pero\\\ndeberás esperar.\\12¿Conoces al TEAM\\\nROCKET? ¡Bah!\\12No importa. Yo\\\nte lo contaré.\\12Se trata de una\\\nbanda malvada que\\12usa POKéMON para\\\nel trabajo sucio.\\12Se supone que se\\\ndisolvieron hace\\11tres años.\\12¡Pero están en el\\\nPOZO cortando\\12COLAS de SLOWPOKE\\\npara venderlas!\\12¡Así que voy a\\\nir allí a darles\\11una lección!\\12¡Resistid,\\\nSLOWPOKE!\\11¡CÉSAR os ayudará!",
  ["55:4990"] = "CÉSAR: ¡{PLAYER}!\\12Te has portado\\\ncomo un auténtico\\11héroe en el POZO.\\12¡Tienes estilo!\\12Sería un honor\\\nhacer alguna BALL\\12para un entrenador\\\ncomo tú.\\12Ahora sólo tengo\\\nésta. Tuya es.",
  ["55:4a44"] = "CÉSAR: Fabrico\\\nlas BALL de\\11los BONGURI.\\12Recógelos de\\\nlos árboles\\11y traémelos.\\12Los usaré para\\\nhacer las BALL.",
  ["55:4ab1"] = "CÉSAR: ¿Tienes\\\nun BONGURI?\\12¡Vale! Te haré\\\nuna BALL.",
  ["55:4af4"] = "CÉSAR: Tardaré un\\\ndía en fabricar\\12una BALL. Vuelve\\\nmañana a por ella.",
  ["55:4b37"] = "CÉSAR: ¡Oh…!\\\n¡Qué decepción!",
  ["55:4b53"] = "CÉSAR: ¡Estoy\\\ntrabajando! ¡Vete!",
  ["55:4b76"] = "CÉSAR: ¡{PLAYER}!\\\nAcabo de terminar\\11tu BALL. Tuya es.",
  ["55:4ba5"] = "CÉSAR: Ha salido\\\nmuy bien.\\12Intenta capturar\\\nPOKéMON con ella.",
  ["55:4bde"] = "Los SLOWPOKE se\\\nhan ido…\\12¿Se los ha llevado\\\nla gente mala?",
  ["55:4c1a"] = "El abuelo se fue.\\\nEstoy tan sola…",
  ["55:4c38"] = "¡El SLOWPOKE\\\nque me regaló mi\\12padre ha vuelto!\\\n¡Y su COLA\\11vuelve a crecer!",
  ["55:4c7e"] = "Papá trabaja en\\\nSILPH y estudia\\11las POKé BALL.\\12Tengo que quedarme\\\nen casa con el\\11abuelo y SLOWPOKE.",
  ["55:4cdb"] = "SLOWPOKE: ¡Mmm!\\\n(Bostezo).",
  ["55:4cee"] = "¿Un joven\\\nPROF. OAK?",
  ["55:4d03"] = "Es una estatua\\\ndel guardián\\11del encinar.",
  ["55:4e83"] = "¡Soy ANTÓN!\\\nSoy invencible\\12con los\\\nPOKéMON bicho.\\12¡Mis estudios me\\\nvan a convertir en\\12una autoridad de\\\nlos POKéMON bicho!\\12Te enseñaré lo\\\nque he aprendido.",
  ["55:4f26"] = "¡Uauu, increíble!\\\n¡Eres un experto\\11en POKéMON!\\12Mi investigación\\\naún no ha acabado.\\12Vale, tú ganas.\\\nToma esta MEDALLA.",
  ["55:4f8c"] = "{PLAYER}\\\nrecibió la\\11MEDALLA COLMENA.",
  ["55:4fa3"] = "¿Conoces las\\\nventajas de la\\11MEDALLA COLMENA?\\12Si la tienes, los\\\nPOKéMON hasta N.30\\11te obedecerán.\\12Y los POKéMON\\\nque sepan CORTE\\12podrán usarlo\\\nfuera del combate.\\12Mira, también te\\\ndaré esto.",
  ["55:5060"] = "MT49 contiene\\\nCORTEFURIA.\\12Si no fallas, se\\\nhace cada vez\\11más fuerte.\\12Cuanto más dure\\\nel combate, más\\11fuerte será.\\12¿No es genial?\\\n¡Lo descubrí yo!",
  ["55:50fe"] = "Los POKéMON bicho\\\nson muy complejos.\\12Quedan muchos\\\nmisterios por\\11resolver.\\12Estudia a fondo\\\ntus favoritos.",
  ["55:515e"] = "Los POKéMON bicho\\\nevolucionan pronto\\12y se hacen fuertes\\\nmucho antes.",
  ["55:519d"] = "¡No se trata sólo\\\nde evolucionar!",
  ["55:51b9"] = "Los POKéMON se\\\nhacen más fuertes\\11si evolucionan.",
  ["55:51e7"] = "¡Los POKéMON bicho\\\nson buenos y muy\\12fuertes! ¡Te lo\\\ndemostraré!",
  ["55:521a"] = "Has demostrado lo\\\nfuerte que eres…",
  ["55:5239"] = "Son geniales,\\\npero la mayoría de\\12las chicas odian\\\nlos POKéMON bicho.\\12No sé por qué…",
  ["55:527e"] = "¿Has salvado a los\\\nSLOWPOKE? ¡Uauu!\\11¡Eres muy fuerte!\\12¡Pero mis\\\nPOKéMON\\12entrenados también\\\nson muy fuertes!",
  ["55:52da"] = "¡Urrggg!",
  ["55:52e4"] = "Supongo que\\\ndebería enseñarles\\11mejores ataques…",
  ["55:530f"] = "AMY: ¿Vas a\\\ndesafiar al LÍDER?\\11¡Ni lo sueñes!",
  ["55:5341"] = "AMY-MAY: ¡Oh,\\\ndoble bondad!",
  ["55:5362"] = "AMY: ¡Eres\\\nmuy fuerte!",
  ["55:537d"] = "MAY: ¿Quieres ver\\\nal LÍDER?\\12¡Pues nosotras\\\nvamos primero!",
  ["55:53ae"] = "AMY-MAY: ¡Oh,\\\ndoble bondad!",
  ["55:53cf"] = "MAY: Han perdido\\\nnuestros POKéMON.\\11¡Qué lástima!",
  ["55:53fc"] = "¡Hola, valiente!\\12ANTÓN es joven,\\\npero conoce muy\\12bien a los POKéMON\\\nbicho.\\12Y sin mis consejos\\\nte resultaría aún\\11más duro.\\12Veamos… A los\\\nPOKéMON bicho no\\11les va el fuego.\\12Y los ataques de\\\ntipo volador son\\11muy efectivos.",
  ["55:54bf"] = "¡Eso es! Ha sido\\\nun gran encuentro\\12entre jóvenes\\\ncon talento.\\12Con gente como tú,\\\n¡el futuro de los\\12POKéMON será\\\nmaravilloso!",
  ["56:400f"] = "Cuando atrapas un\\\nPOKéMON, puede\\11estar débil.\\12Pero éste crecerá\\\ny se hará más\\11fuerte.\\12Es importante\\\ntratar a los\\12POKéMON con\\\nmucho cariño.",
  ["56:4090"] = "Los POKéMON pueden\\\nir equipados con\\12objetos como\\\nPOCIÓN y ANTÍDOTO.\\12Pero parece que\\\nno saben usar los\\12objetos hechos\\\npor el hombre.",
  ["56:41e0"] = "¡Soy PEGASO, líder\\\ndel GIMNASIO de\\11CIUDAD MALVA!\\12Dicen que una\\\nsacudida eléctrica\\12puede acabar con\\\nlas alas de los\\11POKéMON voladores.\\12¡No permitiré\\\nque hablen así\\11de ellos!\\12¡Yo te enseñaré el\\\nauténtico poder de\\12los magníficos\\\npájaros POKéMON!",
  ["56:42b7"] = "¡Maldición! Los\\\nqueridos POKéMON\\11de mi padre…\\12¡Muy bien!\\\nToma esto.\\12Es la MEDALLA\\\nCÉFIRO oficial de\\11la LIGA POKéMON.",
  ["56:431c"] = "{PLAYER} recibió\\\nla MEDALLA CÉFIRO.",
  ["56:4335"] = "La MEDALLA CÉFIRO\\\nmejora el ataque\\11de los POKéMON.\\12Y permite que\\\nlos POKéMON\\12usen DESTELLO, si\\\nlo tienen.\\12Toma, también\\\nte daré esto.",
  ["56:43b5"] = "Al usar una MT, el\\\nPOKéMON aprenderá\\12inmediatamente un\\\nnuevo movimiento.\\12Piensa antes de\\\nactuar, ya que las\\12MT sólo se pueden\\\nusar una vez.\\12MT31 contiene\\\nBOFETÓN-LODO.\\12Reduce la\\\nprecisión del\\12enemigo y causa\\\ngrandes daños.\\12Es decir, es tanto\\\ndefensiva como\\11ofensiva.",
  ["56:44a2"] = "Encontrarás\\\nGIMNASIOS POKéMON\\12en las ciudades\\\ny en los pueblos.\\12Deberías probar\\\ntus habilidades en\\11estos GIMNASIOS.\\12¡Yo seguiré\\\nentrenándome para\\12ser el maestro de\\\nlos pájaros!",
  ["56:453a"] = "¡La clave está en\\\ntener valor!\\12Éstos entrenan\\\nnoche y día para\\12convertirse en\\\nmaestros POKéMON.\\12¡Adelante!",
  ["56:459c"] = "¡Aaah!",
  ["56:45a4"] = "¡La destreza de\\\nPEGASO es real!\\12¡No te confíes\\\npor haberme\\11vencido!",
  ["56:45ec"] = "¡Demuéstrame que\\\neres lo bastante\\11bueno para PEGASO!",
  ["56:4620"] = "¡No puede\\\nser cierto!",
  ["56:4634"] = "¡Qué patético!\\\nHe perdido contra\\11un novato…",
  ["56:4666"] = "¡Hola! ¡No soy\\\nentrenador pero te\\11puedo aconsejar!\\12¡Créeme!\\\nSi confías, tus\\12sueños de triunfo\\\npodrían cumplirse.\\12¿Confías? Pues\\\nescucha.\\12El tipo planta es\\\ndébil contra el\\12tipo volador.\\\n¡No lo olvides!",
  ["56:4735"] = "¡Bonita batalla!\\\n¡Sigue así y\\11serás el CAMPEÓN!",
  ["56:48a8"] = "¡Soy yo, PRIMO!\\12¡Fantásticos son\\\nlos POKéMON!\\12¡A ti yo te\\\nenseñaré a ser un\\11entrenador mejor!\\12¿Quieres saber\\\ncómo ser un\\11ganador?",
  ["56:492a"] = "¡Bien! ¡A ti yo\\\nte enseñaré!\\12¡En combate, los\\\nprimeros POKéMON\\11salen antes!\\12¡Quizá sea más\\\nfácil si cambias\\11el orden!\\12¿Quieres que te\\\ncuente más cosas?",
  ["56:49be"] = "¿Quieres saber\\\ncómo educar bien\\11a los POKéMON?",
  ["56:49e8"] = "¡Bien! ¡A ti yo\\\nte enseñaré!\\12Si un POKéMON\\\nsale al combate,\\12aunque brevemente,\\\ngana puntos EXP.\\12¡Pon arriba los\\\nPOKéMON débiles,\\12y cámbialos rápido\\\nen el combate!\\12¡Así se harán\\\nfuertes los\\11POKéMON débiles!",
  ["56:4a9e"] = "¡Oh! ¡Un alumno\\\nlisto eres! ¡Nada\\11más quieres saber!\\12¡Bueno en POKéMON\\\ndebes de ser!",
  ["56:4aed"] = "Estoy tomando\\\napuntes de lo que\\11dice el profesor.\\12Y debería copiar\\\ntambién lo escrito\\11en la pizarra.",
  ["56:4b47"] = "He cambiado a mis\\\nmejores POKéMON\\11con mi compañero.",
  ["56:4b74"] = "¡El POKéMON que\\\nhe conseguido va\\11equipado con algo!",
  ["56:4ba6"] = "Si un POKéMON va\\\nequipado con una\\12BAYA, se curará él\\\nsolo en combate.\\12Los POKéMON pueden\\\nir equipados con\\11muchos objetos…\\12Es muy duro\\\ntomar apuntes…",
  ["56:4c1f"] = "La pizarra indica\\\ncómo cambian de\\12estado los POKéMON\\\nen combate.",
  ["56:4c6b"] = "Si un POKéMON\\\nes envenenado,\\11perderá PS.\\12El envenenamiento\\\ncontinúa tras el\\12combate y al\\\ncaminar seguirá\\11perdiendo PS.\\12Para curarlo,\\\nusa ANTÍDOTO.",
  ["56:4ced"] = "La parálisis baja\\\nla velocidad y\\12puede impedir el\\\nmovimiento.\\12Permanece tras el\\\ncombate, así que\\11usa ANTIPARALIZ.",
  ["56:4d4f"] = "Si tu POKéMON\\\nse queda dormido\\12no podrá realizar\\\nningún movimiento.\\12Un POKéMON dormido\\\nno se despierta\\11tras el combate.\\12Despiértalo con\\\nDESPERTAR.",
  ["56:4dc2"] = "Las quemaduras\\\nconsumen PS,\\12reducen el poder\\\ndel ataque\\12y permanecen\\\ntras el combate.\\12Usa ANTIQUEMAR\\\ncomo cura.",
  ["56:4e38"] = "Si tu POKéMON está\\\ncongelado, no\\11podrá hacer nada.\\12Seguirá congelado\\\ntras el combate.\\12Descongélalo con\\\nANTIHIELO.",
  ["56:4ea3"] = "Es el cuaderno de\\\neste niño…\\12Captura POKéMON\\\nusando POKé BALL.\\12Tu equipo puede\\\ntener hasta seis.\\12¿Seguir leyendo?",
  ["56:4f04"] = "Antes de lanzar la\\\nPOKé BALL, debes\\11debilitarlo.\\12Atrapar un\\\nPOKéMON quemado\\12o envenenado es\\\nmucho más fácil.\\12¿Seguir leyendo?",
  ["56:4f74"] = "Algunos ataques\\\ncausan confusión.\\12Un POKéMON confuso\\\npuede atacarse a\\11sí mismo.\\12Retirarlo del\\\ncombate, eliminará\\11su confusión.\\12¿Seguir leyendo?",
  ["56:4ff4"] = "Quienes atrapan\\\nPOKéMON y los usan\\12para luchar son\\\nentrenadores.\\12Su misión es ir\\\na los GIMNASIOS\\12y vencer a otros\\\nentrenadores.\\12La hoja siguiente\\\nestá… ¡vacía!\\12Niño: ¡Eh, eh…!\\12No he escrito\\\nnada más…",
  ["56:5167"] = "Ella usa los\\\nnombres de sus\\11comidas favoritas.\\12Quiero decir,\\\ncomo motes para\\11sus POKéMON.",
  ["56:51cb"] = "¡A mi PIDGEY le\\\nllamo FRESITA!",
  ["56:51e9"] = "FRESITA: ¡Pidgey!",
  ["56:52c2"] = "¡{PLAYER}, cuánto\\\ntiempo sin verte!\\12El PROF. ELM te\\\nestá buscando.\\12Quiere pedirte\\\notro favor.\\12¿Puedes llevar el\\\nHUEVO POKéMON?",
  ["56:5332"] = "Hemos descubierto\\\nque los POKéMON\\12salen del HUEVO\\\ncuando crecen.\\12Para que el HUEVO\\\nse abra, debe de\\12estar con otros\\\nPOKéMON activos.\\12{PLAYER}, sólo\\\npodemos confíar\\11en ti.\\12Llama al PROF. ELM\\\ncuando se abra el\\11HUEVO, por favor.",
  ["56:5400"] = "¡Oh, no! No puedes\\\nllevar más\\11POKéMON.\\12Esperaré aquí a\\\nque le hagas\\11sitio al HUEVO.",
  ["56:545f"] = "Pero…\\\nEl PROF. ELM\\11preguntó por ti.",
  ["56:547f"] = "{PLAYER},\\\n¿quieres el HUEVO?",
  ["56:549a"] = "El sistema de\\\nalmacenamiento del\\12PC es de un chico\\\nllamado BILL.",
  ["56:54cd"] = "Fue hace unos\\\ntres años.\\12El TEAM ROCKET\\\nquería hacer daño\\11a los POKéMON.\\12Pero prevaleció la\\\njusticia y un niño\\11acabó con ellos.",
  ["56:5549"] = "Los POKéMON son\\\nlistos y no\\12obedecen a quien\\\nno respetan.\\12Sin las MEDALLAS\\\nnecesarias, harán\\12lo que ellos\\\nquieran.",
  ["56:5628"] = "Los POKéMON que\\\nse intercambian\\11crecen rápido.\\12Pero si no tienes\\\nla MEDALLA\\12adecuada, podrían\\\ndesobedecerte.",
  ["56:56c7"] = "RUINAS ALFA\\12Centro Turístico\\\n¡Mírame y Tócame!\\12¡Intenta mover las\\\npiezas de piedra!",
  ["56:5712"] = "¿Estás estudiando\\\nlas RUINAS?\\12Eres un científico\\\nen potencia.",
  ["56:574e"] = "Hay dibujos en las\\\npiezas de piedra.\\12Intenté moverlas.\\\nMe pregunto\\11qué serán.",
  ["56:5814"] = "Éste es un buen\\\nsitio para pescar.\\12¿Has visto a\\\ngente pescando?\\11¿Y tú?\\12¿Quieres una\\\nde mis CAÑAS?",
  ["56:5879"] = "Eso está\\\nbien.\\12¡Ahora ya eres\\\nun pescador!",
  ["56:58ac"] = "¡Pescar es genial!\\12Si ves agua, ya\\\nsea el mar o un\\12río, utiliza\\\ntu CAÑA.",
  ["56:58fd"] = "¡Vaya! Me has\\\ndecepcionado…",
  ["56:591e"] = "Hola, jovencito.\\\n¿Qué? ¿Pican?",
  ["56:5943"] = "¿Cómo equipar\\\na mi POKéMON?\\12Quizá con un\\\nobjeto que aumente\\11su ATAQUE…",
  ["56:5a70"] = "¡Perdona, chaval!\\\n¿Puedes hacerme\\11un favor?\\12¿Puedes darle este\\\nPOKéMON con CARTA\\11a mi amigo?\\12Está en la\\\nRUTA 31.",
  ["56:5adb"] = "¿Lo harás? Genial.\\\n¡Gracias, chaval!\\12Mi amigo es un\\\nchico gordinflón\\12que siempre está\\\ndurmiendo.\\12¡Le reconocerás\\\nenseguida!",
  ["56:5b4b"] = "{PLAYER} recibió\\\nPOKéMON con CARTA.",
  ["56:5b69"] = "Puedes leerla,\\\n¡pero no la\\11pierdas! ¡RUTA 31!\\12Ah, sí. Un extraño\\\nárbol bloqueaba\\11el camino.\\12¿Lo habrán\\\nretirado ya?",
  ["56:5be9"] = "No puedes llevar\\\notro POKéMON…",
  ["56:5c07"] = "¡Oh…! Entonces,\\\nno importa…",
  ["56:5c1e"] = "¡Gracias, chaval!\\\n¡Muchas gracias\\12por habérselo\\\nllevado!\\12¡Toma esto por\\\nlas molestias!",
  ["56:5c6c"] = "¿A que mi amigo\\\nestaba durmiendo?\\11Te lo dije.",
  ["56:5c9d"] = "Un extraño árbol\\\nbloquea el camino.\\12Si le hablas,\\\nse mueve.\\12Dicen que se\\\nvolvió loco cuando\\12alguien lo mojó\\\ncon una REGADERA.",
  ["56:5d2d"] = "Me gusta la Nana\\\nPOKéMON que ponen\\11en la radio.",
  ["56:5ef2"] = "Hoy es {STRBUF}.\\\nEso significa que\\12hoy es el Concurso\\\nCaptura de Bichos.\\12Las reglas son\\\nsencillas.\\12Usa uno de tus\\\nPOKéMON y captura\\12un POKéMON bicho\\\npara ganar.\\12¿Te gustaría\\\nintentarlo?",
  ["56:5fa4"] = "Aquí tienes las\\\nPARQUE BALL para\\11el Concurso.",
  ["56:5fce"] = "{PLAYER} recibió\\\n20 PARQUE BALL.",
  ["56:5fe9"] = "Aquél que consiga\\\nel POKéMON bicho\\12más fuerte será\\\nel ganador.\\12Tienes 20\\\nminutos.\\12Si te quedas sin\\\nPARQUE BALL, has\\11perdido.\\12Puedes quedarte\\\nel último POKéMON\\11que captures.\\12¡Sal y captura\\\nel POKéMON\\12bicho más fuerte\\\nque encuentres!",
  ["56:60cd"] = "¡Oh, oh…!\\12Tienes más de\\\nun POKéMON.\\12Tendrás que usar\\\na {STRBUF},\\12el primer POKéMON\\\nde tu equipo.\\12¿Te parece\\\nbien?",
  ["56:613e"] = "Bien, guardaremos\\\nlos otros POKéMON\\11mientras compites.",
  ["56:6172"] = "Los POKéMON de\\\n{PLAYER} se quedan\\11con el AYUDANTE.",
  ["56:619e"] = "Elige el POKéMON\\\nque usarás en\\12el Concurso y\\\nluego ven a verme.",
  ["56:61e3"] = "Muy bien.\\\nEsperamos verte\\11pronto por aquí.",
  ["56:620f"] = "¡Oh, oh…!\\\nEl primer POKéMON\\12de tu equipo no\\\npuede luchar.\\12Sustitúyelo por\\\nel POKéMON que\\12quieras usar y\\\nluego ven a verme.",
  ["56:6283"] = "¡Oh, oh…!\\\nTu equipo y\\12tu CAJA del PC\\\nestán llenos.\\12No tienes sitio\\\npara guardar el\\11POKéMON bicho.\\12Haz sitio en\\\ntu equipo o en\\12la CAJA del PC y\\\nluego ven a verme.",
  ["56:6326"] = "¡Oh, oh…! Tienes\\\nun HUEVO como\\12primer POKéMON\\\nde tu equipo.\\12Sustitúyelo por\\\nel POKéMON que\\12quieras usar y\\\nluego ven a verme.",
  ["56:63a1"] = "Aún te quedan\\\n{STRBUF} minuto(s).\\12¿Quieres terminar\\\nahora?",
  ["56:63e2"] = "Bien. Espera en\\\nla Puerta Norte a\\12que se anuncien\\\nlos ganadores.",
  ["56:642a"] = "Vale. Vuelve fuera\\\ny termina\\11el juego.",
  ["56:6456"] = "El Concurso ha\\\nacabado. Esperamos\\12volveros a ver\\\naquí pronto.",
  ["56:649b"] = "En el PARQUE se\\\nsuelen celebrar\\12muchos Concursos.\\\nDeberías probar.",
  ["56:64df"] = "¿Cuándo será el\\\npróximo Concurso\\11Captura de Bichos?",
  ["56:6515"] = "El Concurso de\\\nCaptura de Bichos\\12es los martes,\\\njueves y sábados.\\12No sólo ganas\\\nun premio por\\12participar, sino\\\nque también puedes\\12quedarte con un\\\nPOKéMON bicho.",
  ["56:660d"] = "¿No te imaginas\\\nquién podría\\12hacer algo así?\\\n¿Y por qué?",
  ["56:6648"] = "¿Has visto ese\\\nextraño árbol en\\11el camino?\\12Eso explica por\\\nqué vienen menos\\12personas a visitar\\\nlas RUINAS ALFA.",
  ["56:69c0"] = "Hoy es {STRBUF}.\\\nEso significa que\\12hoy es el Concurso\\\nCaptura de Bichos.\\12Las reglas son\\\nsencillas.\\12Usa uno de tus\\\nPOKéMON y captura\\12un POKéMON bicho\\\npara ganar.\\12¿Te gustaría\\\nintentarlo?",
  ["56:6a70"] = "Aquí tienes las\\\nPARQUE BALL para\\11el Concurso.",
  ["56:6a9a"] = "{PLAYER} recibió\\\n20 PARQUE BALL.",
  ["56:6ab5"] = "Aquél que consiga\\\nel POKéMON bicho\\12más fuerte será\\\nel ganador.\\12Tienes 20\\\nminutos.\\12Si te quedas sin\\\nPARQUE BALL, estás\\11perdido.\\12Puedes quedarte\\\nel último POKéMON\\11que captures.\\12¡Sal y captura\\\nel POKéMON\\12bicho más fuerte\\\nque encuentres!",
  ["56:6b99"] = "¡Oh, oh…!\\12Tienes más de\\\nun POKéMON.\\12Tendrás que usar\\\na {STRBUF},\\12el primer POKéMON\\\nde tu equipo.\\12¿Te parece\\\nbien?",
  ["56:6c0a"] = "Bien, guardaremos\\\nlos otros POKéMON\\11mientras compites.",
  ["56:6c3e"] = "Los POKéMON de\\\n{PLAYER} se quedan\\11con el AYUDANTE.",
  ["56:6c6a"] = "Elige el POKéMON\\\nque usarás en\\12el Concurso y\\\nluego ven a verme.",
  ["56:6caf"] = "Muy bien.\\\nEsperamos verte\\11pronto por aquí.",
  ["56:6cdb"] = "¡Oh, oh…!\\\nEl primer POKéMON\\12de tu equipo no\\\npuede luchar.\\12Sustitúyelo por\\\nel POKéMON que\\12quieras usar y\\\nluego ven a verme.",
  ["56:6d4f"] = "¡Oh, oh…!\\\nTu equipo y\\12tu CAJA del PC\\\nestán llenos.\\12No tienes sitio\\\npara guardar el\\11POKéMON bicho.\\12Haz sitio en\\\ntu equipo o en\\12la CAJA del PC y\\\nluego ven a verme.",
  ["56:6df2"] = "¡Oh, oh…! Tienes\\\nun HUEVO como\\12primer POKéMON\\\nde tu equipo.\\12Sustitúyelo por\\\nel POKéMON que\\12quieras usar y\\\nluego ven a verme.",
  ["56:6e6d"] = "Aún te quedan {STRBUF}\\\nminutos.\\12¿Quieres terminar\\\nahora?",
  ["56:6eac"] = "Bien. Por favor,\\\nespera aquí\\12a que se anuncien\\\nlos ganadores.",
  ["56:6ee7"] = "Bien. Por favor,\\\nvuelve fuera y\\11termina.",
  ["56:6f12"] = "El Concurso ha\\\nacabado. Esperamos\\12volveros a ver\\\naquí pronto.",
  ["56:6f57"] = "Algunos POKéMON\\\nsólo aparecen en\\11el PARQUE.",
  ["56:6f80"] = "RAFA: ¡Uau! Me\\\nhas vencido. Eres\\11bastante bueno.",
  ["56:6fab"] = "RAFA: La suerte\\\ncuenta mucho.\\12Nunca se sabe\\\nqué POKéMON\\11va a aparecer.",
  ["56:6ff6"] = "SAM: Te envidio.\\\nEsta vez no\\11lo he conseguido.",
  ["56:7027"] = "SAM: ¿Has usado\\\nPOKéMON grandes?",
  ["56:7049"] = "NANO: ¡Eso es!\\\nVoy a entrenar\\12mejor a mis\\\nPOKéMON.",
  ["56:707d"] = "NANO: Quizá ganes\\\nmás puntos por\\12un POKéMON de\\\nun color inusual.",
  ["56:70c1"] = "GUILLE: ¿Eres el\\\nganador? ¿Qué\\11has atrapado?",
  ["56:70f1"] = "GUILLE: Me alegra\\\nhaber atrapado\\12el POKéMON\\\nque quería.",
  ["56:7135"] = "TINO: Enhorabuena.\\\n¡Te has ganado mi\\11respeto!",
  ["56:7163"] = "TINO: He atrapado\\\nun SCYTHER,\\11pero he perdido.",
  ["56:7197"] = "BENITO: El POKéMON\\\nque has atrapado…\\11es impresionante.",
  ["56:71c4"] = "BENITO: Es más\\\nfácil ganar con\\12un POKéMON bicho\\\nde nivel alto.\\12Pero creo que\\\ntambién cuentan\\11otros aspectos.",
  ["56:7232"] = "CINDY: ¿Ganaste?\\\n¡Qué bien!\\12¿Te apetece buscar\\\nPOKéMON bicho\\11conmigo?",
  ["56:727f"] = "CINDY: ¡Adoro\\\nlos POKéMON bicho!",
  ["56:729f"] = "KAI: ¡No…!\\\nNo me puedo creer\\11que haya perdido.",
  ["56:72d0"] = "KAI: ¡Dicen que\\\nalguien ha ganado\\11con un CATERPIE!",
  ["56:7302"] = "SAMUEL: La próxima\\\nvez ganaré yo.",
  ["56:7327"] = "SAMUEL: Vaya,\\\ncreí que obtendría\\11más puntos…",
  ["56:7356"] = "KOLDO: ¿Me das\\\nalgún consejo?\\12Quiero estudiar\\\ntu estilo.",
  ["56:7396"] = "KOLDO: He\\\nestudiado mucho,\\12pero eso no vale\\\npara ganar.",
  ["56:74dd"] = "¡Vaya…! Tu MOCHILA\\\nestá llena.\\12Guardaremos\\\ntu premio, pero\\11sólo hoy.\\12Haz sitio en ella\\\ny ven a verme.",
  ["56:754c"] = "¿{PLAYER}?\\12Aquí tienes el\\\npremio que te\\11guardábamos.",
  ["57:4122"] = "¡Hola! Soy BLANCA.\\12¡Todos jugaban a\\\nPOKéMON, así\\11que yo también!\\12¡Los POKéMON son\\\nmuy monos!\\12¿Quieres luchar?\\\n¡Te lo advierto!\\11¡Soy muy buena!",
  ["57:41a5"] = "¡Ayy…!\\12¡Uaaaaaaa!\\\n¡Eres malo!\\12¡No deberías ser\\\ntan serio! ¡Sí,\\11tú, niño, tú!",
  ["57:41f5"] = "¡Uaaaaa!\\12¡Uaaaaa!\\12¡Buaa, buaa…!\\\n¡Eres malo!",
  ["57:4223"] = "¡Sniff…!\\12¿Qué quieres?\\\n¿Una MEDALLA?\\12¡Ah, sí! Se me\\\nolvidaba. Toma la\\11MEDALLA PLANICIE.",
  ["57:4278"] = "{PLAYER}\\\nrecibió la\\11MEDALLA PLANICIE.",
  ["57:4290"] = "Con MED. PLANICIE\\\nlos POKéMON\\12podrán usar FUERZA\\\nfuera del combate.\\12Además, aumentará\\\nla VELOCIDAD de\\11tus POKéMON.\\12¡Ah, toma esto\\\ntambién!",
  ["57:4307"] = "¡Es ATRACCIÓN!\\\nUtiliza todo el\\12encanto de un\\\nPOKéMON.\\12¿No es perfecto\\\npara una monada\\11como yo?",
  ["57:4365"] = "¡Ah, ha estado\\\nmuy bien!\\12¡Vuelve cuando\\\nquieras! ¡Adiós!",
  ["57:43a0"] = "¡No creas que será\\\nfácil vencerme!",
  ["57:43bb"] = "¡Vaya…! Pensaba\\\nque eras débil…",
  ["57:43db"] = "En el mundo de los\\\nPOKéMON, ¿quién\\12es más fuerte: el\\\nmacho o la hembra?",
  ["57:441b"] = "Prefiero un\\\nPOKéMON mono a\\11un POKéMON fuerte.\\12¡Mis POKéMON son\\\nmonos y fuertes!",
  ["57:4469"] = "¡Oh, no, no, no!",
  ["57:447a"] = "Intento vencer a\\\nBLANCA, pero…\\11es deprimente.\\12¡De acuerdo! ¡Si\\\npierdo, volveré\\12a intentarlo\\\notra vez!",
  ["57:44de"] = "¡Oh, no! Has hecho\\\nllorar a BLANCA.\\12¡No te preocupes!\\\nPronto dejará de\\12llorar. Siempre\\\nllora si pierde.",
  ["57:4537"] = "¡Eres muy\\\ngracioso! ¡Me\\12gustas! ¡Pero\\\nno me rendiré!",
  ["57:457e"] = "Veamos… ¡Uups!\\\n¿Ya está?",
  ["57:4599"] = "¡Uau! ¡Debes de\\\nser muy bueno para\\12haberme ganado!\\\n¡Adelante!",
  ["57:45c8"] = "¡Hazlo lo mejor\\\nque puedas o\\11acabaré contigo!",
  ["57:45f7"] = "¡No! ¡Oh, MEOWTH,\\\nlo siento mucho!",
  ["57:4615"] = "Le había enseñado\\\na MEOWTH todo tipo\\11de ataques…",
  ["57:4644"] = "¡Hola, futuro\\\ncampeón!\\12Este GIMNASIO es\\\npara entrenadores\\12que usan POKéMON\\\nde tipo normal.\\12Te recomiendo usar\\\nlos POKéMON de\\11tipo lucha.",
  ["57:46b1"] = "¿Has ganado?\\\n¡Genial! Yo estaba\\12ocupado mirando\\\na las chicas.",
  ["57:4791"] = "(Suspiro…)\\\nMe trasladé aquí,\\12pero no vendo mis\\\nBICIS. ¿Por qué?\\12¿Montarías en una\\\nBICI para hacerme\\11publicidad?",
  ["57:4802"] = "¿De verdad? ¡Bien!\\12Dime tu nombre y\\\nnúmero de teléfono\\12y te prestaré\\\nuna BICI.",
  ["57:4852"] = "{PLAYER} tomó\\\nprestada una BICI.",
  ["57:4869"] = "¡Mis BICIS son de\\\ngran calidad!\\12Puedes usarlas en\\\ncualquier lugar.",
  ["57:48a2"] = "(Suspiro…)\\\n¡Oh, por el amor\\11de Dios…!",
  ["57:48f7"] = "¡Es una BICI\\\nnovísima!",
  ["57:49ad"] = "Si tratas bien a\\\ntus POKéMON,\\12ellos te\\\nquerrán.\\12¿Eh? Déjame ver\\\ntu {STRBUF}…",
  ["57:4a06"] = "¡Parece muy feliz!\\\nTe debe de\\11querer mucho.",
  ["57:4a36"] = "Me parece que\\\nconfía mucho\\11en ti.",
  ["57:4a64"] = "Es cariñoso\\\ncontigo. Parece\\11feliz.",
  ["57:4a98"] = "Es bastante mono.",
  ["57:4aa9"] = "Deberías tratarlo\\\nmejor. No está\\11acostumbrado a ti.",
  ["57:4adb"] = "Da la impresión de\\\nque no le gustas.\\11Parece malvado.",
  ["57:4b0e"] = "No dejo de perder\\\nen los combates y\\12mis POKéMON acaban\\\ndesmayándose…\\12Quizá sea ésa la\\\nrazón por la que\\11no les gusto…",
  ["57:4b71"] = "¡Si uso un objeto\\\ncon mi POKéMON,\\11se pone contento!",
  ["57:4c7e"] = "BILL: ¡Hola,\\\n{PLAYER}! Haznos\\12un favor y acepta\\\neste EEVEE.\\12Apareció cuando\\\najustaba la\\11CÁPSULA de TIEMPO.\\12Alguien tiene que\\\ncuidarlo y a mí\\11no me gusta salir.\\12¿Puedo confiar en\\\nti para jugar con\\11él, {PLAYER}?",
  ["57:4d49"] = "BILL: ¡Lo sabía!\\\n¡Ahí te lo dejo,\\12héroe! ¡Eres\\\ngenial, tío!\\12Vale, confío en\\\ntí. Cuídalo\\11bien.",
  ["57:4db5"] = "¡{PLAYER}\\\nrecibió\\11a EEVEE!",
  ["57:4dc8"] = "BILL: ELM dice que\\\nEEVEE evoluciona\\12en formas nuevas\\\ny desconocidas.",
  ["57:4e09"] = "No, espera. No\\\npuedes llevar\\11más POKéMON.",
  ["57:4e34"] = "¡Oh…! ¿Qué\\\nhacer ahora?",
  ["57:4e49"] = "BILL: Solía\\\nexperimentar con\\11un TELETRANSPORTE.\\12Debería\\\nprofundizar más.",
  ["57:4e93"] = "¡Oh! ¿Coleccionas\\\nPOKéMON? Mi hijo\\12BILL es un\\\nexperto.\\12Pero ha tenido\\\nque ir al CENTRO\\12POKéMON de\\\nCIUDAD IRIS.",
  ["57:4efa"] = "Qué alegría me\\\nda volver a ver\\11a mi hijo.",
  ["57:4f1d"] = "¿Eres entrenador?\\12Tengo un número\\\nde teléfono que\\11te será útil.",
  ["57:4f58"] = "{PLAYER} grabó\\\nel número de BILL.",
  ["57:4f72"] = "Mi hermano creó\\\nel sistema de\\12almacenamiento de\\\nPOKéMON del PC.\\12Te iba a dar el\\\nteléfono de\\11BILL…",
  ["57:4fc5"] = "No puedes grabar\\\nningún número más.",
  ["57:4fe8"] = "Mi hermano BILL\\\ncreó el sistema\\12de almacenamiento\\\nde los POKéMON.",
  ["57:50d7"] = "El tren no ha\\\nllegado…\\12¡Tengo una idea!\\\n¡Llevaré a cuestas\\11a los pasajeros!\\12Aunque no creo\\\nque funcione.",
  ["57:512e"] = "Pronto saldremos\\\npara C. AZAFRÁN.\\12¿Quiere\\\nsubir?",
  ["57:5164"] = "Por favor, ¿puedo\\\nver su PASE?\\12Vale. Pase por\\\naquí, señor.",
  ["57:51a0"] = "Lo siento, pero\\\nno tiene PASE.",
  ["57:51c3"] = "Siempre a su\\\nservicio.",
  ["57:51de"] = "Hemos llegado a\\\nCIUDAD TRIGAL.\\12Siempre a su\\\nservicio.",
  ["57:5217"] = "Soy el PRESIDENTE.\\12Mi sueño era crear\\\nun tren que fuera\\12más rápido que\\\ncualquier POKéMON.\\12Hace que JOHTO\\\nesté mucho más\\11cerca de KANTO.",
  ["57:5311"] = "¡Oh! ¡Eres mejor\\\nque BLANCA!\\12¿Conoces ese árbol\\\nque se mueve?\\12Si lo mojas con\\\nuna REGADERA,\\11ataca.\\12Pero como tienes\\\nalgunas MEDALLAS,\\11no te pasará nada.",
  ["57:53b6"] = "Lalala lalalala.\\\n¡Échale mucha\\11agua, cariño!",
  ["57:53e9"] = "¡Cuando regué ese\\\nárbol que se movía\\12en la RUTA 36, dio\\\nun salto!\\12Creo que se trata\\\nde un POKéMON.\\12Pero sólo alguien\\\ncomo nuestra LÍDER\\12de GIM., BLANCA,\\\npodría vencerle.",
  ["57:5485"] = "¿Conoces ese árbol\\\nque se mueve?\\12Si lo riegas,\\\n¡da un salto\\11de sorpresa!",
  ["57:5513"] = "El COLISEO del\\\npiso de arriba del\\12CENTRO POKéMON es\\\npara conectarse.\\12Los récords de los\\\ncombates están en\\12la pared. No puedo\\\npermitirme perder.",
  ["57:5597"] = "Me pregunto\\\ncuántos tipos de\\12POKéMON hay en\\\nel mundo.\\12Hace tres años, el\\\nPROF. OAK dijo que\\12había 150 tipos\\\ndistintos.",
  ["57:5614"] = "Un POKéMON de\\\nnivel superior no\\11siempre gana.\\12Aún así, su tipo\\\npuede tener alguna\\11desventaja.\\12No creo que haya\\\nun único POKéMON\\12que sea el más\\\nfuerte.",
  ["57:56fe"] = "Un día estaba\\\nluchando y mis\\12POKéMON no se\\\npodían mover.\\12Sus movimientos no\\\ntenían ningún\\12PUNTO de PODER,\\\no PP.",
  ["57:576f"] = "A veces, un\\\nPOKéMON sano\\12no puede usar\\\nsus movimientos.\\12Si ocurre esto,\\\ncúralo en el\\12CENTRO POKéMON,\\\no usa un objeto.",
  ["57:5a38"] = "Bienvenido al\\\nCENTRO COMERCIAL\\11de CIUDAD TRIGAL\\\n",
  ["57:5a5c"] = "El CENTRO\\\nCOMERCIAL tiene\\11buenos artículos.\\12Pero algunos\\\nobjetos sólo se\\12consiguen en\\\nel CASINO.",
  ["57:5abf"] = "¡Me encanta\\\nir de compras!",
  ["57:5adf"] = "Mamá es experta\\\nen gangas.\\12Siempre compra\\\ncosas a precios\\11más bajos.",
  ["57:5b25"] = "PB INFORMACIÓN\\12P1 TIENDA DE\\\n   ENTRENADORES\\12P2 ARTÍCULOS DE\\\n   COMBATE\\12P3 BOTIQUÍN\\12P4 TIENDA DE MT\\12P5 ÚLTIMO PISO",
  ["57:5cb7"] = "El POKéGEAR puede\\\nalmacenar hasta\\11diez números.\\12Es difícil decidir\\\nqué numeros debes\\11guardar.",
  ["57:5d0d"] = "Conseguí mi ABRA\\\nen el CASINO.\\12Ahora es mi mejor\\\ncompañero.",
  ["57:5d49"] = "Este CENTRO\\\nCOMERCIAL indica\\12que CIUDAD TRIGAL\\\nes muy grande.\\12Su gama de\\\nproductos no\\11tiene rival.",
  ["57:5dba"] = "Tu Compañero\\\nde Viaje\\12P1 TIENDA DE\\\n   ENTRENADORES",
  ["57:5e5e"] = "¡Estoy muy\\\ninquieto!\\12Uso VELOCIDAD X\\\npara acelerar\\11a mis POKéMON.",
  ["57:5ea7"] = "¡Eh! ¿Utilizas\\\nESPECIAL X cuando\\11luchas?\\12¡Es increíble!\\\n¡Aumenta las\\12características\\\nESPECIALES!",
  ["57:5f09"] = "Para los amantes\\\nde la victoria\\12P2 COLECCIÓN\\\n   DE COMBATE",
  ["57:5f9d"] = "Me encantan los\\\nPOKéMON fuertes.\\12Les doy PROTEÍNAS\\\npara mejorar su\\11ATAQUE.",
  ["57:5fe7"] = "El HIERRO mejora\\\nsu DEFENSA.",
  ["57:6009"] = "Algunos POKéMON\\\nsólo evolucionan\\12al intercambiarlos\\\ncon el Game Link.\\12Por ejemplo:\\\nMACHOKE, KADABRA,\\12HAUNTER y\\\nGRAVELER.\\12Dicen que hay\\\notros también.",
  ["57:60a2"] = "¡Curamos a\\\ntus POKéMON!\\12P3 BOTIQUÍN",
  ["57:61d8"] = "Hola. ¡Oh, tus\\\nPOKéMON…!",
  ["57:61ef"] = "Están muy unidos\\\na ti.\\12Este movimiento\\\nsería perfecto\\11para vosotros.",
  ["57:623b"] = "¡Son adorables!\\12Enséñales unas\\\nbuenas MT.",
  ["57:626d"] = "Parece malvado.\\\n¿Qué te parece\\11esta MT para él?",
  ["57:6297"] = "Seguro que hay\\\nMT que serían\\12perfectas para\\\ntus POKéMON.",
  ["57:62d6"] = "REGALO MISTERIOSO.\\12Con un simple\\\nbeep, recibes\\12un regalo. Búscalo\\\nen el menú.",
  ["57:630e"] = "La opción REGALO\\\nMISTERIOSO es para\\11Game Boy Color.",
  ["57:6342"] = "Los domingos viene\\\nuna señora a\\11examinar POKéMON.\\12¡Regala\\\nhasta las MT!",
  ["57:6388"] = "No puedes cambiar\\\nel nombre de un\\12POKéMON que has\\\nintercambiado.\\12El nombre refleja\\\nlos sentimientos\\12del entrenador\\\noriginal.",
  ["57:63f9"] = "Personaliza a tus\\\nPOKéMON\\12P4 TIENDA DE MT",
  ["57:6560"] = "¡Una máquina\\\nexpendedora!",
  ["57:6584"] = "¡Clang! ¡Salió\\\nuna lata de\\11{STRBUF}!",
  ["57:65a7"] = "¡Uups! No tienes\\\nbastante dinero.",
  ["57:65c0"] = "No hay sitio\\\npara nada más.",
  ["57:65e0"] = "¿Escuchas el CANAL\\\nde la SUERTE?\\12Si quieres ganar,\\\ncambia POKéMON\\12con mucha gente\\\npara conseguir\\11muchos números ID.",
  ["57:665f"] = "Si estás cansado,\\\nprueba las bebidas\\11de las máquinas.\\12A tus POKéMON\\\nles gustarán.",
  ["57:66af"] = "¡Tómate un\\\nrespiro!\\12P5 ÚLTIMO PISO",
  ["57:6ab5"] = "¡Bienvenido!\\12¡Aquí cambiamos\\\ntus fichas por\\11premios fabulosos!",
  ["57:6af0"] = "¿Qué premio\\\nquieres?",
  ["57:6b0d"] = "{STRBUF}.\\\n¿De acuerdo?",
  ["57:6b22"] = "¡Aquí tienes!",
  ["57:6b30"] = "¡Vaya! ¡Necesitas\\\nmás fichas!",
  ["57:6b4d"] = "Lo siento. No\\\ntienes más sitio.",
  ["57:6b6e"] = "Vale. ¡Guarda tus\\\nfichas y vuelve\\11cuando quieras!",
  ["57:6b9a"] = "¡Vaya! No tienes\\\nun MONEDERO.",
  ["57:6bba"] = "Yo siempre juego\\\nen esta máquina.\\12Gano más fichas\\\nque en otras.",
  ["57:6c03"] = "Me encanta esta\\\nnueva tragaperras.\\12Es más difícil\\\nque las de\\11CIUDAD AZULONA.",
  ["57:6c59"] = "Vivir es un juego,\\\ny yo jugaré hasta\\11que no pueda más.",
  ["57:6c90"] = "Las cartas…\\12Las prefiero a las\\\ntragaperras porque\\12son más fáciles\\\nde acertar.\\12Pero se gana\\\nmucho menos.",
  ["57:6cfc"] = "¡No pararé hasta\\\nque gane!",
  ["57:6d16"] = "Enseñé VENTISCA a\\\nmi POKéMON.\\12Ha sido difícil\\\nganar bastantes\\12fichas pero ha\\\nmerecido la pena.",
  ["57:6d72"] = "No gané en las\\\ntragaperras y\\12lo perdí todo en\\\nlas cartas…\\12Me enfadé tanto\\\nque tiré mi\\12MONEDERO al\\\nSUBTERRÁNEO.",
  ["57:6f2c"] = "El ENCINAR es muy\\\ngrande. ¡Cuidado!\\11No te pierdas.",
  ["57:6f5c"] = "El ENCINAR está\\\nvigilado por su\\11guardián.\\12¡No hagas\\\nnada malo!",
  ["57:6ffe"] = "¿Estás completando\\\nuna POKéDEX?\\12Sería duro si los\\\nPOKéMON no\\12aparecieran.\\\nPrueba esta MT.",
  ["57:7057"] = "Es DULCE AROMA.\\12Úsala siempre que\\\naparezcan POKéMON.\\12Atraerá a los\\\nPOKéMON.",
  ["57:70a2"] = "BUTTERFREE: ¡Frii!",
  ["57:70b6"] = "¿Has visto el\\\nsantuario en honor\\11del guardián?\\12Protege el\\\nBOSQUE desde\\11antaño.\\12Creo que debe\\\nde ser un POKéMON\\11del tipo planta.",
  ["57:71b8"] = "El abuelo te\\\nestaba buscando.",
  ["59:400b"] = "Soy el GURÚ\\\nPESCADOR, el mayor\\12de los HERMANOS\\\nPESCADORES.\\12¿Conoces al\\\nPESCADOR DAVID?\\12Pesca en la\\\nRUTA 44.\\12Me contó un truco\\\nsorprendente\\11por teléfono.\\12Gracias a él,\\\natrapé muchos\\12POKéMON raros.\\\n¡Menudo día aquél!",
  ["59:40fa"] = "Es una foto de\\\ngente pescando…\\12Lo están pasando\\\nmuy bien…",
  ["59:4177"] = "Hay un POKéMON\\\ndormido delante de\\11la CUEVA DIGLETT.\\12¡El momento ideal\\\npara atraparlo!\\12¿Pero cómo\\\ndespertarlo?",
  ["59:41ef"] = "Antes había un\\\nPOKéMON durmiendo\\12delante de la\\\nCUEVA de DIGLETT.\\12Pero parece que\\\nha desaparecido.",
  ["59:4255"] = "El FERRY es un\\\nbuen lugar para\\12conocer y luchar\\\ncon entrenadores.",
  ["59:4292"] = "Tienes algunas\\\nMEDALLAS que no\\11había visto nunca.\\12¡Claro! Las has\\\nganado en JOHTO.",
  ["59:43d8"] = "Soy el PRESIDENTE\\\ndel CLUB de FANS\\11de POKéMON.\\12He curado a más\\\nde 150 POKéMON.\\12Soy muy exigente\\\ncuando se trata de\\11POKéMON.\\12¿Has venido\\\npara saber\\11de mis POKéMON?",
  ["59:4468"] = "¡Muy bien!\\\n¡Pues escucha!\\12Mi… preferido\\\nes RAPIDASH…\\12Es… gracioso…\\\ncariñoso… veloz\\11e increíble…\\11¿No crees…? Es\\11sorprendente…\\11simpático…\\11¡Y lo quiero!\\12Si lo abrazas…\\\ncuando duerme…\\11es tan cálido…\\11y mimoso… Es\\11espectacular…\\11encantador…\\11¡Uuups! ¡Mira qué\\11hora es! ¡Hablo\\11demasiado!",
  ["59:4594"] = "¡Gracias por\\\nescucharme!\\11¡Toma esto!",
  ["59:45c9"] = "Es un CARAMELORARO\\\nque fortalece a\\11los POKéMON.\\12Prefiero que mis\\\nPOKéMON luchen\\12para fortalecerse.\\\n¡Así que toma!",
  ["59:4637"] = "¡Hola, {PLAYER}!\\12¿Has vuelto para\\\nsaber más cosas\\11sobre mis POKéMON?\\12¿No? Pues tengo\\\nmás historias…",
  ["59:468f"] = "¡Qué pena…!\\12¡Vuelve cuando\\\nquieras!",
  ["59:46c4"] = "Al PRESIDENTE\\\nle encanta hablar\\12cuando se trata de\\\nPOKéMON…",
  ["59:46f7"] = "Me encanta el\\\nmodo en que\\12CLEFAIRY mueve el\\\ndedo para usar\\12METRÓNOMO. ¡Es\\\ntan adorable!",
  ["59:4756"] = "Me gusta CLEFAIRY,\\\npero jamás podría\\12atrapar uno.\\\nPor eso me\\12conformo con este\\\nPOKé MUÑECO\\11que he encontrado.",
  ["59:47b1"] = "¡Ah, entiendo! La\\\nniña que perdió el\\12POKé MUÑECO\\\nestá triste…\\12Vale. ¿Podrías\\\ndevolverle este\\12POKé MUÑECO a\\\nesa pobre niña?\\12Un día me haré\\\namigo de un\\12CLEFAIRY real.\\\n¡No te preocupes!",
  ["59:4861"] = "{PLAYER} recibió\\\nPOKé MUÑECO.",
  ["59:4875"] = "¡Ya verás! Voy\\\na hacerme amigo\\12de un auténtico\\\nCLEFAIRY.",
  ["59:48af"] = "Tu MOCHILA está\\\nrepleta.",
  ["59:48ca"] = "¡Mira mi precioso\\\nBAYLEEF!\\12¡Lleva una hoja\\\ntan mona!",
  ["59:4908"] = "¡Es un CLEFAIRY!\\\n¿Verdad?\\12¡No! Es un\\\nPOKé MUÑECO\\11CLEFAIRY.",
  ["59:4940"] = "BAYLEEF: ¡Li liif!",
  ["59:4953"] = "Escuchemos\\\natentamente a\\11los entrenadores.",
  ["59:4980"] = "Si alguno alardea,\\\nhazlo tú también.",
  ["59:4a17"] = "¿Has oído hablar\\\ndel MAGNETOTRÉN?\\12Es un tren que\\\nva hasta CIUDAD\\11TRIGAL, en JOHTO.",
  ["59:4a6d"] = "Quiero ir a CIUDAD\\\nAZAFRÁN para ver\\11el MAGNETOTRÉN.",
  ["59:4ae2"] = "El TEAM ROCKET ya\\\nno está en KANTO.\\12Eso hace que\\\nme sienta mejor.",
  ["59:4b21"] = "Estoy pensando en\\\nir a comprar a\\11CIUDAD AZAFRÁN.",
  ["59:4b8b"] = "Durante años,\\\nDIGLETT ha estado\\12excavando un gran\\\ntúnel.\\12El túnel lleva a\\\nuna ciudad lejana.",
  ["59:4c99"] = "SURGE: ¡Oye,\\\nchaval!\\12Lo reconozco.\\\nPuede que no seas\\12tan listo como\\\npara retirarte,\\12¡pero eres\\\nvaliente!\\12¡En cuanto a\\\nlos POKéMON\\12eléctricos, soy\\\nel número uno!\\12Nunca he perdido\\\nen combate.\\12¡Acabaré contigo,\\\ntal y como hice\\12con mis enemigos\\\nen la guerra!",
  ["59:4d8a"] = "SURGE: ¡Arrrgh!\\\n¡Eres muy fuerte!\\12¡Muy bien! ¡Toma\\\nla MEDALLA TRUENO!",
  ["59:4dc9"] = "{PLAYER} recibió\\\nla MEDALLA TRUENO.",
  ["59:4de3"] = "SURGE: La MEDALLA\\\nTRUENO aumenta la\\12velocidad de los\\\nPOKéMON.\\12Te la mereces por\\\nhaberme vencido.\\12Llévala con\\\norgullo, ¿me oyes?",
  ["59:4e55"] = "SURGE: ¡Hola,\\\nchaval! ¿Aún\\12luchando y\\\nresoplando?\\12¡Mis POKéMON y yo\\\nseguimos en ello!",
  ["59:4ea8"] = "¿Vienes a derrotar\\\nal LT. SURGE?\\12¡No, si yo\\\npuedo impedirlo!",
  ["59:4ede"] = "¡Cuánto siento\\\nhaberle fallado,\\11LT. SURGE!",
  ["59:4f02"] = "Cuando aún estaba\\\nen el ejército, el\\12LT. SURGE me salvó\\\nla vida.",
  ["59:4f3a"] = "El LT. SURGE\\\nreconoció mi\\12potencial con\\\nlos POKéMON\\11eléctricos.\\12¿Crees que puedes\\\nvencerme?",
  ["59:4f89"] = "¡Ooh! ¡Increíble!",
  ["59:4f9d"] = "Si funcionaran las\\\ntrampas del\\12GIMNASIO, no lo\\\nhabrías logrado.",
  ["59:4fd9"] = "¡Voy a acabar\\\ncontigo! ¡Vas\\11a echar chispas!",
  ["59:500c"] = "¡Vaya! Me has\\\nvencido…",
  ["59:5028"] = "No te relajes\\\npor haberme\\12vencido… LT.\\\nSURGE es fuerte.",
  ["59:5069"] = "¡Hola, futuro\\\nCAMPEÓN!\\12Esta vez no\\\ntendrás tanta\\11suerte.\\12El LT. SURGE es\\\nmuy prudente. Ha\\12puesto trampas por\\\ntodo el GIMNASIO.\\12Pero (risas),\\\nlas trampas no\\11están activadas.\\12Te será fácil\\\nencontrar al\\11LT. SURGE.",
  ["59:5131"] = "¡Vaya combate más\\\nelectrizante!\\12¡Me has puesto\\\nmuy nervioso!",
  ["59:5170"] = "¡Bah! Aquí sólo\\\nhay basura.",
  ["59:5250"] = "¡Bienvenido a\\\nCIUDAD AZAFRÁN,\\12hogar del\\\nMAGNETOTRÉN!\\12Eso es lo que\\\nsuelo decir, pero\\12el MAGNETOTRÉN no\\\nfunciona ahora.\\12No recibe\\\nelectricidad\\12porque hay un\\\nproblema en la\\12CENTRAL de\\\nENERGÍA.",
  ["59:531d"] = "El MAGNETOTRÉN\\\nes lo más\\12famoso de\\\nCIUDAD AZAFRÁN.",
  ["59:53bb"] = "¡Hola!\\12ROJO lleva fuera\\\nmucho tiempo.\\12Tampoco ha\\\nllamado, así que\\12no sé dónde está,\\\nni lo que ha\\11estado haciendo.\\12Dicen que si no\\\nhay noticias es\\12que todo va bien,\\\npero estoy\\11preocupada por él.",
  ["59:547c"] = "Me preocupa que\\\nROJO esté herido o\\12enfermo, pero es\\\nun chico. Estoy\\12orgullosa de que\\\nesté haciendo\\12lo que quiere.",
  ["59:54e3"] = "Tienen programas\\\nque no se emiten\\11en JOHTO…",
  ["59:554b"] = "{PLAYER} jugó\\\na la N64.\\12Mejor irse. No hay\\\ntiempo que perder.",
  ["59:5582"] = "Parece que nadie\\\nlo ha usado en\\11mucho tiempo…",
  ["59:562b"] = "DALIA: ¡Hola! Mi\\\nhermano es LÍDER\\12del GIMNASIO de\\\nCIUDAD VERDE.\\12Pero sale tanto de\\\nla ciudad que trae\\12problemas a los\\\nentrenadores.",
  ["59:56b1"] = "DALIA: ¡Llegas\\\na tiempo! Iba a\\11tomar un té.\\12¿Quieres\\\ntomarte uno?\\12Tus POKéMON están\\\nun poco sucios.\\12¿Quieres que\\\nlimpie a uno?",
  ["59:573f"] = "DALIA: ¿Qué\\\nPOKéMON limpio?",
  ["59:5761"] = "DALIA: Vale, haré\\\nque mejore su\\11aspecto enseguida.",
  ["59:5791"] = "{STRBUF}\\\nparece contento.",
  ["59:57a5"] = "DALIA: ¡Ya está!\\\n¡Listo!\\12¿Qué? ¿Tiene buen\\\naspecto o no?\\12¡Qué POKéMON\\\nmás mono!",
  ["59:57f5"] = "DALIA: Siempre\\\ntomo té a esta\\12hora. Ven cuando\\\nquieras.",
  ["59:582f"] = "DALIA: ¿No quieres\\\nque te limpie un\\12POKéMON? Vale, tan\\\nsólo tomaremos té.",
  ["59:5872"] = "DALIA: Lo siento.\\\nNo puedo\\11limpiar un HUEVO.",
  ["59:5922"] = "OAK: ¡Ah, {PLAYER}!\\\nMe alegro de\\12que hayas venido\\\nhasta KANTO.\\12¿Qué opinas de los\\\nentrenadores que\\12hay por aquí? Son\\\nfuertes, ¿verdad?",
  ["59:599d"] = "¿Qué tal va tu\\\nPOKéDEX?\\12Veamos…",
  ["59:59c3"] = "Si pasas por aquí,\\\nespero que vengas\\11a visitarme.",
  ["59:59f7"] = "OAK: ¡Uau!\\\n¡Excelente!\\12Has conseguido las\\\nMEDALLAS de todos\\12los GIMNASIOS de\\\nKANTO. ¡Muy bien!\\12Sabía que\\\neras bueno.\\12¿Sabes qué,\\\n{PLAYER}? Arreglaré\\12todo para que\\\npuedas ir a MONTE\\11PLATEADO.\\12MONTE PLATEADO es\\\nuna gran montaña\\12llena de\\\nPOKéMON salvajes.\\12Es muy peligroso\\\npara un entrenador\\12normal, así que\\\nestá prohibido ir.\\12Pero en tu caso,\\\n{PLAYER}, haremos\\11una excepción.\\12Sube hasta la\\\nMESETA AÑIL. Desde\\12allí puedes llegar\\\na MONTE PLATEADO.",
  ["59:5b9d"] = "OAK: ¿Cómo? ¿No\\\nhas conseguido las\\11MEDALLAS DE KANTO?\\12Los LÍDERES de los\\\nGIMNASIOS de KANTO\\12son tan fuertes\\\ncomo los de JOHTO.\\12Te aconsejo que\\\nte enfrentes a\\11ellos.",
  ["59:5c37"] = "OAK: ¿Quieres\\\nconseguir las\\11MEDALLAS DE KANTO?\\12No será fácil,\\\npero la\\12experiencia\\\ntambién cuenta.\\12Ven a verme cuando\\\nlas tengas todas.\\11Te haré un regalo.\\12¡Sigue así,\\\n{PLAYER}!",
  ["59:5cf6"] = "El programa de\\\nla HORA POKéMON\\12del PROF. OAK\\\nno se emite aquí,\\11en KANTO.\\12¡Qué pena! ¡Me\\\ngustaría oírlo!",
  ["59:5d54"] = "Gracias a tu\\\ntrabajo en la\\12POKéDEX, la\\\ninvestigación del\\11PROF. ha avanzado.",
  ["59:5da2"] = "No se lo digas a\\\nnadie, pero la\\12HORA DE OAK\\\nno es en directo.",
  ["59:5de5"] = "Pulsa START para\\\nacceder al MENÚ.",
  ["59:5e04"] = "La opción GUARDAR\\\nestá en el MENÚ.\\12Utilízala con\\\nfrecuencia.",
  ["59:5e40"] = "Aquí dentro no\\\nhay nada…",
  ["59:5e59"] = "Hay un nuevo\\\ne-mail en el PC.\\12…\\12PROF. OAK,\\\n¿cómo van sus\\11investigaciones?\\12Yo no paro\\\nde estudiar.\\12Dicen que\\\n{PLAYER} se está\\11haciendo famoso.\\12Me alegra mucho\\\noirlo.\\12ELM, desde PUEBLO\\\nPRIMAVERA.",
  ["5a:400f"] = "¡NIDORAN, agítate!",
  ["5a:4020"] = "NIDORAN: ¡Nidoo!",
  ["5a:40cb"] = "BROCK: ¡Uau! No\\\ntodos los días\\12nos desafía\\\nalguien de JOHTO.\\12Soy BROCK, LÍDER\\\ndel GIM. de C.\\12PLATEADA y experto\\\nen POKéMON roca.\\12Mis POKéMON son\\\ninsensibles a la\\12mayoría de ataques\\\nfísicos. Te será\\12muy difícil\\\nhacerles daño.\\12¡Venga!",
  ["5a:41b6"] = "BROCK: Mi dura\\\ndefensa no soportó\\12los ataques de\\\ntus POKéMON…\\12Eres más fuerte de\\\nlo que pensaba…\\12Toma. Coge\\\nesta MEDALLA.",
  ["5a:4238"] = "{PLAYER} recibió\\\nla MEDALLA ROCA.",
  ["5a:4252"] = "BROCK: Gracias,\\\n{PLAYER}. Me gustó\\12luchar contigo,\\\naunque estoy un\\11poco triste.\\12La MEDALLA ROCA\\\nhará que tus\\12POKéMON sean aún\\\nmás fuertes.",
  ["5a:42d5"] = "BROCK: El mundo es\\\nenorme. Hay muchos\\12entrenadores tan\\\nfuertes como tú.\\12Espera y verás.\\\nYo también me voy\\12a hacer más\\\nfuerte.",
  ["5a:435d"] = "Los entrenadores\\\nde este GIMNASIO\\11usan POKéMON roca.\\12Los de roca tienen\\\nmayor DEFENSA.\\12Los combates\\\npueden durar mucho\\12tiempo. ¿Estás\\\npreparado?",
  ["5a:43ec"] = "Tengo que ganar\\\nestos combates…",
  ["5a:440a"] = "¡Eh, tú! ¡Chico\\\nde JOHTO! BROCK\\12es muy duro. Te\\\ncastigará si no\\12le tomas en\\\nserio.",
  ["5a:4469"] = "¡Eh, futuro\\\nCAMPEÓN! Eres\\12realmente temible.\\\n¿Vas a enfrentarte\\12a los LÍDERES DE\\\nGIMNASIO de KANTO?\\12Son fuertes y\\\nentregados, igual\\12que los LÍDERES de\\\nGIMNASIO de JOHTO.",
  ["5a:4502"] = "¡Hola, futuro\\\nCAMPEÓN! Este\\12GIMNASIO no te\\\nha costado mucho.\\12Tu forma de atacar\\\nha sido realmente\\12increíble. Lo\\\ndigo en serio.",
  ["5a:45d3"] = "¡Hola! ¡Mira mi\\\nGYARADOS!\\12Procede de un\\\nMAGIKARP. No me\\12puedo creer lo\\\nfuerte que es.",
  ["5a:4635"] = "Había una vez\\\nun anciano muy\\12raro que vendía\\\nMAGIKARP.\\12Decía que\\\nlos MAGIKARP del\\12LAGO DE LA FURIA\\\neran excelentes.",
  ["5a:46fc"] = "¡Sí! Ya no hay\\\nGIMNASIO en la\\12ISLA CANELA. Me\\\nquedé de piedra.\\12¿Sí? Estoy al\\\nteléfono. ¡Fuera!",
  ["5a:4758"] = "JIGGLYPUFF: Puff,\\\npuff.",
  ["5a:4770"] = "Casi todos los\\\nPOKéMON se duermen\\12al oír cantar a\\\nJIGGLYPUFF.\\12Cuando un POKéMON\\\nestá dormido sólo\\12se pueden usar\\\nciertos ataques.",
  ["5a:485a"] = "Me gusta dormirme\\\ncon la radio en…\\11¡Zzzz…!",
  ["5a:4a24"] = "En la LIGA\\\nPOKéMON, serás\\12puesto a prueba\\\npor el ALTO MANDO.\\12Deberás vencerlos\\\na todos. ¡Si\\12pierdes, volverás\\\na empezar!",
  ["5a:4aa1"] = "Espera.\\12¿Te vas a\\\nenfrentar ahora\\12al desafío de la\\\nLIGA POKéMON?\\12Pues yo no\\\nlo creo.\\12Mis POKéMON\\\nestán muy bien\\12entrenados y van a\\\nacabar contigo.\\12¡{PLAYER}!\\\n¡Te desafío!",
  ["5a:4b41"] = "…\\12Vale. He perdido.",
  ["5a:4b50"] = "¡Maldición…!\\\nSigo sin ganar…\\12Yo… Tengo que\\\npensar más en mis\\11POKéMON…\\12¡Umm! ¡Procura\\\nno perder!",
  ["5a:4ba9"] = "…\\12¡Uau…!\\\nCon ayuda de mis\\12compañeros, ¡voy a\\\nser el CAMPEÓN!",
  ["5a:4be1"] = "¿Qué? ¿Vas a\\\ndesafiar al ALTO\\12MANDO? ¿Seguro que\\\nestás preparado?\\12Si necesitas\\\nentrenarte más, mi\\12ABRA te puede\\\nayudar.\\12ABRA te puede\\\nTELETRANSPORTAR.\\12¿Te gustaría\\\nvolver a casa?",
  ["5a:4c93"] = "Vale. Concéntrate\\\nen la imagen\\11de tu casa…",
  ["5a:4cbd"] = "Vale, vale. ¡Que\\\ntengas suerte!",
  ["5a:4cdf"] = "ABRA: Aabra…",
  ["5a:4ddd"] = "Bienvenido a la\\\nLIGA POKéMON.\\12Permíteme que me\\\npresente. Me llamo\\11MENTO.\\12Me he entrenado\\\npor todo el mundo\\12para mejorar a mis\\\nPOKéMON psíquicos.\\12Y, por fin, me han\\\naceptado en el\\11ALTO MANDO.\\12¡Sólo puedo seguir\\\nmejorando!\\12¡Es imposible\\\nque pierda!",
  ["5a:4ed8"] = "No… Esto es…\\\nincreíble…",
  ["5a:4ef0"] = "Aunque haya\\\nperdido, no\\12cambiaré mis\\\nplanes.\\12¡Seguiré luchando\\\nhasta ser el mejor\\12de todos los\\\nentrenadores!\\12Y ahora {PLAYER},\\\nexperimenta toda\\12la fuerza del\\\nALTO MANDO.",
  ["5a:503f"] = "¡Ja, ja, ja!\\12Soy KOGA, del ALTO\\\nMANDO. Vivo en las\\12sombras, como un\\\nninja.\\12¡Te confundiré y\\\nte destruiré con\\11mi estilo!\\12Confusión, sueño,\\\nveneno…\\12¡Prepárate para\\\nser víctima de\\11mis técnicas!\\12¡Ja, ja, ja!\\12Los POKéMON no\\\nutilizan sólo\\12la fuerza bruta.\\\n¡Ya lo verás!",
  ["5a:5155"] = "¡Ah! ¡Has\\\ndemostrado\\11tu valor!",
  ["5a:5176"] = "He probado\\\ncontigo todo\\11lo que sé.\\12Pero he fallado.\\\nDebería\\11entrenarme más.\\12¡Entra en la\\\nsala siguiente,\\12y demuestra tus\\\nhabilidades!",
  ["5a:52aa"] = "Soy BRUNO, del\\\nALTO MANDO.\\12Entreno siempre al\\\nmáximo porque\\12confío en nuestro\\\npotencial.\\12Por eso somos\\\ntan fuertes.\\12¿Resistirás\\\nnuestro poder?\\12¿Mmm? No veo que\\\ntengas miedo.\\12Pareces decidido.\\\n¡Perfecto!\\12¿Listo, {PLAYER}?\\\n¡Te doblegarás\\12ante nuestro\\\ninmenso poder!\\12¡Ja, ja!",
  ["5a:53cf"] = "¿Qué? ¿Cómo hemos\\\npodido perder?",
  ["5a:53e8"] = "Como he perdido,\\\nno tengo derecho\\11a decir nada…\\12¡Enfréntate al\\\nsiguiente desafío!",
  ["5a:54d3"] = "Soy KAREN, del\\\nALTO MANDO.\\12¿Eres {PLAYER}?\\\n¡Qué gracia!\\12Me gustan los\\\nPOKéMON de tipo\\11siniestro.\\12Su naturaleza tan\\\nfuerte y salvaje\\12me parece muy\\\natractiva.\\12¿Crees que podrás\\\ndetenerlos? ¡A ver\\11que tal lo haces!\\12¡Vamos allá!",
  ["5a:55a4"] = "Eres bueno…\\\nMe gusta eso\\11en un entrenador.",
  ["5a:55d5"] = "POKéMON fuertes.\\12POKéMON débiles.\\12Ésa es la visión\\\negoísta que tiene\\11todo el mundo.\\12Si un entrenador\\\nes bueno, debería\\12ser capaz de ganar\\\ncon sus favoritos.\\12Me gusta tu\\\nestilo. Sabes\\11lo que importa.\\12Adelante. El\\\nCAMPEÓN te espera.",
  ["5a:5816"] = "LANCE: Te estaba\\\nesperando.\\12¡{PLAYER}!\\12Sabía que con tus\\\nhabilidades serías\\12capaz de llegar\\\nhasta mí.\\12No es necesario\\\ndecir nada más.\\12Lucharemos para\\\nsaber quién es el\\12más fuerte de\\\nlos dos.\\12Como entrenador\\\nmás poderoso y\\12CAMPEÓN de la LIGA\\\nPOKéMON…\\12¡Yo, LANCE, el\\\nmaestro de los\\12dragones, acepto\\\ntu desafío!",
  ["5a:5953"] = "Se acabó…\\12Pero es\\\nextraño.\\12No estoy enfadado\\\npor perder. De\\12hecho, estoy\\\ncontento.\\12Estoy contento por\\\nhaber presenciado\\12el nacimiento de\\\nun nuevo CAMPEÓN.",
  ["5a:59e1"] = "¡Uauu…!\\12Te has vuelto muy\\\npoderoso,\\11{PLAYER}.\\12Tus POKéMON han\\\nrespondido bien a\\12tu fuerza y\\\ndecisión.\\12Como entrenador,\\\nseguirás creciendo\\12fuerte con\\\ntus POKéMON.",
  ["5a:5a8c"] = "ROSA: ¡Oh, no!\\\n¡Todo ha acabado!\\12PROF. OAK, si no\\\nfuera tan lento.",
  ["5a:5aca"] = "PROF. OAK: ¡Ah,\\\n{PLAYER}! ¡Cuánto\\12tiempo sin\\\nverte!\\12Pareces más\\\nmaduro.\\12¡Tu victoria en\\\nla LIGA ha sido\\11fantástica!\\12Y todo gracias a\\\ntu dedicación,\\12confianza y amor\\\npor los POKéMON.\\12Tus POKéMON son\\\ngeniales.\\12Confían en ti\\\ncomo entrenador\\12y no se rinden\\\nnunca.\\12¡Enhorabuena,\\\n{PLAYER}!",
  ["5a:5bf6"] = "ROSA: ¡Vamos a\\\nentrevistar al\\11nuevo CAMPEÓN!",
  ["5a:5c26"] = "LANCE: Aquí va a\\\nempezar a haber\\11mucho ruido…\\12{PLAYER}, ¿puedes\\\nvenir conmigo?",
  ["5a:5c70"] = "ROSA: ¡Espera!\\\n¡No hemos hecho\\11la entrevista!",
  ["5a:5d51"] = "LANCE: Ha pasado\\\nmucho tiempo desde\\12la última vez que\\\nvine aquí.\\12Aquí rendimos\\\nhomenaje a los\\12CAMPEONES de la\\\nLIGA, eternamente.\\12Y admitimos\\\na sus valientes\\11POKéMON.\\12Hoy hemos\\\npresenciado el\\12nacimiento de un\\\nnuevo CAMPEÓN\\12de la LIGA. Un\\\nentrenador\\12compasivo,\\\nque confía en\\11sus POKéMON.\\12Un entrenador que\\\nha ganado gracias\\12a su constancia y\\\ndeterminación.\\12¡Un nuevo CAMPEÓN\\\nde la LIGA que\\12ha demostrado\\\nsu grandeza!\\12{PLAYER}, permíteme\\\nregistrarte a ti y\\12a tus compañeros\\\ncomo CAMPEONES.",
  ["5b:41b3"] = "El barco va a\\\nzarpar. Por favor,\\11suba a bordo.",
  ["5b:41de"] = "Lo siento. No\\\npuedes embarcar.",
  ["5b:41fa"] = "Bienvenido al\\\nFERRY S.S. AQUA.\\12¿Vas a embarcar\\\nhoy?",
  ["5b:4238"] = "¿Puedo ver tu\\\nTICKET BARCO?",
  ["5b:4259"] = "Siempre a su\\\nservicio.",
  ["5b:4274"] = "{PLAYER} enseña\\\nel TICKET BARCO.\\12Muy bien.\\\n¡Gracias, señor!",
  ["5b:42a9"] = "{PLAYER} intentó\\\nenseñar el TICKET\\11BARCO…\\12¡Pero no lo tiene!\\12¡Lo siento!\\\nSólo puedes subir\\12si tienes un\\\nTICKET BARCO.",
  ["5b:4310"] = "El FERRY zarpará\\\nel próximo lunes.",
  ["5b:4336"] = "El FERRY zarpará\\\nel viernes.",
  ["5b:435c"] = "Aquí es fácil\\\natrapar SHELLDER.\\12En otros sitios\\\nson raros.",
  ["5b:439d"] = "¿Cuántas CAÑAS\\\ntienes?\\12Las distintas\\\nCAÑAS sirven para\\12atrapar distintos\\\nPOKéMON.",
  ["5b:43de"] = "¡El S.S. AQUA usa\\\npropulsores para\\11surcar las olas!",
  ["5b:440a"] = "En KANTO hay\\\nmuchos POKéMON.\\12¡Ojalá pudiera ir!",
  ["5b:443f"] = "No queremos que te\\\ncaigas al mar\\12y por eso no\\\npuedes entrar.",
  ["5b:466e"] = "El barco va a\\\nzarpar. Por favor,\\11suba a bordo.",
  ["5b:4699"] = "Lo siento. No\\\npuedes embarcar.",
  ["5b:46b5"] = "Bienvenido al\\\nFERRY S.S. AQUA.\\12¿Vas a embarcar\\\nhoy?",
  ["5b:46f3"] = "¿Puedo ver tu\\\nTICKET BARCO?",
  ["5b:4714"] = "Siempre a su\\\nservicio.",
  ["5b:472f"] = "{PLAYER} enseña\\\nel TICKET BARCO.\\12Muy bien.\\\n¡Gracias, señor!",
  ["5b:4764"] = "{PLAYER} intentó\\\nenseñar el TICKET\\11BARCO…\\12¡Pero no lo tiene!\\12¡Lo siento!\\\nSólo puedes subir\\12si tienes un\\\nTICKET BARCO.",
  ["5b:47cb"] = "El FERRY zarpará\\\nel miércoles.",
  ["5b:47f2"] = "El FERRY zarpará\\\nel domingo.",
  ["5b:4818"] = "¿Vienes de\\\nJOHTO?\\12Dicen que allí\\\nviven muchos\\11POKéMON raros.",
  ["5b:49ad"] = "El FERRY S.S. AQUA\\\nse dirige a\\11CIUDAD CARMÍN.\\12Daremos un\\\naviso cuando\\11lleguemos.",
  ["5b:4a0d"] = "El FERRY S.S. AQUA\\\nse dirige a\\11CIUDAD OLIVO.\\12Daremos un\\\naviso cuando\\11lleguemos.",
  ["5b:4a6b"] = "Éste es tu\\\ncamarote.\\12Si están heridos\\\ntus POKéMON,\\12échate una\\\nsiestecita.\\12Eso los curará.",
  ["5b:4ac1"] = "Es tu camarote.\\12Puedes curar a tus\\\nPOKéMON durmiendo\\11una siesta.\\12El barco llegará\\\na su destino\\11mientras duermes.",
  ["5b:4b32"] = "Los pasajeros son\\\nentrenadores.\\12Están deseando\\\nluchar en sus\\11camarotes.",
  ["5b:4b84"] = "¡Uau!\\12Disculpa, hijo.\\\n¡Tenía prisa!\\12¡Mi nieta ha\\\ndesaparecido!\\12Es muy pequeña.\\\nSi la ves, por\\12favor, avísame.\\\n",
  ["5b:4c04"] = "El FERRY S.S. AQUA\\\nha llegado a\\11CIUDAD OLIVO.",
  ["5b:4c35"] = "El FERRY S.S. AQUA\\\nha llegado a\\11CIUDAD CARMÍN.",
  ["5b:4dba"] = "Voy a KANTO a\\\nponerme a prueba.",
  ["5b:4de0"] = "¡Quería ganar!",
  ["5b:4df2"] = "Los entrenadores\\\nde JOHTO pueden\\12luchar contra los\\\nLÍDERES de KANTO.",
  ["5b:4e2a"] = "¡Me entreno para\\\nser la CAMPEONA!",
  ["5b:4e4c"] = "¿En qué somos\\\ntan diferentes?",
  ["5b:4e6e"] = "¡Te ganaré un\\\ndía de éstos!",
  ["5b:4e8d"] = "¿Conoces a LILA?\\\nEs una DJ muy\\11buena de KANTO.",
  ["5b:4eb8"] = "¡Yaaaa!",
  ["5b:4ec2"] = "LILA es buena pero\\\nROSA es la mejor.\\12¡Me encantaría\\\nescuchar las\\11emisoras de JOHTO!",
  ["5b:4f0e"] = "¿Estás solo?\\\n¡Pues luchemos!",
  ["5b:4f30"] = "¡Es demasiado!\\\n",
  ["5b:4f4b"] = "Me pregunto si en\\\nKANTO habrá\\12montañas que valga\\\nla pena escalar.",
  ["5b:4f89"] = "Sí, es verdad,\\\nsoy un marinero.\\12¡No hacía\\\nnada malo!\\12Como el camarote\\\nestaba vacío, me\\11eché un sueñecito.\\12¡Ah! ¡Olvídalo!\\\n¡Luchemos!",
  ["5b:500e"] = "¡Lo siento! ¡Todo\\\nes culpa mía!",
  ["5b:5028"] = "Los marineros\\\nhacemos mucho\\12trabajo físico.\\\n¡Es agotador!",
  ["5b:5068"] = "¡Oh, no! He\\\nperdido algo\\11muy importante.",
  ["5b:509a"] = "No… No lo\\\nencuentro…",
  ["5b:50ae"] = "Me rindo. Hijo, no\\\ntienes por qué\\12buscarlo.\\\n¡Olvídalo!",
  ["5b:50ec"] = "¡Yujuu!\\\n¡Qué suerte!",
  ["5b:50fc"] = "¡Qué mala suerte!\\\n¡He perdido!",
  ["5b:5112"] = "He encontrado una\\\nmoneda muy bonita.\\12Alguien debe de\\\nhaberla perdido…",
  ["5b:5270"] = "¡Voy a KANTO para\\\nactuar en un\\12espectáculo de\\\ncomefuegos!",
  ["5b:52a4"] = "La débil llama\\\npierde fuerza.",
  ["5b:52be"] = "El fuego es débil\\\ncontra el agua.\\12No te importa,\\\n¿verdad?",
  ["5b:52fa"] = "¡Voy a ver a mi\\\nabuela para que me\\12atrape unos\\\ncuantos bichos!",
  ["5b:5329"] = "¡Ooh! ¡Uau!\\\n¡Qué duro eres!",
  ["5b:5347"] = "Encontrarás muchos\\\nPOKéMON en los\\11árboles de JOHTO.",
  ["5b:5379"] = "Intento olvidar a\\\nmis enemigos.\\11¡Luchemos!",
  ["5b:53a4"] = "Estoy desolada…",
  ["5b:53b5"] = "Lo mejor para\\\ncurar las penas\\12es hacer un\\\nviaje en barco.\\12Pero los viajes\\\nen FERRY son\\12demasiado\\\ncortos.",
  ["5b:5418"] = "Voy a una audición\\\nde mis canciones\\12en la EMISORA de\\\nCIUDAD TRIGAL.",
  ["5b:5456"] = "¡Uauu!\\\n¡Distorsión total!",
  ["5b:5470"] = "Hablando de la\\\nEMISORA, ¿cuál es\\12nº de la suerte\\\nde esta semana?",
  ["5b:54af"] = "¡Una buena cama!\\\nA dormir…",
  ["5b:54cc"] = "¡Ah! Me siento\\\ncomo nuevo.",
  ["5b:54e9"] = "El FERRY S.S. AQUA\\\nha llegado a\\11CIUDAD OLIVO.",
  ["5b:551a"] = "El FERRY S.S. AQUA\\\nha llegado a\\11CIUDAD CARMÍN.",
  ["5b:570e"] = "¡Ah! Gracias por\\\nvenir.\\12Estoy agotado\\\nde entretener\\11a esa niña.",
  ["5b:5760"] = "¿Te gusta viajar\\\nen el S.S. AQUA?\\12Prácticamente\\\nvuela por encima\\11de las olas.",
  ["5b:57aa"] = "Hola, hijo…\\\nNo encuentro\\11a mi nieta.\\12Si está en el\\\nbarco, no hay\\12problema. Pero,\\\n¿y si se ha\\11caído al mar?\\12Es muy revoltosa.\\\nPodría estar\\12molestando. Estoy\\\npreocupado…",
  ["5b:585a"] = "{PLAYER}, ¿verdad?\\\nMe han dicho que\\12has entretenido a\\\nmi nieta.\\12Quiero darte\\\nlas gracias.",
  ["5b:58b2"] = "¡Me gustaría que\\\ntuvieras esto!",
  ["5b:58d5"] = "Estamos viajando\\\npor todo el mundo.",
  ["5b:58f7"] = "CAPITÁN, venga,\\\njuegue conmigo.\\12¡Me aburro! Quiero\\\njugar más.",
  ["5b:5936"] = "¡Hola! ¿Quieres\\\njugar conmigo?\\12¿Qué…?\\12¿Que mi abuelo\\\nestá preocupado?\\12¡Debería irme!\\12¡Tengo que buscar\\\nal abuelo!",
  ["5b:599b"] = "¡Hola, abuelo!\\\nEstaba jugando\\12con el CAPITÁN y\\\neste chico.",
  ["5b:59dd"] = "¡Me he divertido\\\nmucho jugando!",
  ["5b:59f9"] = "¡Hola, hijo!\\\n¿Quieres luchar?",
  ["5b:5a1c"] = "¡Eres fuerte!",
  ["5b:5a2b"] = "¿Viajas\\\nsolo?\\12¿Tu madre no está\\\npreocupada?",
  ["5b:5a5e"] = "¿Crees que soy\\\nuna nena?\\11¡No es justo!",
  ["5b:5a84"] = "¡Oh! ¡Perdimos!",
  ["5b:5a92"] = "¡No deberías\\\nllamar nenas a\\11las chicas!",
  ["5b:5ab9"] = "¡No soy una nena!\\12¡Y no deberías\\\nllamar así a\\12una dama!",
  ["5b:5aea"] = "¡Oh! ¡Perdimos!",
  ["5b:5af8"] = "A veces, los niños\\\nson más listos que\\11los adultos.",
  ["5b:5b25"] = "¡Ssh! ¡Mi cerebro\\\nestá captando\\11señales de radio!",
  ["5b:5b51"] = "¡Escucho\\\nalgo…!",
  ["5b:5b67"] = "Entiendo. Puedes\\\noír la radio de\\11JOHTO en el FERRY.",
  ["5b:5b9e"] = "¿Qué opinas? Mis\\\nPOKéMON son\\11bonitos, ¿verdad?",
  ["5b:5bce"] = "¡Oh, no! ¡Mis\\\npreciosos POKéMON!",
  ["5b:5bec"] = "¡Debo ir a la\\\nPELUQUERÍA POKéMON\\12para ponerlos\\\nguapos!",
  ["5b:5c1f"] = "Me voy de compras\\\nal C. COMERCIAL\\11y luego…",
  ["5b:5c4d"] = "¿Qué es lo que\\\niba a hacer?",
  ["5b:5c66"] = "¡Ah, sí! Tengo que\\\nir a buscar a mis\\12POKéMON a la\\\nGUARDERÍA.",
  ["5b:5c97"] = "¿Qué tipos de\\\nPOKé BALL llevas\\11contigo?",
  ["5b:5cc4"] = "¡Espera! ¡Detente!\\\n¡No, por favor!",
  ["5b:5cdf"] = "Deberías usar las\\\nBALL adecuadas\\12para cada\\\nsituación.",
  ["5b:5d15"] = "El FERRY S.S. AQUA\\\nha llegado a\\11CIUDAD CARMÍN.",
  ["5b:5f4b"] = "¡Eh! ¿Podrías\\\nbuscar a mi\\11compañero?\\12¡Está haciendo de\\\nlas suyas en algún\\12sitio! ¡El muy\\\nvago!\\12Me gustaría ir a\\\nbuscarle, pero\\11estoy de servicio.",
  ["5b:5fd7"] = "¡Oh…!\\12El CAPITÁN se\\\npondrá furioso…",
  ["5b:5ffe"] = "¡Gracias, chico!\\\n¡Le he echado una\\12buena bronca y se\\\nha tranquilizado!",
  ["5b:603d"] = "¿Una niña pequeña?\\12Puede que la haya\\\nvisto por aquí.",
  ["5b:606d"] = "El comedor está\\\nahí delante.\\12Las escaleras del\\\nfondo conducen al\\12camarote del\\\nCAPITÁN.",
  ["5b:60bd"] = "No hay nada mejor\\\nque un combate\\12en mi tiempo\\\nlibre.",
  ["5b:60ea"] = "¡Gane o pierda, se\\\nacabó el descanso!",
  ["5b:6108"] = "Supongo que no\\\nganaré si no me\\11lo tomo en serio.",
  ["5b:6133"] = "Me aburro tanto.\\\n¿Quieres luchar?",
  ["5b:6151"] = "¡Uau! ¡Eres\\\ndemasiado fuerte!",
  ["5b:6169"] = "AZAFRÁN…\\\nAZULONA…\\12Dicen que hay\\\nmuchas ciudades\\11grandes en KANTO.",
  ["5b:61a7"] = "¡Urrf…!\\\n¡Estoy mareado!",
  ["5b:61ba"] = "No me puedo\\\nmover…",
  ["5b:61d2"] = "No vuelvo a ir en\\\nbarco. La próxima\\12vez viajaré en el\\\nMAGNETOTRÉN.",
  ["5b:6210"] = "¡Aquí es donde\\\ntrabajamos!",
  ["5b:6230"] = "He perdido en mi\\\npropio campo…",
  ["5b:624a"] = "Llevamos a muchos\\\npasajeros desde\\12CIUDAD CARMÍN a\\\nCIUDAD OLIVO.",
  ["5b:628c"] = "¡Aunque estemos en\\\nel mar, no puedo\\11pescar!\\12¡Qué aburrido!\\\n¡Luchemos!",
  ["5b:62d8"] = "Ya… Ya no\\\nme aburro…",
  ["5b:62f2"] = "Voy a pescar en\\\nlos muelles de\\11CIUDAD CARMÍN.",
  ["5b:6317"] = "¡Fortalezco mis\\\npiernas nadando\\12en la estela\\\ndel barco!",
  ["5b:6355"] = "¡Bailemos el Rock\\\nand Roll!",
  ["5b:636e"] = "No pude encontrar\\\nal REY del KARATE\\11en JOHTO.\\12Dicen que se está\\\nentrenando en\\11alguna cueva.",
  ["5b:63c9"] = "¡Soy marinero!\\12Pero entreno\\\nPOKéMON para\\11ser el CAMPEÓN.",
  ["5b:640c"] = "Me falta\\\nentrenamiento…",
  ["5b:642f"] = "¡Ocho MEDALLAS!\\\nEso demuestra que\\12has vencido a los\\\nLÍDERES de GIM.\\12¡No me extraña que\\\nseas tan bueno!",
  ["5b:6486"] = "¡No toques a\\\nmis alumnos!",
  ["5b:64a9"] = "¡Aaah!",
  ["5b:64b1"] = "Vamos de excursión\\\na las RUINAS de\\12las afueras de\\\nCIUDAD MALVA.",
  ["5b:64e4"] = "¿Conoces las\\\nRUINAS ALFA?",
  ["5b:6504"] = "¡Aarg!",
  ["5b:650d"] = "Las radios captan\\\nseñales extrañas\\11en las RUINAS.",
  ["5b:653f"] = "En las RUINAS\\\nALFA hay unas\\12extrañas piezas\\\nde piedra.",
  ["5b:6576"] = "¡Estoy agotado!",
  ["5b:6586"] = "He leído que hay\\\ncuatro piezas de\\11piedra como ésas.",
  ["5b:667f"] = "El FERRY S.S. AQUA\\\nnavega hasta KANTO\\12los lunes y\\\nlos viernes.",
  ["5b:66ed"] = "El FERRY sale\\\nsiempre los\\12miércoles y\\\nlos domingos.",
  ["5b:680b"] = "PLAZA MT. MOON\\\nNo tirar basura",
  ["5b:6882"] = "Cuando el sol se\\\npone, CLEFAIRY\\11sale a jugar.",
  ["5b:693b"] = "¡Shaoooh!",
  ["5c:400f"] = "Esperaba comprar\\\nalgunos souvenirs\\12en la ZONA SAFARI,\\\npero está cerrada.",
  ["5c:4050"] = "La nieta del\\\nGUARDA de la ZONA\\12SAFARI vive en la\\\nciudad.",
  ["5c:424f"] = "¡Fufufufu…!\\12Lo siento\\\nmucho…\\12¡Sólo bromeaba!\\12¡Soy la auténtica!\\12Soy SACHIKO, del\\\nGIMNASIO FUCSIA.\\11¡La original!",
  ["5c:42bb"] = "SACHIKO: Eres un\\\ntipo duro. ¡Y, sin\\11duda, has ganado!\\12Aquí tienes la\\\nMEDALLA ALMA.",
  ["5c:4305"] = "{PLAYER} recibió\\\nla MEDALLA ALMA.",
  ["5c:431c"] = "SACHIKO: ¡Eres tan\\\nfuerte! ¡Tengo un\\11regalo para ti!\\12Es TÓXICO, un\\\npotente veneno que\\12va agotando los\\\nPS de la víctima.",
  ["5c:438e"] = "SACHIKO: Voy a\\\nesforzarme por\\12mejorar mis\\\nhabilidades.\\12¡Quiero llegar a\\\nser mejor que mi\\11padre y que tú!",
  ["5c:4400"] = "¡Fufufu! ¡Soy\\\nSACHIKO, la LÍDER\\11del GIMNASIO!\\12¡No, no soy yo!\\\n¡Qué tonto eres!",
  ["5c:4440"] = "Te he engañado…",
  ["5c:4453"] = "¿Cómo reconocerás\\\na la auténtica\\11LÍDER?",
  ["5c:4480"] = "¡Te he engañado!\\\n¡Ja ja ja!",
  ["5c:4495"] = "¡Oh…! He perdido…\\\nNo eres débil…",
  ["5c:44b3"] = "¿Qué? ¿Mi disfraz\\\nno era perfecto?",
  ["5c:44d5"] = "¡Soy SACHIKO!\\12¿Cómo has sabido\\\nque no era yo?\\12¡Luchemos!",
  ["5c:450b"] = "¡Maldición!\\\n¡Quería ganar!",
  ["5c:4526"] = "Debes de estar\\\ncansado.",
  ["5c:4542"] = "¡Uajajaja!\\12Acertaste, chaval.\\\n¡Yo soy SACHIKO!",
  ["5c:456a"] = "¿A que era bueno\\\nmi disfraz?",
  ["5c:458b"] = "¡Eh, chico!\\\n¿No era bueno\\11mi disfraz?",
  ["5c:45ba"] = "¡Hola, futuro\\\nCAMPEÓN!\\12Echa un vistazo a\\\ntu alrededor.\\12Todos los\\\nentrenadores se\\11parecen a SACHIKO.\\12¿Cuál será la\\\nauténtica SACHIKO?",
  ["5c:4646"] = "¡Qué bien luchas,\\\nentrenador\\11de JOHTO!",
  ["5c:46e4"] = "Mi abuelo está en\\\ncasa de mi hermano\\12BILL, en CABO\\\nCELESTE.",
  ["5c:471a"] = "He visto a unos\\\nlentos y raros\\12POKéMON en el\\\nCAMINO DE BICIS.",
  ["5c:47b5"] = "¡Anda! Tienes un\\\nnuevo tipo de\\11POKéDEX.\\12¿Te la ha dado\\\nel PROF. OAK?",
  ["5c:47fd"] = "Me sorprendió\\\nmucho el GIMNASIO.\\12Había tres chicas\\\nque parecían\\11idénticas.",
  ["5c:484f"] = "¡Soy SACHIKO!\\\nAbracadabra…",
  ["5c:486f"] = "¿Has visto? ¡Ahora\\\nsoy como ella!",
  ["5c:4907"] = "Mi abuelo es el\\\nGUARDA de la ZONA\\11SAFARI.\\12Al menos lo era…\\12Decidió irse de\\\nvacaciones y se\\12fue al extranjero\\\nél solo.\\12Así fue como dejó\\\nde ocuparse de\\11la ZONA SAFARI.",
  ["5c:49b2"] = "Mucha gente se\\\nenfadó cuando\\12cerraron la ZONA\\\nSAFARI, pero el\\11abuelo es terco.",
  ["5c:4a0b"] = "Es una foto de un\\\nanciano sonriente\\12rodeado de\\\nPOKéMON.",
  ["5c:4a47"] = "Es una foto de una\\\nextensa pradera\\12llena de POKéMON\\\nraros jugando.",
  ["5c:4ac2"] = "¿Estás trabajando\\\nen una POKéDEX?\\12Es muy importante.\\\n¡No te rindas!",
  ["5c:4b31"] = "Los entrenadores\\\nambiciosos escalan\\12el MT. PLATEADO a\\\npesar del peligro.\\12Con sus fieles\\\nPOKéMON, sentirán\\12que pueden ir a\\\ncualquier lado…",
  ["5c:4c13"] = "¡Pues vaya!\\\nMe encontraste.\\12Por favor, no se\\\nlo digas a nadie.\\12Te daré esto si\\\nme guardas el\\11secreto. ¿Vale?",
  ["5c:4c81"] = "Es muy duro\\\nser famoso.\\12Todo el mundo\\\nme persigue.\\12Sólo quiero que me\\\ndejen en paz…",
  ["5c:4ce3"] = "FEAROW: ¡Fearow!",
  ["5c:4fa4"] = "Bienvenido al\\\nCOLISEO DEL\\11CLUB CABLE.\\12Aquí puedes luchar\\\ncontra un amigo.\\12¿Quieres\\\nluchar?",
  ["5c:4ffe"] = "Bienvenido al\\\nCENTRO DE CAMBIO\\11DEL CLUB CABLE.\\12Aquí puedes\\\ncambiar POKéMON\\11con un amigo.\\12¿Quieres cambiar\\\nPOKéMON?",
  ["5c:5068"] = "Bienvenido a la\\\nCÁPSULA DEL TIEMPO\\11DEL CLUB CABLE.\\12Puedes viajar al\\\npasado y cambiar\\11tus POKéMON.\\12¿Quieres viajar al\\\npasado?",
  ["5c:50e2"] = "Tu amigo no\\\nestá preparado.",
  ["5c:50fd"] = "Antes de conectar\\\nlas consolas,\\11guarda el juego.",
  ["5c:5130"] = "Espera, por favor.",
  ["5c:513e"] = "La conexión se ha\\\ninterrumpido por\\11inactividad.\\12Habla con tu\\\namigo y vuelve\\11cuando quieras.",
  ["5c:519a"] = "Vuelve algún día.",
  ["5c:51f2"] = "No puedes\\\nconectarte con\\11el pasado aquí.",
  ["5c:5213"] = "Tu amigo eligió\\\nuna sala distinta.",
  ["5c:5238"] = "Entra, por favor.",
  ["5c:5258"] = "Perdona. No\\\npuedes llevar a\\11{STRBUF}.",
  ["5c:5275"] = "No puedes llevar a\\\n{STRBUF} con\\11{STRBUF}.",
  ["5c:529c"] = "No puedes llevarte\\\na {STRBUF}\\11con la CARTA.",
  ["5c:52cd"] = "Lo siento. Estamos\\\narreglando la\\11CÁPSULA DE TIEMPO.",
  ["5c:52fc"] = "Lo siento. Estamos\\\najustando la\\11MÁQUINA DE CAMBIO.",
  ["5c:532c"] = "Lo siento. Estamos\\\najustando la\\11MÁQUINA DE LUCHA.",
  ["5c:535d"] = "¡Hola! Tú eres\\\n{PLAYER}, ¿no?\\12¿Quieres recoger\\\nlo que tengo\\11para ti?",
  ["5c:5391"] = "¡Aquí tienes!",
  ["5c:539f"] = "Esperamos poder\\\nayudarte de nuevo.",
  ["5c:53bc"] = "¡Oh! No tienes\\\nespacio para esto.\\12Para en cualquier\\\nCENTRO POKéMON\\12del país y podrás\\\nrecogerlo.",
  ["5c:541a"] = "¿No? Es muy\\\nextraño…",
  ["5c:553d"] = "Tu amigo está\\\npreparado.",
  ["5c:55be"] = "Tu amigo está\\\npreparado.",
  ["5d:401f"] = "Al norte de\\\nPUEBLO LAVANDA\\12está el TÚNEL\\\nROCA. Crúzalo\\12para llegar a\\\nla CENTRAL\\11de ENERGÍA.",
  ["5d:4072"] = "Hay un programa\\\nde radio que\\12pone música de\\\nPOKé FLAUTA.\\12Necesitas una\\\nTARJETA EXPN para\\11sintonizarlo.",
  ["5d:40db"] = "La EMISORA no\\\npuede transmitir\\12porque la CENTRAL\\\nde ENERGÍA no\\11funciona.",
  ["5d:411e"] = "El DIRECTOR de\\\nla EMISORA estaba\\11muy contento.\\12Dijo que han\\\nvuelto a emitir\\12porque la CENTRAL\\\nde ENERGÍA ya\\11funciona.",
  ["5d:4222"] = "El SR. FUJI vive\\\naquí, pero ahora\\11no está en casa.\\12Debe de estar en\\\nel CEMENTERIO.",
  ["5d:4271"] = "Algunas personas\\\nson tan crueles\\12que abandonan a\\\nsus POKéMON.\\12El abuelo recoge a\\\nlos POKéMON que\\12no tienen hogar\\\ny los cuida.",
  ["5d:42e7"] = "PSYDUCK: ¿Psyay?",
  ["5d:42fa"] = "NIDORINO: ¡Nido!",
  ["5d:430b"] = "PIDGEY: ¡Pijji!",
  ["5d:437e"] = "El PUEBLO LAVANDA\\\nes un pequeño y\\12apacible lugar,\\\nal pie de las\\11montañas.\\12Desde que se\\\nconstruyó la TORRE\\12de RADIO, acude\\\nalgo más de gente.",
  ["5d:445a"] = "Si vas a explorar\\\nuna cueva, debes\\12llevar siempre\\\nREPELENTE.\\12Aunque me gusta la\\\nexploración, aún\\12no he explorado\\\ntodas las cuevas.",
  ["5d:44dd"] = "He oído hablar de\\\nun artesano que\\12fabrica POKé BALL\\\na medida en PUEBLO\\12AZALEA, en JOHTO.\\\n¡Yo quiero una!",
  ["5d:4586"] = "SR. FUJI: ¡Hola!\\12¡Mmm…! Parece que\\\nestás educando a\\12tus POKéMON con\\\nmucho cariño.\\12Los amantes de los\\\nPOKéMON vienen a\\12rendir homenaje a\\\nPOKéMON muertos.\\12Por favor, muestra\\\ntu condolencia por\\12las almas POKéMON\\\nque han partido.\\12Seguro que eso\\\nles hará felices.",
  ["5d:4680"] = "Creo que aquí hay\\\notras tumbas de\\11POKéMON.\\12Hay muchas cámaras\\\nen las que sólo\\12puede entrar\\\nel SR. FUJI.",
  ["5d:46e4"] = "He venido con mi\\\nmadre a visitar\\12las tumbas de los\\\nPOKéMON…",
  ["5d:470e"] = "A los POKéMON que\\\nvivían conmigo…\\12los quería como a\\\nmis nietos…",
  ["5d:47f2"] = "¡Bienvenido!\\\nMira por donde\\12quieras en este\\\npiso.",
  ["5d:482d"] = "Lo siento, pero\\\nsólo puedes dar\\12una vuelta por la\\\nplanta baja.\\12Desde que una\\\nbanda criminal\\12asaltó la TORRE de\\\nRADIO, tuvimos\\12que incrementar\\\nnuestra seguridad.",
  ["5d:48c3"] = "En la TORRE de\\\nRADIO hay mucha\\12gente que trabaja\\\nduramente.\\12Seguro que están\\\nhaciendo todo lo\\12posible por emitir\\\nbuenos programas.",
  ["5d:492e"] = "¡Oh, no, no, no!\\12No hemos emitido\\\ndesde que cerró la\\12CENTRAL de\\\nENERGÍA.\\12Si no emitimos, de\\\nnada servirá el\\12esfuerzo realizado\\\npor la emisora.\\12¡Me arruinaré!",
  ["5d:49d4"] = "¿Eres tú\\\n{PLAYER}? ¿El que\\12arregló la CENTRAL\\\nde ENERGÍA?\\12Gracias a ti, no\\\nperdí mi empleo.\\12¡Sin duda, tú eres\\\nmi salvador!\\12Toma esto como\\\nagradecimiento.",
  ["5d:4a74"] = "Con eso podrás\\\nsintonizar los\\12programas de\\\nradio de KANTO.\\12¡Jajajaja!",
  ["5d:4ac6"] = "¡Oye, tío!\\12¡Soy el DIRECTOR\\\nde MÚSICA!\\12¡Vaya! Tu POKéGEAR\\\nno sintoniza mis\\12programas de\\\nmúsica. ¡Qué pena!\\12Si consigues una\\\nTARJETA EXPN, los\\12podrás oír. ¡Hazte\\\ncon una!",
  ["5d:4b83"] = "¡Oye, tío!\\12¡Soy el DIRECTOR\\\nde MÚSICA!\\12Soy el encargado\\\nde las fantásticas\\12melodías que se\\\nemiten aquí.\\12No seas anticuado.\\\n¡Atrapa la música\\11de las ondas!",
  ["5d:4c26"] = "PB RECEPCIÓN\\\nP1 VENTAS\\11P2 PERSONAL\\11P3 PRODUCCIÓN\\11P4 DESPACHO DEL\\11   DIRECTOR",
  ["5d:4c70"] = "Anima a los POKé-\\\nMON con la melodía\\12de la POKé FLAUTA\\\ndel CANAL 20",
  ["5d:4d5c"] = "¿Has estado en\\\nPUEBLO LAVANDA?\\12Hay una TORRE\\\nde RADIO muy alta.",
  ["5d:4df2"] = "Soy el hermano\\\npequeño del GURÚ\\11PESCADOR.\\12Veo que te gusta\\\npescar. ¡No\\12tengo ninguna\\\nduda!\\12Sé que tengo\\\nrazón.",
  ["5d:4e72"] = "Sí, sí. ¡Justo lo\\\nque pensaba!\\12¡Aquí tienes!\\\nToma esto. Es\\11una SÚPER CAÑA.",
  ["5d:4ebf"] = "Intenta pescar\\\nallí donde veas\\11agua.\\12Recuerda: puedes\\\ncapturar POKéMON\\12diferentes usando\\\ndistintas CAÑAS.",
  ["5d:4f2f"] = "¿Eh? ¿Me engañan\\\nmis ojos?",
  ["5d:4ff8"] = "¡Estoy alucinado!\\12Vino un chico\\\nde tu edad, de\\12pelo largo y\\\nmirada penetrante.\\12¡Y me obligó a\\\ndarle mis\\11queridos POKéMON!\\12Todavía me queda\\\nuno, ¿pero qué\\11hago si vuelve?\\12Pareces fuerte.\\\n¿Podrías cuidar\\12de mi POKéMON\\\nun rato?",
  ["5d:50e2"] = "¡Oh, gracias!\\12¡Cuídale bien,\\\npor favor!",
  ["5d:5110"] = "{PLAYER} recibió\\\nun POKéMON.",
  ["5d:5124"] = "No puedes llevar\\\nmás POKéMON.",
  ["5d:513e"] = "¡Oh, no…!\\\n¿Y qué hago\\11si vuelve?",
  ["5d:5165"] = "¡Hola! ¿Cómo está\\\nmi POKéMON?\\12Creo que ya\\\npasó el peligro.\\11¿Me lo devuelves?",
  ["5d:51a6"] = "¡Gracias!",
  ["5d:51b2"] = "¡Oye! ¡No llevas\\\na mi POKéMON\\11contigo!",
  ["5d:51d8"] = "Mi POKéMON te\\\nha tomado cariño.\\12¡Vale! ¡Quédatelo,\\\npero prométeme\\12que serás bueno\\\ncon él!",
  ["5d:5234"] = "¡Oh, no, no…!\\\nEs como si me\\11hubieran robado.",
  ["5d:5261"] = "Para los POKéMON,\\\nla felicidad es\\12estar con quien\\\nlos quiere.",
  ["5d:53ee"] = "¡UAUUUU!\\12¡Has llegado\\\nhasta aquí!\\12¡Que sepas que\\\nsoy muy fuerte!\\12¡Mis POKéMON\\\naplastarán piedras\\11y romperán huesos!\\12¡Atento!",
  ["5d:5464"] = "ANÍBAL: ¡Urgg!\\\n¡Urgg…!\\12¡Oooarrg!",
  ["5d:547f"] = "¿Qué? Ahora tienes\\\nmiedo, ¿no?\\12¿Qué? ¿No tiene\\\nnada que ver con\\12los POKéMON?\\\n¡Es cierto!\\12Venga.\\\n¡Luchemos!",
  ["5d:54eb"] = "¿Qué? ¿Cómo?\\\n¿He perdido?\\12¡Muy bien!\\\n¡Te mereces la\\11MEDALLA TORMENTA!",
  ["5d:552a"] = "{PLAYER}\\\nrecibió la\\11MEDALLA TORMENTA.",
  ["5d:5542"] = "Con MED. TORMENTA,\\\nte obedecerán los\\12POKéMON hasta\\\nel nivel 70.\\12Y permitirá a\\\ntus POKéMON usar\\12VUELO cuando no\\\nestén luchando.\\12¡Toma esto\\\ntambién!",
  ["5d:55cf"] = "Se trata de\\\nPUÑODINÁMICO.\\12¡No siempre golpea\\\npero cuando lo\\12hace produce\\\nconfusión!",
  ["5d:5625"] = "¡UAJAJAA! ¡Ha sido\\\nmuy divertido!\\12¡Pero una derrota\\\nes una derrota!\\12¡Desde ahora, voy\\\na entrenar 24\\11horas al día!",
  ["5d:568c"] = "A mis POKéMON y\\\na mí nos une una\\11gran amistad.\\12¡Nuestro vínculo\\\nnunca se romperá!",
  ["5d:56de"] = "¡No puede ser!",
  ["5d:56ef"] = "¡Parece que tú y\\\ntus POKéMON estáis\\11muy unidos!",
  ["5d:5723"] = "¡Los expertos en\\\nartes marciales no\\11tememos a nada!",
  ["5d:5745"] = "¡Es increíble!",
  ["5d:5756"] = "Los POKéMON de\\\nlucha temen a los\\11psíquicos…",
  ["5d:577f"] = "Las palabras no\\\nsirven. ¡Deja que\\11hablen tus puños!",
  ["5d:57b2"] = "…",
  ["5d:57b5"] = "¡He perdido!\\\n¡No sé qué decir!",
  ["5d:57ce"] = "¡Mis furiosos\\\npuños destrozarán\\11a tus POKéMON!",
  ["5d:57f7"] = "¡Me has aplastado!",
  ["5d:5809"] = "¡Mis POKéMON han\\\nperdido! Has\\11herido mi orgullo.",
  ["5d:58dd"] = "¿Conoces al\\\nPOKéMANÍACO?\\12Siempre está\\\npresumiendo de sus\\11raros POKéMON.",
  ["5d:5923"] = "Los entrenadores\\\nde este GIMNASIO\\11son muy peleones.\\12Si me quedo, puede\\\nque vengan\\11a por mí.\\12Éste es mi\\\nconsejo: el LÍDER\\12del GIMNASIO usa\\\nPOKéMON de lucha.\\12Para confundirle\\\nutiliza POKéMON\\11psíquicos.\\12Debilita a sus\\\nPOKéMON antes de\\12que puedan usar\\\nla fuerza física.",
  ["5d:5a2a"] = "¡{PLAYER}! ¡Has\\\nganado! ¡Con sólo\\11mirarte, lo sé!",
  ["5d:5ac9"] = "Parece que tus\\\nPOKéMON están\\12bien. ¿Hay algo\\\nque te preocupa?\\12…\\12¿El POKéMON del\\\nFARO tiene\\11problemas?\\12¡Entendido!\\12Esto debería\\\nayudarte.",
  ["5d:5b52"] = "{PLAYER}\\\nrecibió la\\11POCIÓN SECRETA.",
  ["5d:5b6c"] = "Mi POCIÓN SECRETA\\\nes muy potente.\\12Sólo la doy en\\\ncasos de urgencia.",
  ["5d:5bf5"] = "Tienes unos\\\nPOKéMON\\11magníficos.\\12¿Quieres una foto\\\nde recuerdo?",
  ["5d:5c3e"] = "¡Vale! ¡Sonríe!",
  ["5d:5c52"] = "¡Oh! ¡Qué mal!\\\nPensaba que sería\\12un maravilloso\\\nrecuerdo…",
  ["5d:5cb8"] = "¿Vienes de\\\nCIUDAD OLIVO?\\12¿Te acuerdas de\\\nlas cuatro islas\\11del camino?\\12Dicen que en\\\nellas se esconde\\12una criatura\\\nmítica marina.",
  ["5d:5d3b"] = "Dicen que sólo\\\npuedes verla si\\12tienes un ALA\\\nPLATEADA.\\12Debe de tener la\\\nmisma esencia que\\11la criatura.",
  ["5d:5da5"] = "Los torbellinos\\\nque rodean las\\12islas deben de\\\nser obra de esa\\11criatura.",
  ["5e:4011"] = "¡Hola! ¡Bienvenido\\\nal CENTRO\\12COMERCIAL de\\\nCIUDAD AZULONA!\\12El directorio\\\nestá en la pared.",
  ["5e:4057"] = "Este C. COMERCIAL\\\npertenece a la\\12misma cadena que\\\nel de TRIGAL.\\12Los dos fueron\\\nrenovados al\\11mismo tiempo.",
  ["5e:40cb"] = "Es la primera vez\\\nque vengo.\\12Es muy grande…\\12Me da miedo\\\nperderme.",
  ["5e:410c"] = "PB: INFORMACIÓN\\12P1: TIENDA DE\\\n    ENTRENADORES\\12P2: TIENDA DE MT\\12P3: REGALOS\\12P4: FARMACIA\\12P5: MÁQUINAS\\\n    EXPENDEDORAS",
  ["5e:41ed"] = "Hace poco que soy\\\nentrenador. Mi\\12hijo me animó a\\\nserlo.\\12Estoy impresionado\\\npor la cantidad de\\12objetos útiles\\\nque hay.",
  ["5e:4262"] = "A mi padre le está\\\ncostando aprender\\12los nombres de los\\\nobjetos y cómo se\\12supone que debe\\\nutilizarlos…",
  ["5e:42c0"] = "¡Objetos de máxima\\\ncalidad para\\11entrenadores!\\12P1: TIENDA DE\\\n    ENTRENADORES",
  ["5e:4377"] = "No sé en qué\\\nPOKéMON debería\\12utilizar esta\\\nMT…",
  ["5e:43aa"] = "¡Oh, oh! Cambié\\\nmis POKéMON sin\\12quitarles la\\\nMEJORA.",
  ["5e:43eb"] = "¡Sí! ¡Ya tengo\\\nun PORYGON!\\12Se me dan muy mal\\\nlas tragaperras.\\12¡Jamás ganaría\\\nbastantes fichas!\\12¿Ehh…?\\12¡El PORYGON que he\\\ncambiado se ha\\12convertido en otro\\\nPOKéMON!",
  ["5e:4485"] = "En la TIENDA DE MT\\\nhay ataques raros.",
  ["5e:44a9"] = "P2: TIENDA DE MT\\12¡Fortalece a tus\\\nPOKéMON!",
  ["5e:4545"] = "He venido a por\\\nuna CARTA SURF\\11para mi novia.",
  ["5e:4579"] = "Éste es el único\\\nlugar en el que\\12encontrarás\\\nCARTAS AMOR.",
  ["5e:45b0"] = "¡Dilo con un\\\nregalo!\\12P3: REGALOS",
  ["5e:4647"] = "Quiero comprar\\\nobjetos que\\12aumenten las\\\nhabilidades de\\12mis POKéMON. ¡Pero\\\nno tengo dinero!",
  ["5e:4696"] = "Quiero MÁS PP,\\\npara aumentar los\\12PP de los ataques.\\\n¡Pero no se vende!",
  ["5e:46da"] = "Si usas objetos en\\\ntus POKéMON, se\\11pondrán contentos.\\12Sin embargo, odian\\\nalgunos objetos.",
  ["5e:4724"] = "P4: FARMACIA",
  ["5e:486c"] = "¡Una máquina\\\nexpendedora!",
  ["5e:4890"] = "¡Clang!\\12Salió\\\n{STRBUF}.",
  ["5e:48aa"] = "¡Uups, no tienes\\\nbastante dinero!",
  ["5e:48c3"] = "No hay sitio\\\npara nada más…",
  ["5e:48e3"] = "Una máquina\\\nexpendedora con\\12una ruleta de\\\npremios…\\12Nunca verás\\\nnada igual.",
  ["5e:492c"] = "¡Auu! ¡Aquí no\\\nhay juegos!\\12¡Quería jugar…!",
  ["5e:495a"] = "ÚLTIMO PISO\\\nEXPENDEDORAS",
  ["5e:4a32"] = "Mis queridos\\\nPOKéMON me hacen\\12compañía, así que\\\nnunca estoy sola.\\12MEOWTH hasta trae\\\ndinero a casa.",
  ["5e:4a8c"] = "MEOWTH: ¡Meow!",
  ["5e:4a9b"] = "CLEFAIRY: ¡Clef\\\ncleff!",
  ["5e:4ab2"] = "NIDORAN: ¡Nido\\\nnido!",
  ["5e:4ac7"] = "DESPACHO DEL JEFE\\\nDE MANSIÓN AZULONA",
  ["5e:4b55"] = "{PLAYER} encendió\\\nel PC.\\12…\\12Alguien estaba\\\nescribiendo\\11un e-mail.\\12Espero que\\\nvengas a KANTO.\\12Te sorprenderás de\\\ncuánto han\\12cambiado las\\\ncosas por aquí.\\12También verás\\\nmuchos POKéMON\\12que no son nativos\\\nde JOHTO.\\12Al PRODUCTOR\\12…",
  ["5e:4c48"] = "SALA DE REUNIONES\\\nDE GAME FREAK",
  ["5e:4cea"] = "¡Hola!\\12¡Soy el DISEÑADOR\\\nDEL JUEGO!\\12Te costará\\\ncompletar tu\\12POKéDEX, pero\\\n¡no te rindas!",
  ["5e:4d41"] = "¡Uau! ¡Excelente!\\\n¡Has completado tu\\11POKéDEX!\\12¡Enhorabuena!",
  ["5e:4d7c"] = "…",
  ["5e:4d7f"] = "El ARTISTA GRÁFICO\\\nte imprimirá un\\11DIPLOMA.\\12Deberías presumir\\\nde ello.",
  ["5e:4dd0"] = "Soy el ARTISTA\\\nGRÁFICO.\\12¡Te he dibujado!",
  ["5e:4df4"] = "Soy el ARTISTA\\\nGRÁFICO.\\12¿Has completado\\\ntu POKéDEX?\\12¿Quieres imprimir\\\ntu DIPLOMA?",
  ["5e:4e4c"] = "Avísame si quieres\\\nque te imprima tu\\11DIPLOMA.",
  ["5e:4eb1"] = "¿Quién? ¿Yo? Soy\\\nel PROGRAMADOR.\\12¡Juega a las\\\ntragaperras!",
  ["5e:4ee6"] = "¿A que las GEMELAS\\\nson adorables?\\12Y YASMINA también\\\nes muy guapa.\\12¡Me encantan!",
  ["5e:4f27"] = "SALA DE DESARROLLO\\\nDE GAME FREAK",
  ["5e:4f44"] = "Es un dibujo\\\ndetallado de\\11una chica guapa.",
  ["5e:4f6e"] = "Es el programa\\\ndel juego. ¡No lo\\12toques! ¡Podrías\\\nestropearlo!",
  ["5e:4fb2"] = "Está lleno de\\\nmaterial de\\12referencia: hasta\\\nun POKé MUÑECO.",
  ["5e:50ad"] = "Te contaré una\\\nhistoria de miedo.",
  ["5e:50d0"] = "Pero no te dará\\\ntanto miedo si\\11aún es de día.\\12Vuelve cuando\\\nanochezca, ¿vale?",
  ["5e:5129"] = "Érase una vez un\\\nniño pequeño al\\12que le regalaron\\\nuna BICICLETA…\\12Quería probarla\\\nenseguida…\\12Se lo estaba\\\npasando tan bien\\12que olvidó que\\\nanochecía…\\12De vuelta a casa,\\\nen plena noche,\\12¡la bici empezó\\\na frenarse!\\12¡Cada vez era más\\\ndifícil pedalear!\\12Y cuando dejó de\\\npedalear, ¡la bici\\12empezó a moverse\\\nhacia atrás!\\12Era como si la\\\nbici estuviera\\12maldita y él fuera\\\na desaparecer.\\12…\\12…\\12(¡CHILLIDO!)\\12¡Y el niño siguió\\\nsubiendo por el\\11CAMINO de BICIS!\\12¡Ba-dum!\\\n¡Ba-dum ba-dum!\\12Por haberme\\\nescuchado, ¡aquí\\11tienes esta MT03!",
  ["5e:5339"] = "MT03 es MALDICIÓN.\\12Es un terrible\\\nataque que reduce\\12poco a poco los\\\nPS de la víctima.",
  ["5e:53b4"] = "ERIKA es experta\\\nen POKéMON planta.\\12Si no tienes\\\ncuidado, acabará\\11contigo.",
  ["5e:5405"] = "El TEAM ROCKET\\\nestá escondido\\12en el sótano del\\\nCASINO.\\12Espera. Eso fue\\\nhace tres años.",
  ["5e:5571"] = "¡Bienvenido!\\12Al lado puedes\\\ncambiar tus\\12fichas por\\\npremios fabulosos.",
  ["5e:55b6"] = "Todas las\\\ntragaperras son de\\11última generación.",
  ["5e:55e3"] = "Quiero jugar en\\\nesta máquina.\\12Ayer me desplumó,\\\nasí que hoy\\12soltará el\\\ndinero.",
  ["5e:5636"] = "Creo que esta\\\nmáquina soltará\\11el dinero…\\12Las posibilidades\\\nvarían según\\11la máquina.",
  ["5e:567d"] = "¡Bien!\\12¡Las fichas no\\\ndejan de salir!\\12¿Qué, chico?\\\n¿Quieres jugar?\\12¡Compartiré la\\\nsuerte contigo!",
  ["5e:56e6"] = "¡Bien!\\12¡Me gusta hacer\\\nfavores a la\\11gente!",
  ["5e:572b"] = "¡Eh! No tienes\\\nningún MONEDERO.\\12¿Y cómo te voy a\\\ndar las fichas,\\11chico?",
  ["5e:577a"] = "¡Eh! Tu MONEDERO\\\nestá lleno, chico.\\12Tú también debes\\\nde estar de\\11suerte.",
  ["5e:57c6"] = "¡Eh! ¡Futuro\\\nCAMPEÓN!\\12¿Tú también juegas\\\na las tragaperras?\\12Quiero conseguir\\\nbastantes fichas\\11para un POKéMON.\\12Pero aún no tengo\\\nbastantes…",
  ["5e:584e"] = "¡Mmm…! Los impares\\\nson mejores para\\12la línea PIKACHU.\\\n¿Qué hago?",
  ["5e:5894"] = "¡Eh!\\12Debajo de este\\\npóster…\\12¡No hay nada!",
  ["5e:58c2"] = "¡Eh!\\12Debajo de este\\\npóster…\\12¡No hay nada!",
  ["5e:58f0"] = "Aquí hay un\\\nencendedor.",
  ["5e:5908"] = "¡Un refresco!\\12Alguien se lo\\\nhabrá dejado…\\12¿Uh? ¡Está vacío!",
  ["5e:5c59"] = "Yo quería a\\\nMR.MIME, pero me\\12faltaban 100\\\nfichas…",
  ["5e:5c8a"] = "¡Uauu…!\\12Debo permanecer\\\ntranquilo…\\12No puedo perder\\\nla cabeza o\\11perderé todo…",
  ["5e:5cdf"] = "¡Bienvenido!\\12¡Aquí te cambiamos\\\ntus fichas por\\11premios fabulosos!",
  ["5e:5d15"] = "¿Qué premio\\\nquieres?",
  ["5e:5d32"] = "De acuerdo,\\\n¿{STRBUF}?",
  ["5e:5d4e"] = "¡Aquí tienes!",
  ["5e:5d5c"] = "No tienes\\\nbastantes fichas.",
  ["5e:5d79"] = "No tienes espacio\\\nsuficiente.",
  ["5e:5d93"] = "¡Vuelve cuando\\\ntengas fichas!",
  ["5e:5db5"] = "¡Vaya! No tienes\\\nun MONEDERO.",
  ["5e:5ec9"] = "ERIKA: Hola…\\\nBonito día,\\12¿verdad? Se está\\\ntan bien…\\12Podría hasta\\\ndormirme…\\12Me llamo ERIKA.\\\nSoy la LÍDER\\12del GIMNASIO de\\\nCIUDAD AZULONA.\\12¿Cómo? ¿Vienes\\\nde JOHTO?\\11¡Qué bien…!\\12¡Oh! Lo siento,\\\nno me di cuenta\\12de que querías\\\ndesafiarme.\\12Muy bien, pero\\\nno perderé.",
  ["5e:5fdf"] = "ERIKA: ¡Oh! Admito\\\nque he perdido…\\12Eres realmente\\\nbueno…\\12Te daré la MEDALLA\\\nARCOIRIS…",
  ["5e:6037"] = "{PLAYER} recibió\\\nMEDALLA ARCOIRIS.",
  ["5e:6051"] = "ERIKA: Ha sido un\\\ncombate genial.\\12Me has inspirado.\\\nAcepta esta MT\\11como regalo.\\12Es GIGA-DRENADO.\\12Es un fantástico\\\nataque que drena\\12la mitad del daño\\\nproducido para\\11curar al POKéMON.\\12Úsalo si\\\nquieres…",
  ["5e:6130"] = "ERIKA: La derrota\\\ndeja mal sabor\\11de boca…\\12Pero saber que\\\nhay entrenadores\\12más fuertes me\\\nanima a mejorar…",
  ["5e:619d"] = "¡Alto! ¡Aquí sólo\\\npueden entrar\\11las chicas!",
  ["5e:61c1"] = "¡Oh, maldición!",
  ["5e:61cd"] = "No es que no nos\\\ngusten los chicos.\\12Pero hay ciertos\\\ntemas de los que\\12sólo pueden hablar\\\nlas chicas.",
  ["5e:622f"] = "¡Oh! ¿Un combate?\\\nMe da un poco de\\11miedo, pero bueno.",
  ["5e:625b"] = "¡Oh! ¿Se acabó?",
  ["5e:626a"] = "¡Uauu! ¡Tienes\\\nmuchas MEDALLAS!\\12¡No me extraña\\\nhaber perdido!",
  ["5e:62a1"] = "¿Estabas mirando\\\nestas flores o\\11a mí?",
  ["5e:62ce"] = "¡Qué rabia!",
  ["5e:62dd"] = "¿Cómo voy a hacer\\\npara llegar a ser\\12tan elegante\\\ncomo ERIKA?",
  ["5e:630e"] = "¡Te enseñaremos\\\nlos movimientos\\12POKéMON que nos\\\nenseñó ERIKA!",
  ["5e:633e"] = "Hemos perdido…",
  ["5e:634c"] = "¡ERIKA te lo\\\nhará pagar!",
  ["5e:636d"] = "¡Vamos a proteger\\\na ERIKA!",
  ["5e:638b"] = "No ganamos…",
  ["5e:639c"] = "¡ERIKA es mucho,\\\nmucho más fuerte!",
  ["5e:64ba"] = "¡Hola!\\12Estamos celebrando\\\nun concurso\\11de tragones.\\12Perdona. Ahora no\\\npodemos atenderte.",
  ["5e:6505"] = "¡Ñam, ñam…!",
  ["5e:6516"] = "¡No me hables!\\12¡Me vas a\\\ndesconcentrar!",
  ["5e:6546"] = "¡Glup…! ¡Ñam…!",
  ["5e:6554"] = "¡Mejor cantidad\\\nque calidad!\\12¡Si estoy lleno,\\\nestoy feliz!",
  ["5e:658a"] = "¡Ñam, ñam…!",
  ["5e:6599"] = "La comida de aquí\\\nes buena, pero\\12en CIUDAD TRIGAL\\\nes aún mejor.",
  ["5e:65dd"] = "¡Ñam… Ñam…!",
  ["5e:65ee"] = "Aquí nadie te va\\\na dar un MONEDERO.\\12Mejor que lo\\\nbusques en JOHTO.",
  ["5e:6630"] = "¡Ñam… ñam…!\\12¡Sigo comiendo!",
  ["5e:6654"] = "¡Más, JEFE!",
  ["5e:6661"] = "¡Concurso de\\\ntragones! ¡Sin\\12tiempo! ¡Una lucha\\\nsin fin! ¡El mayor\\12tragón podrá\\\ncomer gratis!",
  ["5e:66c3"] = "{PLAYER} encontró\\\n{STRBUF}.",
  ["5e:66d5"] = "Pero {PLAYER} no\\\ntiene espacio…",
  ["5e:6757"] = "Si bajas por el\\\nCAMINO BICIS,\\12llegarás a\\\nCIUDAD FUCSIA.",
  ["5e:67e6"] = "Aquí empieza el\\\nCAMINO BICIS.\\12Es todo cuesta\\\nabajo. Es muy\\11emocionante.\\12Es una sensación\\\nque no se\\12experimenta en\\\nbarco o en tren.",
  ["5e:6874"] = "¡Eh! ¡Alto!\\12No puedes pasar\\\npor el CAMINO\\12BICIS si no vas\\\nen BICICLETA.",
  ["5e:690a"] = "¿Has oído lo del\\\naccidente de la\\11CENTRAL ENERGÍA?\\12Se encuentra al\\\nEste, cerca de\\11PUEBLO LAVANDA.",
  ["5e:6970"] = "Me tomo muy en\\\nserio mi trabajo\\11de GUARDA.\\12¡Eh! Tienes una\\\nPOKéDEX.\\12Vale. Puedes\\\npasar.",
  ["5e:6a0a"] = "CAMINO BICIS\\\nA partir de aquí,\\11es cuesta arriba.",
  ["5e:6a2b"] = "¡Alto! ¿No tienes\\\nuna BICI?\\12Aquí empieza el\\\nCAMINO BICIS.\\12Necesitas una\\\nBICI para seguir.",
  ["5f:4057"] = "AZUL: Bien. Por\\\nfin aquí, ¿no?\\12En ISLA CANELA no\\\nestaba de humor,\\12pero ahora estoy\\\nlisto para luchar.\\12…\\12¿Dices que has\\\nganado en todos\\12los GIMNASIOS de\\\nJOHTO?\\12¡Bah! Pues los\\\nGIMNASIOS de JOHTO\\12deben de ser\\\npatéticos.\\12Pero, ¡no más\\\npalabras!\\12Sabré si eres\\\nbueno o no\\12luchando contra\\\nti, ahora mismo.\\12¿Preparado, chico?",
  ["5f:4188"] = "AZUL: ¿Qué?\\12¿Cómo diablos he\\\nperdido?\\12…\\12¡Está bien…!\\\nToma, aquí tienes\\11la MEDALLA TIERRA.",
  ["5f:41e9"] = "{PLAYER} recibió\\\nla MEDALLA TIERRA.",
  ["5f:4201"] = "AZUL: …\\12De acuerdo, me he\\\nequivocado. Tenías\\12razón. Eres un\\\nbuen entrenador.\\12Pero algún día\\\nte derrotaré.\\12¡No lo\\\nolvides!",
  ["5f:4285"] = "AZUL: Escucha.\\12Será mejor que no\\\npierdas hasta que\\12yo te derrote.\\\n¿Entendido?",
  ["5f:42c8"] = "¡Hola, futuro\\\nCAMPEÓN! ¿Qué\\12tal te va?\\\nParece que estás\\11de suerte.\\12El LÍDER DEL\\\nGIMNASIO luchó\\12contra el CAMPEÓN\\\nhace 3 años.\\12¡Es un tipo duro!\\12¡Debes esforzarte\\\nal máximo!",
  ["5f:437a"] = "Tío, eres\\\nrealmente duro…\\12¡Qué batalla más\\\nemocionante!\\12Me ha hecho\\\nllorar.",
  ["5f:442e"] = "¿Dedicas mucho\\\ntiempo a pensar\\12en nombres para\\\ntus POKéMON?\\12Es más divertido\\\nintercambiarlos\\12si les pones\\\nbuenos motes.",
  ["5f:44a5"] = "Son SPEARY, un\\\nSPEAROW, y RATTEY,\\11un RATTATA.",
  ["5f:44d8"] = "SPEARY: ¡Spea!",
  ["5f:44ea"] = "RATTEY: ¡Ratii!",
  ["5f:4559"] = "Bienvenido a la\\\nCASA DEL\\12ENTRENADOR, el\\\nlugar más popular\\11de CIUDAD VERDE.\\12Es sólo para\\\nentrenadores.\\12Puedes luchar\\\ncontra los mejores\\12entrenadores en el\\\npiso de abajo.",
  ["5f:45ff"] = "La CIUDAD VERDE\\\nes la más cercana\\11a la MESETA AÑIL.\\12Construyeron este\\\nlugar debido al\\12gran número de\\\nentrenadores que\\12pasaban de camino\\\na la MESETA AÑIL.",
  ["5f:468f"] = "Aquí abajo tienen\\\nlugar combates\\11de entrenamiento.\\12Me encantaría ver\\\nlo bien que lucha\\12un entrenador de\\\nJOHTO.",
  ["5f:46f7"] = "Creo que no puedes\\\nser el CAMPEÓN\\12si no luchas\\\ncon toda la gente\\12que te encuentres\\\npor ahí.\\12El CAMPEÓN de\\\nPALETA viajó por\\12las ciudades y\\\npueblos de KANTO.",
  ["5f:47a3"] = "¡Ah…! Estoy\\\ndescansando de los\\11combates POKéMON.",
  ["5f:47ce"] = "Los combates de\\\nentrenamiento se\\12celebran en HALL\\\nDE ENTRENAMIENTO.\\12Los entrenadores\\\nmás hábiles están\\11invitados.",
  ["5f:4837"] = "No existen reglas\\\nsobre los combates\\12de prueba. Al\\\nigual que en los\\12combates reales,\\\naquí vale todo.",
  ["5f:489b"] = "¿Qué es esto?\\\n¿Una estrategia?\\12Esta letra se\\\nparece a las\\12huellas de ONIX…\\\n¡Es ilegible…!",
  ["5f:49fa"] = "Bienvenido al HALL\\\nDE ENTRENAMIENTO.\\12Puedes luchar\\\ncon un entrenador\\11cada día.",
  ["5f:4a44"] = "{STRBUF}\\\nserá hoy tu rival.",
  ["5f:4a61"] = "¿Quieres\\\nluchar?",
  ["5f:4a7c"] = "Entra, por\\\nfavor.\\12Puedes empezar\\\nahora mismo.",
  ["5f:4ab0"] = "Lo siento. Sólo\\\npueden entrar\\12aquéllos que van\\\na luchar.",
  ["5f:4af7"] = "Lo siento, señor.\\\nÉsta es la segunda\\12vez que viene hoy.\\\nSólo se puede\\12entrar una vez\\\nal día.",
  ["5f:4b57"] = "He perdido…\\\n¡Qué pena…!",
  ["5f:4b66"] = "He viajado hasta\\\naquí sólo para\\11luchar contra ti.",
  ["5f:4bd3"] = "El LÍDER de este\\\nGIMNASIO es\\11genial.",
  ["5f:4bf9"] = "¿Has estado en\\\nISLA CANELA?\\12Es una isla muy\\\nal sur de aquí.",
  ["5f:4c8c"] = "¿Dónde estará el\\\nLÍDER del GIMNASIO\\12de CIUDAD VERDE?\\\nQuería desafiarle.",
  ["5f:4cd4"] = "No hay ningún\\\nENTRENADOR en\\12el GIMNASIO de\\\nCIUDAD VERDE.\\12El LÍDER dice que\\\nsu política es\\12ganar sin tener\\\nsubordinados.",
  ["5f:4d4a"] = "Dicen que el\\\nGIMNASIO de ISLA\\12CANELA está\\\ndestruido.\\12Me pregunto que\\\nhabrá sido de\\11BLAINE, su LÍDER.",
  ["5f:4da7"] = "Mi sueño es ser\\\nLÍDER de GIMNASIO.",
  ["5f:4e44"] = "¡Hola! Me alegro\\\nde verte.\\12Eres la primera\\\nvisita que recibo\\12desde hace\\\nmucho tiempo.\\12¡Estoy muy\\\ncontento! Te voy\\12a hacer un\\\npequeño regalo.",
  ["5f:4ec4"] = "Es una PEPITA.\\12No puedo darte\\\npepitas de la\\12sabiduría,\\\n¡sólo esto!",
  ["5f:4f34"] = "¿Eres {PLAYER}?\\12Soy el AYUDANTE\\\ndel PROF. OAK.\\12No sabía que\\\nestabas aquí.\\12El LAB. del PROF.\\\nOAK está cerca de\\11PUEBLO PALETA.",
  ["5f:5008"] = "Sólo pueden pasar\\\nlos entrenadores\\12que demuestren\\\nsu valía.",
  ["5f:503e"] = "No tienes todas\\\nlas MEDALLAS\\11de JOHTO.\\12Lo siento, pero no\\\npuedo dejarte\\11pasar.",
  ["5f:5093"] = "¡Oh! ¡Las ocho\\\nMEDALLAS de JOHTO!\\12¡Le ruego que\\\npase, señor!",
  ["5f:50d0"] = "Este camino lleva\\\na MT.PLATEADO.\\12Donde verás a unos\\\nPOKéMON fuertes\\11y terribles.",
  ["5f:5116"] = "Vas a la LIGA\\\nPOKéMON, ¿verdad?\\12El ALTO MANDO es\\\ntan fuerte que da\\12miedo. ¡Están\\\nesperándote!",
  ["60:43f7"] = "ELM: ¡{PLAYER}!\\\n¡Eres tú!\\12Quería pedirte\\\nun favor.\\12Conozco a un tal\\\nSR. POKéMON,\\11que siempre está\\12descubriendo\\\ncosas nuevas\\12y presumiendo\\\nde ellas.\\12Acabo de recibir\\\nun e-mail suyo\\12diciendo que esta\\\nvez va en serio.\\12Me intriga, pero\\\nestamos ocupados\\12estudiando a los\\\nPOKéMON.\\12¿Podrías indagar\\\npor nosotros?\\12Te daré un POKéMON\\\npara que te\\11acompañe.\\12Todos son POKéMON\\\nraros que acabamos\\11de encontrar.\\12Venga. ¡Elige uno!",
  ["60:4590"] = "Si aparece un\\\nPOKéMON salvaje,\\12haz que tu POKéMON\\\nluche contra él.",
  ["60:45c2"] = "ELM: ¡Espera!\\\n¿Adónde vas?",
  ["60:45e3"] = "ELM: ¿Quieres a\\\nCYNDAQUIL, el\\11POKéMON de fuego?",
  ["60:460e"] = "ELM: ¿Quieres a\\\nTOTODILE, el\\11POKéMON de agua?",
  ["60:463a"] = "ELM: ¿Quieres a\\\nCHIKORITA, el\\11POKéMON planta?",
  ["60:4668"] = "ELM: Piénsalo\\\ncon cuidado.\\12Tu compañero es\\\nimportante.",
  ["60:46a2"] = "ELM: ¡Yo también\\\ncreo que es un\\11POKéMON genial!",
  ["60:46c8"] = "¡{PLAYER}\\\nrecibió a\\11{STRBUF}!",
  ["60:46db"] = "El SR. POKéMON\\\nvive cerca de\\11CIUDAD CEREZO.\\12Está casi en\\\nlínea recta.",
  ["60:472f"] = "Si hieren a tu\\\nPOKéMON, cúralo\\11con esta máquina.",
  ["60:476c"] = "Éste es mi número\\\nde teléfono.\\12Llámame si surge\\\nalgo.",
  ["60:47a9"] = "{PLAYER} anotó\\\nel número de ELM.",
  ["60:47c3"] = "El SR. POKéMON va\\\na todas partes y\\11encuentra rarezas.\\12¡Qué pena que\\\nsean tan raros\\11y tan inútiles!\\12¡{PLAYER},\\\nconfío en ti!",
  ["60:4835"] = "Contiene un\\\nPOKéMON atrapado\\11por el PROF. ELM.",
  ["60:485d"] = "Me pregunto qué\\\nserá esto.",
  ["60:4877"] = "¿Curar a\\\ntus POKéMON?",
  ["60:4883"] = "ELM: {PLAYER},\\\n¡qué horror…!\\12¡Ah, sí! ¿Cuál\\\nera el gran\\12descubrimiento del\\\nSR. POKéMON?",
  ["60:48c8"] = "{PLAYER} le dio el\\\nHUEVO MISTERIOSO\\11al PROF. ELM.",
  ["60:48ef"] = "ELM: ¿Esto?",
  ["60:48fb"] = "Pero… ¿Es un\\\nHUEVO de POKéMON?\\12Si lo es, ¡vaya\\\ndescubrimiento!",
  ["60:4936"] = "ELM: ¿¡Qué!?\\12¿El PROF. OAK te\\\ndio una POKéDEX?\\12{PLAYER}, ¿es eso\\\ncierto? ¡Mm…,\\11increíble!\\12OAK no suele\\\nequivocarse al\\12juzgar a un\\\nentrenador.\\12¡Oh, {PLAYER}!\\\nPuede que tengas\\12lo necesario para\\\nser un CAMPEÓN.\\12Además, pareces\\\nllevarte bien con\\11los POKéMON.\\12Deberías aceptar\\\nel desafío de un\\11GIMNASIO POKéMON.\\12El GIMNASIO más\\\ncercano es el de\\11CIUDAD MALVA.",
  ["60:4a85"] = "{PLAYER}. El\\\ncamino hacia la\\12gloria será\\\nlargo.\\12Antes de irte, no\\\nolvides hablar\\11con tu madre.",
  ["60:4af2"] = "ELM: ¡No te\\\nrindas! Si sé algo\\12sobre ese HUEVO,\\\nte llamaré.",
  ["60:4b33"] = "ELM: ¿{PLAYER}?\\\n¿No has visto a\\11mi ayudante?\\12Te esperaba con\\\nel HUEVO en el\\12CENTRO POKéMON\\\nde CIUDAD MALVA.\\12Si no lo has\\\nvisto, búscalo\\11ahí.",
  ["60:4bd1"] = "ELM: ¿Alguna\\\nnovedad?",
  ["60:4bf6"] = "¿{PLAYER}? Creía\\\nque el huevo se\\11había abierto.\\12¿Dónde está el\\\nPOKéMON?",
  ["60:4c28"] = "ELM: ¡Qué buen\\\naspecto, {PLAYER}!",
  ["60:4c41"] = "¿Qué?\\\n¿¡Ese POKéMON!?",
  ["60:4c55"] = "¡El HUEVO se\\\nabrió! Los POKéMON\\11deben nacer así.\\12Quizá no todos\\\nlos POKéMON.\\12¡Uauu! Aún nos\\\nqueda mucho por\\11aprender.",
  ["60:4cd2"] = "¡Gracias, {PLAYER}!\\\nNos estás ayudando\\12a descubrir los\\\nmisterios POKéMON.\\12¡Recibe esto\\\ncomo prueba\\11de nuestra estima!",
  ["60:4d43"] = "Eso es una\\\nPIEDRAETERNA.\\12Algunos POKéMON\\\nevolucionan al\\12alcanzar ciertos\\\nniveles.\\12Si un POKéMON\\\nva equipado con la\\12PIEDRAETERNA,\\\nno evolucionará.\\12Dásela al POKéMON\\\n\\\nque no quieras que\\11evolucione.",
  ["60:4ded"] = "ELM: {PLAYER},\\\nsi surge algo,\\11te llamaré.",
  ["60:4e1b"] = "(Suspiro…). El\\\nPOKéMON robado.\\12Me pregunto\\\ncómo estará.\\12Dicen que los\\\nPOKéMON educados\\12por malas personas\\\nse vuelven malos.",
  ["60:4e86"] = "ELM: ¡{PLAYER}!\\\nGracias a ti,\\12mis estudios\\\nvan fenomenal.\\12Toma esto como\\\nprueba de mi\\11estima.",
  ["60:4ee7"] = "¡La MASTER BALL\\\nes la mejor!\\12¡Es la BALL\\\ndefinitiva! Atrapa\\12cualquier tipo\\\nde POKéMON.\\12Sólo la tienen\\\nlos auténticos\\12investigadores\\\nde POKéMON.\\12¡Toma, {PLAYER}!\\\n¡Creo que a ti\\12te ayudará más\\\nque a mí!",
  ["60:4fa4"] = "ELM: ¡{PLAYER}!\\\n¿Qué tal?\\12Te he llamado\\\nporque tengo\\11algo para ti.\\12Es un TICKET\\\nde BARCO.\\12Ahora podrás\\\natrapar POKéMON\\11en KANTO.",
  ["60:5020"] = "El barco zarpa de\\\nCIUDAD OLIVO.\\12Pero eso ya lo\\\nsabías, {PLAYER}.\\12Has viajado por\\\ntodas partes con\\11tus POKéMON.\\12¡Dale recuerdos\\\nal PROF. OAK\\11en KANTO!",
  ["60:50e9"] = "{PLAYER}, toma\\\nesto por las\\11molestias.",
  ["60:5116"] = "Sólo somos dos,\\\nasí que siempre\\11estamos ocupados.",
  ["60:5146"] = "Oimos un ruido\\\nmuy fuerte…\\12Y cuando salimos\\\na mirar, alguien\\12nos robó un\\\nPOKéMON.\\12¡Es horrible\\\nque alguien\\11hiciera eso!\\12(Suspiro…) El\\\nPOKéMON robado.\\12Me pregunto cómo\\\nestará.\\12Dicen que los\\\nPOKéMON educados\\12por malas personas\\\nse vuelven malos.",
  ["60:5229"] = "¡{PLAYER}!\\12¡Usa esto para\\\nllenar tu POKéDEX!",
  ["60:524b"] = "Atrapa POKéMON\\\npara completar\\11tu POKéDEX.\\12Atrapa POKéMON\\\nsalvajes usando\\11las POKé BALL.",
  ["60:52a1"] = "Dicen que han\\\nrobado un POKéMON.\\12Y acabo de recibir\\\ncierta información\\11del PROF. ELM.\\12Parece que fue un\\\njoven pelirrojo,\\11de pelo largo.\\12¿Qué?\\12¿Que tú te has\\\nenfrentado a un\\11entrenador así?\\12¿Y sabes cómo\\\nse llama?",
  ["60:5371"] = "¡Bien! Así que su\\\nnombre es {RIVAL}.\\12¡Gracias por tu\\\ncolaboración!",
  ["60:53ae"] = "La ventana está\\\nabierta.\\12Entra una\\\nsuave brisa.",
  ["60:53e2"] = "¡Entró por\\\naquí!",
  ["60:53fd"] = "{PLAYER} abrió\\\nun libro.\\12Pista de viaje 1:\\12Pulsa START para\\\nabrir el MENÚ.",
  ["60:543b"] = "{PLAYER} abrió\\\nun libro.\\12Pista de viaje 2:\\12¡Graba tu viaje\\\ncon GUARDAR!",
  ["60:5477"] = "{PLAYER} abrió\\\nun libro.\\12Pista de viaje 3:\\12Abre tu MOCHILA y\\\npulsa SELECT para\\11mover objetos.",
  ["60:54c6"] = "{PLAYER} abrió\\\nun libro.\\12Pista de viaje 4:\\12Mira los ataques\\\nde tus POKéMON.\\12Pulsa A para\\\ncambiar de ataque.",
  ["60:5521"] = "Dentro está el\\\nenvoltorio del\\12tentempié que se\\\ntomó el PROF. ELM.",
  ["60:5719"] = "¡Ah, {PLAYER}…!\\\nNuestro vecino,\\12el PROF. ELM, te\\\nestaba buscando.\\12Dijo que quería\\\nque le hicieras\\11un favor.\\12¡Ah! ¡Casi se me\\\nolvida! Ya han\\12traído tu POKéGEAR\\\ndel taller.\\12¡Aquí tienes!",
  ["60:57d2"] = "El POKéMON GEAR o\\\nsólo POKéGEAR.\\12Es básico si\\\nquieres ser un\\11buen entrenador.\\12¡Ah! Falta el día\\\nde la semana.\\12¡No olvides\\\nponerlo!",
  ["60:5857"] = "¿Es horario\\\nde verano?",
  ["60:5878"] = "Vuelve a casa\\\npara cambiar de\\11hora el reloj.\\12Por cierto,\\\n¿sabes cómo usar\\11el TELÉFONO?",
  ["60:58e0"] = "¿Recuerdas que\\\nhay que encender\\12el POKéGEAR\\\ny elegir el\\11TELÉFONO?",
  ["60:591c"] = "Te leeré las\\\ninstrucciones.\\12Enciende el\\\nPOKéGEAR y elige\\11el TELÉFONO.",
  ["60:5965"] = "Los números están\\\nen la memoria.\\12Elige el nombre\\\nque quieras.\\12¿No te parece\\\nestupendo?",
  ["60:59ca"] = "El PROF. ELM te\\\nestá esperando.\\12¡Date prisa!",
  ["60:59fa"] = "¿Qué quería\\\nel PROF. ELM?\\12…\\12Parece muy\\\ndíficil.\\12Deberías estar\\\norgulloso de\\12que la gente\\\nconfíe en ti.",
  ["60:5a6c"] = "¡Vamos, {PLAYER}!\\12¡Cuentas con\\\ntoda mi ayuda!",
  ["60:5a92"] = "¡La especialidad\\\nde mi madre!\\12¡HAMBURGUESA\\\nVOLCÁN CANELA!",
  ["60:5abc"] = "El fregadero está\\\nimpecable. A mamá\\11le gusta limpio.",
  ["60:5ae9"] = "Veamos qué hay\\\nen la nevera…\\12¡AGUA FRESCA y una\\\nsabrosa LIMONADA!",
  ["60:5b28"] = "Una peli en TV:\\\ndos niños suben\\12a un tren bajo un\\\ncielo estrellado.\\12¡Mejor que yo\\\ntambién me vaya!",
  ["60:5c5c"] = "¡La HORA POKéMON\\\ndel PROF. OAK!\\12¡Sintonízanos la\\\npróxima vez!",
  ["60:5c8d"] = "¡EL CANAL POKéMON!",
  ["60:5c9c"] = "¡Soy la DJ ROSA,\\\nla presentadora!",
  ["60:5cbc"] = "¡POKéMON!\\\nCANAL POKéMON…",
  ["60:5d64"] = "PIKACHU es un\\\nPOKéMON\\11evolucionado.\\12Los hallazgos del\\\nPROF. ELM me\\11sorprendieron.\\12Es famoso por\\\nsus estudios\\12sobre la evolución\\\nde los POKéMON.\\12(Suspiro…).\\12Me gustaría ser\\\nuna investigadora\\11como él…",
  ["60:5e09"] = "¡La HORA POKéMON\\\ndel PROF. OAK!\\12¡Sintonízanos la\\\npróxima vez!",
  ["60:5e3a"] = "¡EL CANAL POKéMON!",
  ["60:5e49"] = "¡Soy la DJ ROSA,\\\nla presentadora!",
  ["60:5e69"] = "¡POKéMON!\\\nCANAL POKéMON…",
  ["60:5eb8"] = "¡Hola, {PLAYER}!\\\nMi marido siempre\\12está muy ocupado.\\\n¡Ojalá esté bien!\\12Cuando estudia\\\na los POKéMON,\\12se olvida hasta\\\nde comer.",
  ["60:5f2c"] = "¡Cuando sea mayor,\\\nayudaré a mi\\11padre!\\12¡Voy a ser un\\\ngran profesor\\11POKéMON!",
  ["60:5fdc"] = "Los POKéMON.\\\n¿De dónde vienen?\\12¿Adónde van?\\12¿Por qué no ha\\\npresenciado nadie\\12el nacimiento de\\\nun POKéMON?\\12¡Quiero saber!\\\n¡Quiero dedicar mi\\12vida al estudio de\\\nlos POKéMON!\\12…\\12Son algunos\\\npapeles del\\11PROF. ELM.",
  ["60:610b"] = "Tus POKéMON\\\nparecen cansados.\\12Deberías dejarlos\\\ndescansar un poco.",
  ["60:6149"] = "¡Vaya! ¡Tus\\\nPOKéMON tienen\\11buen aspecto!\\12¡Sigue así!",
  ["60:61b7"] = "Aquí hay algo\\\nescrito.\\12¿Quieres leerlo?",
  ["60:61e0"] = "A mis hermanos y\\\nhermanas:\\12Nos orgullece\\\nayudar a los\\12entrenadores\\\nPOKéMON.\\12Cuando habléis con\\\nlos entrenadores,\\11dadles algo útil.\\12Besos,\\\nLUNA\\12¿Seguir leyendo?",
  ["60:6277"] = "Lunes, LUNA\\\nRUTA 40\\12Martes, MARTA\\\nRUTA 29\\12Miércoles, MIGUEL\\\nLAGO DE LA FURIA\\12Jueves, JOSUÉ\\\nRUTA 36\\12Viernes, VICKI\\\nRUTA 32\\12Sábado, SABINO\\\nCIUDAD ENDRINO\\12Domingo, DOMINGO\\\nRUTA 37",
  ["60:6384"] = "¿A dónde vas con\\\nlos POKéMON?\\12¿A la LIGA\\\nPOKéMON?\\12¿Son tus POKéMON\\\nlo bastante\\12fieles como para\\\npemitirte ganar?\\12Déjame ver…",
  ["60:63e9"] = "¡Ah! Tus POKéMON\\\nconfían mucho\\11en ti.\\12Da gusto ver a un\\\nbuen entrenador.\\12Toma. Un regalo\\\npara el viaje.",
  ["60:644d"] = "MT37 contiene\\\nTORMENTA ARENA.\\12Este movimiento\\\ndaña a ambos\\11combatientes.\\12Es para entrenado-\\\nres avanzados.\\12Úsala si te\\\natreves. ¡Suerte!",
  ["60:64dd"] = "Si no confían\\\nmás en ti,\\12tendrás problemas\\\npara ganar.\\12La confianza es el\\\nvínculo entre los\\12POKéMON y sus\\\nentrenadores.",
  ["60:657f"] = "No puedes cruzar\\\nsetos.\\12Pero puedes saltar\\\npor encima de\\11ellos para atajar.",
  ["60:65cb"] = "Más adelante\\\naparecen muchos\\12tipos de\\\nPOKéMON.\\12Si quieres hacerte\\\ncon todos, tendrás\\12que buscar por\\\ntodas partes.",
  ["61:400d"] = "¡Hola!\\12El REY del KARATE,\\\nel maestro del\\12DOJO-KARATE, está\\\nentrenando en una\\11cueva de JOHTO.",
  ["61:4061"] = "¡Lo que tenga que\\\nser será!",
  ["61:4081"] = "¡Enemigos por\\\ntodas partes!",
  ["61:4180"] = "SABRINA: Sabía\\\nque vendrías…\\12Hace tres años\\\ntuve una visión\\11de tu llegada.\\12Tú lo que quieres\\\nes mi MEDALLA.\\12No me gusta\\\nluchar, pero mi\\12deber como LÍDER\\\nes conceder\\12MEDALLAS a todo\\\naquel que se las\\11merezca.\\12Como eso es lo que\\\nquieres, mira mis\\11poderes psíquicos.",
  ["61:4295"] = "SABRINA: Tu\\\npoder…\\12supera con creces\\\nlo que esperaba…\\12Quizá no se pueda\\\npredecir del todo\\12lo que nos espera\\\nen el futuro…\\12Vale, tú ganas.\\\nTe has ganado la\\11MEDALLA PANTANO.",
  ["61:4336"] = "{PLAYER} recibió\\\nMEDALLA PANTANO.",
  ["61:434e"] = "SABRINA: La\\\nMEDALLA PANTANO\\12muestra tus\\\npoderes ocultos.\\12Aunque no supe\\\npredecir tu poder\\12con exactitud,\\\nsabía que valías\\11mucho.\\12¡Te convertirás en\\\nun amado y alabado\\11CAMPEÓN!",
  ["61:440d"] = "SABRINA: Tu amor\\\npor tus POKéMON\\12supera mi poder\\\npsíquico…\\12Creo que el poder\\\ndel amor es un\\12tipo de poder\\\npsíquico…",
  ["61:448a"] = "¡El poder de todos\\\nlos que venciste\\11está en mí!",
  ["61:44bc"] = "Fuerte…\\\nMuy fuerte…",
  ["61:44d5"] = "¿De dónde proviene\\\ntu poder?",
  ["61:44f8"] = "El poder psíquico\\\nes el poder de tu\\11alma.",
  ["61:4522"] = "¡Tu alma tiene más\\\npoder que la mía!",
  ["61:4547"] = "Has fortalecido tu\\\nalma, no sólo tus\\11habilidades.",
  ["61:457e"] = "¡Fufufufu…!\\\nLo veo claramente.\\12¡Puedo leer\\\ntu alma!",
  ["61:45b5"] = "A pesar de leerte\\\nel pensamiento,\\11he perdido…",
  ["61:45d7"] = "¡Maldición! Olvidé\\\nque predije mi\\11derrota contra ti.",
  ["61:460d"] = "El DOJO-KARATE era\\\nel GIMNASIO\\11de esta ciudad.",
  ["61:4643"] = "¡Eres bueno…!",
  ["61:4654"] = "El REY del KARATE,\\\nel maestro del\\12DOJO-KARATE, acaba\\\nde ser machacado\\11por SABRINA.",
  ["61:46a2"] = "¡Hola, futuro\\\nCAMPEÓN!\\12Un entrenador tan\\\nhabilidoso como tú\\12no necesita que le\\\ndigan cómo luchar\\12contra POKéMON\\\npsíquicos, ¿no?\\12¡Espero mucho\\\nde ti!\\12¡Buena suerte!",
  ["61:4741"] = "¡Otro combate\\\nfantástico!",
  ["61:486d"] = "En PUEBLO LAVANDA\\\nhay una gran TORRE\\11de RADIO.",
  ["61:4894"] = "Quiero ser más\\\nfuerte, pero aún\\11soy muy mala…\\12¿Podrías enseñarme\\\ncómo algún día?",
  ["61:493b"] = "Hay una enorme\\\nCENTRAL de ENERGÍA\\12al norte de PUEBLO\\\nLAVANDA.",
  ["61:496e"] = "Acabo de cruzar\\\nel TÚNEL ROCA.\\12Pasaba algo en\\\nla CENTRAL de\\11ENERGÍA.",
  ["61:49c9"] = "Las cuevas suelen\\\nderrumbarse.\\12Últimamente han\\\ndesaparecido\\12varias cuevas,\\\ncomo la de\\11CIUDAD CELESTE.\\12Para un MONTAÑERO\\\nprofesional, eso\\11es obvio.",
  ["61:4a60"] = "La OFICINA CENTRAL\\\nde SILPH S.A. y\\12la ESTACIÓN del\\\nMAGNETOTRÉN son\\12los lugares más\\\nvistos de AZAFRÁN.",
  ["61:4b33"] = "…\\12…\\12…\\12¡Lo conseguí!\\12¡Tú lo quisiste!",
  ["61:4b56"] = "MT29 es PSÍQUICO.\\12Puede reducir\\\nlas HABILIDADES\\12ESPECIALES del\\\nblanco.",
  ["61:4c45"] = "Lo siento, pero el\\\nMAGNETOTRÉN no\\11funciona ahora.",
  ["61:4c79"] = "Pronto saldremos\\\nhacia CIUDAD\\11TRIGAL.\\12¿Quiere\\\nsubir?",
  ["61:4cb3"] = "Por favor, ¿puedo\\\nver su PASE?\\12Vale. Pase por\\\naquí, señor.",
  ["61:4cef"] = "Lo siento, pero\\\nno tiene un PASE.",
  ["61:4d11"] = "¡Vuelve siempre\\\nque quieras!",
  ["61:4d2c"] = "Hemos llegado a\\\nCIUDAD AZAFRÁN.\\12Siempre a\\\nsu servicio.",
  ["61:4d63"] = "El MAGNETOTRÉN es\\\nun tren ultra-\\12moderno, accionado\\\npor electricidad\\12e imanes. Su\\\nvelocidad es\\11increíble.\\12Sin embargo,\\\nsi no hay\\11electricidad…",
  ["61:4dfa"] = "¡Caramba…!\\12¡Cuántas veces he\\\nido de KANTO a\\12JOHTO y de JOHTO\\\na KANTO!",
  ["61:4e44"] = "Antes de que se\\\nconstruyera la\\12ESTACIÓN, ahí\\\nhabía una casa.\\12Y en ella vivía\\\nuna niña\\11llamada COPIONA.",
  ["61:4eb9"] = "Hola. ¿Tienes un\\\nPASE? Yo sí. Toda\\12la gente de CIUDAD\\\nAZAFRÁN que usa el\\12MAGNETOTRÉN tiene\\\nun PASE.",
  ["61:4f9c"] = "Bienvenido a la\\\nOFICINA CENTRAL\\11de SILPH S.A.",
  ["61:4fcf"] = "Al piso de arriba\\\nsólo pueden subir\\11los empleados.\\12Pero como has\\\nvenido desde tan\\12lejos, toma este\\\npequeño recuerdo.",
  ["61:5041"] = "Es lo último de\\\nSILPH S.A. Aún\\12no se encuentra\\\na la venta.",
  ["61:50cd"] = "A mi hija le gusta\\\nimitar a la gente.\\12Y por eso la\\\nllaman la\\11COPIONA.",
  ["61:512e"] = "Mi hija es muy\\\nintrovertida…\\12Tiene muy\\\npocos amigos.",
  ["61:516c"] = "Acaba de perder\\\nel POKé MUÑECO que\\12le regaló un niño\\\nhace tres años.\\12Desde entonces,\\\nimita a la gente\\11mucho mejor…",
  ["61:51e4"] = "BLISSEY: ¡Bliisii!",
  ["61:52f1"] = "{PLAYER}: ¿Te gusta\\\nPOKéMON?\\12{PLAYER}: No, yo\\\nsólo preguntaba.\\12{PLAYER}: ¿Eh?\\\n¡Eres muy rara!",
  ["61:533f"] = "COPIONA: ¿Cómo?\\\n¿Que no imite?\\12¡Pero si es mi\\\nhobby favorito!",
  ["61:537b"] = "{PLAYER}: ¡Hola!\\\nDicen que has\\12perdido tu POKé\\\nMUÑECO favorito.\\12{PLAYER}: Si lo\\\nencuentro, ¿me\\11darás un PASE?\\12{PLAYER}: Iré\\\na buscarlo.\\12¿Crees que lo\\\nperdiste en\\11CIUDAD CARMÍN?",
  ["61:542d"] = "COPIONA: ¿Perdona?\\12¿No tendría que\\\ndecirte yo lo\\11que debes hacer?\\12Estoy preocupada.\\\n¿Y si alguien\\11lo encuentra?",
  ["61:5496"] = "COPIONA: ¡Sí! ¡Ése\\\nes mi POKé MUÑECO\\11CLEFAIRY!\\12¿Ves el descosido\\\nque tiene en la\\12pata derecha?\\\n¡Ésa es la prueba!",
  ["61:54f9"] = "Está bien. ¡Aquí\\\ntienes el PASE del\\12MAGNETOTRÉN que\\\nte prometí!",
  ["61:552b"] = "COPIONA: Ése es\\\nel PASE para el\\11MAGNETOTRÉN.\\12La empresa de\\\nferrocarriles me\\12lo dio cuando\\\nderribaron nuestra\\12casa para edificar\\\nla ESTACIÓN.",
  ["61:55af"] = "{PLAYER}: ¡Hola!\\\nMuchas gracias por\\11el PASE de tren.\\12{PLAYER}: ¿Perdona?\\12{PLAYER}: ¿Tanto\\\nte divierte imitar\\11todo lo que hago?",
  ["61:560c"] = "COPIONA: ¿Apuestas\\\nalgo? ¡Es genial!",
  ["61:562d"] = "DODRIO: ¡Dodrii!",
  ["61:5640"] = "ESPEJITO, ESPEJITO\\\n¿QUIÉN ES EL MÁS\\12GUAPO DE\\\nTODOS?",
  ["61:567b"] = "¡Qué POKéMON\\\nmás raro!\\12Es un muñeco…",
  ["61:5702"] = "Muchas ciudades de\\\nJOHTO están llenas\\12de historia. ¡Cómo\\\nme gustaría ir!",
  ["61:5766"] = "Eres de JOHTO,\\\n¿verdad?\\12¿Qué opinas de\\\nKANTO? Es bonito,\\11¿no crees?",
  ["61:57ff"] = "¡Aaaayy!\\12Siento que una\\\nsiniestra sombra\\12se cierne\\\nsobre ti.\\12¡Toma esto para\\\nprotegerte!",
  ["61:5851"] = "Corrías un peligro\\\nmortal, pero ahora\\11estás protegido.",
  ["61:5888"] = "A mi abuela le\\\ngusta protegerse\\12contra supuestos\\\nmalos espíritus.\\12Perdona si te\\\nha asustado.",
  ["62:402c"] = "¡Se han quedado\\\nsin POKé BALL!\\12¿Cuándo\\\nconseguirán más?",
  ["62:406b"] = "¡Tengo POKé BALL\\\nde reserva! ¡Puedo\\11atrapar POKéMON!",
  ["62:4098"] = "Cuando iba por la\\\nhierba, un POKéMON\\12bicho envenenó\\\na mis POKéMON.\\12Yo seguí andando,\\\npero mi POKéMON\\11se debilitó.\\12Deberías llevar un\\\nANTÍDOTO contigo.",
  ["62:4182"] = "¡Es genial! Puedo\\\nguardar a todos\\12los POKéMON que\\\nquiera, ¡y gratis!",
  ["62:41c0"] = "Ese PC puede ser\\\nusado por todo\\11entrenador.",
  ["62:41e9"] = "El CENTRO de\\\nCOMUNICACIONES de\\12arriba está recién\\\nconstruido.\\12Pero aún no está\\\nterminado.",
  ["62:423e"] = "El CENTRO de\\\nCOMUNICACIONES de\\12arriba está recién\\\nconstruido.\\12¡Yo ya he cambiado\\\nPOKéMON en él!",
  ["62:42e2"] = "¿Quieres saber lo\\\nbueno que eres\\12como entrenador\\\nPOKéMON?\\12Pues vete a los\\\nGIMNASIOS POKéMON\\12de JOHTO y gana\\\nmuchas MEDALLAS.",
  ["62:435d"] = "¡Cuando sea mayor,\\\nvoy a ser un LÍDER\\11de GIMNASIO!\\12¡Hago luchar a mis\\\nPOKéMON con los\\12de mi amigo para\\\nfortalecerlos!",
  ["62:4405"] = "¡Cuando era niño,\\\nera un brillante\\11entrenador!\\12Éste es mi\\\nconsejo: ¡Atrapa\\11muchos POKéMON!\\12¡Y trátalos con\\\nmucho cariño!",
  ["62:44bb"] = "Luchando, los\\\nPOKéMON ganan\\12experiencia y se\\\ntransforman.",
  ["62:44f4"] = "¿Se transforman?\\12¡Alucinaría si\\\nlo viera!",
  ["62:457a"] = "Los POKéMON\\\ncomen BAYAS.\\12Mi POKéMON se\\\ncuró comiendo\\11una BAYA.\\12Toma. ¡Te daré\\\nuna!",
  ["62:45e4"] = "Busca BAYAS\\\nen los árboles.\\12Son muy fáciles\\\nde encontrar.",
  ["62:4755"] = "¡Hola! Debes de\\\nser {PLAYER}.\\12El PROF. ELM dijo\\\nque vendrías.",
  ["62:4797"] = "Esto es lo que\\\nquiero que\\12examine el\\\nPROF. ELM.",
  ["62:47c1"] = "{PLAYER} recibió\\\nun HUEVO MIST.",
  ["62:47da"] = "Conozco a una\\\npareja que tiene\\12una GUARDERÍA\\\nPOKéMON.\\12Ellos me dieron\\\nese HUEVO.\\12Como me intrigaba,\\\nle mandé una carta\\11al PROF. ELM.\\12El PROF. ELM es la\\\nmáxima autoridad\\12en evolución de\\\nlos POKéMON.",
  ["62:4881"] = "Hasta el PROF. OAK\\\nlo reconoce.",
  ["62:48a6"] = "Si tengo razón,\\\nel PROF. ELM lo\\11sabrá.",
  ["62:48dc"] = "¿Vas a ir a ver\\\nal PROF. ELM?\\12Toma. Tus POKéMON\\\ndeberían descansar\\11un poco.",
  ["62:4923"] = "¡Confío\\\nen ti!",
  ["62:4939"] = "¡La vida es\\\ngenial! ¡Siempre\\12quedan cosas por\\\ndescubrir!",
  ["62:4974"] = "OAK: ¡Así que tú\\\neres {PLAYER}!\\12¡Yo soy OAK!\\\n¡Un científico\\11POKéMON!\\12Estaba visitando a\\\nmi viejo amigo el\\11SR. POKéMON.\\12Y como me dijo que\\\ntenías algo para\\12el PROF. ELM,\\\ndecidí esperarte.\\12¡Oh! ¿Qué es esto?\\\n¡Un POKéMON raro!\\12Veamos…\\12¡Mmm, ya veo!\\12Ahora entiendo por\\\nqué el PROF. ELM\\12te confió un\\\nPOKéMON.\\12Para científicos\\\ncomo el PROF. ELM\\12y yo, los POKéMON\\\nson amigos.\\12Sabía que\\\ntratarías a tus\\12POKéMON con\\\nmucho cariño.\\12¡Ah!\\12Pareces ser de\\\nconfianza.\\12¿Te gustaría\\\nayudarme?\\12Mira. Ésta es la\\\núltima versión de\\11la POKéDEX.\\12Registra los datos\\\nde los POKéMON\\12que has atrapado\\\no que has visto.\\12¡Es una moderna\\\nenciclopedia!",
  ["62:4bbb"] = "¡{PLAYER} recibió\\\nla POKéDEX!",
  ["62:4bcd"] = "Busca muchos\\\ntipos de POKéMON\\12y completa esa\\\nPOKéDEX.\\12Ahora tengo\\\nque irme.\\12Me esperan en\\\nCIUDAD TRIGAL para\\12presentar mi\\\nprograma de radio.\\12¡{PLAYER}, cuento\\\ncontigo!",
  ["62:4c65"] = "¿Mmm? ¡Esa ESCAMA!\\\n¿De qué es? ¿De\\11un GYARADOS rojo?\\12¡Es muy rara!\\\nQuiero tenerla…\\12{PLAYER}, ¿quieres\\\nintercambiarla?\\12Yo te ofrezco\\\nREPARTIR EXP.\\12Me lo dio\\\nel PROF. OAK.",
  ["62:4cfc"] = "Es una pena.\\\nEs realmente\\11raro.",
  ["62:4d32"] = "Lleno de revistas\\\nextranjeras.\\12Ni siquiera puedo\\\nleer los títulos.",
  ["62:4d73"] = "Es un ordenador\\\nenorme. ¡Mmm!\\11Está estropeado.",
  ["62:4d9b"] = "¡Un montón de\\\nmonedas extrañas!\\12Quizá sean de\\\notro país…",
  ["62:4e29"] = "¡Hola, chico!\\\n¿Has visitado la\\11TORRE BELLSPROUT?",
  ["62:4e4f"] = "Estoy demasiado\\\nlejos. ¡Mejor que\\11llame a casa!",
  ["64:558c"] = "",
  ["64:558e"] = "Soy el ENCARGADO\\\nde la GUARDERÍA.\\12¿Quieres que\\\ncuide un POKéMON?",
  ["64:55bd"] = "Soy el ENCARGADO\\\nde la GUARDERÍA.\\12¿Sabes algo sobre\\\nlos HUEVOS?\\12Mi mujer y yo\\\nestábamos cuidando\\11unos POKéMON.\\12¡Y de pronto\\\nvimos un HUEVO!\\12¿No te parece\\\nincreíble?\\12¿Quieres que te\\\ncuide un POKéMON?",
  ["64:566a"] = "Soy la ENCARGADA\\\nde la GUARDERÍA.\\12¿Quieres que te\\\ncuide un POKéMON?",
  ["64:56a0"] = "Soy la ENCARGADA\\\nde la GUARDERÍA.\\12¿Sabes algo sobre\\\nlos HUEVOS?\\12Mi marido y yo\\\nestábamos cuidando\\11unos POKéMON.\\12¡Y de pronto\\\nvimos un HUEVO!\\12¿No te parece\\\nincreíble?\\12¿Quieres que te\\\ncuide un POKéMON?",
  ["64:575e"] = "¿Cuál quieres\\\nque cuide?",
  ["64:577c"] = "¿Oh? Pero sólo\\\ntienes un POKéMON.",
  ["64:579d"] = "Perdona, pero no\\\nacepto HUEVOS.",
  ["64:57bf"] = "Quita la CARTA y\\\nvuelve a verme.",
  ["64:57e4"] = "Si me lo das,\\\n¿con quién vas\\11a combatir?",
  ["64:5815"] = "Vale. Cuidaré de\\\ntu {STRBUF}.",
  ["64:5830"] = "Vuelve a por él\\\nmás tarde.",
  ["64:5849"] = "¿Somos geniales o\\\nno? ¿Quieres ver a\\11tu {STRBUF}?",
  ["64:587b"] = "Tu {STRBUF}\\\nha crecido mucho.\\12En cuanto a nivel,\\\nha subido {NUM}.\\12Recuperar a tu\\\nPOKéMON te\\11costará {NUM}¥.",
  ["64:58e9"] = "¡Perfecto! ¡Aquí\\\nestá tu POKéMON!",
  ["64:5904"] = "{PLAYER} recogió\\\na {STRBUF}.",
  ["64:5917"] = "¿Ya de vuelta?\\\nTu {STRBUF}\\12debería pasar más\\\ntiempo aquí. Pero\\12recoger ahora\\\na tu POKéMON, te\\11costará 100¥.",
  ["64:5987"] = "No tienes espacio\\\nsuficiente.",
  ["64:59a1"] = "No tienes\\\nbastante dinero.",
  ["64:59be"] = "No hay problema.",
  ["64:59ce"] = "Vuelve cuando\\\nquieras.",
  ["64:59db"] = "Aún no…",
  ["64:59e5"] = "¡Ah, eres tú!\\12Estábamos cuidando\\\nde tus POKéMON y\\12¡menuda sorpresa\\\nnos hemos llevado!\\12¡Tus POKéMON han\\\ntenido un HUEVO!\\12No sabemos cómo ha\\\nllegado ahí, pero\\12es de tus POKéMON.\\\n¿Lo quieres?",
  ["64:5a8a"] = "¡{PLAYER} recibió\\\nel HUEVO!",
  ["64:5a9f"] = "Cuídalo\\\nbien.",
  ["64:5ab6"] = "Cuidaré de él.\\\n¡Gracias!",
  ["64:5ad7"] = "No tienes sitio en\\\ntu equipo. Vuelve\\11en otro momento.",
  ["65:4751"] = "¿Qué?\\12",
  ["65:4759"] = "",
  ["65:475b"] = "¡{STRBUF}\\\nsalió del\\11HUEVO!",
  ["65:4778"] = "¿Quieres darle\\\nun mote a\\11{STRBUF}?",
  ["65:4793"] = "Es el {STRBUF}\\\nque dejé con\\12la ENCARGADA de\\\nla GUARDERÍA.",
  ["65:47c4"] = "Es el {STRBUF}\\\nque dejé con el\\12ENCARGADO de\\\nla GUARDERÍA.",
  ["65:47f4"] = "Está rebosante\\\nde energía.",
  ["65:480f"] = "No está interesado\\\nen {STRBUF}.",
  ["65:482d"] = "Está interesado\\\nen {STRBUF}.",
  ["65:484c"] = "Es agradable con\\\n{STRBUF}.",
  ["65:4866"] = "Muestra interés\\\npor {STRBUF}.",
  ["65:4883"] = "Aquí no hay\\\nninguna CARTA.",
  ["65:4899"] = "La CARTA fue\\\nenviada.",
  ["65:48b9"] = "¡MOCHILA llena!",
  ["65:48cc"] = "Perderás el\\\nmensaje de\\11la CARTA. ¿Vale?",
  ["65:48f1"] = "Ya lleva\\\nun objeto.",
  ["65:4911"] = "Un HUEVO no puede\\\nllevar CARTAS.",
  ["65:492d"] = "La CARTA fue\\\nsacada del BUZÓN.",
  ["65:4993"] = "Hay un POKéMON que\\\nlleva una CARTA.\\12Por favor, quita\\\nla CARTA.",
  ["65:544a"] = "Primero quita\\\nla CARTA.",
  ["65:54fd"] = "¿O prefieres\\\nborrar el mensaje?",
  ["65:5522"] = "Quitada CARTA de\\\n{STRBUF}.",
  ["65:553d"] = "No hay bastante\\\nespacio para\\11quitar la CARTA.",
  ["65:5561"] = "¿Enviar la\\\nCARTA a tu PC?",
  ["65:5584"] = "El BUZÓN de tu\\\nPC está lleno.",
  ["65:559f"] = "La CARTA fue\\\nenviada a tu PC.",
  ["65:5c61"] = "¿Cuántos?",
  ["65:5c6c"] = "{NUM} unidad/es\\\nde {STRBUF}\\11serán {NUM}¥.",
  ["65:5c8c"] = "Hola, hijo.\\12Vendo hierbas\\\nmedicinales.\\12Son buenas, pero\\\nun poco amargas.\\12Quizá tus POKéMON\\\nno las quieran.\\12¡Je, je, je…!",
  ["65:5d07"] = "¿Cuántos?",
  ["65:5d12"] = "{NUM} unidad/es\\\nde {STRBUF}\\11serán {NUM}¥.",
  ["65:5d32"] = "Gracias, hijo.\\\n¡Je, je, je…!",
  ["65:5d4e"] = "¡Oh! Tu MOCHILA\\\nestá llena, hijo.",
  ["65:5d6c"] = "¡Je, je…! No\\\ntienes ese dinero.",
  ["65:5d8e"] = "Vuelve otra vez.\\\n¡Je, je, je…!",
  ["65:5dab"] = "¡Oye! ¿Quieres ver\\\nunas gangas?\\12Vendo objetos que\\\nnadie posee, pero\\12sólo un objeto de\\\ncada tipo.",
  ["65:5e14"] = "{STRBUF}\\\ncuesta {NUM}¥.\\11¿Lo quieres?",
  ["65:5e31"] = "Gracias.",
  ["65:5e3a"] = "¡Oh! Tu MOCHILA\\\nestá a tope.",
  ["65:5e5b"] = "Eso ya lo has\\\ncomprado. No me\\11quedan más.",
  ["65:5e8c"] = "¡Oh! No tienes\\\nsuficiente dinero.",
  ["65:5eaa"] = "Vuelve en otra\\\nocasión.",
  ["65:5ec3"] = "¿Qué quieres?\\\n¿Alguna medicina?",
  ["65:5ee2"] = "¿Cuántos?",
  ["65:5eed"] = "{NUM} unidad/es\\\nde {STRBUF}\\11serán {NUM}¥.",
  ["65:5f0f"] = "¡Muchas gracias!",
  ["65:5f1d"] = "No te queda\\\nsitio.",
  ["65:5f3c"] = "¿Eh? No tienes\\\nbastante dinero.",
  ["65:5f5a"] = "De acuerdo.\\\nHasta luego.",
  ["65:5f76"] = "No tienes nada\\\npara vender.",
  ["65:5f97"] = "¿Cuántos?",
  ["65:5fa2"] = "Puedo pagarte\\\n{NUM}¥.\\12¿Te parece bien?",
  ["65:5fc6"] = "¡Bienvenido!\\\n¿Qué deseas?",
  ["65:5fe4"] = "Aquí tienes.\\\n¡Gracias!",
  ["65:5ffe"] = "No tienes\\\nbastante dinero.",
  ["65:601b"] = "No puedes llevar\\\nmás objetos.",
  ["65:603b"] = "Lo siento. No te\\\npuedo comprar eso.",
  ["65:605d"] = "¡Vuelve cuando\\\nquieras!",
  ["65:6071"] = "¿Puedo ayudarte\\\nen algo más?",
  ["65:6092"] = "Recibiste {NUM} ¥\\\npor {STRBUF}.",
}